(*==============================================================================
 * 组件名称 (Component)  : FC_DL_PolygonArea
 * 所属子库 (Sublibrary) : DL_MathData
 * 当前版本 (Version)    : 1.0.0
 * 兼容性   (Platform)   : CODESYS 3.5 / TwinCAT 3 / 汇川 InoProShop / Machine Expert
 *                         仅依赖 Standard.library（ABS / MOD），全 LREAL 运算，无状态
 * 功能描述 (Function)   : 平面多边形有向面积、绝对面积与质心坐标（鞋带公式 / Green 定理的
 *                         离散形式）。用于视觉定位的料框有效面积、零件轮廓面积校验、
 *                         机器人平面抓取中心计算、皮带跑偏区域判断。
 *                         返回值即绝对面积，有向面积符号经 bCcw 输出，供调用方判断轮廓
 *                         绕向（多数视觉库输出顺时针轮廓，需要翻转才能与机器人坐标系一致）。
 *
 * 【失真与语义披露 / Distortion disclosure】
 *   1) 自交多边形：鞋带公式返回的是代数面积（正负抵消），不是几何面积。结果无几何意义，
 *      调用方必须保证输入是简单多边形；视觉轮廓应先按角度排序并去重，再送进来。
 *   2) 顶点约定"末点不重复首点"。若调用方重复传入首点，面积仍正确，但质心会偏移
 *      （重复点参与一次额外的零面积边，却多算了一次顶点权重）。检测办法：首末点距离
 *      小于 eps 时把 nCount 减 1 再调用。
 *   3) 退化（点数 < 3、共线、零面积）时质心返回顶点算术平均，而不是 (0,0)：
 *      (0,0) 会让机器人在异常时朝原点狂奔，算术平均至少落在轮廓附近。
 *   4) 必须用 LREAL：32 点 × 1e6 mm 坐标的叉积累加可达 1e12，REAL 的 24 位尾数在这个
 *      量级已经丢掉 5 位有效数字，面积会算出负偏差。
 *
 * 开源溯源 (Origin)     : 原创实现（参考西门子 LGF 数学功能组中平面几何族的分类位置，
 *                         鞋带公式为公开数学方法，clean-room 独立实现）
 * 依赖     (Depends)    : 无 DL_ 内部依赖；Standard.library: ABS / MOD
 * 红线自检 (Redline)    : R1 ✓ 零全局变量表与外部变量引用 ｜ R2 ✓ 零物理 IO 地址直写
 *                         R3 ✓ 纯 IEC 61131-3（MOD 取模闭合索引，无负索引）
 *                         R4 ✓ 点数双向钳位 + 索引只经 MOD + 面积零容差 + 质心分母判零
 *                         R5 ✓ 全变量中英双语同行注释 ｜ R6 N/A（无状态机）｜ R7 N/A（无实例调用）
 * 修订历史 (Revision)   :
 *   2026-11-14  v1.0.0  首版入库（Phase 1 收口批次 · R3）
 *============================================================================*)
FUNCTION FC_DL_PolygonArea : LREAL
VAR_IN_OUT
    afX : ARRAY[0..31] OF LREAL;          // 顶点 X 序列，末点不重复首点（上限 32 点）/ Vertex X, not closed, max 32
    afY : ARRAY[0..31] OF LREAL;          // 顶点 Y 序列（上限 32 点）/ Vertex Y, max 32
END_VAR
VAR_INPUT
    nCount : INT;                         // 顶点数，合法域 3..32 / Vertex count, valid 3..32
END_VAR
VAR_OUTPUT
    fCentroidX  : LREAL;                  // 质心 X [mm] / Centroid X [mm]
    fCentroidY  : LREAL;                  // 质心 Y [mm] / Centroid Y [mm]
    bCcw        : BOOL;                   // TRUE = 逆时针（右手系）/ TRUE = counter-clockwise, right-handed
    bDegenerate : BOOL;                   // TRUE = 退化（共线或面积为零）/ TRUE = degenerate polygon
    uErrorId    : UDINT;                  // 故障码，0 = 无故障 / Error code, 0 = no error
END_VAR
VAR
    nI      : INT;                        // 顶点索引 / Vertex index
    nJ      : INT;                        // 下一顶点索引 (nI + 1) MOD nCount / Next vertex index
    nCnt    : INT;                        // 钳位后的有效顶点数 / Clamped effective vertex count
    nGuard  : INT;                        // 循环防死锁计数器 / Loop guard counter
    fCross  : LREAL;                      // 单边叉积项 [mm^2] / Per-edge cross term [mm^2]
    fArea2  : LREAL;                      // 二倍有向面积 [mm^2] / Twice the signed area [mm^2]
    fCxAcc  : LREAL;                      // 质心 X 累加 [mm^3] / Centroid X accumulator [mm^3]
    fCyAcc  : LREAL;                      // 质心 Y 累加 [mm^3] / Centroid Y accumulator [mm^3]
    fDen    : LREAL;                      // 质心公式分母 3×fArea2 [mm^2] / Centroid denominator
    fMeanX  : LREAL;                      // 顶点算术平均 X（退化回退）[mm] / Mean X fallback [mm]
    fMeanY  : LREAL;                      // 顶点算术平均 Y（退化回退）[mm] / Mean Y fallback [mm]
END_VAR
VAR CONSTANT
    DL_PGA_PTS_MIN : INT   := 3;          // 最少顶点数 / Minimum vertex count
    DL_PGA_PTS_MAX : INT   := 32;         // 最多顶点数，等于数组维度 / Maximum vertex count, equals the array size
    DL_PGA_EPS     : LREAL := 1.0E-12;    // 面积零判定容差 [mm^2] / Zero-area tolerance [mm^2]
    DL_PGA_TWO     : LREAL := 2.0;        // 面积公式分母常数 / Area denominator constant
    DL_PGA_THREE   : LREAL := 3.0;        // 质心分母常数，6×(A2/2) 折算为 3×A2 / Reduced centroid denominator
END_VAR

(*------------------------------------------------------------------------------
 * 段 1｜安全预置（边界 B6）：质心先落到 0，后续任何异常路径都要再覆盖它
 *      Safe preset: the centroid starts at zero, every abnormal path overwrites it
 *-----------------------------------------------------------------------------*)
FC_DL_PolygonArea := 0.0;
fCentroidX        := 0.0;
fCentroidY        := 0.0;
bCcw              := FALSE;
bDegenerate       := FALSE;
uErrorId          := 16#0000_0000;
fArea2            := 0.0;
fCxAcc            := 0.0;
fCyAcc            := 0.0;
nGuard            := 0;

(*------------------------------------------------------------------------------
 * 段 2｜点数校验（边界 B1）：上限向下钳位（多点比少点安全），下限直接拒绝
 *      Count check: clamp the upper bound down (more points is safer), reject the lower
 *-----------------------------------------------------------------------------*)
nCnt := nCount;

IF nCnt > DL_PGA_PTS_MAX THEN
    nCnt      := DL_PGA_PTS_MAX;
    uErrorId  := 16#0001_0001;
END_IF

IF nCnt < DL_PGA_PTS_MIN THEN
    (* 边界 B6：退化时给顶点算术平均，绝不返回 (0,0) *)
    (* Degenerate: return the vertex mean, never the origin *)
    IF nCnt < 1 THEN
        fCentroidX := 0.0;
        fCentroidY := 0.0;
    ELSE
        fMeanX := 0.0;
        fMeanY := 0.0;
        FOR nI := 0 TO (nCnt - 1) DO
            fMeanX := fMeanX + afX[nI];
            fMeanY := fMeanY + afY[nI];
        END_FOR
        fCentroidX := fMeanX / INT_TO_LREAL(nCnt);
        fCentroidY := fMeanY / INT_TO_LREAL(nCnt);
    END_IF
    bDegenerate := TRUE;
    uErrorId    := 16#0002_000C;
    RETURN;
END_IF

(*------------------------------------------------------------------------------
 * 段 3｜单遍累加（鞋带公式）：边权与质心权重共用同一个叉积项，只算一次
 *      Single-pass shoelace: the edge weight and the centroid weight share one cross term
 *      nJ 用 MOD nCount 闭合，nCnt >= 3 已保证除数非零，索引永不等于 nCnt
 *-----------------------------------------------------------------------------*)
FOR nI := 0 TO (nCnt - 1) DO

    nJ     := (nI + 1) MOD nCnt;
    fCross := (afX[nI] * afY[nJ]) - (afX[nJ] * afY[nI]);

    fArea2 := fArea2 + fCross;
    fCxAcc := fCxAcc + ((afX[nI] + afX[nJ]) * fCross);
    fCyAcc := fCyAcc + ((afY[nI] + afY[nJ]) * fCross);

    nGuard := nGuard + 1;

END_FOR

IF nGuard > (nCnt + 1) THEN
    (* 理论上不可达（FOR 定长），纯防御：循环计数异常即报表 *)
    (* Unreachable in theory: a bounded FOR loop cannot overrun, defence only *)
    uErrorId := 16#0001_0004;
END_IF

(*------------------------------------------------------------------------------
 * 段 4｜退化判定（边界 B3/B6）：共线或重合时面积为零，质心回退算术平均
 *      Degenerate test: zero area falls back to the vertex mean
 *-----------------------------------------------------------------------------*)
IF ABS(fArea2) <= DL_PGA_EPS THEN

    fMeanX := 0.0;
    fMeanY := 0.0;
    FOR nI := 0 TO (nCnt - 1) DO
        fMeanX := fMeanX + afX[nI];
        fMeanY := fMeanY + afY[nI];
    END_FOR

    fCentroidX  := fMeanX / INT_TO_LREAL(nCnt);
    fCentroidY  := fMeanY / INT_TO_LREAL(nCnt);
    bCcw        := FALSE;
    bDegenerate := TRUE;
    uErrorId    := 16#0002_000C;
    FC_DL_PolygonArea := 0.0;
    RETURN;

END_IF

(*------------------------------------------------------------------------------
 * 段 5｜正常路径：面积 = |fArea2| / 2，质心 = 累加 / (3 × fArea2)
 *      Normal path: area = |fArea2| / 2, centroid = accumulator / (3 × fArea2)
 *      分母用 3×fArea2 而不是 6×(fArea2/2)，少一次除法，少一次舍入
 *      bCcw 由 fArea2 的符号直接给出，不做"面积恒正后再判断"的二次推导
 *-----------------------------------------------------------------------------*)
bCcw := (fArea2 > 0.0);

fDen := DL_PGA_THREE * fArea2;

IF ABS(fDen) > DL_PGA_EPS THEN
    fCentroidX := fCxAcc / fDen;
    fCentroidY := fCyAcc / fDen;
ELSE
    (* 二次防御：段 4 已排除近零面积，此处仅防数值极端情形下的除零 *)
    (* Second defence: near-zero area was excluded in stage 4, this guards extremes *)
    fCentroidX  := 0.0;
    fCentroidY  := 0.0;
    bDegenerate := TRUE;
    uErrorId    := 16#0002_000C;
END_IF

FC_DL_PolygonArea := ABS(fArea2) / DL_PGA_TWO;
END_FUNCTION

(*==============================================================================
 * 组件名称 (Component)  : FC_DL_StringReplaceAll
 * 所属子库 (Sublibrary) : DL_MathData
 * 当前版本 (Version)    : 1.0.1
 * 兼容性   (Platform)   : CODESYS 3.5 / TwinCAT 3 / 汇川 InoProShop / Machine Expert
 *                         仅依赖 Standard.library 标准串函数（LEN / FIND / LEFT / MID / CONCAT）
 * 功能描述 (Function)   : 定长字符串内「全部出现」的子串替换，一次调用给出替换次数、
 *                         结果串与截断标志。用于条码前缀规范化、报表模板占位符替换
 *                         （百分号包裹的批次号与日期占位符）、设备商旧机型代号批量改新代号。
 *                         现场手写 WHILE + FIND + DELETE + INSERT 的典型事故是「替换串里
 *                         含模式串」时缓冲自增长、永不退出扫描，本件用「替换后游标跳到
 *                         插入段之后」的推进律从算法层消灭该类死循环，并叠加次数上限与
 *                         守卫计数器两道闸。
 * 出口契约 (Exit)       : 函数返回值 = 实际替换次数（与出口 nReplaced 同值）；异常路径返回 0。
 *                         任何路径（含早退）sResult 均有确定内容，绝不返回未初始化串。
 * 开源溯源 (Origin)     : 来源标签 lgf-datahandling。许可证：LGF 为免费闭源发布，未取得源码，
 *                         不构成衍生作品。借鉴点仅为「Data Handling 组把 FIFO/LIFO、数组检索、
 *                         排序、字符串并列成数据操作族」的分类骨架，以及字符串族「定长缓冲 +
 *                         原地操作、不做动态分配」的参数域约定。
 *                         clean-room 独立实现：算法、切分策略、游标推进律、计数语义、错误码
 *                         全部自有，零代码行、零注释、零结构体复制。
 * 码位说明 (Codes)      : 信息级 16#0001_0130（模式串为空）/ 0131（达替换次数上限）/
 *                         0132（结果被长度上限截断）/ 0133（长度参数越界已钳位）。
 *                         共 4 码，全部落在 R12 计划第 1.2 节分配给本件的码段内，无段外码。
 * 依赖     (Depends)    : 无 DL_ 内部依赖；Standard.library: LEN / FIND / LEFT / MID / CONCAT
 * 红线自检 (Redline)    : 1 ✓ 零全局变量表依赖、零外部变量声明、零物理地址
 *                         2 ✓ 纯 IEC 61131-3 跨平台语法，无指针、无厂商库
 *                         3 ✓ 模式空硬闸、数组与串长先判界、每轮回夹、双闸防死循环
 *                         4 ✓ 全变量中英双语同行注释
 *                         5 N/A 纯函数无状态机 ｜ 6 N/A 无定时器与边沿实例
 *                         7 ✓ END_FUNCTION 位于文件最后有效行
 * 规格偏离留档 (Deviation):
 *   D1 计划 3.6 节把 bValid 定义为「模式串非空且长度参数合法」。本实现多收一环：
 *      达替换次数上限（码 0131，结果不完整）时 bValid 亦为假。理由：bValid 在本库
 *      统一承载「结果可否直接采信」，不完整的替换结果采信即等于静默丢字段；
 *      完整性细粒度判据由调用方读 uErrorId 与 bTruncated 取得。
 * 修订历史 (Revision)   :
 *   2026-11-15  v1.0.0  首版入库（R12 · Level 0 DL_MathData 字符串族）
 *   2026-11-15  v1.0.1  终审定点修复 A-D01：拼接长度超串型上限（255）时原实现由
 *      LEFT 静默回夹，bTruncated 与 0132 永不置位（验收向量 V5 期望的截断标志恒假）；
 *      补「拼接长度预判」，超限即置 bTruncated 与 0132，杜绝静默丢字符
 *============================================================================*)
FUNCTION FC_DL_StringReplaceAll : INT
VAR_INPUT
    sSource      : STRING(255);          // 源串，最长 255 字符 / Source string, up to 255 characters
    sPattern     : STRING(32);           // 被替换子串，长度 0 视为非法 / Pattern to replace, empty is illegal
    sReplace     : STRING(64);           // 替换子串，允许为空（即删除） / Replacement, empty means delete
    nMaxReplace  : INT := 32;            // 替换次数上限 [次]，域 0~255，0 = 不限 / Replacement limit, zero means unlimited
    nMaxLen      : INT := 255;           // 结果串长度上限 [字符]，域 1~255 / Result length limit, 1..255
END_VAR
VAR_OUTPUT
    sResult      : STRING(255);          // 替换结果，超长时按 nMaxLen 截断 / Result, truncated to nMaxLen
    nReplaced    : INT;                  // 实际替换次数 [次] / Replacement count
    bTruncated   : BOOL;                 // 结果被长度上限截断 TRUE / Result was truncated
    uErrorId     : UDINT;                // 事件码，0 = 无事件 / Event code, zero means none
    bValid       : BOOL;                 // 模式串非空、长度参数未钳位且未达替换次数上限 = TRUE（结果可直接采信） / Pattern non-empty, lengths legal and the count limit not hit, the result may be trusted as is
END_VAR
VAR
    sBuf         : STRING(255);          // 工作缓冲，逐轮就地改写 / Working buffer, rewritten in place
    sHead         : STRING(255);         // 本次替换位置之前的头部片段 / Head fragment before the hit
    sTail        : STRING(255);          // 本次替换位置之后的尾部片段 / Tail fragment after the hit
    sScan        : STRING(255);          // 查找窗口，从 nSearchFrom 起的剩余串 / Search window starting at nSearchFrom
    nPos         : INT;                  // 当前命中位置，1 起，0 = 未命中 [字符位] / Current hit position, one based
    nSearchFrom  : INT;                  // 下一轮查找起点，1 起 [字符位] / Next search start position
    nLenBuf      : INT;                  // 当前缓冲长度 [字符] / Current buffer length
    nLenPat      : INT;                  // 模式串长度 [字符] / Pattern length
    nLenRep      : INT;                  // 替换串长度 [字符] / Replacement length
    nTailStart   : INT;                  // 尾部片段起始位置 [字符位] / Tail fragment start position
    nMaxRepUse   : INT;                  // 生效替换次数上限 [次] / Effective replacement limit
    nMaxLenUse   : INT;                  // 生效结果长度上限 [字符] / Effective result length limit
    nGuard       : DINT;                 // 循环守卫，防串函数异常导致死循环 / Loop guard against endless looping
END_VAR
VAR CONSTANT
    DL_STR_MAX   : INT  := 255;          // 单字节串长度上限，与类型声明一致 [字符] / Single byte string ceiling
    DL_PAT_MAX   : INT  := 32;           // 模式串长度上限，与入参声明一致 [字符] / Pattern ceiling
    DL_REP_MAX   : INT  := 64;           // 替换串长度上限，与入参声明一致 [字符] / Replacement ceiling
    DL_GUARD_MAX : DINT := 512;          // 循环守卫上限 [次] / Loop guard limit
END_VAR

(*------------------------------------------------------------------------------
 * 段 1｜结果预置（P-01 范式）：先给全部出口与全部中间量确定值
 *      Safe preset: every output and every intermediate gets a defined value
 *-----------------------------------------------------------------------------*)
FC_DL_StringReplaceAll := 0;
sResult    := '';
nReplaced  := 0;
bTruncated := FALSE;
uErrorId   := 16#0000_0000;
bValid     := FALSE;
sBuf       := '';
sHead      := '';
sTail      := '';
sScan      := '';
nPos       := 0;
nSearchFrom := 1;
nLenBuf    := 0;
nLenPat    := 0;
nLenRep    := 0;
nTailStart := 0;
nMaxRepUse := 0;
nMaxLenUse := 1;
nGuard     := 0;

(*------------------------------------------------------------------------------
 * 段 2｜参数闸门：串长快照 + 两个长度上限钳位（信息级，钳位后照常执行）
 *      Parameter gates: string snapshots and the two length clamps (informational)
 *-----------------------------------------------------------------------------*)
nLenPat := LEN(sPattern);
IF nLenPat > DL_PAT_MAX THEN
    nLenPat := DL_PAT_MAX;
END_IF
nLenRep := LEN(sReplace);
IF nLenRep > DL_REP_MAX THEN
    nLenRep := DL_REP_MAX;
END_IF

nMaxRepUse := nMaxReplace;
IF nMaxRepUse < 0 THEN
    nMaxRepUse := 0;
    uErrorId := 16#0001_0133;
ELSIF nMaxRepUse > DL_STR_MAX THEN
    nMaxRepUse := DL_STR_MAX;
    IF uErrorId = 16#0000_0000 THEN
        uErrorId := 16#0001_0133;
    END_IF
END_IF
IF nMaxRepUse = 0 THEN
    nMaxRepUse := DL_STR_MAX;
END_IF

nMaxLenUse := nMaxLen;
IF nMaxLenUse < 1 THEN
    nMaxLenUse := 1;
    IF uErrorId = 16#0000_0000 THEN
        uErrorId := 16#0001_0133;
    END_IF
ELSIF nMaxLenUse > DL_STR_MAX THEN
    nMaxLenUse := DL_STR_MAX;
    IF uErrorId = 16#0000_0000 THEN
        uErrorId := 16#0001_0133;
    END_IF
END_IF

bValid := (uErrorId = 16#0000_0000);
sBuf   := LEFT(sSource, DL_STR_MAX);

(*------------------------------------------------------------------------------
 * 段 3｜模式串硬闸：长度 0 直接早退，绝不进入查找循环
 *      Hard gate on the pattern: a zero length pattern never reaches the loop
 *      空模式在 FIND 上的行为跨平台不一致，且会让游标推进律失效，必须在算法入口拦死
 *      An empty pattern makes FIND platform dependent and breaks cursor advance
 *-----------------------------------------------------------------------------*)
IF nLenPat <= 0 THEN
    bValid   := FALSE;
    uErrorId := 16#0001_0130;
ELSE

    (*--------------------------------------------------------------------------
     * 段 4｜主替换循环：三闸并行 —— 次数上限、守卫计数、游标只前进
     *      Main replace loop guarded by the count limit, the guard counter and a
     *      strictly advancing cursor
     *      切分口径：头部保留 + 替换串 + 尾部保留，拼装后立即按串上限回夹
     *      Split policy: head kept, replacement inserted, tail kept, then re-clamped
     *      回夹前必须预判长度：静默回夹等于丢字符，bTruncated 与 0132 必须同时置位
     *      The length is predicted before clamping so truncation is never silent
     *-----------------------------------------------------------------------*)
    nSearchFrom := 1;
    nReplaced   := 0;
    nGuard      := 0;

    WHILE (nReplaced < nMaxRepUse) AND (nGuard < DL_GUARD_MAX) DO
        nGuard  := nGuard + 1;
        nLenBuf := LEN(sBuf);
        nPos    := 0;

        IF (nSearchFrom >= 1) AND (nSearchFrom <= nLenBuf) THEN
            sScan := MID(sBuf, nLenBuf - nSearchFrom + 1, nSearchFrom);
            nPos  := FIND(sScan, sPattern);
            IF nPos > 0 THEN
                nPos := nPos + nSearchFrom - 1;
            END_IF
        END_IF

        IF nPos <= 0 THEN
            EXIT;
        END_IF

        IF nPos > 1 THEN
            sHead := LEFT(sBuf, nPos - 1);
        ELSE
            sHead := '';
        END_IF

        nTailStart := nPos + nLenPat;
        IF nTailStart <= nLenBuf THEN
            sTail := MID(sBuf, nLenBuf - nTailStart + 1, nTailStart);
        ELSE
            sTail := '';
        END_IF

        (* 拼接长度预判：超出串型上限即属截断，先置标志与事件码，绝不静默丢字符 *)
        (* Predict the joined length: exceeding the string ceiling is a truncation *)
        IF (LEN(sHead) + nLenRep + LEN(sTail)) > DL_STR_MAX THEN
            bTruncated := TRUE;
            IF uErrorId = 16#0000_0000 THEN
                uErrorId := 16#0001_0132;
            END_IF
        END_IF
        sBuf := CONCAT(sHead, sReplace);
        sBuf := CONCAT(sBuf, sTail);
        sBuf := LEFT(sBuf, DL_STR_MAX);

        nReplaced := nReplaced + 1;

        (* 游标跳到「已插入替换串之后」：替换串含模式串时天然跳过新插入段 *)
        (* Cursor jumps past the inserted replacement: self growing patterns are safe *)
        nSearchFrom := nPos + nLenRep;
        IF nSearchFrom < 1 THEN
            nSearchFrom := 1;
        END_IF
    END_WHILE;

    (*--------------------------------------------------------------------------
     * 段 5｜上限判定：达到次数上限且剩余串内仍有模式串，说明结果不完整
     *      Limit verdict: hitting the count limit with the pattern still present
     *      means the result is incomplete and must be reported, never silently cut
     *-----------------------------------------------------------------------*)
    nLenBuf := LEN(sBuf);
    IF nReplaced >= nMaxRepUse THEN
        nPos := 0;
        IF (nSearchFrom >= 1) AND (nSearchFrom <= nLenBuf) THEN
            sScan := MID(sBuf, nLenBuf - nSearchFrom + 1, nSearchFrom);
            nPos  := FIND(sScan, sPattern);
        END_IF
        IF nPos > 0 THEN
            bValid := FALSE;
            IF uErrorId = 16#0000_0000 THEN
                uErrorId := 16#0001_0131;
            END_IF
        END_IF
    END_IF

END_IF

(*------------------------------------------------------------------------------
 * 段 6｜结果截断（两条路径共用）：超长按上限裁剪并置标志，事件码首事件优先
 *      Shared truncation step: crop to the limit and keep the first event code
 *-----------------------------------------------------------------------------*)
nLenBuf := LEN(sBuf);
IF nLenBuf > nMaxLenUse THEN
    sBuf       := LEFT(sBuf, nMaxLenUse);
    bTruncated := TRUE;
    IF uErrorId = 16#0000_0000 THEN
        uErrorId := 16#0001_0132;
    END_IF
END_IF

(*------------------------------------------------------------------------------
 * 段 7｜结果落地：返回值与出口同源，保证「同入参同结果」的可重入语义
 *      Result publication: the return value and the output share one source
 *-----------------------------------------------------------------------------*)
sResult := sBuf;
FC_DL_StringReplaceAll := nReplaced;
END_FUNCTION

// =====================================================================
// FB_DL_RackDiagSummary.st
// 机架诊断汇总与首出定位（板级状态字聚合 + 首出三律 + 诊断风暴提示）
// Rack diagnostics aggregation with first-out location and storm hint
// 所属子库: DL_Device    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0003_03ED ~ 16#0003_03F1 (本件独占 5 槽, 勿复用)
// 溯源: 道莅 clean-room 防御性实现
//       来源组标签: diagnostics, axioline, first-out, rack
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 5)
// 注: 板级诊断状态字经输入引脚注入, 零外部系统变量依赖, 与库内端口诊断
//     聚合件和单板诊断锁存件的契约字段语义一一对应, 同名位语义不复定义
// =====================================================================
FUNCTION_BLOCK FB_DL_RackDiagSummary
VAR_INPUT
    auBoardStat : ARRAY[1..8] OF WORD;  // 各板卡诊断状态字注入, 非 0 即该板存在故障 / Per-board status word injected, nonzero = fault
    bReset      : BOOL  := FALSE;       // 首出复位命令 / First-out reset command
END_VAR
VAR_OUTPUT
    uwFaultMask : WORD   := 0;          // 板级故障掩码, 位 0..7 对应板 1..8 / Board fault mask, bit0..7 = board 1..8
    uFirstBoard : USINT  := 0;          // 首出板号 1~8, 0 = 无 / First-out board 1..8, 0 = none
    uFirstCode  : UDINT  := 0;          // 首出板状态字快照回放 / First-out board status snapshot replay
    bStorm      : BOOL   := FALSE;      // 诊断风暴单拍标志, 不锁存不置故障级 / Storm single-cycle flag, info only
    eErr        : UDINT  := 16#0003_03ED;  // 错误码 / Error code
END_VAR
VAR
    rtrReset    : R_TRIG;               // 复位上升沿检测, 每拍无条件刷新 / Reset edge, refreshed every cycle
    uwPrevMask  : WORD   := 0;          // 上拍故障掩码快照 / Previous cycle mask snapshot
    uNewCnt     : USINT  := 0;          // 本拍新故障板数 / New fault board count this cycle
    wBit        : WORD   := 0;          // 位测试掩码 / Bit test mask
    bAllFault   : BOOL   := FALSE;      // 全板故障标记 / All-boards-fault flag
    uZi         : INT    := 1;          // 1..8 数组下标 / Array subscript 1..8
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0003_03ED 信息 全部板卡无故障
//   16#0003_03EE 信息 诊断风暴提示（单拍新故障板数不小于 4, 仅提示, 不进入故障级）
//   16#0003_03EF 故障 存在板卡故障（掩码非零）, 解除式 = 对应板状态字归零
//   16#0003_03F0 故障 首出锁定有效（板号与状态字快照持续回放）,
//                解除式 = bReset 上升沿 且 首出板故障位已消失
//   16#0003_03F1 故障 全部 8 块板卡故障（整架失效）
// ---------------------------------------------------------------------

// ---- 逐板故障判与掩码聚合 / Per-board fault judge and mask aggregation ----
uwFaultMask := 0;                   // 掩码复位 / Reset mask
FOR uZi := 1 TO 8 DO
    IF auBoardStat[uZi] <> 0 THEN
        uwFaultMask := uwFaultMask OR SHL(WORD#1, uZi - 1);     // 移位量 0..7 小于字宽, 合规 / Shift within word width
    END_IF
END_FOR

// ---- 本拍新故障板数差分（与上拍掩码比对）/ New fault count vs previous mask ----
uNewCnt := 0;                       // 新故障计数复位 / Reset new fault count
FOR uZi := 1 TO 8 DO
    wBit := SHL(WORD#1, uZi - 1);   // 当前板位掩码 / Current board bit mask
    IF (uwFaultMask AND wBit) <> 0 THEN
        IF (uwPrevMask AND wBit) = 0 THEN
            uNewCnt := uNewCnt + 1; // 本拍新出现故障的板 / Newly faulted board this cycle
        END_IF
    END_IF
END_FOR
bStorm := uNewCnt >= 4;             // 单拍新故障板数达 4 判风暴, 单拍标志当拍自清 / Storm if 4+ new per cycle
uwPrevMask := uwFaultMask;          // 快照更新供下拍差分 / Snapshot for next cycle

// ---- 复位沿实例无条件刷新 / Unconditional reset edge refresh ----
rtrReset(CLK := bReset);

// ---- 首出三律: 未锁存才仲裁, 同拍取最小板号, 解除在仲裁后 / First-out three laws ----
IF uFirstBoard = 0 THEN
    FOR uZi := 1 TO 8 DO
        IF (uFirstBoard = 0) AND ((uwFaultMask AND SHL(WORD#1, uZi - 1)) <> 0) THEN
            uFirstBoard := INT_TO_USINT(uZi);                   // 升序扫描取最小板号 / Ascending scan picks min board
            uFirstCode  := WORD_TO_UDINT(auBoardStat[uZi]);     // 锁存首出板状态字快照 / Latch status snapshot
        END_IF
    END_FOR
END_IF
// 解除式: bReset 上升沿 且 首出板故障位已消失 / Release: reset edge AND first-out fault bit gone
IF rtrReset.Q AND (uFirstBoard <> 0)
   AND ((uwFaultMask AND SHL(WORD#1, uFirstBoard - 1)) = 0) THEN
    uFirstBoard := 0;               // 释放首出板号 / Release first-out board
    uFirstCode  := 0;               // 清状态字快照 / Clear snapshot
END_IF

// ---- 全板故障判 / All-boards-fault judge ----
bAllFault := (uwFaultMask = 16#00FF);   // 8 位全 1 即整架失效 / All 8 bits set = rack failure

// ---- 错误码仲裁 / Error arbitration ----
IF bAllFault THEN
    eErr := 16#0003_03F1;           // 整架失效 / Rack failure
ELSIF uFirstBoard <> 0 THEN
    eErr := 16#0003_03F0;           // 首出锁定回放 / First-out latch replay
ELSIF uwFaultMask <> 0 THEN
    eErr := 16#0003_03EF;           // 存在板卡故障 / Board fault present
ELSIF bStorm THEN
    eErr := 16#0003_03EE;           // 诊断风暴提示 / Storm hint
ELSE
    eErr := 16#0003_03ED;           // 全部正常 / All normal
END_IF

END_FUNCTION_BLOCK

// =====================================================================
// FB_DL_WaferScanRouter.st
// 晶圆盒扫码路由（扫码契约 + 花篮位取模索引 + 分道路由）
// Wafer cassette scan routing with modulo slot index
// 所属子库: DL_Process    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0005_0467 ~ 16#0005_046B (本件独占 5 槽, 勿复用)
// 溯源: 道莅 clean-room 防御性实现
//       来源组标签: semiconductor, barcode-routing, modulo-index, wafer
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 6)
// =====================================================================
FUNCTION_BLOCK FB_DL_WaferScanRouter
VAR_INPUT
    bScanTrigger : BOOL  := FALSE;  // 扫码触发沿 / Scan trigger edge
    sBarcode     : STRING := '';    // 条码内容（扫码器回读注入）/ Barcode content injected
    bReadOk      : BOOL  := FALSE;  // 读码有效标志 / Read valid flag
    uStationMod  : USINT := 1;      // 花篮位号 1~25, 0 = 组态非法 / Station number 1..25
    abRouteEn    : ARRAY[1..8] OF BOOL;  // 分道允许表, 位序对应分道 1..8 / Route enable table 1..8
    tScanTimeout : TIME  := T#2S;   // 扫码超时窗 T#10MS~T#60S / Scan timeout window [s]
END_VAR
VAR_OUTPUT
    uRouteSel    : USINT := 0;      // 选中分道 1~8, 0 = 拒收 / Selected route, 0 = reject
    bRouteOk     : BOOL  := FALSE;  // 路由成功标志 / Route accepted flag
    uSlotIdx     : USINT := 0;      // 花篮位取模索引 1~8 / Modulo slot index 1..8
    eErr         : UDINT := 16#0005_0467;  // 错误码 / Error code
END_VAR
VAR
    rtrScan      : R_TRIG;          // 扫码触发沿检测, 每拍无条件刷新 / Scan trigger edge, refreshed every cycle
    rtrRead      : R_TRIG;          // 读码有效沿检测, 每拍无条件刷新 / Read-valid edge, refreshed every cycle
    tonScan      : TON;             // 扫码超时定时器, 每拍无条件刷新 / Scan timeout timer, refreshed every cycle
    xBusy        : BOOL  := FALSE;  // 扫码窗进行中标志 / Scan window busy flag
    uRouteCnt    : USINT := 0;      // 使能分道计数 0~8 / Enabled route count 0..8
    uSlotCalc    : USINT := 1;      // 取模索引计算临时量 / Slot index calculation temporary
    uGuard       : USINT := 0;      // 条件减法守卫计数 / Conditional subtraction guard counter
    uZi          : INT   := 1;      // 1..8 数组下标 / Array subscript 1..8
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0005_0467 信息 路由成功
//   16#0005_0468 信息 组态非法拒收（花篮位号为 0 或分道全禁用）
//   16#0005_0469 故障 扫码超时未读（拒收）; 码随最近一次判定保持, 重新触发扫码即刷新解除
//   16#0005_046A 信息 读码失败拒收（条码数据在而有效标志为假, 与空串语义分离）
//   16#0005_046B 信息 空条码拒收（读码有效但条码长度为零）
// ---------------------------------------------------------------------

// ---- 分道使能计数 / Enabled route count ----
uRouteCnt := 0;                     // 计数复位 / Reset count
FOR uZi := 1 TO 8 DO
    IF abRouteEn[uZi] THEN
        uRouteCnt := uRouteCnt + 1; // 累计使能分道 / Count enabled route
    END_IF
END_FOR

// ---- 边沿与定时器实例无条件周期刷新（调用不进任何 IF 分支）/ Unconditional edge and timer refresh ----
rtrScan(CLK := bScanTrigger);       // 扫码触发沿 / Scan trigger edge
rtrRead(CLK := bReadOk);            // 读码有效沿 / Read valid edge
tonScan(IN := xBusy, PT := tScanTimeout);   // 扫码窗计时 / Scan window timing

// ---- 触发沿启动扫码窗 / Trigger edge starts scan window ----
IF rtrScan.Q THEN
    xBusy := TRUE;                  // 拍 N 进入扫码窗 / Enter scan window
END_IF

// ---- 扫码窗内判定 / Judgement inside scan window ----
IF xBusy THEN
    IF tonScan.Q THEN
        // 本拍行为: 超时拒收并关窗 / Timeout reject and close window
        uRouteSel := 0;             // 拒收 / Reject
        uSlotIdx  := 0;             // 索引无效 / Index void
        bRouteOk  := FALSE;         // 路由失败 / Route failed
        eErr      := 16#0005_0469;  // 扫码超时 / Scan timeout
        xBusy     := FALSE;         // 拍 N+1 窗关闭, 等下次触发 / Window closed
    ELSIF bReadOk AND (LEN(sBarcode) = 0) THEN
        // 空条码: 读码有效但无内容 / Empty barcode: valid flag but no content
        uRouteSel := 0;
        uSlotIdx  := 0;
        bRouteOk  := FALSE;
        eErr      := 16#0005_046B;  // 空条码拒收 / Empty barcode reject
        xBusy     := FALSE;
    ELSIF (NOT bReadOk) AND (LEN(sBarcode) > 0) THEN
        // 读码失败: 数据在而有效标志为假 / Read failed: data present, valid flag false
        uRouteSel := 0;
        uSlotIdx  := 0;
        bRouteOk  := FALSE;
        eErr      := 16#0005_046A;  // 读码失败拒收 / Read-fail reject
        xBusy     := FALSE;
    ELSIF bReadOk AND (LEN(sBarcode) > 0) THEN
        // 读码成功: 组态校验后路由 / Read ok: config check then route
        IF (uStationMod = 0) OR (uRouteCnt = 0) THEN
            uRouteSel := 0;         // 组态非法拒收 / Config illegal reject
            uSlotIdx  := 0;
            bRouteOk  := FALSE;
            eErr      := 16#0005_0468;
        ELSE
            // 取模索引: 条件减法实现, 不用取余运算（跨平台负数歧义禁令）
            // Modulo by conditional subtraction, no remainder operator
            uSlotCalc := uStationMod;       // 从花篮位号起算 / Start from station number
            uGuard    := 0;                 // 守卫计数清零 / Clear guard
            WHILE (uSlotCalc > uRouteCnt) AND (uGuard < 32) DO
                uSlotCalc := uSlotCalc - uRouteCnt;     // 减一轮分道数 / Subtract one route round
                uGuard    := uGuard + 1;                // 守卫计数防死循环 / Guard against dead loop
            END_WHILE
            uSlotIdx := uSlotCalc;      // 输出取模索引 1..分道数 / Output slot index
            // 路由选择: 升序取首个使能分道 / Route select: first enabled ascending
            uRouteSel := 0;
            FOR uZi := 1 TO 8 DO
                IF (uRouteSel = 0) AND abRouteEn[uZi] THEN
                    uRouteSel := INT_TO_USINT(uZi);     // 首个使能分道 / First enabled route
                END_IF
            END_FOR
            bRouteOk := TRUE;           // 路由成功 / Route accepted
            eErr     := 16#0005_0467;   // 正常码 / Normal code
        END_IF
        xBusy := FALSE;                 // 判定完成关窗 / Judgement done, close window
    END_IF
END_IF

END_FUNCTION_BLOCK

// =====================================================================
// FB_DL_SiloLevelInterlock.st
// 料仓高低料位-输送联锁（防溢仓/空跑双联锁 + 卡料窗）
// Silo level interlock with conveyor, overflow/empty trips and jam window
// 所属子库: DL_Process    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0005_046C ~ 16#0005_0470 (本件独占 5 槽, 勿复用)
// 溯源: 道莅 clean-room 防御性实现
//       来源组标签: process-control, silo, interlock, conveyor
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 7)
// 安全声明: 料位开关以假 = 未到达该料位为正常态（失电安全侧: 开关失电判为
//           未到达）; 输送允许输出安全侧为假; 各锁存位解除式均可达
// =====================================================================
FUNCTION_BLOCK FB_DL_SiloLevelInterlock
VAR_INPUT
    bHighLevel : BOOL := FALSE;     // 高料位开关, 真 = 到达高料位 / High level switch, TRUE = reached
    bLowLevel  : BOOL := FALSE;     // 低料位开关, 真 = 到达低料位 / Low level switch, TRUE = reached
    bConvRun   : BOOL := FALSE;     // 输送运行反馈 / Conveyor run feedback
    bRunDemand : BOOL := FALSE;     // 输送运行需求注入（上位流程给出, 供卡料判据使用）/ Run demand injected
    tJamWin    : TIME := T#5S;      // 卡料确认窗 T#100MS~T#60S / Jam confirm window [s]
    bReset     : BOOL := FALSE;     // 联锁复位命令 / Interlock reset command
END_VAR
VAR_OUTPUT
    bConvPermit   : BOOL := FALSE;  // 输送允许, 安全侧为假; 高料位联锁只停进料不停输送 / Conveyor permit, safe FALSE
    bOverflowTrip : BOOL := FALSE;  // 溢仓联锁锁存 / Overflow trip latch
    bEmptyTrip    : BOOL := FALSE;  // 空跑联锁锁存 / Empty-run trip latch
    bJamDet       : BOOL := FALSE;  // 卡料检测锁存 / Jam detection latch
    eErr          : UDINT := 16#0005_046C;  // 错误码 / Error code
END_VAR
VAR
    rtrReset  : R_TRIG;             // 复位上升沿检测, 每拍无条件刷新 / Reset edge, refreshed every cycle
    tonJam    : TON;                // 卡料确认定时器, 每拍无条件刷新 / Jam confirm timer, refreshed every cycle
    bConflict : BOOL := FALSE;      // 料位组态矛盾锁存 / Level configuration conflict latch
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0005_046C 信息 联锁正常（输送允许且无锁存事件）
//   16#0005_046D 故障 料位组态矛盾（高低料位同时有效）,
//                解除式 = 双开关恢复互斥 且 bReset 上升沿
//   16#0005_046E 故障 溢仓联锁（高料位: 停进料, 输送允许保持完成当前批次）,
//                解除式 = 高料位消失 且 bReset 上升沿
//   16#0005_046F 故障 空跑联锁（低料位: 停输送防空跑）,
//                解除式 = 低料位消失 且 bReset 上升沿
//   16#0005_0470 故障 卡料（运行需求持续而输送无反馈超窗）,
//                解除式 = 输送反馈恢复 且 bReset 上升沿
// ---------------------------------------------------------------------

// ---- 复位沿实例无条件刷新 / Unconditional reset edge refresh ----
rtrReset(CLK := bReset);

// ---- 组态矛盾与联锁锁存置位（锁存置位, 解除见各解除式）/ Conflict and trip latches ----
IF bHighLevel AND bLowLevel THEN
    bConflict := TRUE;              // 高低料位同时有效 = 组态矛盾 / Both levels active = conflict
END_IF
IF bHighLevel THEN
    bOverflowTrip := TRUE;          // 高料位置溢仓联锁 / High level sets overflow trip
END_IF
IF bLowLevel THEN
    bEmptyTrip := TRUE;             // 低料位置空跑联锁 / Low level sets empty trip
END_IF

// ---- 卡料确认定时器无条件周期刷新（有运行需求而无运行反馈才计时）/ Jam timer unconditional refresh ----
tonJam(IN := bRunDemand AND (NOT bConvRun) AND (NOT bJamDet)
        AND (NOT bConflict) AND (NOT bEmptyTrip),
       PT := tJamWin);
IF tonJam.Q THEN
    bJamDet := TRUE;                // 窗内持续无反馈判卡料 / No feedback through window = jam
END_IF

// ---- 锁存解除式（全部可达, R28 自证）/ Latch release paths, all reachable ----
IF rtrReset.Q AND (NOT (bHighLevel AND bLowLevel)) THEN
    bConflict := FALSE;             // 矛盾解除: 双开关恢复互斥 / Conflict release
END_IF
IF rtrReset.Q AND (NOT bHighLevel) THEN
    bOverflowTrip := FALSE;         // 溢仓解除: 高料位消失 / Overflow release
END_IF
IF rtrReset.Q AND (NOT bLowLevel) THEN
    bEmptyTrip := FALSE;            // 空跑解除: 低料位消失 / Empty release
END_IF
IF rtrReset.Q AND bConvRun THEN
    bJamDet := FALSE;               // 卡料解除: 运行反馈恢复 / Jam release
END_IF

// ---- 输送允许: 矛盾/空跑/卡料任一锁存即禁止; 溢仓联锁不停输送（完成当前批次）
//      Conveyor permit: blocked by conflict/empty/jam; overflow keeps conveyor ----
bConvPermit := (NOT bConflict) AND (NOT bEmptyTrip) AND (NOT bJamDet);

// ---- 错误码仲裁（联锁动作与告警码分离输出）/ Error arbitration ----
IF bConflict THEN
    eErr := 16#0005_046D;           // 组态矛盾 / Configuration conflict
ELSIF bOverflowTrip THEN
    eErr := 16#0005_046E;           // 溢仓联锁 / Overflow trip
ELSIF bEmptyTrip THEN
    eErr := 16#0005_046F;           // 空跑联锁 / Empty trip
ELSIF bJamDet THEN
    eErr := 16#0005_0470;           // 卡料 / Jam
ELSE
    eErr := 16#0005_046C;           // 联锁正常 / Interlock normal
END_IF

END_FUNCTION_BLOCK

// =====================================================================
// FB_DL_WeightClassifySort.st
// 重量四档分级剔除（复用库内判档律 + 剔除口放行 + 档位计数）
// Weight 4-band classification with reject gate and band counters
// 所属子库: DL_Process    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0005_0476 ~ 16#0005_047A (本件独占 5 槽, 勿复用)
// 溯源: 道莅 clean-room 防御性实现
//       来源组标签: packaging, weight-sorting, classification, reject
// 枚举属主: E_DL_WeightClass —— 本文件为全库唯一属主, 其他件只引用不重声明
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 9)
// 分层声明: 判档律消费 DL_Base 的 FC_DL_LimitClassify（四阈值五档, 返回
//           E_DL_LimitBand）, 本件不重写分级律, 只做判档→剔除口→计数编排;
//           区间归属沿用判档件闭区间口径（等于阈值归更严档, 容差判等）
// =====================================================================
// ---------------------------------------------------------------------
// 枚举定义: E_DL_WeightClass (全库唯一属主, 其他件只引用不重声明;
//           R30 序 11 称重剔除秤件引用本枚举)
// ---------------------------------------------------------------------
TYPE E_DL_WeightClass :
(
    eLL,            // 严重欠重档 / Severely underweight band
    eL,             // 欠重档 / Underweight band
    eOK,            // 合格档 / Ok band
    eH,             // 超重档 / Overweight band
    eHH             // 严重超重档 / Severely overweight band
);
END_TYPE

FUNCTION_BLOCK FB_DL_WeightClassifySort
VAR_INPUT
    bPartInZone : BOOL := FALSE;    // 检重区有件信号（分类触发沿）/ Part in check zone, classification trigger
    fWeight_g   : REAL := 0.0;      // 称重值 0~5000 g / Measured weight [g]
    fTh_LL_g    : REAL := 150.0;    // 低低阈值（严重欠重）0~5000 g / Low-low threshold [g]
    fTh_L_g     : REAL := 250.0;    // 低阈值（欠重）0~5000 g / Low threshold [g]
    fTh_H_g     : REAL := 750.0;    // 高阈值（超重）0~5000 g / High threshold [g]
    fTh_HH_g    : REAL := 850.0;    // 高高阈值（严重超重）0~5000 g / High-high threshold [g]
    bRejectArm  : BOOL := FALSE;    // 剔除口布防 / Reject gate armed
END_VAR
VAR_OUTPUT
    eClass      : E_DL_WeightClass := E_DL_WeightClass.eOK;  // 本件判档结果 / Classification result
    bRejectOut  : BOOL := FALSE;    // 剔除口放行脉冲（单拍自清）/ Reject gate pulse, one cycle
    uOkCount    : UDINT := 0;       // 合格计数 / Ok count
    uNgCount    : UDINT := 0;       // 不合格计数（含欠/超重/传感器故障/组态故障安全分流）/ Ng count
    eErr        : UDINT := 16#0005_0476;  // 错误码 / Error code
END_VAR
VAR
    rtrPart     : R_TRIG;           // 有件沿检测, 每拍无条件刷新 / Part edge, refreshed every cycle
    bCfgErr     : BOOL := FALSE;    // 阈值组态非法标记 / Threshold configuration error flag
    eBand       : E_DL_LimitBand := E_DL_LimitBand.eInvalid;  // 判档件返回档 / Band returned by classifier
    bBandInv    : BOOL := FALSE;    // 判档返回非法档标记 / Classifier invalid-band flag
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0005_0476 信息 分级正常（判档完成, OK 或常规 NG 计数）
//   16#0005_0477 故障 阈值组态非法（阈值非有限或越出 0~5000 g 域, 或判档件
//                返回非法档: 阈值序倒置）; 解除式 = 恢复合法单调阈值组态
//   16#0005_0478 故障 重量非有限（传感器故障, NG 侧安全分流, 与超重 NG 区分）,
//                解除式 = 称重值恢复有限且量程内
//   16#0005_0479 信息 超量程（负重为负或超 5000 g, 按 NG 安全分流计数）
//   16#0005_047A 信息 剔除脉冲输出拍（单拍信息, 随剔除口放行同拍发出）
// ---------------------------------------------------------------------

// ---- 有件沿实例无条件刷新 / Unconditional part edge refresh ----
rtrPart(CLK := bPartInZone);

// ---- 阈值组态闸: 四阈值逐一判非有限与量程域（单调性交由判档件校验）
//      Threshold config gate: finite and domain check per threshold ----
bCfgErr := FALSE;                   // 组态标记复位 / Reset config flag
IF (fTh_LL_g <> fTh_LL_g) OR (fTh_LL_g < 0.0) OR (fTh_LL_g > 5000.0) THEN
    bCfgErr := TRUE;                // 低低阈值非法 / Low-low threshold illegal
END_IF
IF (fTh_L_g <> fTh_L_g) OR (fTh_L_g < 0.0) OR (fTh_L_g > 5000.0) THEN
    bCfgErr := TRUE;                // 低阈值非法 / Low threshold illegal
END_IF
IF (fTh_H_g <> fTh_H_g) OR (fTh_H_g < 0.0) OR (fTh_H_g > 5000.0) THEN
    bCfgErr := TRUE;                // 高阈值非法 / High threshold illegal
END_IF
IF (fTh_HH_g <> fTh_HH_g) OR (fTh_HH_g < 0.0) OR (fTh_HH_g > 5000.0) THEN
    bCfgErr := TRUE;                // 高高阈值非法 / High-high threshold illegal
END_IF

// ---- 剔除口缺省收口（单拍脉冲当拍自清）/ Reject pulse default off, self-clearing ----
bRejectOut := FALSE;
bBandInv := FALSE;                  // 非法档标记复位 / Reset invalid-band flag

// ---- 有件沿触发判档编排 / Part edge triggers classification orchestration ----
IF rtrPart.Q THEN
    IF (fWeight_g <> fWeight_g) OR (ABS(fWeight_g) >= 1.0E12) THEN
        // 传感器故障: NG 侧安全分流, 独立故障码 / Sensor fault: NG safe routing, distinct code
        eClass := E_DL_WeightClass.eLL;     // 分流到欠重侧 / Route to underweight side
        bRejectOut := bRejectArm;           // 布防时剔除 / Reject when armed
        uNgCount := uNgCount + 1;           // NG 计数 / Count NG
        eErr := 16#0005_0478;               // 传感器故障码 / Sensor fault code
    ELSIF (fWeight_g < 0.0) OR (fWeight_g > 5000.0) THEN
        // 超量程（含负重为负）: NG 安全分流 / Out of range incl. negative: NG safe routing
        eClass := E_DL_WeightClass.eHH;     // 分流到超重侧 / Route to overweight side
        bRejectOut := bRejectArm;
        uNgCount := uNgCount + 1;
        eErr := 16#0005_0479;               // 超量程信息码 / Over-range info code
    ELSIF bCfgErr THEN
        // 组态故障: 安全侧拒绝分档, 按 NG 分流 / Config fault: safe side, route as NG
        eClass := E_DL_WeightClass.eLL;
        bRejectOut := bRejectArm;
        uNgCount := uNgCount + 1;
        eErr := 16#0005_0477;               // 组态故障码 / Config fault code
    ELSE
        // 判档律消费: 调 DL_Base 判档函数, 闭区间口径 / Consume classifier, closed-interval convention
        eBand := FC_DL_LimitClassify(REAL_TO_LREAL(fWeight_g),
                                     REAL_TO_LREAL(fTh_LL_g),
                                     REAL_TO_LREAL(fTh_L_g),
                                     REAL_TO_LREAL(fTh_H_g),
                                     REAL_TO_LREAL(fTh_HH_g));
        CASE eBand OF
            E_DL_LimitBand.eLowTripped:     // 低低档 → 严重欠重 / Low-low to severely under
                eClass := E_DL_WeightClass.eLL;
            E_DL_LimitBand.eLowWarn:        // 低档 → 欠重 / Low to under
                eClass := E_DL_WeightClass.eL;
            E_DL_LimitBand.eNormal:         // 正常档 → 合格 / Normal to ok
                eClass := E_DL_WeightClass.eOK;
            E_DL_LimitBand.eUpWarn:         // 高档 → 超重 / High to over
                eClass := E_DL_WeightClass.eH;
            E_DL_LimitBand.eUpTripped:      // 高高档 → 严重超重 / High-high to severely over
                eClass := E_DL_WeightClass.eHH;
            ELSE                            // 非法档兜底: NG 安全侧 / Invalid band fallback: NG safe side
                eClass := E_DL_WeightClass.eLL;
                bBandInv := TRUE;           // 置非法档标记 / Set invalid-band flag
        END_CASE
        // 档位计数与剔除口放行 / Band counting and reject gate
        IF eClass = E_DL_WeightClass.eOK THEN
            uOkCount := uOkCount + 1;       // 合格计数 / Count ok
        ELSE
            uNgCount := uNgCount + 1;       // 不合格计数 / Count ng
        END_IF
        bRejectOut := bRejectArm AND (eClass <> E_DL_WeightClass.eOK);  // 非 OK 布防剔除 / Reject non-ok when armed
        IF bBandInv THEN
            eErr := 16#0005_0477;           // 判档非法兜底码 / Invalid band code
        ELSE
            eErr := 16#0005_0476;           // 分级正常 / Classification normal
        END_IF
    END_IF
END_IF

END_FUNCTION_BLOCK

// =====================================================================
// FB_DL_EmoAndonFab.st
// 洁净室 EMO-安灯联动呼叫（EMO 急停优先仲裁 + 门审计联动 + 应答/复位管理）
// Cleanroom EMO andon linkage with priority arbitration and door audit
// 所属子库: DL_Process    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0005_047B ~ 16#0005_047F (本件独占 5 槽, 勿复用)
// 溯源: 道莅 clean-room 防御性实现
//       来源组标签: semiconductor, andon, emo, safety-linkage
// 枚举属主: E_DL_AndonLevel —— 全库唯一属主为 DL_Process 安灯呼叫系统件,
//           本件只引用不重声明
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 10)
// 分层声明: 本件为联动编排件, 四级仲裁律全部消费库内安灯呼叫系统件的
//           E_DL_AndonLevel 契约, 不重写普通呼叫仲裁; EMO 触发不唯一属主,
//           首出定位到按钮号; 门审计事件经门开位掩码引脚注入
// =====================================================================
FUNCTION_BLOCK FB_DL_EmoAndonFab
VAR_INPUT
    abEmo        : ARRAY[1..6] OF BOOL;  // EMO 急停按钮阵列 / EMO button array
    bDoorOpenMask: WORD := 0;        // 安全门开位掩码注入, 位 0..5 对应门 1..6 / Door-open mask injected, bit0..5 = door 1..6
    bAck         : BOOL := FALSE;    // 呼叫应答命令 / Call acknowledge command
    bReset       : BOOL := FALSE;    // 事件复位命令 / Event reset command
END_VAR
VAR_OUTPUT
    eAndonLevel  : E_DL_AndonLevel := E_DL_AndonLevel.eNone;  // 联动安灯级别 / Linked andon level
    bLampRed     : BOOL := FALSE;    // 红灯输出 / Red lamp output
    bBuzzer      : BOOL := FALSE;    // 蜂鸣输出（应答后静音）/ Buzzer output, muted after ack
    uFirstEmo    : USINT := 0;       // 首出 EMO 按钮号 1~6, 0 = 无 / First-out EMO button, 0 = none
    eErr         : UDINT := 16#0005_047B;  // 错误码 / Error code
END_VAR
VAR
    rtrAck       : R_TRIG;           // 应答沿检测, 每拍无条件刷新 / Ack edge, refreshed every cycle
    rtrReset     : R_TRIG;           // 复位沿检测, 每拍无条件刷新 / Reset edge, refreshed every cycle
    bEmoAny      : BOOL := FALSE;    // 任一 EMO 有效标记 / Any EMO active flag
    uFirstThis   : USINT := 0;       // 本拍首出候选按钮号 / First-out candidate this cycle
    uFirstLatch  : USINT := 0;       // 首出锁存按钮号 / First-out latched button
    bAckLatch    : BOOL := FALSE;    // 应答静音锁存 / Acknowledge mute latch
    uZi          : INT   := 1;       // 1..6 数组下标 / Array subscript 1..6
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0005_047B 信息 无 EMO 无门审计事件
//   16#0005_047C 故障 EMO 急停触发（任一按钮有效, 优先级高于门审计）,
//                解除式 = 全部按钮释放 且 bReset 上升沿
//   16#0005_047D 故障 安全门审计联动（门开掩码非零）, 解除式 = 门掩码归零
//   16#0005_047E 信息 应答沿确认（事件存续期间的应答统计拍,
//                未应答解除不计入应答统计, 沿用安灯呼叫系统语义）
//   16#0005_047F 信息 复位确认（事件已解除后的复位拍, 清应答锁存）
// ---------------------------------------------------------------------

// ---- EMO 首出候选扫描（升序取最小按钮号）/ EMO first-out candidate scan ----
bEmoAny := FALSE;                   // 标记复位 / Reset flag
uFirstThis := 0;                    // 候选清零 / Clear candidate
FOR uZi := 1 TO 6 DO
    IF abEmo[uZi] THEN
        bEmoAny := TRUE;            // 任一按钮有效 / Any button active
        IF uFirstThis = 0 THEN
            uFirstThis := INT_TO_USINT(uZi);    // 升序首出候选 / Ascending first candidate
        END_IF
    END_IF
END_FOR

// ---- 应答与复位沿实例无条件刷新 / Unconditional ack and reset edge refresh ----
rtrAck(CLK := bAck);
rtrReset(CLK := bReset);

// ---- 首出锁存与解除 / First-out latch and release ----
IF (uFirstLatch = 0) AND bEmoAny THEN
    uFirstLatch := uFirstThis;      // 未锁存才仲裁, 同拍取最小按钮号 / Arbitrate only if unlatched, min button
END_IF
IF NOT bEmoAny THEN
    uFirstLatch := 0;               // 全部释放解除首出锁存 / Release when all clear
END_IF
uFirstEmo := uFirstLatch;           // 输出首出按钮号 / Output first-out button

// ---- 应答锁存管理（未应答解除不计入应答统计: 解除拍自动清锁存）
//      Ack latch management, un-acked release clears latch ----
IF rtrAck.Q AND (bEmoAny OR (bDoorOpenMask <> 0)) THEN
    bAckLatch := TRUE;              // 事件存续期间应答生效 / Ack effective while event present
END_IF
IF (NOT bEmoAny) AND (bDoorOpenMask = 0) THEN
    bAckLatch := FALSE;             // 事件消失清应答锁存 / Clear latch on event clear
END_IF

// ---- 联动级别仲裁: EMO 优先于门审计, 同拍取高者 / Level arbitration: EMO over door ----
IF bEmoAny THEN
    eAndonLevel := E_DL_AndonLevel.eMaint;      // EMO 映射最高优先级维修级 / EMO maps to highest level
ELSIF bDoorOpenMask <> 0 THEN
    eAndonLevel := E_DL_AndonLevel.eDevice;     // 门审计映射设备级 / Door audit maps device level
ELSE
    eAndonLevel := E_DL_AndonLevel.eNone;       // 无事件 / No event
END_IF

// ---- 灯与蜂鸣输出（蜂鸣按级别 CASE 判定, 含 ELSE 兜底）/ Lamp and buzzer with CASE fallback ----
bLampRed := bEmoAny OR (bDoorOpenMask <> 0);    // 红灯: 任一事件点亮 / Lamp on any event
CASE eAndonLevel OF
    E_DL_AndonLevel.eNone:     bBuzzer := FALSE;                        // 无事件不鸣响 / No event, silent
    E_DL_AndonLevel.eMaterial: bBuzzer := FALSE;                        // 本件不消费普通缺料级 / Material level not consumed here
    E_DL_AndonLevel.eQuality:  bBuzzer := FALSE;                        // 本件不消费普通品质级 / Quality level not consumed here
    E_DL_AndonLevel.eDevice:   bBuzzer := bLampRed AND (NOT bAckLatch); // 设备级: 未应答鸣响 / Device level: buzzer until ack
    E_DL_AndonLevel.eMaint:    bBuzzer := bLampRed AND (NOT bAckLatch); // 维修级: 未应答鸣响 / Maint level: buzzer until ack
    ELSE                       bBuzzer := bLampRed;                     // 兜底: 未知级别按最响处理 / Fallback: loudest
END_CASE

// ---- 错误码仲裁 / Error arbitration ----
IF bEmoAny THEN
    eErr := 16#0005_047C;           // EMO 触发（最高优先级）/ EMO active, highest priority
ELSIF rtrAck.Q AND bLampRed THEN
    eErr := 16#0005_047E;           // 应答沿确认拍 / Ack edge cycle
ELSIF bDoorOpenMask <> 0 THEN
    eErr := 16#0005_047D;           // 门审计联动 / Door audit linkage
ELSIF rtrReset.Q AND (NOT bEmoAny) THEN
    eErr := 16#0005_047F;           // 复位确认拍 / Reset confirm cycle
ELSE
    eErr := 16#0005_047B;           // 无事件 / No event
END_IF

END_FUNCTION_BLOCK

// =====================================================================
// FB_DL_LamStepperFeed.st
// 层压机铺膜步进送料（开环步进契约消费 + 膜长累计 + 保养窗冻结 + 堵转判据）
// Laminator film stepper feeding with maintenance freeze and stall judge
// 所属子库: DL_Motion    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0004_0359 ~ 16#0004_035D (本件独占 5 槽, 勿复用)
// 溯源: 道莅 clean-room 防御性实现
//       来源组标签: photovoltaic, laminator, stepper-open-loop, maintenance
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 15)
// 分层声明: 本件为组合编排件, 开环步进运动语义全部经引脚注入消费
//           （就绪/完成/故障回读对应开环步进契约, 不自造轴状态枚举）;
//           累计送料经定长计米件注入; 保养窗经保养窗管理件注入
// =====================================================================
FUNCTION_BLOCK FB_DL_LamStepperFeed
VAR_INPUT
    bStepperReady    : BOOL := FALSE;   // 步进驱动就绪回读注入 / Stepper ready feedback injected
    bStepperDone     : BOOL := FALSE;   // 步进完成回读注入 / Stepper done feedback injected
    bStepperFault    : BOOL := FALSE;   // 步进故障回读注入 / Stepper fault feedback injected
    bFeedStart       : BOOL := FALSE;   // 送料步启动命令 / Feed step start command
    fFilmLen_m       : REAL := 300.0;   // 单卷膜长 0~2000 m / Film roll length [m]
    fStepLen_m       : REAL := 0.5;     // 单步步长 0~10 m / Step length [m]
    fChangeReserve_m : REAL := 5.0;     // 换膜余量 0~50 m / Change reserve [m]
    fFedLen_m        : REAL := 0.0;     // 累计送料反馈注入 0~2000 m / Fed length feedback injected [m]
    bMaintWin        : BOOL := FALSE;   // 保养窗激活注入 / Maintenance window injected
    tFeedTimeout     : TIME := T#10S;   // 送料超时窗（理论耗时×1.5 口径）T#100MS~T#120S / Feed timeout [s]
END_VAR
VAR_OUTPUT
    bFeedCmd    : BOOL := FALSE;        // 送料指令输出 / Feed command output
    bFeedDone   : BOOL := FALSE;        // 步完成脉冲（单拍自清）/ Step done pulse, one cycle
    fRemainLen_m: REAL := 0.0;          // 剩余膜长 / Remaining film length [m]
    bMaintHold  : BOOL := FALSE;        // 保养窗冻结标志（安全侧不启动）/ Maintenance hold flag
    eErr        : UDINT := 16#0004_0359;  // 错误码 / Error code
END_VAR
VAR
    rtrStart  : R_TRIG;                 // 启动沿检测, 每拍无条件刷新 / Start edge, refreshed every cycle
    rtrDone   : R_TRIG;                 // 完成沿检测, 每拍无条件刷新 / Done edge, refreshed every cycle
    tonFeed   : TON;                    // 送料超时定时器, 每拍无条件刷新 / Feed timeout timer, refreshed every cycle
    xFeedAct  : BOOL := FALSE;          // 送料步进行中标志 / Feed step active flag
    bTmoLatch : BOOL := FALSE;          // 超时堵转锁存 / Timeout stall latch
    bCfgErr   : BOOL := FALSE;          // 组态非法标记 / Configuration error flag
    bWarn     : BOOL := FALSE;          // 膜长耗尽预警标记 / Film-end warning flag
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0004_0359 信息 送料正常
//   16#0004_035A 故障 送料超时判堵转（指令后未在窗内完成, 指令立即收口）,
//                解除式 = 步进就绪恢复 且 送料步已收口
//   16#0004_035B 故障 步进驱动故障回读有效（指令立即收口）,
//                解除式 = 故障回读消失
//   16#0004_035C 信息 膜长耗尽预警（剩余膜长低于换膜余量, 送料继续）
//   16#0004_035D 故障 组态非法（膜长/步长/余量非有限或不大于 0）,
//                解除式 = 恢复合法组态
// ---------------------------------------------------------------------

// ---- 边沿与定时器实例无条件周期刷新 / Unconditional edge and timer refresh ----
rtrStart(CLK := bFeedStart);        // 启动沿 / Start edge
rtrDone(CLK := bStepperDone);       // 完成沿 / Done edge
tonFeed(IN := xFeedAct, PT := tFeedTimeout);    // 超时计时 / Timeout timing

// ---- 组态闸 / Configuration gate ----
bCfgErr := FALSE;
IF (fFilmLen_m <> fFilmLen_m) OR (fFilmLen_m <= 0.0) OR (fFilmLen_m > 2000.0) THEN
    bCfgErr := TRUE;                // 膜长非法 / Illegal film length
END_IF
IF (fStepLen_m <> fStepLen_m) OR (fStepLen_m <= 0.0) OR (fStepLen_m > 10.0) THEN
    bCfgErr := TRUE;                // 步长非法 / Illegal step length
END_IF
IF (fChangeReserve_m <> fChangeReserve_m) OR (fChangeReserve_m <= 0.0) OR (fChangeReserve_m > 50.0) THEN
    bCfgErr := TRUE;                // 余量非法 / Illegal reserve
END_IF
IF (fFedLen_m <> fFedLen_m) OR (fFedLen_m < 0.0) THEN
    bCfgErr := TRUE;                // 累计送料非法 / Illegal fed length
END_IF

// ---- 保养窗冻结（安全侧: 冻结期指令保持断开）/ Maintenance freeze, safe side ----
bMaintHold := bMaintWin;

// ---- 剩余膜长（负差钳零）/ Remaining film length, negative clamped ----
fRemainLen_m := fFilmLen_m - fFedLen_m;
IF fRemainLen_m < 0.0 THEN
    fRemainLen_m := 0.0;            // 负差钳零 / Clamp to zero
END_IF

// ---- 超时堵转锁存与解除 / Timeout stall latch and release ----
IF tonFeed.Q THEN
    bTmoLatch := TRUE;              // 窗内未完成判堵转锁存 / Stall latch
END_IF
IF bStepperReady AND (NOT xFeedAct) THEN
    bTmoLatch := FALSE;             // 就绪恢复且步已收口 → 解除 / Release on ready recovery
END_IF

// ---- 输出缺省（完成脉冲单拍自清）/ Output defaults, done pulse self-clearing ----
bFeedCmd  := FALSE;
bFeedDone := FALSE;

// ---- 启动沿派步（保养冻结/组态错/堵转/驱动故障/膜尽均不派）/ Start dispatch ----
IF rtrStart.Q AND (NOT bMaintHold) AND (NOT bCfgErr) AND (NOT bTmoLatch)
   AND (NOT bStepperFault) AND bStepperReady AND (fRemainLen_m > 0.0) AND (NOT xFeedAct) THEN
    xFeedAct := TRUE;               // 拍 N 进入送料步 / Enter feed step
END_IF

// ---- 送料步执行与收口 / Feed step execution and closing ----
IF xFeedAct THEN
    IF bMaintHold OR bCfgErr OR bStepperFault THEN
        xFeedAct := FALSE;          // 冻结或故障立即收口（安全侧指令断）/ Close on freeze or fault
    ELSE
        bFeedCmd := TRUE;           // 指令输出 / Command on
        IF rtrDone.Q THEN
            bFeedDone := TRUE;      // 单拍完成脉冲 / One-cycle done pulse
            xFeedAct := FALSE;      // 拍 N+1 步收口 / Close step
        ELSIF tonFeed.Q THEN
            xFeedAct := FALSE;      // 超时收口, 锁存已置 / Close on timeout
        END_IF
    END_IF
END_IF

// ---- 膜长耗尽预警（低于换膜余量, 送料继续）/ Film-end warning, feeding continues ----
bWarn := fRemainLen_m < fChangeReserve_m;

// ---- 错误码仲裁 / Error arbitration ----
IF bCfgErr THEN
    eErr := 16#0004_035D;           // 组态非法 / Config fault
ELSIF bTmoLatch THEN
    eErr := 16#0004_035A;           // 堵转锁存回放 / Stall latch replay
ELSIF bStepperFault THEN
    eErr := 16#0004_035B;           // 驱动故障 / Drive fault
ELSIF bWarn THEN
    eErr := 16#0004_035C;           // 耗尽预警 / Film-end warning
ELSE
    eErr := 16#0004_0359;           // 送料正常 / Feeding normal
END_IF

END_FUNCTION_BLOCK

// =====================================================================
// FB_DL_ElectrodeRollDiameter.st
// 极卷直径跟踪与换卷预警（卷径递推 + 低速保护 + 单调校核 + 换卷阈值预警）
// Electrode roll diameter tracking with change-over warning
// 所属子库: DL_Motion    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0004_035E ~ 16#0004_0362 (本件独占 5 槽, 勿复用)
// 溯源: 道莅 clean-room 防御性实现
//       来源组标签: lithium-battery, winding, coil-diameter, warning
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 16)
// 分层声明: 卷径换算公式与 FC_DL_CoilDiameterCalc 口径一致（本件只加跟踪
//           与预警层, 不重写公式件）: D = v·k/(π·n), k = 1000 mm/m
// =====================================================================
FUNCTION_BLOCK FB_DL_ElectrodeRollDiameter
VAR_INPUT
    fLineSpd_mmin : REAL := 0.0;    // 线速度 0~300 m/min / Line speed [m/min]
    fRollRpm      : REAL := 0.0;    // 卷轴转速 0~3000 r/min / Roll speed [r/min]
    fPrevDia_mm   : REAL := 500.0;  // 上次卷径注入 0~2000 mm / Previous diameter injected [mm]
    fCoreDia_mm   : REAL := 76.0;   // 卷芯直径 0~2000 mm / Core diameter [mm]
    fThick_um     : REAL := 25.0;   // 层厚校核值 0~500 um / Layer thickness [um]
    fWarnDia_mm   : REAL := 120.0;  // 换卷预警径 0~2000 mm / Change warning diameter [mm]
END_VAR
VAR_OUTPUT
    fDia_mm     : REAL := 0.0;      // 当前卷径 / Current diameter [mm]
    bChangeWarn : BOOL := FALSE;    // 换卷预警 / Change-over warning
    bAtCore     : BOOL := FALSE;    // 卷径触及芯径 / At core flag
    eErr        : UDINT := 16#0004_035E;  // 错误码 / Error code
END_VAR
VAR
    rPi     : REAL := 3.14159265358979;   // 圆周率 / Pi constant
    fSpdMin : REAL := 1.0;          // 低速门限（线速度）m/min, 工程固定门限 / Min line speed gate
    fRpmMin : REAL := 5.0;          // 低速门限（转速）r/min, 工程固定门限 / Min roll speed gate
    fCalcDia: REAL := 0.0;          // 本拍换算卷径 / Calculated diameter this cycle [mm]
    fTolDia : REAL := 0.0;          // 单调校核容差（双倍层厚换算）/ Monotonic tolerance from thickness [mm]
    bCfgErr : BOOL := FALSE;        // 组态非法标记 / Configuration error flag
    bHoldErr: BOOL := FALSE;        // 递推保持标记（非有限或单调违反）/ Recursion hold flag
    bLowSpd : BOOL := FALSE;        // 低速保护标记 / Low speed protection flag
    xFirst  : BOOL := TRUE;         // 首扫标记 / First-scan flag
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0004_035E 信息 卷径跟踪正常
//   16#0004_035F 故障 组态非法（芯径/预警径非有限或不大于 0, 或芯径不低于
//                预警径倒置）; 解除式 = 恢复合法组态
//   16#0004_0360 故障 递推保持（速度/转速非有限, 或新卷径违反放卷单调递减）,
//                卷径保持上拍值; 解除式 = 输入恢复有限且差分恢复单调
//   16#0004_0361 信息 低速保护冻结（线速或转速低于门限, 卷径保持不递推）
//   16#0004_0362 信息 换卷预警（卷径不大于预警径, 含触及芯径）
// ---------------------------------------------------------------------

// ---- 首扫: 以注入的上次卷径为初始跟踪值 / First scan: seed from injected ----
IF xFirst THEN
    fDia_mm := fPrevDia_mm;     // 初始卷径 / Initial diameter [mm]
    xFirst := FALSE;            // 清首扫标记 / Clear flag
END_IF

// ---- 组态闸 / Configuration gate ----
bCfgErr := FALSE;
IF (fCoreDia_mm <> fCoreDia_mm) OR (fCoreDia_mm <= 0.0) OR (fCoreDia_mm > 2000.0) THEN
    bCfgErr := TRUE;            // 芯径非法 / Illegal core diameter
END_IF
IF (fWarnDia_mm <> fWarnDia_mm) OR (fWarnDia_mm <= 0.0) OR (fWarnDia_mm > 2000.0) THEN
    bCfgErr := TRUE;            // 预警径非法 / Illegal warning diameter
END_IF
IF (NOT bCfgErr) AND (fCoreDia_mm >= fWarnDia_mm) THEN
    bCfgErr := TRUE;            // 芯径不低于预警径 = 倒置 / Inverted config
END_IF

// ---- 输出缺省 / Output defaults ----
bHoldErr := FALSE;
bLowSpd  := FALSE;

IF bCfgErr THEN
    // 组态非法: 卷径保持, 安全侧不递推 / Config fault: hold, no recursion
    eErr := 16#0004_035F;
ELSE
    // ---- 低速保护判 / Low speed protection judge ----
    bLowSpd := (fLineSpd_mmin < fSpdMin) OR (fRollRpm < fRpmMin);
    // ---- 非有限判 / Finite judge ----
    IF (fLineSpd_mmin <> fLineSpd_mmin) OR (ABS(fLineSpd_mmin) >= 1.0E12)
       OR (fRollRpm <> fRollRpm) OR (ABS(fRollRpm) >= 1.0E12)
       OR (fPrevDia_mm <> fPrevDia_mm) THEN
        bHoldErr := TRUE;       // 非有限保持 / Non-finite hold
        eErr := 16#0004_0360;
    ELSIF bLowSpd THEN
        // 低速保护: 冻结递推, 卷径保持 / Freeze recursion on low speed
        eErr := 16#0004_0361;
    ELSE
        // ---- 卷径递推: D = v·k/(π·n), k = 1000 mm/m, 转速门限已保证不为零
        //      Diameter recursion with guarded division ----
        fCalcDia := (fLineSpd_mmin * 1000.0) / (rPi * fRollRpm);
        // 层厚校核容差: 允许的单拍回升量 = 两倍层厚换算 / Monotonic tolerance from thickness
        fTolDia := 2.0 * fThick_um / 1000.0;
        IF fCalcDia > (fDia_mm + fTolDia) THEN
            // 放卷单调递减违反: 保持 + 故障码 / Monotonic violation: hold
            bHoldErr := TRUE;
            eErr := 16#0004_0360;
        ELSE
            fDia_mm := fCalcDia;    // 递推更新 / Update diameter
            // 卷径下限钳卷芯径 / Clamp to core diameter
            IF fDia_mm < fCoreDia_mm THEN
                fDia_mm := fCoreDia_mm;
            END_IF
            eErr := 16#0004_035E;   // 跟踪正常 / Tracking normal
        END_IF
    END_IF
END_IF

// ---- 预警与触芯输出（闭口径: 恰好等于预警径即触发）/ Warning and at-core ----
bChangeWarn := fDia_mm <= fWarnDia_mm;      // 恰好等于预警径与更低均触发 / Trigger at and below
bAtCore := (fDia_mm - fCoreDia_mm) < 1.0E-6;    // 容差判触芯 / At core with tolerance

END_FUNCTION_BLOCK

// =====================================================================
// FB_DL_FanArraySeq.st
// 风机阵列轮值与变频/工频混拖调度（轮值均衡 + 分级投切 + 混拖互斥）
// Fan array duty rotation and VFD/direct staging scheduler
// 所属子库: DL_Algo    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0002_3729 ~ 16#0002_372D (本件独占 5 槽, 勿复用)
// 溯源: 道莅 clean-room 防御性实现
//       来源组标签: hvac, fan-array, duty-rotation, staging
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 17)
// 分层声明: 本件为阵列级编排, 轮值均衡沿用库内轮值件范式、分级投切沿用
//           风机阵列分级件范式, 单台风机本体控制不在本件复现;
//           混拖互斥: 同一台风机同一拍至多处于变频或工频一种模式
// =====================================================================
FUNCTION_BLOCK FB_DL_FanArraySeq
VAR_INPUT
    bEnable    : BOOL  := FALSE;    // 使能 / Enable
    uReqStages : USINT := 2;        // 需求台数 0~6, 越界钳位 / Required stages, clamped
    abFanAvail : ARRAY[1..6] OF BOOL;   // 各台风机可用反馈 / Fan availability
    abVfdEn    : ARRAY[1..6] OF BOOL;   // 各台变频位（真 = 具备变频能力）/ VFD-capable flag
    tMinRun    : TIME  := T#30S;    // 最短运行时间（防振颤与轮值门槛）T#1S~T#60M / Min run time [s]
    bRotateReq : BOOL  := FALSE;    // 轮值请求命令 / Rotation request
END_VAR
VAR_OUTPUT
    abFanRun     : ARRAY[1..6] OF BOOL;   // 各台运行输出 / Fan run outputs
    abFanVfdMode : ARRAY[1..6] OF BOOL;   // 各台变频模式输出 / Fan VFD mode outputs
    uRunCount    : USINT := 0;      // 运行台数 / Running count
    eErr         : UDINT := 16#0002_3729;  // 错误码 / Error code
END_VAR
VAR
    rtrRotate  : R_TRIG;            // 轮值请求沿, 每拍无条件刷新 / Rotate edge, refreshed every cycle
    aTonRun    : ARRAY[1..6] OF TON;    // 各台运行计时, 每拍无条件刷新 / Per-fan run timers, refreshed every cycle
    abRunSel   : ARRAY[1..6] OF BOOL;   // 本拍期望运行集 / Desired run set this cycle
    uLeadIdx   : USINT := 1;       // 轮值起始索引 / Rotation lead index
    uReq       : USINT := 0;       // 钳位后需求台数 / Clamped demand
    uTarget    : USINT := 0;       // 实际目标台数 / Effective target
    uAvailCnt  : USINT := 0;       // 可用台数 / Available count
    uSelCnt    : USINT := 0;       // 已选台数 / Selected count
    uK         : USINT := 0;       // 轮转探测偏移 / Rotation probe offset
    uIdx       : USINT := 1;       // 轮转探测索引 / Rotation probe index
    uNext      : USINT := 1;       // 轮值推进探测索引 / Lead advance probe index
    uProbe     : USINT := 0;       // 轮值推进守卫计数 / Lead advance guard counter
    bClamp     : BOOL := FALSE;     // 需求越界钳位标记 / Demand clamp flag
    bShort     : BOOL := FALSE;     // 需求超可用标记 / Demand exceeds availability flag
    bRotOk     : BOOL := FALSE;     // 轮值允许标记 / Rotation allowed flag
    bStarted   : BOOL := FALSE;     // 本拍已投一台标记 / Started one this cycle flag
    bStopped   : BOOL := FALSE;     // 本拍已停一台标记 / Stopped one this cycle flag
    uZi        : INT   := 1;       // 1..6 数组下标 / Array subscript 1..6
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0002_3729 信息 阵列调度正常
//   16#0002_372A 信息 需求台数越界钳位（大于 6 已钳到 6）
//   16#0002_372B 信息 需求超可用（只投可用台数, 缺口提示）
//   16#0002_372C 信息 轮值等待（存在未达最短运行时间的运行台, 轮值请求挂起）
//   16#0002_372D 信息 待机未使能（全停安全侧）
// ---------------------------------------------------------------------

// ---- 需求钳位 / Demand clamp ----
bClamp := FALSE;
uReq := uReqStages;
IF uReqStages > 6 THEN
    uReq := 6;                      // 上界钳位 / Clamp upper
    bClamp := TRUE;                 // 置钳位信息 / Set clamp info
END_IF

// ---- 可用台数 / Available count ----
uAvailCnt := 0;
FOR uZi := 1 TO 6 DO
    IF abFanAvail[uZi] THEN
        uAvailCnt := uAvailCnt + 1;
    END_IF
END_FOR

// ---- 目标台数（不超可用, 台数 0 → 全停安全侧）/ Effective target ----
uTarget := uReq;
IF uTarget > uAvailCnt THEN
    uTarget := uAvailCnt;           // 只投可用数 / Only available count
    bShort := TRUE;                 // 置缺口信息 / Set shortfall info
END_IF

// ---- 轮值沿与运行计时实例无条件周期刷新 / Unconditional edge and timer refresh ----
rtrRotate(CLK := bRotateReq);
FOR uZi := 1 TO 6 DO
    aTonRun[uZi](IN := abFanRun[uZi], PT := tMinRun);   // 运行计时 / Run timing
END_FOR

// ---- 未使能全停（安全侧）/ All stop when disabled ----
IF NOT bEnable THEN
    FOR uZi := 1 TO 6 DO
        abFanRun[uZi] := FALSE;     // 全停 / All stop
    END_FOR
END_IF

// ---- 轮值允许判: 全部运行台已达最短运行时间 / Rotation allowed judge ----
bRotOk := TRUE;
FOR uZi := 1 TO 6 DO
    IF abFanRun[uZi] AND (NOT aTonRun[uZi].Q) THEN
        bRotOk := FALSE;            // 存在未达门槛的运行台 / Some fan below min run
    END_IF
END_FOR

// ---- 轮值推进: 全部运行台达门槛时沿探测推进起始索引（守卫计数防死循环）
//      Lead advance on rotation request ----
IF rtrRotate.Q AND bEnable AND bRotOk THEN
    uNext := uLeadIdx;              // 自当前起始索引探测 / Probe from lead
    uProbe := 0;
    WHILE uProbe < 6 DO
        uNext := uNext + 1;
        IF uNext > 6 THEN
            uNext := 1;             // 回绕 / Wrap
        END_IF
        uProbe := uProbe + 1;
        IF abFanAvail[uNext] THEN
            uLeadIdx := uNext;      // 推进起始索引 / Advance lead
            uProbe := 6;            // 提前退出 / Early exit
        END_IF
    END_WHILE
END_IF

// ---- 分级投切选择: 变频台优先, 轮值序探测, 工频补位 / Staging selection ----
FOR uZi := 1 TO 6 DO
    abRunSel[uZi] := FALSE;         // 期望集清空 / Clear desired set
END_FOR
uSelCnt := 0;
IF bEnable AND (uTarget > 0) THEN
    // 第一遍: 沿轮值序选变频台 / Pass 1: VFD-capable fans in rotation order
    uK := 0;
    WHILE (uK < 6) AND (uSelCnt < uTarget) DO
        uIdx := uLeadIdx + uK;
        IF uIdx > 6 THEN
            uIdx := uIdx - 6;       // 条件回绕, 不用取余 / Conditional wrap
        END_IF
        uK := uK + 1;
        IF abFanAvail[uIdx] AND abVfdEn[uIdx] AND (NOT abRunSel[uIdx]) THEN
            abRunSel[uIdx] := TRUE;
            uSelCnt := uSelCnt + 1;
        END_IF
    END_WHILE
    // 第二遍: 沿轮值序用工频台补位 / Pass 2: direct-on-line fans fill
    uK := 0;
    WHILE (uK < 6) AND (uSelCnt < uTarget) DO
        uIdx := uLeadIdx + uK;
        IF uIdx > 6 THEN
            uIdx := uIdx - 6;
        END_IF
        uK := uK + 1;
        IF abFanAvail[uIdx] AND (NOT abRunSel[uIdx]) THEN
            abRunSel[uIdx] := TRUE;
            uSelCnt := uSelCnt + 1;
        END_IF
    END_WHILE
END_IF

// ---- 分级投切执行: 同拍至多投一台、停一台（防振颤, 未达门槛不停机）
//      Staged apply: at most one start and one stop per cycle ----
bStarted := FALSE;
bStopped := FALSE;
FOR uZi := 1 TO 6 DO
    IF abRunSel[uZi] AND (NOT abFanRun[uZi]) AND (NOT bStarted) THEN
        abFanRun[uZi] := TRUE;      // 投入一台 / Start one
        bStarted := TRUE;
    END_IF
END_FOR
FOR uZi := 1 TO 6 DO
    IF (NOT abRunSel[uZi]) AND abFanRun[uZi] AND aTonRun[uZi].Q AND (NOT bStopped) THEN
        abFanRun[uZi] := FALSE;     // 停运一台（已达最短运行时间才停）/ Stop one eligible
        bStopped := TRUE;
    END_IF
END_FOR

// ---- 混拖模式输出（一台一拍至多一种模式）/ Mode outputs, one mode per fan ----
FOR uZi := 1 TO 6 DO
    abFanVfdMode[uZi] := abFanRun[uZi] AND abVfdEn[uZi];
END_FOR

// ---- 运行台数 / Running count ----
uRunCount := 0;
FOR uZi := 1 TO 6 DO
    IF abFanRun[uZi] THEN
        uRunCount := uRunCount + 1;
    END_IF
END_FOR

// ---- 错误码仲裁 / Error arbitration ----
IF NOT bEnable THEN
    eErr := 16#0002_372D;           // 待机全停 / Standby all stop
ELSIF bClamp THEN
    eErr := 16#0002_372A;           // 需求钳位 / Demand clamped
ELSIF bShort THEN
    eErr := 16#0002_372B;           // 需求超可用 / Short of availability
ELSIF bRotateReq AND (NOT bRotOk) THEN
    eErr := 16#0002_372C;           // 轮值等待 / Rotation pending
ELSE
    eErr := 16#0002_3729;           // 调度正常 / Normal
END_IF

END_FUNCTION_BLOCK

// =====================================================================
// FB_DL_ChwDifferentialPressure.st
// 冷冻水差压旁通控制（压差平滑 + 设定值重置限速 + PID 指令注入 + 阀位限幅）
// CHW differential pressure bypass control with smoothing and valve clamp
// 所属子库: DL_Algo    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0002_372E ~ 16#0002_3732 (本件独占 5 槽, 勿复用)
// 溯源: 道莅 clean-room 防御性实现
//       来源组标签: hvac, chw, differential-pressure, pid
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 18)
// 分层声明: 压差平滑组合消费 DL_MathData 的 FB_DL_MovingAverage 实例;
//           设定值重置限速组合消费 DL_Algo 的 FB_DL_RateLimiter 实例
//           （斜坡防水锤）; PID 闭环本身不内联, 控制件阀位指令输出经引脚注入
// =====================================================================
FUNCTION_BLOCK FB_DL_ChwDifferentialPressure
VAR_INPUT
    bEnable        : BOOL  := FALSE;   // 使能 / Enable
    fDp_kPa        : REAL  := 0.0;     // 供回水压差 0~400 kPa / Supply-return dP [kPa]
    fDpSet_kPa     : REAL  := 120.0;   // 压差设定值 0~400 kPa / dP setpoint [kPa]
    fPidOut_Pct    : REAL  := 0.0;     // PID 阀位指令注入（控制件 fOut 语义）/ PID valve command injected [pct]
    fValveMin_Pct  : REAL  := 0.0;     // 阀位下限 0~100 百分比 / Valve lower limit [pct]
    fValveMax_Pct  : REAL  := 100.0;   // 阀位上限 0~100 百分比 / Valve upper limit [pct]
    fResetRate_kPa_s: REAL := 5.0;     // 设定值重置限速 0~100 kPa/s, 0 = 不限 / Setpoint reset rate [kPa/s]
END_VAR
VAR_OUTPUT
    fValveOut_Pct  : REAL  := 0.0;    // 旁通阀位输出 / Bypass valve output [pct]
    fDpSmooth_kPa  : REAL  := 0.0;    // 平滑后压差 / Smoothed dP [kPa]
    bByPassActive  : BOOL  := FALSE;  // 旁通投入标志 / Bypass active flag
    eErr           : UDINT := 16#0002_372E;  // 错误码 / Error code
END_VAR
VAR
    movAvg      : FB_DL_MovingAverage;  // 压差平滑实例（组合消费）/ Smoothing instance, composed
    ratSet      : FB_DL_RateLimiter;    // 设定值限速实例（组合消费）/ Setpoint rate limiter instance
    bCfgErr     : BOOL  := FALSE;   // 组态非法标记 / Configuration error flag
    bInFErr     : BOOL  := FALSE;   // 输入非有限标记 / Input non-finite flag
    bSatInfo    : BOOL  := FALSE;   // 阀位限幅饱和信息标记 / Valve saturation info flag
    fValveHold  : REAL  := 0.0;     // 阀位保持量（非有限拍保持）/ Valve hold value [pct]
    fValveCmd   : REAL  := 0.0;     // 阀位指令临时量 / Valve command temporary [pct]
    fSetUse     : REAL  := 0.0;     // 限速后设定值（诊断保持）/ Rate-limited setpoint [kPa]
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0002_372E 信息 旁通控制正常
//   16#0002_372F 故障 输入非有限（压差或 PID 指令注入非有限, 阀位保持上拍值,
//                不新增动作）; 解除式 = 输入恢复有限
//   16#0002_3730 故障 组态非法（设定值越出 0~400 kPa, 阀限幅越域或倒置,
//                重置速率越出 0~100 kPa/s）; 解除式 = 恢复合法组态
//   16#0002_3731 信息 阀位限幅饱和（PID 指令越出阀限幅, 已钳位输出）
//   16#0002_3732 信息 待机未使能（阀位回下限, 旁通关闭安全侧）
// ---------------------------------------------------------------------

// ---- 组态闸 / Configuration gate ----
bCfgErr := FALSE;
IF (fDpSet_kPa <> fDpSet_kPa) OR (fDpSet_kPa < 0.0) OR (fDpSet_kPa > 400.0) THEN
    bCfgErr := TRUE;                // 设定值越域 / Setpoint out of domain
END_IF
IF (fValveMin_Pct <> fValveMin_Pct) OR (fValveMin_Pct < 0.0) OR (fValveMin_Pct > 100.0) THEN
    bCfgErr := TRUE;                // 下限越域 / Lower limit out of domain
END_IF
IF (fValveMax_Pct <> fValveMax_Pct) OR (fValveMax_Pct < 0.0) OR (fValveMax_Pct > 100.0) THEN
    bCfgErr := TRUE;                // 上限越域 / Upper limit out of domain
END_IF
IF (NOT bCfgErr) AND (fValveMin_Pct >= fValveMax_Pct) THEN
    bCfgErr := TRUE;                // 阀限幅倒置 / Inverted valve limits
END_IF
IF (fResetRate_kPa_s <> fResetRate_kPa_s) OR (fResetRate_kPa_s < 0.0) OR (fResetRate_kPa_s > 100.0) THEN
    bCfgErr := TRUE;                // 重置速率越域 / Reset rate out of domain
END_IF

// ---- 输入非有限判 / Input finite judge ----
bInFErr := (fDp_kPa <> fDp_kPa) OR (ABS(fDp_kPa) >= 1.0E12)
        OR (fPidOut_Pct <> fPidOut_Pct) OR (ABS(fPidOut_Pct) >= 1.0E12);

// ---- 压差平滑消费（组合实例调用）/ Smoothing via composed instance ----
movAvg(fInput := fDp_kPa, nWindowSize := 8,
       bSample := bEnable AND (NOT bInFErr) AND (NOT bCfgErr),
       bEnable := bEnable, bReset := FALSE);
fDpSmooth_kPa := movAvg.fAverage;   // 平滑压差输出 / Smoothed dP output

// ---- 设定值重置限速消费（组合实例调用, 斜坡防水锤）/ Setpoint rate limit ----
ratSet(bEnable := bEnable AND (NOT bCfgErr), fIn := fDpSet_kPa,
       fRateUp := fResetRate_kPa_s, fRateDown := fResetRate_kPa_s,
       bTrack := (NOT bEnable), fTrackValue := fDpSet_kPa,
       tSampleTime := T#100MS);
fSetUse := ratSet.fOut;             // 限速后设定值保持（供上位诊断）/ Held setpoint for diagnostics

// ---- 待机安全侧: 阀位回下限（旁通关闭）/ Standby: valve to lower limit ----
IF NOT bEnable THEN
    fValveOut_Pct := fValveMin_Pct; // 关闭旁通 / Close bypass
    fValveHold := fValveMin_Pct;    // 保持量同步 / Sync hold
    bByPassActive := FALSE;         // 旁通退出 / Bypass off
    eErr := 16#0002_3732;           // 待机码 / Standby code
ELSIF bInFErr OR bCfgErr THEN
    // 非有限或组态非法: 阀位保持上拍值, 不新增动作 / Hold valve, no new action
    fValveOut_Pct := fValveHold;
    bByPassActive := FALSE;
    IF bCfgErr THEN
        eErr := 16#0002_3730;       // 组态码 / Config code
    ELSE
        eErr := 16#0002_372F;       // 非有限码 / Non-finite code
    END_IF
ELSE
    // ---- 阀位指令限幅输出 / Valve command with clamping ----
    fValveCmd := fPidOut_Pct;       // PID 指令注入 / Injected PID command
    bSatInfo := FALSE;
    IF fValveCmd > fValveMax_Pct THEN
        fValveCmd := fValveMax_Pct; // 上限钳位 / Clamp upper
        bSatInfo := TRUE;           // 置饱和信息 / Set saturation info
    END_IF
    IF fValveCmd < fValveMin_Pct THEN
        fValveCmd := fValveMin_Pct; // 下限钳位 / Clamp lower
        bSatInfo := TRUE;
    END_IF
    fValveOut_Pct := fValveCmd;     // 阀位输出 / Valve output
    fValveHold := fValveCmd;        // 更新保持量 / Update hold
    // 旁通投入判（容差比较, 浮点禁直接判等）/ Bypass active with margin
    bByPassActive := (fValveOut_Pct - fValveMin_Pct) > 0.1;
    IF bSatInfo THEN
        eErr := 16#0002_3731;       // 饱和信息 / Saturation info
    ELSE
        eErr := 16#0002_372E;       // 正常 / Normal
    END_IF
END_IF

END_FUNCTION_BLOCK

// =====================================================================
// FC_DL_ChecksumSum64.st
// LWORD 数组 64 位累加和校验（纯函数, 模 2^64 自然回绕求和 + 越界守卫）
// 64-bit LWORD array additive checksum, pure function
// 所属子库: DL_MathData    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0001_048A ~ 16#0001_048D (本件独占 4 槽, FC 纯函数分型, 勿复用)
// 溯源: IEC 61131-3 标准语义的道莅防御性实现
//       来源组标签: checksum, data-integrity, pure-function, lword
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 19)
// 语义声明: 模 2^64 累加和由 LWORD 无符号加法自然回绕实现, 禁用取余运算;
//           与 FC_DL_ChecksumSum8 构成 8/64 位宽两件, 位宽变体不再扩充;
//           错误出口约定与 FC_DL_ChecksumSum8 现行 uErrorId 出口一致;
//           纯函数无内部状态, 码为返回拍瞬时值, 无锁存面
// =====================================================================
FUNCTION FC_DL_ChecksumSum64 : LWORD   // 返回累加和, 异常路径返回哨兵零值 / Returns sum, sentinel zero on fault
VAR_INPUT
    aData  : ARRAY[*] OF LWORD;     // 被校验数组（开数组, 实测边界）/ Data array, open bounds
    uCount : USINT;                 // 参与求和的元素个数 1~255 / Element count
END_VAR
VAR_OUTPUT
    uErrorId : UDINT;               // 错误码, 见码表 / Error code, see table
END_VAR
VAR
    uCap   : DINT := 0;             // 数组实测元素容量 / Measured array capacity
    uNum   : DINT := 0;             // 钳位后的求和个数 / Effective count
    iIdx   : DINT := 0;             // 循环下标 / Loop index
    iElem  : DINT := 0;             // 数组元素下标 / Element index
    lwSum  : LWORD := LWORD#0;      // 累加和 / Accumulated sum
    lwPrev : LWORD := LWORD#0;      // 上拍和快照（回绕检测）/ Previous sum for wrap detect
    xWrap  : BOOL := FALSE;         // 自然回绕发生标记 / Wraparound occurred flag
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0001_048A 信息 累加和计算完成（含自然回绕路径）
//   16#0001_048B 信息 空输入（计数为 0, 返回哨兵零值）
//   16#0001_048C 故障 计数越界（大于数组实测容量, 强制退出, 返回零值）,
//                纯函数无锁存面, 修正入参重新调用即解除
//   16#0001_048D 信息 求和自然回绕发生（本拍回绕旁证, 供数据链路诊断）
// ---------------------------------------------------------------------

// ---- 缺省返回哨兵零值 / Default sentinel zero ----
FC_DL_ChecksumSum64 := LWORD#0;

// ---- 容量实测（开数组边界实测, 不假设下标起点）/ Measured capacity ----
IF UPPER_BOUND(aData, 1) >= LOWER_BOUND(aData, 1) THEN
    uCap := (UPPER_BOUND(aData, 1) - LOWER_BOUND(aData, 1)) + 1;    // 元素个数 / Element count
END_IF

// ---- 空输入: 计数为 0, 返回哨兵零 + 信息码 / Empty input ----
IF uCount = 0 THEN
    uErrorId := 16#0001_048B;       // 空输入码 / Empty input code
    RETURN;                         // 返回零值 / Return zero
END_IF

// ---- 计数越界守护: 强制退出 / Count overrun guard: force exit ----
uNum := USINT_TO_DINT(uCount);
IF uNum > uCap THEN
    uErrorId := 16#0001_048C;       // 越界故障码 / Overrun fault code
    RETURN;                         // 强制退出返回零 / Force exit with zero
END_IF

// ---- 模 2^64 累加（LWORD 自然回绕, 禁用取余）/ Modulo sum by natural wrap ----
lwSum := LWORD#0;                   // 和清零 / Clear sum
xWrap := FALSE;                     // 回绕标记复位 / Reset wrap flag
FOR iIdx := 1 TO uNum DO
    iElem := LOWER_BOUND(aData, 1) + (iIdx - 1);    // 实测下标映射 / Measured index mapping
    lwPrev := lwSum;                // 上拍和快照 / Snapshot previous sum
    lwSum := lwSum + aData[iElem];  // 累加（无符号自然回绕）/ Accumulate with natural wrap
    IF lwSum < lwPrev THEN
        xWrap := TRUE;              // 无符号回绕旁证 / Unsigned wrap occurred
    END_IF
END_FOR

FC_DL_ChecksumSum64 := lwSum;       // 返回累加和 / Return sum
IF xWrap THEN
    uErrorId := 16#0001_048D;       // 回绕旁证码 / Wrap hint code
ELSE
    uErrorId := 16#0001_048A;       // 完成码 / Done code
END_IF

END_FUNCTION

// =====================================================================
// FC_DL_BitArraySegCopy.st
// 位段数组多段一次搬（源到目标多段批量复制, 逐段域校验 + 整段原子性）
// Multi-segment batch bit-array copy with per-segment domain validation
// 所属子库: DL_Base    版本: v1.0.0    兼容: CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop
// 码位: 16#0001_048E ~ 16#0001_0491 (本件独占 4 槽, FC 纯函数分型, 勿复用)
// 溯源: IEC 61131-3 标准语义的道莅防御性实现
//       来源组标签: bit-field, array-copy, batch-transfer, lgf-bitlogic
// 修改记录: R30 初版 (ROUND_PLAN_R30 序 20)
// 语义声明: 一次调用搬 N 段; 逐段域校验（起位 + 长度不超过数组位容量）
//           先整体校验后统一搬移, 任一段非法则零段搬移并回放段号;
//           跨字窗口逐位读改写沿用 Extract/Insert 范式（移位量以取余 32
//           归一, 全程仅 32 位移位, 无 64 位移位）; 段表内重叠段不做去重,
//           后段覆盖前段; 与 FC_DL_BitArrayExtract/Insert 逐段对拍位守恒
// =====================================================================
FUNCTION FC_DL_BitArraySegCopy : BOOL   // 返回真 = 全部段搬移完成 / TRUE when all segments copied
VAR_IN_OUT
    aSrc   : ARRAY[*] OF DWORD;     // 源位数组（开数组, 实测边界）/ Source bit array
    aDst   : ARRAY[*] OF DWORD;     // 目标位数组（开数组, 实测边界）/ Destination bit array
END_VAR
VAR_INPUT
    aSrcBit   : ARRAY[*] OF UINT;   // 各段源起始位号 0 起 / Per-segment source start bit
    aDstBit   : ARRAY[*] OF UINT;   // 各段目标起始位号 0 起 / Per-segment destination start bit
    aLen      : ARRAY[*] OF USINT;  // 各段长度（位）1~255 / Per-segment length in bits
    uSegCount : USINT;              // 段数 / Segment count
END_VAR
VAR_OUTPUT
    uErrorId : UDINT;               // 错误码, 见码表 / Error code, see table
    uFailSeg : USINT;               // 非法段号回放 1~N, 0 = 无 / Failed segment replay, 0 = none
END_VAR
VAR
    uSrcCap  : DINT := 0;           // 源数组实测位容量 / Source capacity in bits
    uDstCap  : DINT := 0;           // 目标数组实测位容量 / Destination capacity in bits
    uTabCap1 : DINT := 0;           // 段表 1 实测容量 / Segment table 1 capacity
    uTabCap2 : DINT := 0;           // 段表 2 实测容量 / Segment table 2 capacity
    uTabCap3 : DINT := 0;           // 段表 3 实测容量 / Segment table 3 capacity
    uTabCap  : DINT := 0;           // 段表最小容量 / Minimum table capacity
    uSegUse  : DINT := 0;           // 实际处理段数（钳位后）/ Effective segment count
    iS       : DINT := 0;           // 段循环下标 / Segment loop index
    iJ       : DINT := 0;           // 位循环下标 / Bit loop index
    iSIdx    : DINT := 0;           // 段表元素下标 / Segment table element index
    uSrcPos  : DINT := 0;           // 当前源位号 / Current source bit position
    uDstPos  : DINT := 0;           // 当前目标位号 / Current destination bit position
    iW       : DINT := 0;           // 字下标 / Word index
    dwMask   : DWORD := DWORD#0;    // 位掩码 / Bit mask
    dwWord   : DWORD := DWORD#0;    // 目标字读改写临时量 / Destination word read-modify-write temp
    xBit     : BOOL := FALSE;       // 当前位值 / Current bit value
    uSegLen  : DINT := 0;           // 当前段长度 / Current segment length
END_VAR

// ---------------------------------------------------------------------
// 代码位表（本件独占, 勿复用）:
//   16#0001_048E 信息 批量搬移完成（含段表重叠时后段覆盖前段语义）
//   16#0001_048F 信息 空段表（段数为 0, 零搬移成功返回）
//   16#0001_0490 故障 段域非法（起位 + 长度超过数组位容量, 段号经 uFailSeg
//                回放, 零段搬移原子回退）; 纯函数无锁存面, 修正段表重新调用即解除
//   16#0001_0491 信息 段计数越界钳位（段数大于段表实测容量, 已按容量截断处理）
// ---------------------------------------------------------------------

// ---- 缺省收口 / Defaults ----
FC_DL_BitArraySegCopy := FALSE;     // 缺省失败 / Default fail
uErrorId := 16#0001_048E;           // 缺省完成码, 异常路径覆盖 / Default done code
uFailSeg := 0;                      // 段号清零 / Clear segment number

// ---- 容量实测（开数组边界实测, 不假设下标起点）/ Measured capacities ----
uSrcCap := 32 * ((UPPER_BOUND(aSrc, 1) - LOWER_BOUND(aSrc, 1)) + 1);    // 源位容量 / Source bits
uDstCap := 32 * ((UPPER_BOUND(aDst, 1) - LOWER_BOUND(aDst, 1)) + 1);    // 目标位容量 / Destination bits
uTabCap1 := (UPPER_BOUND(aSrcBit, 1) - LOWER_BOUND(aSrcBit, 1)) + 1;
uTabCap2 := (UPPER_BOUND(aDstBit, 1) - LOWER_BOUND(aDstBit, 1)) + 1;
uTabCap3 := (UPPER_BOUND(aLen, 1) - LOWER_BOUND(aLen, 1)) + 1;
// 取三段表最小容量 / Minimum of the three table capacities
uTabCap := uTabCap1;
IF uTabCap2 < uTabCap THEN
    uTabCap := uTabCap2;
END_IF
IF uTabCap3 < uTabCap THEN
    uTabCap := uTabCap3;
END_IF

// ---- 空段表: 零搬移成功返回 / Empty segment table ----
IF uSegCount = 0 THEN
    uErrorId := 16#0001_048F;       // 空段表码 / Empty table code
    FC_DL_BitArraySegCopy := TRUE;  // 零搬移成功 / Zero-copy success
    RETURN;
END_IF

// ---- 段计数钳位（信息级, 按段表容量截断）/ Segment count clamp ----
uSegUse := USINT_TO_DINT(uSegCount);
IF uSegUse > uTabCap THEN
    uSegUse := uTabCap;             // 截断处理 / Truncate
    uErrorId := 16#0001_0491;       // 钳位信息码 / Clamp info code
END_IF

// ---- 整体校验: 逐段域校验, 任一非法即零段搬移退出（整段原子性）
//      Whole validation first, any invalid segment aborts with zero moved ----
FOR iS := 1 TO uSegUse DO
    iSIdx := LOWER_BOUND(aSrcBit, 1) + (iS - 1);    // 段表下标映射 / Table index mapping
    uSrcPos := UINT_TO_DINT(aSrcBit[iSIdx]);
    uSegLen := USINT_TO_DINT(aLen[iSIdx]);
    IF (uSrcPos + uSegLen) > uSrcCap THEN
        uErrorId := 16#0001_0490;   // 段域非法码 / Illegal segment domain
        uFailSeg := DINT_TO_USINT(iS);  // 回放段号 / Replay segment number
        RETURN;                     // 零段搬移退出 / Abort with zero moved
    END_IF
    uDstPos := UINT_TO_DINT(aDstBit[iSIdx]);
    IF (uDstPos + uSegLen) > uDstCap THEN
        uErrorId := 16#0001_0490;   // 段域非法码 / Illegal segment domain
        uFailSeg := DINT_TO_USINT(iS);
        RETURN;                     // 零段搬移退出 / Abort
    END_IF
END_FOR

// ---- 统一搬移: 逐段逐位读改写（后段覆盖前段, 不去重）/ Unified copy ----
FOR iS := 1 TO uSegUse DO
    iSIdx := LOWER_BOUND(aSrcBit, 1) + (iS - 1);
    uSegLen := USINT_TO_DINT(aLen[iSIdx]);
    uSrcPos := UINT_TO_DINT(aSrcBit[iSIdx]);    // 源位号复位 / Reset source position
    uDstPos := UINT_TO_DINT(aDstBit[iSIdx]);    // 目标位号复位 / Reset destination position
    FOR iJ := 1 TO uSegLen DO
        // 读源位（跨字窗口, 移位量取余 32 归一, 小于 32 位宽合规）
        // Read source bit across word boundary, shift normalized mod 32
        iW := LOWER_BOUND(aSrc, 1) + (uSrcPos / 32);
        dwMask := SHL(DWORD#1, uSrcPos MOD 32);
        xBit := (aSrc[iW] AND dwMask) <> DWORD#0;
        // 写目标位（读改写保持其余位）/ Write destination bit with read-modify-write
        iW := LOWER_BOUND(aDst, 1) + (uDstPos / 32);
        dwWord := aDst[iW];
        dwMask := SHL(DWORD#1, uDstPos MOD 32);
        IF xBit THEN
            dwWord := dwWord OR dwMask;             // 置位 / Set bit
        ELSE
            dwWord := dwWord AND (NOT dwMask);      // 清位 / Clear bit
        END_IF
        aDst[iW] := dwWord;                         // 回写字 / Write back
        uSrcPos := uSrcPos + 1;                     // 源位推进 / Advance source
        uDstPos := uDstPos + 1;                     // 目标位推进 / Advance destination
    END_FOR
END_FOR

FC_DL_BitArraySegCopy := TRUE;      // 全部段完成 / All segments done

END_FUNCTION

(*
  组件名 Component   : FB_DL_CircInterp2Axis
  子库 Sublibrary    : DL_Motion
  版本 Version       : 1.0.0
  兼容性 Platform    : CODESYS 3.5 / TwinCAT 3 / 汇川 InoProShop / Machine Expert（仅 Standard.library）
  功能 Function      : 两轴圆弧插补（与 FB_DL_LineInterp2Axis 同线直角补口）：
                       1) 双模式几何解算：圆心模式（半径由起点到圆心距实测，终点距圆心
                       超容差判组态非法）/ 半径模式（由起终点弦长与半径反解圆心，CW/CCW
                       定唯一解，弦长 > 2R 判组态非法）；
                       2) 弓高误差弦长分段：每拍角步长 = 进给/半径 与 弦长上限角步长
                       取小（弦长上限由弓高误差限反解，半径/进给除法前置域闸）；
                       3) 象限跨越判据：本拍与上拍象限号不同 → bQuadCross 单拍脉冲；
                       4) 终点判定：剩余弧角 <= 步长 → 落终点，eDone 驻留。
  边界 Boundary      : ① 本件只出两轴位置设定点，不接管轴使能与物理 IO；
                       ② 角度归一化循环带守卫计数器（上限 8 次，超限判几何非法）；
                       ③ 反三角经 FC_DL_Atan2Ex 唯一属主（DL_MathData），本件零重写；
                       ④ 非有限值（NaN 自反 + 无穷差值自减）判非法锁存，出点冻结；
                       ⑤ 故障锁存解除唯一路径 = bReset 上升沿（输入引脚，恒可达）；
                       ⑥ 无全局变量引用、无外部变量声明、无物理地址寻址。
  依赖 Depends       : FC_DL_Atan2Ex（DL_MathData，按 registry 实名）；Standard.library（R_TRIG）
  溯源 Origin        : 道莅自研 clean-room（参考 t1-8-github motion 线分类与参数域，
                       零代码行复制；圆弧参数化与弓高分段为公开几何语义）
  码位 Code          : 16#04_0_AC
  码表 Error codes（Motion 格 04_0_AC，单轨：故障 0x02AC / 信息 0x01AC）:
    16#0004_02AC 故障级：几何解算非法（弦长 > 2R / 终点半径超容差 / 进给或弓高限
                 非法 / 输入非有限 / 归一化守卫超限），锁存至 bReset 上升沿
    16#0004_01AC 信息级：象限跨越脉冲沿（bQuadCross 置位拍）
  修订历史 Revision  :
    2026-11-19  v1.0.0  R44 首版（批次 2 · 序号 9）
*)

TYPE E_DL_CiaState :
(
    eIdle   := 0,   // 空闲：等启动沿 / Idle, waiting start edge
    eGeom   := 10,  // 几何：单拍解算圆心/半径/弧角 / Geometry, one-pass solve
    eRun    := 20,  // 插补：逐拍步进出点 / Interpolating, per-scan stepping
    eDone   := 30,  // 完成：落终点驻留 / Done, at end point
    eFault  := 90   // 故障：几何/输入锁存 / Fault, latched
);
END_TYPE

FUNCTION_BLOCK FB_DL_CircInterp2Axis
VAR_INPUT
    bStartCmd    : BOOL;                   // 启动指令（上升沿承载）[-] / Start command edge
    bReset       : BOOL;                   // 上升沿清故障锁存 [-] / Reset edge
    fStartXMm    : REAL;                   // 起点坐标 X [mm] / Start point X
    fStartYMm    : REAL;                   // 起点坐标 Y [mm] / Start point Y
    fEndXMm      : REAL;                   // 终点坐标 X [mm] / End point X
    fEndYMm      : REAL;                   // 终点坐标 Y [mm] / End point Y
    bUseRadius   : BOOL;                   // 模式：TRUE = 半径模式 / Mode, TRUE = radius mode
    fCenterXMm   : REAL;                   // 圆心坐标 X（圆心模式）[mm] / Center X
    fCenterYMm   : REAL;                   // 圆心坐标 Y（圆心模式）[mm] / Center Y
    fRadiusMm    : REAL;                   // 半径（半径模式）[mm] / Radius
    bCwDir       : BOOL;                   // 方向：TRUE = 顺时针 [-] / Direction, TRUE = CW
    fFeedMmS     : REAL := 50.0;           // 合成进给速度 [mm/s] / Feed velocity
    fSagittaMaxMm: REAL := 0.01;           // 弓高误差限 [mm] / Sagitta error limit
    fRadTolMm    : REAL := 0.01;           // 终点半径容差 [mm] / End radius tolerance
    tCycle       : TIME := T#10MS;         // 扫描周期 [毫秒] / Scan cycle time
END_VAR
VAR_OUTPUT
    fPosXMm      : REAL;                   // 位置设定点 X [mm] / Position setpoint X
    fPosYMm      : REAL;                   // 位置设定点 Y [mm] / Position setpoint Y
    bBusy        : BOOL;                   // 插补进行中电平 [-] / Interpolation busy
    bDone        : BOOL;                   // 到达终点电平 [-] / End-point reached level
    bQuadCross   : BOOL;                   // 象限跨越单拍脉冲 [-] / Quadrant crossing pulse
    fArcLenMm    : REAL;                   // 解算弧长 [mm] / Computed arc length
    eState       : E_DL_CiaState;          // 状态出口，段尾单点映射 / State outlet
    bError       : BOOL;                   // 故障锁存标志 [-] / Fault latch flag
    uErrId       : UDINT;                  // 事件码，0 = 无事件 / Event code
END_VAR
VAR
    rtReset : R_TRIG;                      // 复位沿实例，段 0 无条件刷新 / Reset edge
    rtStart : R_TRIG;                      // 启动沿实例，段 0 无条件刷新 / Start edge
    _eState : E_DL_CiaState := E_DL_CiaState.eIdle;    // 内部相位（CASE 唯一写入目标）/ Internal phase
    _fCtrXMm: REAL;                        // 解算圆心 X [mm] / Solved center X
    _fCtrYMm: REAL;                        // 解算圆心 Y [mm] / Solved center Y
    _fRadMm : REAL;                        // 解算半径 [mm] / Solved radius
    _fAng0  : REAL;                        // 起点角 [弧度] / Start angle
    _fAng1  : REAL;                        // 终点角 [弧度] / End angle
    _fSweep : REAL;                        // 弧角绝对扫角 [弧度] / Absolute sweep
    _fAngCur: REAL;                        // 当前角 [弧度] / Current angle
    _fDAng  : REAL;                        // 每拍角步长 [弧度] / Angular step per scan
    _nQuadPrev: DINT;                      // 上拍象限号 [-] / Previous quadrant
    _nQuadCur : DINT;                      // 本拍象限号 [-] / Current quadrant
    _bFault : BOOL;                        // 故障锁存位（锁存量） / Latched fault bit
    _uFault : UDINT;                       // 故障码锁存（锁存量） / Latched fault code
    _bCfgBad: BOOL;                        // 组态非法当拍量 [-] / Config illegal flag
    _bNonFin: BOOL;                        // 输入非有限当拍量 [-] / Non-finite input flag
    _bValid : BOOL;                        // Atan2Ex 属主返回有效标志（两调用与集） / Atan2 validity flag
    _bVal0  : BOOL;                        // 起点角属主有效标志 [-] / Start angle validity
    _bVal1  : BOOL;                        // 终点角属主有效标志 [-] / End angle validity
    fDxGeom : LREAL;                       // 几何解算弦向量 X [mm] / Geometry chord vector X
    fDyGeom : LREAL;                       // 几何解算弦向量 Y [mm] / Geometry chord vector Y
    fChordGeom : LREAL;                    // 几何解算弦长 [mm] / Geometry chord length
    fHGeom  : LREAL;                       // 圆心偏距 [mm] / Center offset distance
    fAng0Geom : LREAL;                     // 起点角属主返回值 [弧度] / Start angle owner result
    fAng1Geom : LREAL;                     // 终点角属主返回值 [弧度] / End angle owner result
    fSweepGeom: LREAL;                     // 扫角归一化中间量 [弧度] / Sweep normalization temp
    _nNormGuard: DINT;                     // 归一化守卫计数 [次] / Normalization guard counter
    fStepFeed : LREAL;                     // 进给角步长 [弧度] / Feed angular step
    fChordMax : LREAL;                     // 弓高弦长上限 [mm] / Sagitta chord ceiling
    fStepGeom : LREAL;                     // 弦长上限角步长 [弧度] / Chord-ceiling angular step
    fRemainGeom: LREAL;                    // 剩余扫角 [弧度] / Remaining sweep
END_VAR
VAR CONSTANT
    DL_TWO_PI  : REAL := 6.283185307;      // 全周角 [弧度] / Full turn angle
    DL_HALF_PI : REAL := 1.570796327;      // 直角 [弧度] / Quarter turn angle
    DL_TWO     : REAL := 2.0;              // 二常量 [无量纲] / Two constant
    DL_EPS     : REAL := 1.0E-6;           // 几何退化判据 [mm] / Degenerate geometry tolerance
    DL_NORM_GUARD: DINT := 8;              // 角度归一化守卫上限 [次] / Normalization guard limit
    DL_ABS_MAX : REAL := 1.0E30;           // 有限值判定上界 [mm] / Finite bound
    DL_ZERO    : REAL := 0.0;              // 零常量 [mm] / Zero constant
    DL_MS_PER_S: REAL := 1000.0;           // 毫秒 → 秒换算系数 [毫秒/秒] / Milliseconds per second
END_VAR

(* —— 段 0｜沿实例每拍无条件刷新（禁置于 IF/CASE 内） —— *)
rtReset(CLK := bReset);
rtStart(CLK := bStartCmd);

(* —— 段 1｜瞬时量预清零（锁存量 _bFault/_uFault/bDone/几何量不入清单） —— *)
uErrId     := 16#0000_0000;
bQuadCross := FALSE;                     // 跨越脉冲单拍量，每拍清零
_bCfgBad   := FALSE;
_bNonFin   := FALSE;
_bValid    := TRUE;

(* —— 段 2｜复位沿：故障一次性清干净，相位回空闲 —— *)
IF rtReset.Q THEN
    _bFault := FALSE;
    _uFault := 16#0000_0000;
    bDone   := FALSE;
    _eState := E_DL_CiaState.eIdle;
END_IF

(* —— 段 3｜公共组态闸与非有限判据（覆盖全部参与换算引脚） —— *)
IF (fFeedMmS <= DL_ZERO) OR (fSagittaMaxMm <= DL_ZERO) OR (fRadTolMm <= DL_ZERO)
   OR (tCycle = T#0S) THEN
    _bCfgBad := TRUE;
END_IF
IF (fStartXMm <> fStartXMm) OR ((fStartXMm - fStartXMm) <> DL_ZERO)
   OR (fStartYMm <> fStartYMm) OR ((fStartYMm - fStartYMm) <> DL_ZERO)
   OR (fEndXMm <> fEndXMm) OR ((fEndXMm - fEndXMm) <> DL_ZERO)
   OR (fEndYMm <> fEndYMm) OR ((fEndYMm - fEndYMm) <> DL_ZERO) THEN
    _bNonFin := TRUE;
END_IF

(* —— 段 4｜主状态机：五态全覆盖 + ELSE 兜底 —— *)
CASE _eState OF

E_DL_CiaState.eIdle:
    bBusy := FALSE;
    IF rtStart.Q AND (NOT _bFault) AND (NOT _bCfgBad) AND (NOT _bNonFin) THEN
        fPosXMm := fStartXMm;            // 出点先落起点
        fPosYMm := fStartYMm;
        bDone   := FALSE;
        _eState := E_DL_CiaState.eGeom;
    ELSIF rtStart.Q AND (_bFault OR _bCfgBad OR _bNonFin) THEN
        _bFault := TRUE;                 // 带病启动拒绝
        _uFault := 16#0004_02AC;
        bError  := TRUE;
        _eState := E_DL_CiaState.eFault;
    END_IF

E_DL_CiaState.eGeom:
    (* 单拍几何解算：圆心 / 半径 / 起终角 / 扫角 *)
    IF _bNonFin THEN
        _bFault := TRUE;
        _uFault := 16#0004_02AC;
        bError  := TRUE;
        _eState := E_DL_CiaState.eFault;
    ELSE
        IF bUseRadius THEN
            (* 半径模式：弦长反解圆心（CW/CCW 定唯一解），弦长 > 2R 判非法 *)
            _fRadMm := ABS(fRadiusMm);
            IF _fRadMm <= DL_EPS THEN
                _bFault := TRUE;
                _uFault := 16#0004_02AC;
                bError  := TRUE;
                _eState := E_DL_CiaState.eFault;
            ELSE
                fDxGeom := fEndXMm - fStartXMm;          // 弦向量 X
                fDyGeom := fEndYMm - fStartYMm;          // 弦向量 Y
                fChordGeom := SQRT(fDxGeom * fDxGeom + fDyGeom * fDyGeom);
                IF fChordGeom <= DL_EPS THEN
                    _bFault := TRUE;     // 起终点重合：圆弧退化
                    _uFault := 16#0004_02AC;
                    bError  := TRUE;
                    _eState := E_DL_CiaState.eFault;
                ELSIF fChordGeom > (DL_TWO * _fRadMm) THEN
                    _bFault := TRUE;     // 弦长超直径：无解
                    _uFault := 16#0004_02AC;
                    bError  := TRUE;
                    _eState := E_DL_CiaState.eFault;
                ELSE
                    fHGeom := SQRT(MAX(_fRadMm * _fRadMm - (fChordGeom * fChordGeom) / (DL_TWO * DL_TWO), DL_ZERO));
                    _fCtrXMm := (fStartXMm + fEndXMm) / DL_TWO;
                    _fCtrYMm := (fStartYMm + fEndYMm) / DL_TWO;
                    IF bCwDir THEN
                        _fCtrXMm := _fCtrXMm + (fDyGeom / fChordGeom) * fHGeom;
                        _fCtrYMm := _fCtrYMm - (fDxGeom / fChordGeom) * fHGeom;
                    ELSE
                        _fCtrXMm := _fCtrXMm - (fDyGeom / fChordGeom) * fHGeom;
                        _fCtrYMm := _fCtrYMm + (fDxGeom / fChordGeom) * fHGeom;
                    END_IF
                    _eState := E_DL_CiaState.eRun;
                END_IF
            END_IF
        ELSE
            (* 圆心模式：半径由起点实测，终点半径超容差判非法 *)
            _fCtrXMm := fCenterXMm;
            _fCtrYMm := fCenterYMm;
            fDxGeom := fStartXMm - _fCtrXMm;
            fDyGeom := fStartYMm - _fCtrYMm;
            _fRadMm := SQRT(fDxGeom * fDxGeom + fDyGeom * fDyGeom);
            fDxGeom := fEndXMm - _fCtrXMm;
            fDyGeom := fEndYMm - _fCtrYMm;
            fChordGeom := SQRT(fDxGeom * fDxGeom + fDyGeom * fDyGeom);
            IF _fRadMm <= DL_EPS THEN
                _bFault := TRUE;         // 起点与圆心重合
                _uFault := 16#0004_02AC;
                bError  := TRUE;
                _eState := E_DL_CiaState.eFault;
            ELSIF ABS(fChordGeom - _fRadMm) > fRadTolMm THEN
                _bFault := TRUE;         // 终点半径与起点半径超容差
                _uFault := 16#0004_02AC;
                bError  := TRUE;
                _eState := E_DL_CiaState.eFault;
            ELSE
                _eState := E_DL_CiaState.eRun;
            END_IF
        END_IF
        IF _eState = E_DL_CiaState.eRun THEN
            (* 起终角经 Atan2Ex 唯一属主（返回弧度），属主无效即判故障 *)
            fAng0Geom := FC_DL_Atan2Ex(lrY := fStartYMm - _fCtrYMm, lrX := fStartXMm - _fCtrXMm,
                                       bValid => _bVal0);
            fAng1Geom := FC_DL_Atan2Ex(lrY := fEndYMm - _fCtrYMm, lrX := fEndXMm - _fCtrXMm,
                                       bValid => _bVal1);
            _bValid := _bVal0 AND _bVal1;
            IF NOT _bValid THEN
                _bFault := TRUE;
                _uFault := 16#0004_02AC;
                bError  := TRUE;
                _eState := E_DL_CiaState.eFault;
            ELSE
                IF bCwDir THEN
                    fSweepGeom := fAng0Geom - fAng1Geom;
                ELSE
                    fSweepGeom := fAng1Geom - fAng0Geom;
                END_IF
                _nNormGuard := 0;
                WHILE (fSweepGeom < DL_ZERO) AND (_nNormGuard < DL_NORM_GUARD) DO
                    fSweepGeom := fSweepGeom + DL_TWO_PI;    // 负角加全周归一
                    _nNormGuard := _nNormGuard + 1;
                END_WHILE;
                _nNormGuard := 0;
                WHILE (fSweepGeom >= DL_TWO_PI) AND (_nNormGuard < DL_NORM_GUARD) DO
                    fSweepGeom := fSweepGeom - DL_TWO_PI;    // 超全周减全周归一
                    _nNormGuard := _nNormGuard + 1;
                END_WHILE;
                IF (_nNormGuard >= DL_NORM_GUARD) OR (fSweepGeom <= DL_EPS) THEN
                    _bFault := TRUE;     // 归一化守卫超限或扫角退化
                    _uFault := 16#0004_02AC;
                    bError  := TRUE;
                    _eState := E_DL_CiaState.eFault;
                ELSE
                    _fSweep  := LREAL_TO_REAL(fSweepGeom);
                    _fAng0   := LREAL_TO_REAL(fAng0Geom);
                    _fAngCur := _fAng0;
                    fArcLenMm := _fSweep * _fRadMm;
                    (* 每拍角步长：进给步长与弓高弦长上限步长取小（除数均已过域闸） *)
                    fStepFeed := fFeedMmS * TIME_TO_REAL(tCycle) / DL_MS_PER_S / _fRadMm;
                    fChordMax := DL_TWO * SQRT(DL_TWO * _fRadMm * fSagittaMaxMm
                                 - fSagittaMaxMm * fSagittaMaxMm);
                    fStepGeom := fChordMax / _fRadMm;
                    _fDAng := LREAL_TO_REAL(MIN(fStepFeed, fStepGeom));
                    _nQuadPrev := -1;    // 象限号初始化为哨兵
                    bBusy := TRUE;
                END_IF
            END_IF
        END_IF
    END_IF

E_DL_CiaState.eRun:
    bBusy := TRUE;
    IF bCwDir THEN
        _fAngCur := _fAngCur - _fDAng;
    ELSE
        _fAngCur := _fAngCur + _fDAng;
    END_IF
    (* 象限号判据：cos/sin 符号四象限编码（0..3），本上拍不同即跨越 *)
    IF COS(_fAngCur) >= DL_ZERO THEN
        IF SIN(_fAngCur) >= DL_ZERO THEN
            _nQuadCur := 0;              // 第一象限
        ELSE
            _nQuadCur := 3;              // 第四象限
        END_IF
    ELSE
        IF SIN(_fAngCur) >= DL_ZERO THEN
            _nQuadCur := 1;              // 第二象限
        ELSE
            _nQuadCur := 2;              // 第三象限
        END_IF
    END_IF
    IF (_nQuadPrev >= 0) AND (_nQuadCur <> _nQuadPrev) THEN
        bQuadCross := TRUE;              // 象限跨越脉冲（单拍）
        uErrId := 16#0004_01AC;          // 信息级：象限跨越沿
    END_IF
    _nQuadPrev := _nQuadCur;
    (* 出点由圆心 + 半径 × 当前角三角合成（正解三角为 Standard.library 标准函数） *)
    fPosXMm := _fCtrXMm + COS(_fAngCur) * _fRadMm;
    fPosYMm := _fCtrYMm + SIN(_fAngCur) * _fRadMm;
    (* 终点判定：剩余扫角耗尽 → 落终点驻留 *)
    fRemainGeom := ABS(_fAngCur - _fAng0);
    IF fRemainGeom >= (_fSweep - _fDAng) THEN
        fPosXMm := fEndXMm;
        fPosYMm := fEndYMm;
        bBusy := FALSE;
        bDone := TRUE;
        _eState := E_DL_CiaState.eDone;
    END_IF

E_DL_CiaState.eDone:
    bDone := TRUE;
    bBusy := FALSE;
    IF NOT bStartCmd THEN
        _eState := E_DL_CiaState.eIdle;  // 启动指令撤销：回空闲
    END_IF

E_DL_CiaState.eFault:
    bBusy := FALSE;
    bError := TRUE;
    ;                                    // 故障相驻留：出点冻结，只认复位沿（段 2 迁出）

ELSE
    _bFault := TRUE;                     // 兜底：非法相位锁存
    _uFault := 16#0004_02AC;
    bError  := TRUE;
    _eState := E_DL_CiaState.eFault;
END_CASE

(* —— 段 5｜状态出口单点映射 —— *)
eState := _eState;
END_FUNCTION_BLOCK

