TYPE E_DL_PstState :
(
    eIdle   := 0,   // 空闲：等测试沿 / Idle, waiting test edge
    eCheck  := 10,  // 检查：许可与组态闸 / Checking permissive and configuration
    eMove   := 20,  // 行程：开阀至测试目标位 / Moving to test target position
    eReturn := 30,  // 回程：回正常位 / Returning to normal position
    eDone   := 40,  // 完成：判级驻留 / Done, grading held
    eFault  := 90   // 故障：PST 锁存 / Fault, latched
);
END_TYPE

TYPE E_DL_PstCause :
(
    eNone       := 0,  // 无故障成因 / No cause
    ePermissive := 1,  // 测试许可撤销 / Test permissive lost
    eMoveTo     := 2,  // 目标位超时未到位 / Move target timeout
    eReturnTo   := 3,  // 回位超时未到位 / Return timeout
    eCfgIllegal := 4,  // 组态非法 / Illegal configuration
    eNonFinite  := 5   // 输入非有限 / Non-finite input
);
END_TYPE

FUNCTION_BLOCK FB_DL_ValvePartialStrokeTest
VAR_INPUT
    bEnable        : BOOL;               // 使能（电平）[-] / Enable
    bReset         : BOOL;               // 上升沿清故障锁存 [-] / Reset edge
    bTestCmd       : BOOL;               // 测试指令（上升沿承载）[-] / Test command edge
    bProcessPermissive: BOOL;            // 过程测试许可（硬联锁）[-] / Process test permissive
    fActPosPct     : REAL;               // 阀实际位置 [%] / Valve actual position
    fTestTargetPct : REAL;               // 测试目标位（会被钳入测试带）[%] / Test target position
    fNormalPosPct  : REAL := 0.0;        // 正常工作位 [%] / Normal operating position
    fTestLoPct     : REAL := 10.0;       // 测试带下限 [%] / Test band floor
    fTestHiPct     : REAL := 30.0;       // 测试带上限 [%] / Test band ceiling
    fTravelTolPct  : REAL := 2.0;        // 行程到位容差 [%] / Travel tolerance
    tMoveTo        : TIME := T#30S;      // 行程超时 [毫秒] / Move timeout
    tReturnTo      : TIME := T#30S;      // 回程超时 [毫秒] / Return timeout
END_VAR
VAR_OUTPUT
    fValveCmdPct   : REAL;               // 阀位指令输出 [%] / Valve position command
    bTestActive    : BOOL;               // 测试进行中电平 [-] / Test active level
    bTestPass      : BOOL;               // 结论：合格 [-] / Verdict pass flag
    bTestDerated   : BOOL;               // 结论：降级（短行程）[-] / Verdict derated flag
    fTestTravelPct : REAL;               // 实测测试行程 [%] / Measured test travel
    eNe107         : E_DL_Ne107Status;   // NE107 健康出口（唯一属主枚举） / NE107 health outlet
    eState         : E_DL_PstState;      // 状态出口，段尾单点映射 / State outlet
    eCause         : E_DL_PstCause;      // 故障成因出口（R190） / Fault cause outlet
    bError         : BOOL;               // 故障锁存标志 [-] / Fault latch flag
    uErrId         : UDINT;              // 事件码，0 = 无事件 / Event code
END_VAR
VAR
    rtReset: R_TRIG;                     // 复位沿实例，段 0 无条件刷新 / Reset edge
    rtTest : R_TRIG;                     // 测试沿实例，段 0 无条件刷新 / Test edge
    tonMoveTo : TON;                     // 行程超时（专用超时件命名） / Move timeout
    tonReturnTo: TON;                    // 回程超时（专用超时件命名） / Return timeout
    _eState: E_DL_PstState := E_DL_PstState.eIdle;     // 内部相位（CASE 唯一写入目标）/ Internal phase
    _eCause: E_DL_PstCause := E_DL_PstCause.eNone;     // 故障成因锁存（锁存量）/ Latched cause
    _fTargetUse: REAL;                   // 钳位后测试目标位 [%] / Clamped test target
    _fPosStart : REAL;                   // 测试起点位置 [%] / Test start position
    _bFault: BOOL;                       // 故障锁存位（锁存量） / Latched fault bit
    _uFault: UDINT;                      // 故障码锁存（锁存量） / Latched fault code
    _bCfgBad: BOOL;                      // 组态非法当拍量 [-] / Config illegal flag
    _bNonFin: BOOL;                      // 输入非有限当拍量 [-] / Non-finite input flag
    _bInPos: BOOL;                       // 到位当拍量 [-] / In-position flag
END_VAR
VAR CONSTANT
    DL_ABS_MAX : REAL := 1.0E30;         // 有限值判定上界 [%] / Finite bound
    DL_ZERO    : REAL := 0.0;            // 零常量 [%] / Zero constant
END_VAR

(* —— 段 0｜沿与定时器每拍无条件刷新（禁置于 IF/CASE 内） —— *)
rtReset(CLK := bReset);
rtTest (CLK := bTestCmd);
tonMoveTo  (IN := (_eState = E_DL_PstState.eMove) AND (NOT _bFault), PT := tMoveTo);
tonReturnTo(IN := (_eState = E_DL_PstState.eReturn) AND (NOT _bFault), PT := tReturnTo);

(* —— 段 1｜瞬时量预清零（锁存量 _bFault/_uFault/bTestPass/bTestDerated 不入清单） —— *)
uErrId   := 16#0000_0000;
bTestActive := FALSE;
_bInPos  := FALSE;
_bCfgBad := FALSE;
_bNonFin := FALSE;

(* —— 段 2｜复位沿：故障一次性清干净，相位回空闲，阀位指令撤销 —— *)
IF rtReset.Q THEN
    _bFault := FALSE;
    _uFault := 16#0000_0000;
    _eCause := E_DL_PstCause.eNone;
    fValveCmdPct := fNormalPosPct;       // 复位后指令回正常位（安全侧）
    _eState := E_DL_PstState.eIdle;
END_IF

(* —— 段 3｜组态闸与非有限判据 —— *)
IF (fTestLoPct >= fTestHiPct) OR (fTravelTolPct <= DL_ZERO) OR (fNormalPosPct < DL_ZERO)
   OR (tMoveTo = T#0S) OR (tReturnTo = T#0S) THEN
    _bCfgBad := TRUE;
END_IF
IF (fActPosPct <> fActPosPct) OR ((fActPosPct - fActPosPct) <> DL_ZERO)
   OR (fTestTargetPct <> fTestTargetPct) OR ((fTestTargetPct - fTestTargetPct) <> DL_ZERO) THEN
    _bNonFin := TRUE;
END_IF

(* —— 段 4｜主状态机：六态全覆盖 + ELSE 兜底 —— *)
CASE _eState OF

E_DL_PstState.eIdle:
    fValveCmdPct := fNormalPosPct;
    eNe107 := E_DL_Ne107Status.eOk;      // 空闲相健康出口正常
    IF bTestDerated AND (NOT bTestPass) THEN
        eNe107 := E_DL_Ne107Status.eMaintenanceReq;   // 上轮降级结论驻留期维持维护等级
    END_IF
    IF rtTest.Q AND bEnable AND (NOT _bFault) AND (NOT _bCfgBad) AND (NOT _bNonFin) THEN
        bTestPass := FALSE;
        bTestDerated := FALSE;
        _eState := E_DL_PstState.eCheck;
    ELSIF rtTest.Q AND (_bFault OR _bCfgBad OR _bNonFin) THEN
        _bFault := TRUE;                 // 带病启动拒绝
        _uFault := 16#0003_052F;
        IF _bCfgBad THEN
            _eCause := E_DL_PstCause.eCfgIllegal;
        ELSE
            _eCause := E_DL_PstCause.eNonFinite;
        END_IF
        bError  := TRUE;
        _eState := E_DL_PstState.eFault;
    END_IF

E_DL_PstState.eCheck:
    bTestActive := TRUE;
    eNe107 := E_DL_Ne107Status.eCheckFunction;    // 检查相：功能检查等级
    IF NOT bProcessPermissive THEN
        _bFault := TRUE;                 // 许可撤销：测试前置硬闸不过
        _uFault := 16#0003_052F;
        _eCause := E_DL_PstCause.ePermissive;
        bError  := TRUE;
        _eState := E_DL_PstState.eFault;
    ELSE
        _fTargetUse := MIN(MAX(fTestTargetPct, fTestLoPct), fTestHiPct);  // 行程限幅钳位
        _fPosStart := fActPosPct;
        fValveCmdPct := _fTargetUse;
        _eState := E_DL_PstState.eMove;
    END_IF

E_DL_PstState.eMove:
    bTestActive := TRUE;
    fValveCmdPct := _fTargetUse;
    eNe107 := E_DL_Ne107Status.eCheckFunction;
    _bInPos := ABS(fActPosPct - _fTargetUse) <= fTravelTolPct;
    IF _bNonFin THEN
        _bFault := TRUE;
        _uFault := 16#0003_052F;
        _eCause := E_DL_PstCause.eNonFinite;
        bError  := TRUE;
        _eState := E_DL_PstState.eFault;
    ELS    IF _bInPos THEN
        fTestTravelPct := ABS(fActPosPct - _fPosStart);   // 行程实测：目标位达成拍快照
        _eState := E_DL_PstState.eReturn;    // 迁出条件 1：目标位达成
    ELSIF NOT bProcessPermissive THEN
        _bFault := TRUE;                 // 迁出条件 2（故障路）：行程中许可撤销
        _uFault := 16#0003_052F;
        _eCause := E_DL_PstCause.ePermissive;
        bError  := TRUE;
        _eState := E_DL_PstState.eFault;
    ELSIF tonMoveTo.Q THEN
        _bFault := TRUE;                 // 迁出条件 3（故障路）：行程超时
        _uFault := 16#0003_052F;
        _eCause := E_DL_PstCause.eMoveTo;
        bError  := TRUE;
        _eState := E_DL_PstState.eFault;
    END_IF

E_DL_PstState.eReturn:
    bTestActive := TRUE;
    fValveCmdPct := fNormalPosPct;
    eNe107 := E_DL_Ne107Status.eCheckFunction;
    _bInPos := ABS(fActPosPct - fNormalPosPct) <= fTravelTolPct;
    IF _bInPos THEN
        _eState := E_DL_PstState.eDone;  // 回位达成：进判级相（行程已在 eMove 快照）
    ELSIF tonReturnTo.Q THEN
        _bFault := TRUE;
        _uFault := 16#0003_052F;
        _eCause := E_DL_PstCause.eReturnTo;
        bError  := TRUE;
        _eState := E_DL_PstState.eFault;
    END_IF

E_DL_PstState.eDone:
    bTestActive := FALSE;
    fValveCmdPct := fNormalPosPct;
    (* 判级：行程完全未动（<= 容差）→ 失效锁存；短行程（< 指令行程 - 容差）→ 降级 *)
    IF fTestTravelPct <= fTravelTolPct THEN
        _bFault := TRUE;                 // 行程完全未动：失效级
        _uFault := 16#0003_052F;
        _eCause := E_DL_PstCause.eMoveTo;
        bError  := TRUE;
        eNe107  := E_DL_Ne107Status.eFailure;
        _eState := E_DL_PstState.eFault;
    ELSE
        bTestPass := fTestTravelPct >= (ABS(_fTargetUse - _fPosStart) - fTravelTolPct);
        bTestDerated := NOT bTestPass;
        IF bTestDerated THEN
            eNe107 := E_DL_Ne107Status.eMaintenanceReq;   // 降级：需要维护
        ELSE
            eNe107 := E_DL_Ne107Status.eOk;
        END_IF
        IF NOT bTestCmd THEN
            _eState := E_DL_PstState.eIdle;   // 测试指令撤销：回空闲（结论锁存保留）
        END_IF
    END_IF

E_DL_PstState.eFault:
    bTestActive := FALSE;
    fValveCmdPct := fNormalPosPct;       // 故障相：阀位指令安全侧回正常位
    bError := TRUE;
    eNe107 := E_DL_Ne107Status.eFailure; // 故障相健康出口失效级
    ;                                    // 故障相驻留：只认复位沿（段 2 迁出）

ELSE
    _bFault := TRUE;                     // 兜底：非法相位锁存
    _uFault := 16#0003_052F;
    _eCause := E_DL_PstCause.eCfgIllegal;
    bError  := TRUE;
    eNe107  := E_DL_Ne107Status.eFailure;
    _eState := E_DL_PstState.eFault;
END_CASE

(* —— 段 5｜状态出口单点映射 —— *)
eState := _eState;
END_FUNCTION_BLOCK

(*
  组件名 Component   : FB_DL_DesiccantRegenSeq
  子库 Sublibrary    : DL_Process
  版本 Version       : 1.0.0
  兼容性 Platform    : CODESYS 3.5 / TwinCAT 3 / 汇川 InoProShop / Machine Expert（仅 Standard.library）
  功能 Function      : 干燥剂吸附塔再生顺控（ISA-88 相语义最小子集）：
                       1) 四相顺控：吸附（eAdsorb）→ 再生（eRegen）→ 吹冷（eCool）→
                       切换驻留（eSwitchDwell）→ 回吸附，吸附时长由 tAdsorbDur 承载；
                       2) 塔间轮换：A/B 双塔，eSwitchDwell 相完成阀组切换并翻转
                       bTowerAActive/bTowerBActive（切换指令单点出口）；
                       3) 再生温度曲线监视：再生相内再生温度须在
                       [fRegenTempLoC, fRegenTempHiC] 曲线带内，越带持续 tTempDevTo
                       → 故障锁存；
                       4) 各相计时独立 TON 实例（禁跨相复用，R228A）。
  边界 Boundary      : ① 本件只出阀组/加热指令与塔选通，不写物理 IO；
                       ② 吹冷相退出双条件：吹冷计时到 或 出口温度低于 fCoolEndC
                       （事件达成 + 前置消失双路径）；再生许可不满足时吸附相驻留等待；
                       ③ 故障锁存解除唯一路径 = bReset 上升沿（输入引脚，恒可达）；
                       ④ 无全局变量引用、无外部变量声明、无物理地址寻址。
  依赖 Depends       : Standard.library（R_TRIG / TON）
  溯源 Origin        : 道莅自研 clean-room（参考 t2-8-isa88 相语义分类与参数域，
                       零代码行复制）
  码位 Code          : 16#06_0_BE（Process 段 0006，B 子带 BE 格）
  码表 Error codes（本件格 06_0_BE，单轨子道：故障 0x02BE / 信息 0x01BE）:
    16#0006_02BE 故障级：再生顺控故障总码（再生温度越带 / 切换超时 / 组态非法 /
                 输入非有限），锁存至复位
    16#0006_01BE 信息级：塔切换完成沿（eSwitchDwell → eAdsorb 迁移拍）
  修订历史 Revision  :
    2026-11-19  v1.0.0  R44 首版（批次 3 · 序号 15）
*)

TYPE E_DL_DrsPhase :
(
    eIdle        := 0,   // 空闲：未使能 / Idle, not enabled
    eAdsorb      := 10,  // 吸附：当前塔吸附运行 / Adsorbing on active tower
    eRegen       := 20,  // 再生：离线塔再生加热 / Regenerating offline tower
    eCool        := 30,  // 吹冷：再生塔吹冷 / Cooling regenerated tower
    eSwitchDwell := 40,  // 切换：塔间阀组切换驻留 / Switching towers dwell
    eFault       := 90   // 故障：总码锁存 / Fault, latched
);
END_TYPE

FUNCTION_BLOCK FB_DL_DesiccantRegenSeq
VAR_INPUT
    bEnable      : BOOL;                   // 使能（电平）[-] / Enable
    bReset       : BOOL;                   // 上升沿清故障锁存 [-] / Reset edge
    bRegenPermissive: BOOL;                // 再生许可（电平）[-] / Regen permissive
    fRegenTempC  : REAL;                   // 再生温度 [摄氏度] / Regen temperature
    fCoolOutTempC: REAL;                   // 吹冷出口温度 [摄氏度] / Cooling outlet temperature
    tAdsorbDur   : TIME := T#8H;           // 吸附时长 [毫秒] / Adsorption duration
    tRegenDur    : TIME := T#4H;           // 再生时长 [毫秒] / Regen duration
    tCoolMaxDur  : TIME := T#2H;           // 吹冷最大时长 [毫秒] / Cooling max duration
    tSwitchDur   : TIME := T#60S;          // 切换驻留 [毫秒] / Switch dwell
    fRegenTempLoC: REAL := 120.0;          // 再生温度带下限 [摄氏度] / Regen band floor
    fRegenTempHiC: REAL := 200.0;          // 再生温度带上限 [摄氏度] / Regen band ceiling
    fCoolEndC    : REAL := 45.0;           // 吹冷结束温度 [摄氏度] / Cooling end temperature
    tTempDevTo   : TIME := T#30S;          // 温度越带确认窗 [毫秒] / Temperature deviation timeout
END_VAR
VAR_OUTPUT
    bTowerAActive: BOOL;                   // A 塔吸附选通 [-] / Tower A active
    bTowerBActive: BOOL;                   // B 塔吸附选通 [-] / Tower B active
    bRegenHeatCmd: BOOL;                   // 再生加热指令 [-] / Regen heat command
    bRegenCoolCmd: BOOL;                   // 吹冷指令 [-] / Regen cool command
    bSwitchCmd   : BOOL;                   // 塔切换指令（驻留相电平）[-] / Tower switch command
    ePhase       : E_DL_DrsPhase;          // 相位出口，段尾单点映射 / Phase outlet
    bError       : BOOL;                   // 故障锁存标志 [-] / Fault latch flag
    uErrId       : UDINT;                  // 事件码，0 = 无事件 / Event code
END_VAR
VAR
    rtReset   : R_TRIG;                    // 复位沿实例，段 0 无条件刷新 / Reset edge
    tonAdsorb : TON;                       // 吸附计时（独立实例） / Adsorption timer
    tonRegen  : TON;                       // 再生计时（独立实例） / Regen timer
    tonCoolMax: TON;                       // 吹冷最大计时（独立实例） / Cooling max timer
    tonSwitch : TON;                       // 切换驻留计时（独立实例） / Switch dwell timer
    tonTempDevTo: TON;                     // 温度越带确认（专用超时件命名） / Temp deviation timeout
    _ePhase   : E_DL_DrsPhase := E_DL_DrsPhase.eIdle;  // 内部相位（CASE 唯一写入目标）/ Internal phase
    _bTowerA  : BOOL := TRUE;              // 内部塔选（TRUE = A 塔吸附）/ Internal tower select
    _bFault   : BOOL;                      // 故障锁存位（锁存量） / Latched fault bit
    _uFault   : UDINT;                     // 故障码锁存（锁存量） / Latched fault code
    _bCfgBad  : BOOL;                      // 组态非法当拍量 [-] / Config illegal flag
    _bNonFin  : BOOL;                      // 输入非有限当拍量 [-] / Non-finite input flag
    _bTempDev : BOOL;                      // 温度越带当拍量 [-] / Temperature deviation flag
END_VAR
VAR CONSTANT
    DL_ABS_MAX : REAL := 1.0E30;           // 有限值判定上界 [摄氏度] / Finite bound
    DL_ZERO    : REAL := 0.0;              // 零常量 [摄氏度] / Zero constant
END_VAR

(* —— 段 0｜沿与定时器每拍无条件刷新（禁置于 IF/CASE 内；各相独立实例禁复用） —— *)
rtReset(CLK := bReset);
tonAdsorb (IN := (_ePhase = E_DL_DrsPhase.eAdsorb) AND (NOT _bFault), PT := tAdsorbDur);
tonRegen  (IN := (_ePhase = E_DL_DrsPhase.eRegen) AND (NOT _bFault), PT := tRegenDur);
tonCoolMax(IN := (_ePhase = E_DL_DrsPhase.eCool) AND (NOT _bFault), PT := tCoolMaxDur);
tonSwitch (IN := (_ePhase = E_DL_DrsPhase.eSwitchDwell) AND (NOT _bFault), PT := tSwitchDur);
_bTempDev := (_ePhase = E_DL_DrsPhase.eRegen)
             AND ((fRegenTempC < fRegenTempLoC) OR (fRegenTempC > fRegenTempHiC));
tonTempDevTo(IN := _bTempDev AND (NOT _bFault), PT := tTempDevTo);

(* —— 段 1｜瞬时量预清零（锁存量 _bFault/_uFault/_bTowerA 不入清单） —— *)
uErrId   := 16#0000_0000;
_bCfgBad := FALSE;
_bNonFin := FALSE;

(* —— 段 2｜复位沿：故障一次性清干净，相位回空闲 —— *)
IF rtReset.Q THEN
    _bFault := FALSE;
    _uFault := 16#0000_0000;
    _ePhase := E_DL_DrsPhase.eIdle;
END_IF

(* —— 段 3｜组态闸与非有限判据（覆盖全部参与判据换算引脚） —— *)
IF (fRegenTempLoC >= fRegenTempHiC) OR (tAdsorbDur = T#0S) OR (tRegenDur = T#0S)
   OR (tCoolMaxDur = T#0S) OR (tSwitchDur = T#0S) OR (tTempDevTo = T#0S) THEN
    _bCfgBad := TRUE;
END_IF
IF (fRegenTempC <> fRegenTempC) OR ((fRegenTempC - fRegenTempC) <> DL_ZERO)
   OR (fCoolOutTempC <> fCoolOutTempC) OR ((fCoolOutTempC - fCoolOutTempC) <> DL_ZERO) THEN
    _bNonFin := TRUE;
END_IF

(* —— 段 4｜主状态机：六态全覆盖 + ELSE 兜底 —— *)
CASE _ePhase OF

E_DL_DrsPhase.eIdle:
    bTowerAActive := FALSE;
    bTowerBActive := FALSE;
    bRegenHeatCmd := FALSE;
    bRegenCoolCmd := FALSE;
    bSwitchCmd    := FALSE;
    IF bEnable AND (NOT _bCfgBad) THEN
        _bTowerA := TRUE;                // 入运行相：A 塔先吸附（固定初序）
        _ePhase  := E_DL_DrsPhase.eAdsorb;
    ELSIF bEnable AND _bCfgBad THEN
        _bFault := TRUE;
        _uFault := 16#0006_02BE;
        bError  := TRUE;
        _ePhase := E_DL_DrsPhase.eFault;
    END_IF

E_DL_DrsPhase.eAdsorb:
    bTowerAActive := _bTowerA;
    bTowerBActive := NOT _bTowerA;
    bRegenHeatCmd := FALSE;
    bRegenCoolCmd := FALSE;
    bSwitchCmd    := FALSE;
    IF _bNonFin THEN
        _bFault := TRUE;
        _uFault := 16#0006_02BE;
        bError  := TRUE;
        _ePhase := E_DL_DrsPhase.eFault;
    ELSIF NOT bEnable THEN
        _ePhase := E_DL_DrsPhase.eIdle;  // 使能撤销回空闲
    ELSIF tonAdsorb.Q AND bRegenPermissive THEN
        _ePhase := E_DL_DrsPhase.eRegen; // 吸附时长到且再生许可满足：进再生
    ELSIF tonAdsorb.Q THEN
        ;                                // 吸附时长到但许可未满足：吸附相驻留等待（退出前置消失路径）
    END_IF

E_DL_DrsPhase.eRegen:
    bTowerAActive := _bTowerA;
    bTowerBActive := NOT _bTowerA;
    bRegenHeatCmd := TRUE;
    bRegenCoolCmd := FALSE;
    bSwitchCmd    := FALSE;
    IF _bNonFin OR tonTempDevTo.Q THEN
        _bFault := TRUE;                 // 温度越带或输入非法：锁存
        _uFault := 16#0006_02BE;
        bError  := TRUE;
        _ePhase := E_DL_DrsPhase.eFault;
    ELSIF NOT bEnable THEN
        _ePhase := E_DL_DrsPhase.eIdle;  // 使能撤销回空闲
    ELSIF tonRegen.Q THEN
        _ePhase := E_DL_DrsPhase.eCool;  // 迁出条件 1：再生时长到
    END_IF

E_DL_DrsPhase.eCool:
    bTowerAActive := _bTowerA;
    bTowerBActive := NOT _bTowerA;
    bRegenHeatCmd := FALSE;
    bRegenCoolCmd := TRUE;
    bSwitchCmd    := FALSE;
    IF _bNonFin THEN
        _bFault := TRUE;
        _uFault := 16#0006_02BE;
        bError  := TRUE;
        _ePhase := E_DL_DrsPhase.eFault;
    ELSIF NOT bEnable THEN
        _ePhase := E_DL_DrsPhase.eIdle;  // 使能撤销回空闲
    ELSIF (fCoolOutTempC <= fCoolEndC) OR tonCoolMax.Q THEN
        _ePhase := E_DL_DrsPhase.eSwitchDwell;   // 迁出双条件：温度达成 或 吹冷计时到
    END_IF

E_DL_DrsPhase.eSwitchDwell:
    bTowerAActive := FALSE;
    bTowerBActive := FALSE;
    bRegenHeatCmd := FALSE;
    bRegenCoolCmd := FALSE;
    bSwitchCmd    := TRUE;               // 切换指令（驻留相电平）
    IF _bNonFin THEN
        _bFault := TRUE;
        _uFault := 16#0006_02BE;
        bError  := TRUE;
        _ePhase := E_DL_DrsPhase.eFault;
    ELSIF NOT bEnable THEN
        _ePhase := E_DL_DrsPhase.eIdle;  // 使能撤销回空闲
    ELSIF tonSwitch.Q THEN
        _bTowerA := NOT _bTowerA;        // 塔间轮换翻转
        uErrId := 16#0006_01BE;          // 信息级：塔切换完成沿
        _ePhase := E_DL_DrsPhase.eAdsorb;    // 回吸附相（待机可返回路径）
    END_IF

E_DL_DrsPhase.eFault:
    bTowerAActive := FALSE;
    bTowerBActive := FALSE;
    bRegenHeatCmd := FALSE;              // 故障相：加热指令安全侧撤销
    bRegenCoolCmd := FALSE;
    bSwitchCmd    := FALSE;
    bError := TRUE;
    ;                                    // 故障相驻留：只认复位沿（段 2 迁出）

ELSE
    _bFault := TRUE;                     // 兜底：非法相位锁存
    _uFault := 16#0006_02BE;
    bError  := TRUE;
    _ePhase := E_DL_DrsPhase.eFault;
END_CASE

(* —— 段 5｜相位出口单点映射 —— *)
ePhase := _ePhase;
END_FUNCTION_BLOCK

(*
  组件名 Component   : FB_DL_AirLeakDecayTest
  子库 Sublibrary    : DL_Process
  版本 Version       : 1.0.0
  兼容性 Platform    : CODESYS 3.5 / TwinCAT 3 / 汇川 InoProShop / Machine Expert（仅 Standard.library）
  功能 Function      : 气密压降法泄漏测试（与 FC 氦检分工：空气压降 vs 氦质谱）：
                       1) 三段顺控：充压（eCharge，出充压指令至测试压力确认）→
                       稳压（eStabilize，驻留 tStabDur 待温度平衡）→ 测量（eMeasure，
                       驻留 tMeasDur，窗始/窗末压力双快照）；
                       2) 温度补偿：绝对温标折算，压降补偿值 =
                       p1 - p2 × (T1/T2)，T 为绝对温度（摄氏度 + 开尔文偏置）；
                       3) 泄漏率换算判级：泄漏率 = 补偿压降 × 容积 / 测量时长，
                       <= fLeakLim 判合格，否则不合格；
                       4) 测量段压力跌破 fPressMinPa → 充压丢失故障锁存。
  边界 Boundary      : ① 本件只出充压指令与测试结论，不写物理 IO；
                       ② 除法前置域闸：测量时长秒值下限 1.0 s、绝对温度下限
                       1.0 K、容积 > 0（组态闸承载）；
                       ③ 各相计时独立 TON 实例（禁跨相复用）；窗始快照进相首拍
                       写定，锁存回放不重扫；
                       ④ 故障锁存解除唯一路径 = bReset 上升沿（输入引脚，恒可达）；
                       ⑤ 无全局变量引用、无外部变量声明、无物理地址寻址。
  依赖 Depends       : Standard.library（R_TRIG / TON）
  溯源 Origin        : 道莅自研 clean-room（自研行业池：通用质量工装气密检测
                       共性语义，零外部代码行复制）
  码位 Code          : 16#06_0_C2（Process 段 0006，C 子带 C2 格）
  码表 Error codes（本件格 06_0_C2，单轨子道：故障 0x02C2 / 信息 0x01C2）:
    16#0006_02C2 故障级：气密测试故障总码（充压超时 / 测量段压力跌破下限 /
                 组态非法 / 输入非有限），锁存至复位
    16#0006_01C2 信息级：测试结论写定沿（合格或不合格判定拍）
  修订历史 Revision  :
    2026-11-19  v1.0.0  R44 首版（批次 4 · 序号 19）
*)

TYPE E_DL_AltPhase :
(
    eIdle      := 0,   // 空闲：等测试沿 / Idle, waiting test edge
    eCharge    := 10,  // 充压：至测试压力确认 / Charging to test pressure
    eStabilize := 20,  // 稳压：温度平衡驻留 / Stabilizing dwell
    eMeasure   := 30,  // 测量：双快照驻留 / Measuring dwell
    eDone      := 40,  // 完成：结论驻留 / Done, verdict held
    eFault     := 90   // 故障：总码锁存 / Fault, latched
);
END_TYPE

FUNCTION_BLOCK FB_DL_AirLeakDecayTest
VAR_INPUT
    bEnable      : BOOL;                   // 使能（电平）[-] / Enable
    bReset       : BOOL;                   // 上升沿清故障锁存 [-] / Reset edge
    bTestCmd     : BOOL;                   // 测试指令（上升沿承载）[-] / Test command edge
    fPressPa     : REAL;                   // 腔体实测压力 [帕斯卡] / Measured pressure
    fTempC       : REAL;                   // 腔体实测温度 [摄氏度] / Measured temperature
    fTestPressPa : REAL := 500000.0;       // 测试压力 [帕斯卡] / Test pressure
    fPressMinPa  : REAL := 400000.0;       // 测量段压力下限 [帕斯卡] / Measurement pressure floor
    fVolumeL     : REAL := 10.0;           // 腔体容积 [升] / Cavity volume
    fLeakLimPaLs : REAL := 1.0;            // 泄漏率合格限 [帕·升/秒] / Leak rate pass limit
    tStabDur     : TIME := T#60S;          // 稳压驻留 [毫秒] / Stabilization dwell
    tMeasDur     : TIME := T#120S;         // 测量驻留 [毫秒] / Measurement dwell
    tChargeTo    : TIME := T#120S;         // 充压超时 [毫秒] / Charge timeout
END_VAR
VAR_OUTPUT
    bChargeCmd   : BOOL;                   // 充压指令输出 [-] / Charge command output
    bTestPass    : BOOL;                   // 结论：合格 [-] / Verdict pass flag
    fLeakRatePaLs: REAL;                   // 实测泄漏率 [帕·升/秒] / Measured leak rate
    fDpCompPa    : REAL;                   // 温度补偿压降 [帕斯卡] / Compensated pressure drop
    ePhase       : E_DL_AltPhase;          // 相位出口，段尾单点映射 / Phase outlet
    bError       : BOOL;                   // 故障锁存标志 [-] / Fault latch flag
    uErrId       : UDINT;                  // 事件码，0 = 无事件 / Event code
END_VAR
VAR
    rtReset: R_TRIG;                       // 复位沿实例，段 0 无条件刷新 / Reset edge
    rtTest : R_TRIG;                       // 测试沿实例，段 0 无条件刷新 / Test edge
    tonStabDur: TON;                       // 稳压驻留计时（独立实例） / Stabilization timer
    tonMeasDur: TON;                       // 测量驻留计时（独立实例） / Measurement timer
    tonChargeTo: TON;                      // 充压超时（专用超时件命名） / Charge timeout
    _ePhase: E_DL_AltPhase := E_DL_AltPhase.eIdle;     // 内部相位（CASE 唯一写入目标）/ Internal phase
    _fP1Pa : REAL;                         // 窗始压力快照 [帕斯卡] / Window-start pressure snapshot
    _fT1C  : REAL;                         // 窗始温度快照 [摄氏度] / Window-start temperature snapshot
    _bSnapDone: BOOL;                      // 窗始快照已取标志 [-] / Snapshot taken flag
    _fT1K  : REAL;                         // 窗始绝对温度 [开尔文] / Window-start absolute temperature
    _fT2K  : REAL;                         // 窗末绝对温度 [开尔文] / Window-end absolute temperature
    _bFault: BOOL;                         // 故障锁存位（锁存量） / Latched fault bit
    _uFault: UDINT;                        // 故障码锁存（锁存量） / Latched fault code
    _bCfgBad: BOOL;                        // 组态非法当拍量 [-] / Config illegal flag
    _bNonFin: BOOL;                        // 输入非有限当拍量 [-] / Non-finite input flag
END_VAR
VAR CONSTANT
    DL_KELVIN_OFF : REAL := 273.15;        // 开尔文偏置 [开尔文] / Kelvin offset
    DL_T_ABS_MIN  : REAL := 1.0;           // 绝对温度下限 [开尔文] / Absolute temperature floor
    DL_MEAS_MIN_S : REAL := 1.0;           // 测量时长秒值下限 [秒] / Measurement seconds floor
    DL_MS_PER_S   : REAL := 1000.0;        // 毫秒 → 秒换算系数 [毫秒/秒] / Milliseconds per second
    DL_ABS_MAX    : REAL := 1.0E30;        // 有限值判定上界 [工程单位] / Finite bound
    DL_ZERO       : REAL := 0.0;           // 零常量 [工程单位] / Zero constant
END_VAR

(* —— 段 0｜沿与定时器每拍无条件刷新（禁置于 IF/CASE 内；各相独立实例禁复用） —— *)
rtReset(CLK := bReset);
rtTest (CLK := bTestCmd);
tonStabDur (IN := (_ePhase = E_DL_AltPhase.eStabilize) AND (NOT _bFault), PT := tStabDur);
tonMeasDur (IN := (_ePhase = E_DL_AltPhase.eMeasure) AND (NOT _bFault), PT := tMeasDur);
tonChargeTo(IN := (_ePhase = E_DL_AltPhase.eCharge) AND (NOT _bFault), PT := tChargeTo);

(* —— 段 1｜瞬时量预清零（锁存量 _bFault/_uFault/bTestPass/_fP1Pa 不入清单） —— *)
uErrId   := 16#0000_0000;
_bCfgBad := FALSE;
_bNonFin := FALSE;

(* —— 段 2｜复位沿：故障一次性清干净，相位回空闲，充压指令撤销 —— *)
IF rtReset.Q THEN
    _bFault := FALSE;
    _uFault := 16#0000_0000;
    bChargeCmd := FALSE;
    _ePhase := E_DL_AltPhase.eIdle;
END_IF

(* —— 段 3｜组态闸与非有限判据（覆盖全部参与判据换算引脚） —— *)
IF (fTestPressPa <= fPressMinPa) OR (fPressMinPa <= DL_ZERO) OR (fVolumeL <= DL_ZERO)
   OR (fLeakLimPaLs <= DL_ZERO) OR (tStabDur = T#0S) OR (tMeasDur = T#0S)
   OR (tChargeTo = T#0S) THEN
    _bCfgBad := TRUE;
END_IF
IF (fPressPa <> fPressPa) OR ((fPressPa - fPressPa) <> DL_ZERO)
   OR (fTempC <> fTempC) OR ((fTempC - fTempC) <> DL_ZERO) THEN
    _bNonFin := TRUE;
END_IF

(* —— 段 4｜主状态机：六态全覆盖 + ELSE 兜底 —— *)
CASE _ePhase OF

E_DL_AltPhase.eIdle:
    bChargeCmd := FALSE;
    IF rtTest.Q AND bEnable AND (NOT _bFault) AND (NOT _bCfgBad) AND (NOT _bNonFin) THEN
        bTestPass := FALSE;
        fLeakRatePaLs := DL_ZERO;
        fDpCompPa := DL_ZERO;
        _bSnapDone := FALSE;
        _ePhase := E_DL_AltPhase.eCharge;
    ELSIF rtTest.Q AND (_bFault OR _bCfgBad OR _bNonFin) THEN
        _bFault := TRUE;                 // 带病启动拒绝
        _uFault := 16#0006_02C2;
        bError  := TRUE;
        _ePhase := E_DL_AltPhase.eFault;
    END_IF

E_DL_AltPhase.eCharge:
    bChargeCmd := TRUE;
    IF _bNonFin THEN
        _bFault := TRUE;
        _uFault := 16#0006_02C2;
        bError  := TRUE;
        _ePhase := E_DL_AltPhase.eFault;
    ELSIF fPressPa >= fTestPressPa THEN
        bChargeCmd := FALSE;
        _ePhase := E_DL_AltPhase.eStabilize;     // 迁出条件 1：测试压力达成
    ELSIF tonChargeTo.Q THEN
        _bFault := TRUE;                 // 迁出条件 2（故障路）：充压超时
        _uFault := 16#0006_02C2;
        bError  := TRUE;
        bChargeCmd := FALSE;
        _ePhase := E_DL_AltPhase.eFault;
    END_IF

E_DL_AltPhase.eStabilize:
    bChargeCmd := FALSE;
    IF _bNonFin THEN
        _bFault := TRUE;
        _uFault := 16#0006_02C2;
        bError  := TRUE;
        _ePhase := E_DL_AltPhase.eFault;
    ELSIF tonStabDur.Q THEN
        _bSnapDone := FALSE;
        _ePhase := E_DL_AltPhase.eMeasure;   // 稳压驻留完成：进测量相
    END_IF

E_DL_AltPhase.eMeasure:
    bChargeCmd := FALSE;
    IF _bNonFin THEN
        _bFault := TRUE;
        _uFault := 16#0006_02C2;
        bError  := TRUE;
        _ePhase := E_DL_AltPhase.eFault;
    ELSIF fPressPa < fPressMinPa THEN
        _bFault := TRUE;                 // 测量段压力跌破下限：充压丢失
        _uFault := 16#0006_02C2;
        bError  := TRUE;
        _ePhase := E_DL_AltPhase.eFault;
    ELSIF NOT _bSnapDone THEN
        _fP1Pa := fPressPa;              // 窗始双快照：进相首拍写定（锁存回放不重扫）
        _fT1C  := fTempC;
        _bSnapDone := TRUE;
    ELSIF tonMeasDur.Q THEN
        (* 温度补偿判级：绝对温标折算，除子 = 绝对温度/测量时长，域闸均已过 *)
        _fT1K := _fT1C + DL_KELVIN_OFF;
        _fT2K := fTempC + DL_KELVIN_OFF;
        IF (_fT1K >= DL_T_ABS_MIN) AND (_fT2K >= DL_T_ABS_MIN) THEN
            fDpCompPa := _fP1Pa - (fPressPa * _fT1K / _fT2K);   // 补偿压降
            fLeakRatePaLs := MAX(fDpCompPa, DL_ZERO) * fVolumeL
                             / MAX(TIME_TO_REAL(tMeasDur) / DL_MS_PER_S, DL_MEAS_MIN_S);
            bTestPass := fLeakRatePaLs <= fLeakLimPaLs;
            uErrId := 16#0006_01C2;      // 信息级：结论写定沿
            _ePhase := E_DL_AltPhase.eDone;
        ELSE
            _bFault := TRUE;             // 绝对温度越下限：判据不可信
            _uFault := 16#0006_02C2;
            bError  := TRUE;
            _ePhase := E_DL_AltPhase.eFault;
        END_IF
    END_IF

E_DL_AltPhase.eDone:
    bChargeCmd := FALSE;
    IF NOT bTestCmd THEN
        _ePhase := E_DL_AltPhase.eIdle;  // 测试指令撤销：回空闲（结论锁存保留）
    END_IF

E_DL_AltPhase.eFault:
    bChargeCmd := FALSE;                 // 故障相：充压指令安全侧撤销
    bError := TRUE;
    ;                                    // 故障相驻留：只认复位沿（段 2 迁出）

ELSE
    _bFault := TRUE;                     // 兜底：非法相位锁存
    _uFault := 16#0006_02C2;
    bError  := TRUE;
    _ePhase := E_DL_AltPhase.eFault;
END_CASE

(* —— 段 5｜相位出口单点映射 —— *)
ePhase := _ePhase;
END_FUNCTION_BLOCK

// ==============================================================================
// 组件名 Component  : FC_DL_StringEditDistance
// 分类   Category   : DL_Base
// 前缀   Naming     : FC_DL_ ｜ b/n/f/c/s 类型前缀制（R265）
// 版本   Version    : 1.0.0
// 复杂度 Complexity : 中
// 功能   Purpose    : 两串编辑距离（Levenshtein，插入 / 删除 / 替换各记 1）：
//                      滚动单行动态规划，上一行整型数组暂存（空间 O(64)）；
//                      空串处理：一方为空返回另一方长度，双空返回 0；
//                      大小写可选（bCaseSense 默认敏感）。纯 ST 手写 DP，
//                      不调平台专有函数。
// 开源溯源 Origin    : 道莅原创（编辑距离为公开经典算法定义，本实现
//                      clean-room，未复制任何源码行）
// 许可证 License    : MIT
// 参考   Reference  : IEC 61131-3:2013 §6.6.4 FOR 遍历与数组语义；
//                      Levenshtein 距离公开算法定义（借定义，不抄实现）
// 平台   Platform   : 纯 IEC 61131-3（FOR / 数组 / LEN / MID / FIND），三平台通用
// 依赖   Depends    : 无（零委托、零库件；LEN / MID / FIND 为 IEC 标准函数）
// 分工声明 Split     : FC_DL_StringWildMatch（通配匹配）与本件互引；本件量化
//                      两串差异度，彼件判定模式命中，语义互补不重叠（R216）。
// 归属 Ownership     : 本件无 TYPE 声明；全部引脚为 IEC 标准原生类型。
// ------------------------------------------------------------------
// 边界 Boundary     :
//   一 长度一次锁存：LEN 各取一次；STRING(64) 声明容量即上限，实测长度触
//      64 上界即视为调用方侧可能已截断 → bTooLong 置位（信息语义，距离仍
//      按现内容计算，bValid 不受影响）；
//   二 DP 行数组 aPrev[0..64] 全容量恒等预置为行 0；nLenB <= 64 已证，
//      aPrev 下标 [0, nLenB] 不越界；内层左邻取 aPrev[nJ-1]（nJ >= 1 已证
//      下标 >= 0）；
//   三 大小写折叠只用 FIND 定位 + MID 取字（域内字符恒命中，nPos 在
//      1..26 内），域外字符不折叠直比；
//   四 空串口径：nLenA = 0 时外层整段跳过，行 0 恒等即为结果行，
//      nDist = nLenB（等价另一方长度），双空 → 0，无需特判分支；
//   五 纯函数：无记忆量、无定时器、无边沿实例，每调用重算；
//   六 无除法；无全局、无外部变量、无物理地址。
// 错误码 Codes      :
//   16#0001_0740【信息级】任一串长度触 64 声明上限，可能已被调用方截断
//                （bTooLong = TRUE，bValid 保持 TRUE，距离按现内容给出）
//   注：本件引脚契约按任务定稿无独立 eErr 出口，故障语义经出口组合表达；
//   bValid = FALSE 无可达路径（本件恒可用，防御性异常长度已钳零吸收）。
// 验收 Acceptance   :
//   算法已证（脚本）：未跑 ｜ 编译器已证（三平台）：未跑
//   V1 kitten / sitting → 3
//   V2 空串 / abc → 3；V3 双空 → 0
//   V4 bCaseSense = FALSE 时 abc / ABC → 0
//   V5 64 字符串 → bTooLong = TRUE 且 bValid = TRUE、距离可用
// 修订记录 Revision  :
//   2026-11-22  v1.0.0  R65 首版（批 1 · 序号 1）
// ==============================================================================
FUNCTION FC_DL_StringEditDistance : BOOL
VAR_INPUT
    sA         : STRING(64);       // 串 A [字符] / string A [chars]
    sB         : STRING(64);       // 串 B [字符] / string B [chars]
    bCaseSense : BOOL := TRUE;     // 大小写敏感开关，默认敏感 [-] / case sensitivity switch, sensitive by default
END_VAR
VAR_OUTPUT
    nDist    : INT;                // 编辑距离 [次]，插入 / 删除 / 替换各记 1 / the edit distance in operations
    bValid   : BOOL;               // 结果可用标志 [-]，本件恒 TRUE / the result usable flag, always true here
    bTooLong : BOOL;               // 触 64 上限提示 [-]（信息级 0740）/ the at-cap flag, informational
END_VAR
VAR
    aPrev   : ARRAY[0..64] OF INT; // DP 上一行整型数组 [次]，行 0 恒等预置 / the previous DP row, row zero preset to identity
    nLenA   : INT;                 // 锁存的串 A 长度 [字符] / the latched length of string A
    nLenB   : INT;                 // 锁存的串 B 长度 [字符] / the latched length of string B
    nI      : INT;                 // 外层行索引（串 A 方向）[字符] / the outer row index along string A
    nJ      : INT;                 // 内层列索引（串 B 方向）[字符] / the inner column index along string B
    nDiag   : INT;                 // 对角缓存 dp[i-1][j-1] [次] / the diagonal staging value
    nUp     : INT;                 // 上邻缓存 dp[i-1][j] [次] / the upper neighbor staging value
    nBest   : INT;                 // 当前三选一最小值 [次] / the current minimum of the three candidates
    cA      : STRING(1);           // 串 A 当前字符 [字符] / the current char of string A
    cB      : STRING(1);           // 串 B 当前字符 [字符] / the current char of string B
    cAf     : STRING(1);           // 折叠后串 A 字符 [字符] / the case folded char of string A
    cBf     : STRING(1);           // 折叠后串 B 字符 [字符] / the case folded char of string B
    nPos    : INT;                 // 码表定位 [索引]，1 起 / the table position, one based
    bEq     : BOOL;                // 当前字符对相等标志 [-] / the equality flag of the char pair
END_VAR
VAR CONSTANT
    DL_SED_NMAX : INT := 64;       // 串长上限 [字符]，与形参声明一致 / the string cap aligned with the declarations
    DL_SED_ONE  : INT := 1;        // 整型一常量 [字符] / the integer one constant
END_VAR

// 段 1｜返回值与全部出口预置（R45 四段式第一段）/ segment 1, the preset of the return and all outlets
FC_DL_StringEditDistance := FALSE; // 返回值预置假 / preset the return false
nDist    := 0;                     // 距离预置零 [次] / preset the distance zero
bValid   := TRUE;                  // 有效标志预置真（本件恒可用）/ preset valid, always usable
bTooLong := FALSE;                 // 触界提示预置假 / preset the cap flag false

// 段 2｜长度一次锁存 + 触界提示（边界一）/ segment 2, latch the lengths once with the cap flag
nLenA := LEN(sA);                  // 串 A 长度 [字符] / the length of string A
nLenB := LEN(sB);                  // 串 B 长度 [字符] / the length of string B
IF nLenA < 0 THEN                  // 防御性异常长度（结构性不可达）/ a defensive anomalous length
    nLenA := 0;                    // 异常返回值钳零 / clamp the anomalous value to zero
END_IF
IF nLenB < 0 THEN                  // 防御性异常长度（结构性不可达）/ a defensive anomalous length
    nLenB := 0;                    // 异常返回值钳零 / clamp the anomalous value to zero
END_IF
IF (nLenA >= DL_SED_NMAX) OR (nLenB >= DL_SED_NMAX) THEN // 任一串触声明上限 / either string at the declared cap
    bTooLong := TRUE;              // 触上限提示（信息级 0740，可能已截断）/ the at-cap flag raised
END_IF

// 段 3｜DP 行 0 恒等预置（边界二）/ segment 3, the DP row zero identity preset
FOR nJ := 0 TO DL_SED_NMAX DO      // 全容量有界遍历 / the full capacity bounded traversal
    aPrev[nJ] := nJ;               // 行 0：dp[0][j] = j [次] / row zero, dp[0][j] equals j
END_FOR

// 段 4｜滚动单行 DP 主循环（边界四：nLenA = 0 时整段跳过即空串口径）/ segment 4, the rolling single row DP
FOR nI := 1 TO nLenA DO            // 串 A 方向逐行 / row by row along string A
    nDiag := aPrev[0];             // 对角缓存 dp[i-1][0]（覆盖前先存）/ stage the diagonal before the overwrite
    aPrev[0] := nI;                // 首列 dp[i][0] = i [次] / the first column
    FOR nJ := 1 TO nLenB DO        // 串 B 方向逐列 / column by column along string B
        nUp := aPrev[nJ];          // 上邻 dp[i-1][j] 暂存 [次] / stage the upper neighbor
        cA := MID(sA, DL_SED_ONE, nI); // 取串 A 当前字符 / take the current char of string A
        cB := MID(sB, DL_SED_ONE, nJ); // 取串 B 当前字符 / take the current char of string B
        cAf := cA;                 // 折叠暂存默认原值 / the folded staging defaults to the original
        cBf := cB;                 // 折叠暂存默认原值 / the folded staging defaults to the original
        IF NOT bCaseSense THEN     // 大小写不敏感才折叠（边界三）/ fold only when insensitive
            IF (cA >= 'A') AND (cA <= 'Z') THEN // 串 A 字符在大写域内 / the char of A in the uppercase domain
                nPos := FIND('ABCDEFGHIJKLMNOPQRSTUVWXYZ', cA); // 大写码表定位（域内恒命中 1..26）/ locate in the uppercase table
                cAf := MID('abcdefghijklmnopqrstuvwxyz', DL_SED_ONE, nPos); // 同位取小写 / the same position lowercase
            END_IF
            IF (cB >= 'A') AND (cB <= 'Z') THEN // 串 B 字符在大写域内 / the char of B in the uppercase domain
                nPos := FIND('ABCDEFGHIJKLMNOPQRSTUVWXYZ', cB); // 大写码表定位 / locate in the uppercase table
                cBf := MID('abcdefghijklmnopqrstuvwxyz', DL_SED_ONE, nPos); // 同位取小写 / the same position lowercase
            END_IF
        END_IF
        bEq := (cAf = cBf);        // 折叠后比对（边界三）/ the folded compare
        IF bEq THEN                // 字符相等 / the chars equal
            nBest := nDiag;        // 取对角（零代价）[次] / take the diagonal, zero cost
        ELSE                       // 字符不等 / the chars differ
            nBest := nDiag + DL_SED_ONE;          // 替换代价 [次] / the substitution cost
            IF (nUp + DL_SED_ONE) < nBest THEN    // 删除代价更小 / the deletion cost is smaller
                nBest := nUp + DL_SED_ONE;        // 取删除代价 [次] / take the deletion cost
            END_IF
            IF (aPrev[nJ - 1] + DL_SED_ONE) < nBest THEN // 插入代价更小（左邻已为本行新值）/ the insertion cost is smaller
                nBest := aPrev[nJ - 1] + DL_SED_ONE;     // 取插入代价 [次] / take the insertion cost
            END_IF
        END_IF
        nDiag := nUp;              // 对角推进（先存后写，滚动关键序）/ advance the diagonal before the overwrite
        aPrev[nJ] := nBest;        // 写当前行当前列 [次]（下标 nJ <= 64 已证）/ write the current cell
    END_FOR
END_FOR

// 段 5｜出口装配（边界四：空串口径由行 0 恒等自然成立）/ segment 5, the outlet assembly
nDist := aPrev[nLenB];             // 距离出口 [次]（nLenB = 0 时取 aPrev[0]）/ the distance outlet
FC_DL_StringEditDistance := TRUE;  // 返回成功 / return success
END_FUNCTION

// ==============================================================================
// 组件名 Component  : FC_DL_StringWildMatch
// 分类   Category   : DL_Base
// 前缀   Naming     : FC_DL_ ｜ b/n/c/s 类型前缀制（R265）
// 版本   Version    : 1.0.0
// 复杂度 Complexity : 中
// 功能   Purpose    : 通配符匹配：'*' 匹配任意长度（含空），'?' 匹配单个
//                      字符，其余字符直比。迭代双指针算法（无递归），记录
//                      最后一次 '*' 位置用于失配回溯；连续 '*' 允许并按折叠
//                      语义天然处理（重复推进模式指针即可）。大小写可选
//                      （bCaseSense 默认敏感，由调用方传参决定，无默认折叠）。
// 开源溯源 Origin    : 道莅原创（通配匹配双指针回溯为公开经典算法语义，
//                      本实现 clean-room，未复制任何源码行）
// 许可证 License    : MIT
// 参考   Reference  : IEC 61131-3:2013 §6.6.4 WHILE / FOR 遍历语义；
//                      单 '*' 回溯双指针公开算法定义（借定义，不抄实现）
// 平台   Platform   : 纯 IEC 61131-3（WHILE / FOR / LEN / MID / FIND），三平台通用
// 依赖   Depends    : 无（零委托、零库件；LEN / MID / FIND 为 IEC 标准函数）
// 分工声明 Split     : FC_DL_StringEditDistance（编辑距离量化）与本件互引；
//                      本件判定模式命中与否，彼件量化差异度，互补不重叠（R216）。
// 归属 Ownership     : 本件无 TYPE 声明；全部引脚为 IEC 标准原生类型。
// ------------------------------------------------------------------
// 边界 Boundary     :
//   一 长度一次锁存：STRING(64) 声明容量即上限，实测长度触 64 上界即视为
//      调用方侧可能已截断 → bValid = FALSE 拒绝判定（保守拒绝，不输出
//      存疑匹配结果）；
//   二 无递归：双指针 + 单星回溯点（nStarP / nStarT），每次回溯 nStarT
//      单调递增且 nT 归位 nStarT，全程终止有证；WHILE 带计数护栏
//      nGuard（上界 4096，远大于最坏 2*(64+64) 指针步数），护栏命中强制
//      失配退出（结构性不可达兜底，不静默死循环）；
//   三 尾部模式核查：文本耗尽后剩余模式必须全为 '*' 才命中（FOR 扫描），
//      防止 "a*b" 类模式对短文本误报命中；
//   四 大小写折叠只用 FIND 定位 + MID 取字（域内恒命中），域外字符不折叠
//      直比；'?' 不参与折叠（单字符任意匹配语义优先）；
//   五 空串口径：空模式只命中空文本（尾部核查自然覆盖）；空文本对 '*'
//      结尾模式命中；
//   六 纯函数：无记忆量、无定时器、无边沿实例，每调用重算；
//   七 无除法；无全局、无外部变量、无物理地址。
// 错误码 Codes      :
//   16#0001_0742【信息级】任一串长度触 64 声明上限视为可能截断
//                （bValid = FALSE 拒绝判定，bMatch 置 FALSE）
//   注：本件引脚契约按任务定稿无独立 eErr 出口，故障语义经出口组合表达；
//   护栏命中与 bValid 通道无关（结构性不可达兜底，仅强制 bMatch = FALSE）。
// 验收 Acceptance   :
//   算法已证（脚本）：未跑 ｜ 编译器已证（三平台）：未跑
//   V1 "a*c" / "abbbc" → TRUE；V2 "a?c" / "abc" → TRUE；V3 "a?c" / "abbc" → FALSE
//   V4 "**" 折叠连续星 / 任意串 → TRUE；V5 "a*" / "" → TRUE；V6 "" / "" → TRUE
//   V7 "a*b" / "abbc" → FALSE（尾部核查）；V8 64 字符串 → bValid = FALSE
// 修订记录 Revision  :
//   2026-11-22  v1.0.0  R65 首版（批 1 · 序号 2）
// ==============================================================================
FUNCTION FC_DL_StringWildMatch : BOOL
VAR_INPUT
    sPat       : STRING(64);   // 模式串 [字符]，'*' 任意长度 / '?' 单字符 / the pattern string
    sTxt       : STRING(64);   // 文本串 [字符] / the text string
    bCaseSense : BOOL := TRUE; // 大小写敏感开关，默认敏感 [-] / case sensitivity switch, sensitive by default
END_VAR
VAR_OUTPUT
    bMatch : BOOL;             // 匹配结果 [-]，TRUE = 命中 / the match result, true means hit
    bValid : BOOL;             // 结果可用 [-]，任一串触 64 上限（可能截断）为 FALSE / the validity flag, false when possibly truncated
END_VAR
VAR
    nPatLen : INT;             // 锁存的模式串长度 [字符] / the latched pattern length
    nTxtLen : INT;             // 锁存的文本串长度 [字符] / the latched text length
    nP      : INT;             // 模式指针 [字符位序]，1 起 / the pattern pointer, one based
    nT      : INT;             // 文本指针 [字符位序]，1 起 / the text pointer, one based
    nStarP  : INT;             // 最后一次 '*' 的模式位序 [字符位序]，0 = 无 / the last star pattern position, zero means none
    nStarT  : INT;             // 该 '*' 已吞噬到的文本位序 [字符位序] / the text position consumed by that star
    nGuard  : INT;             // 循环护栏计数 [次] / the loop guard counter
    nK      : INT;             // 尾部模式扫描索引 [字符位序] / the trailing pattern scan index
    nPos    : INT;             // 码表定位 [索引]，1 起 / the table position, one based
    cP      : STRING(1);       // 模式当前字符 [字符] / the current pattern char
    cT      : STRING(1);       // 文本当前字符 [字符] / the current text char
    cPf     : STRING(1);       // 折叠后模式字符 [字符] / the case folded pattern char
    cTf     : STRING(1);       // 折叠后文本字符 [字符] / the case folded text char
    bRest   : BOOL;            // 剩余模式含非星字符标志 [-] / the flag that the rest contains a non star char
END_VAR
VAR CONSTANT
    DL_SWM_NMAX : INT := 64;   // 串长上限 [字符]，与形参声明一致 / the string cap aligned with the declarations
    DL_SWM_ONE  : INT := 1;    // 整型一常量 [字符] / the integer one constant
    DL_SWM_GMAX : INT := 4096; // 护栏计数上界 [次]，远大于最坏指针步数 256 / the guard bound far above the worst case
END_VAR

// 段 1｜返回值与全部出口预置（R45 四段式第一段）/ segment 1, the preset of the return and all outlets
FC_DL_StringWildMatch := FALSE; // 返回值预置假 / preset the return false
bMatch := FALSE;                // 匹配结果预置不命中 / preset the match false
bValid := FALSE;                // 有效标志预置假（段 2 按触界复核）/ preset the validity false

// 段 2｜长度一次锁存 + 触界截断闸（边界一）/ segment 2, latch lengths with the truncation gate
nPatLen := LEN(sPat);           // 模式串长度 [字符] / the pattern length
nTxtLen := LEN(sTxt);           // 文本串长度 [字符] / the text length
IF nPatLen < 0 THEN             // 防御性异常长度（结构性不可达）/ a defensive anomalous length
    nPatLen := 0;               // 异常返回值钳零 / clamp the anomalous value to zero
END_IF
IF nTxtLen < 0 THEN             // 防御性异常长度（结构性不可达）/ a defensive anomalous length
    nTxtLen := 0;               // 异常返回值钳零 / clamp the anomalous value to zero
END_IF
IF (nPatLen >= DL_SWM_NMAX) OR (nTxtLen >= DL_SWM_NMAX) THEN // 任一串触声明上限 / either string at the declared cap
    bMatch := FALSE;            // 可能截断，拒绝输出存疑匹配 / possibly truncated, refuse the doubtful match
    RETURN;                     // 早退（信息级 0742 通道即 bValid = FALSE）/ early return
END_IF
bValid := TRUE;                 // 触界闸通过，判定可用 / the gate passed, the verdict usable

// 段 3｜双指针主循环（边界二：单星回溯 + 护栏，无递归）/ segment 3, the two pointer main loop with the single star backtrack
nP := DL_SWM_ONE;               // 模式指针起始 [字符位序] / the pattern pointer start
nT := DL_SWM_ONE;               // 文本指针起始 [字符位序] / the text pointer start
nStarP := 0;                    // 回溯星位序清零（0 = 无）/ clear the star position
nStarT := 0;                    // 回溯星吞噬位清零 / clear the star consumed position
bMatch := TRUE;                 // 乐观预置，失配即断 / preset optimistic, break on mismatch
nGuard := 0;                    // 护栏清零 / reset the guard
WHILE nT <= nTxtLen DO          // 文本耗尽即出循环转尾部核查 / exit when the text is exhausted
    nGuard := nGuard + DL_SWM_ONE; // 护栏计数推进 / advance the guard
    IF nGuard > DL_SWM_GMAX THEN   // 护栏命中（结构性不可达兜底，边界二）/ the guard tripped, structurally unreachable
        bMatch := FALSE;           // 强制失配退出，禁死循环 / force the mismatch, no hang
        EXIT;                      // 断主循环 / break the main loop
    END_IF
    IF nP <= nPatLen THEN          // 模式未耗尽 / the pattern not exhausted
        cP := MID(sPat, DL_SWM_ONE, nP); // 取模式当前字符 / take the current pattern char
        cT := MID(sTxt, DL_SWM_ONE, nT); // 取文本当前字符 / take the current text char
        IF cP = '*' THEN           // 通配星：登记回溯点后推进模式指针（连续星折叠语义天然成立）/ a star, register the backtrack point
            nStarP := nP;          // 登记星位序 / register the star position
            nStarT := nT;          // 登记当前文本位序 / register the text position
            nP := nP + DL_SWM_ONE; // 模式指针推进 / advance the pattern pointer
        ELSE                       // 非星字符 / a non star char
            cPf := cP;             // 折叠暂存默认原值 / the folded staging defaults to the original
            cTf := cT;             // 折叠暂存默认原值 / the folded staging defaults to the original
            IF NOT bCaseSense THEN // 大小写不敏感才折叠（边界四）/ fold only when insensitive
                IF (cP >= 'A') AND (cP <= 'Z') THEN // 模式字符在大写域内 / the pattern char in the uppercase domain
                    nPos := FIND('ABCDEFGHIJKLMNOPQRSTUVWXYZ', cP); // 大写码表定位（域内恒命中）/ locate in the uppercase table
                    cPf := MID('abcdefghijklmnopqrstuvwxyz', DL_SWM_ONE, nPos); // 同位取小写 / the same position lowercase
                END_IF
                IF (cT >= 'A') AND (cT <= 'Z') THEN // 文本字符在大写域内 / the text char in the uppercase domain
                    nPos := FIND('ABCDEFGHIJKLMNOPQRSTUVWXYZ', cT); // 大写码表定位 / locate in the uppercase table
                    cTf := MID('abcdefghijklmnopqrstuvwxyz', DL_SWM_ONE, nPos); // 同位取小写 / the same position lowercase
                END_IF
            END_IF
            IF (cP = '?') OR (cPf = cTf) THEN // 问号单字符任意匹配或折叠后相等 / a question mark or the folded equality
                nP := nP + DL_SWM_ONE; // 双指针同步推进 / advance both pointers
                nT := nT + DL_SWM_ONE; // 双指针同步推进 / advance both pointers
            ELSIF nStarP > 0 THEN  // 失配但有回溯星：星多吞一个字符后重试 / a mismatch with a star, let the star swallow one more
                nStarT := nStarT + DL_SWM_ONE; // 星吞噬位递增 / advance the swallowed position
                nT := nStarT;      // 文本指针归位到星吞噬位 / reset the text pointer
                nP := nStarP + DL_SWM_ONE; // 模式指针归位到星后一位 / reset the pattern pointer
            ELSE                   // 失配且无回溯星 / a mismatch without any star
                bMatch := FALSE;   // 判定不命中 / the verdict is a miss
                EXIT;              // 断主循环 / break the main loop
            END_IF
        END_IF
    ELSIF nStarP > 0 THEN          // 模式已耗尽但有回溯星：星继续吞噬 / the pattern exhausted, the star swallows on
        nStarT := nStarT + DL_SWM_ONE; // 星吞噬位递增 / advance the swallowed position
        nT := nStarT;              // 文本指针归位 / reset the text pointer
        nP := nStarP + DL_SWM_ONE; // 模式指针归位 / reset the pattern pointer
    ELSE                           // 模式与文本均无余量且无星 / nothing left without a star
        bMatch := FALSE;           // 判定不命中 / the verdict is a miss
        EXIT;                      // 断主循环 / break the main loop
    END_IF
END_WHILE

// 段 4｜尾部模式核查（边界三：剩余模式必须全为 '*'）/ segment 4, the trailing pattern check
IF bMatch THEN                  // 主循环未失配才核查 / check only without a mismatch
    bRest := FALSE;             // 非星残留标志预置假 / preset the non star rest flag false
    FOR nK := nP TO nPatLen DO  // 剩余模式有界扫描 / the bounded scan of the rest
        IF MID(sPat, DL_SWM_ONE, nK) <> '*' THEN // 发现非星字符 / a non star char found
            bRest := TRUE;      // 置残留标志 / raise the rest flag
        END_IF
    END_FOR
    IF bRest THEN               // 剩余模式含非星字符 / the rest contains a non star char
        bMatch := FALSE;        // 判定不命中（防 "a*b" 对短文本误报）/ the verdict is a miss
    END_IF
END_IF

// 段 5｜出口装配 / segment 5, the outlet assembly
FC_DL_StringWildMatch := bValid; // 返回判定可用性 / return the verdict usability
END_FUNCTION

// ==============================================================================
// 组件名 Component  : FC_DL_ArrFillEx
// 分类   Category   : DL_Base
// 前缀   Naming     : FC_DL_ ｜ b/n/i/f 类型前缀制（R265）
// 版本   Version    : 1.0.0
// 复杂度 Complexity  : 低
// 功能   Purpose    : 定长 LREAL 数组区间填充：把 [iFrom, iTo] 闭区间各槽位
//                      写为 fVal；区间越界自动钳位（iFrom < 0 钳 0、
//                      iTo > 255 钳 255），iFrom > iTo 零填充合法返回；
//                      bFillNaN = FALSE 且 fVal 非有限时拒绝填充
//                      （bValid = FALSE，数组零写回）。供清屏 / 预置 /
//                      坏点填充类调用方使用。
// 开源溯源 Origin    : 西门子 LGF 分类语义借鉴，clean-room 重写（LGF
//                      Data Handling「定长缓冲批量写」分类学口径借鉴，只借
//                      骨不抄肉，实现零代码复制）
// 许可证 License    : MIT
// 参考   Reference  : IEC 61131-3:2013 §6.6.4 FOR 遍历与数组语义
// 平台   Platform   : 纯 IEC 61131-3（FOR / 数组 / 比较），三平台通用
// 依赖   Depends    : 无（零委托、零库件）
// 分工声明 Split     : FC_DL_ArrCopySeg（段拷贝）与本件互引；本件为常数填充
//                      （源是标量），彼件为数组段搬运（源是数组），语义正交
//                      （R216）。
// 归属 Ownership     : 本件无 TYPE 声明；全部引脚为 IEC 标准原生类型。
// ------------------------------------------------------------------
// 边界 Boundary     :
//   一 区间钳位闸（逐项点名，R272）：iFrom < 0 钳 0、iTo > 255 钳 255，
//      钳位后照常填充（信息级语义，bValid 保持 TRUE）；iFrom / iTo 反向
//      （含钳位后反向）→ 零填充合法返回（nFilled = 0、bValid = TRUE）；
//   二 非有限闸：fVal 为 NaN（自反判 x <> x）或 ±Inf（差值自反判
//      (x - x) <> (x - x)）且 bFillNaN = FALSE → bValid = FALSE、
//      nFilled = 0、数组零写回早退（R272 非有限防护）；bFillNaN = TRUE
//      时允许显式填充 NaN / Inf（调用方自担，bValid 保持 TRUE）；
//   三 填充序：FOR 闭区间顺序写，上界 iToC <= 255、下界 iFromC >= 0 已证
//      （钳位闸证明），下标越界不可达；
//   四 纯函数：无记忆量、无定时器、无边沿实例，每调用重算；
//   五 无除法；无全局、无外部变量、无物理地址。
// 错误码 Codes      :
//   16#0001_0743【信息级】区间越界已钳位续填（iFrom 钳 0 / iTo 钳 255，
//                bValid = TRUE，nFilled 反映实际填充数）
//   16#0001_0744【故障级】fVal 非有限且 bFillNaN = FALSE，拒绝填充
//                （bValid = FALSE、nFilled = 0、数组零写回）
//   注：本件引脚契约按任务定稿无独立 eErr 出口，上述码位为文档级语义，
//   经 bValid / nFilled 通道表达；钳位续填与正常填充出口同形（仅区间
//   收窄），无独立输出通道可承载，不另设出口位（R90 反证句）。
// 验收 Acceptance   :
//   算法已证（脚本）：未跑 ｜ 编译器已证（三平台）：未跑
//   V1 iFrom = 10、iTo = 20、fVal = 5.0 → 槽位 10..20 全为 5.0、nFilled = 11
//   V2 iFrom = -5 → 钳 0 续填；iTo = 300 → 钳 255 续填
//   V3 iFrom > iTo → nFilled = 0、bValid = TRUE、数组原样
//   V4 fVal = NaN、bFillNaN = FALSE → bValid = FALSE、零写回
//   V5 fVal = NaN、bFillNaN = TRUE → 填入 NaN、bValid = TRUE
// 修订记录 Revision  :
//   2026-11-22  v1.0.0  R65 首版（批 1 · 序号 3，LGF Data Handling 补口）
// ==============================================================================
FUNCTION FC_DL_ArrFillEx : BOOL
VAR_IN_OUT
    arrDst : ARRAY[0..255] OF LREAL; // 目标数组 [工程单位]，闭区间填充 / the target array filled over the closed range
END_VAR
VAR_INPUT
    iFrom    : INT;              // 填充起点 [下标]，闭区间含端点 / the fill start index, inclusive
    iTo      : INT;              // 填充终点 [下标]，闭区间含端点 / the fill end index, inclusive
    fVal     : LREAL;            // 填充值 [工程单位] / the fill value
    bFillNaN : BOOL := FALSE;    // 允许非有限填充开关 [-]，TRUE 时允许填 NaN / Inf / the non finite fill switch
END_VAR
VAR_OUTPUT
    nFilled : INT;               // 实际填充槽位数 [个] / the actually filled slot count
    bValid  : BOOL;              // 结果可用 [-]，拒绝填充为 FALSE / the result usable flag
END_VAR
VAR
    iFromC     : INT;            // 钳位后的填充起点 [下标] / the clamped fill start
    iToC       : INT;            // 钳位后的填充终点 [下标] / the clamped fill end
    k          : INT;            // 遍历索引 [下标] / the traversal index
    xNonFinite : BOOL;           // fVal 非有限标志 [-] / the non finite flag of fVal
END_VAR
VAR CONSTANT
    DL_AFE_NMAX : INT := 255;    // 数组容量上界 [个]，与数组容量一致 / the capacity aligned with the array
    DL_AFE_ZERO : INT := 0;      // 整型零常量 [个] / the integer zero constant
END_VAR

// 段 1｜返回值与全部出口预置（R45 四段式第一段）/ segment 1, the preset of the return and all outlets
FC_DL_ArrFillEx := FALSE;        // 返回值预置假 / preset the return false
nFilled := DL_AFE_ZERO;          // 填充数预置零 [个] / preset the filled count zero
bValid  := TRUE;                 // 有效标志预置真（零填充合法口径）/ preset valid, a legal zero fill

// 段 2｜区间钳位闸（边界一：iFrom 钳 0 / iTo 钳 255，逐项点名）/ segment 2, the range clamp gate
iFromC := iFrom;                 // 起点接管 / take the start
iToC   := iTo;                   // 终点接管 / take the end
IF iFromC < DL_AFE_ZERO THEN     // 起点下越界 / the start below the domain
    iFromC := DL_AFE_ZERO;       // 钳 0 续填（信息级 0743）/ clamp to zero and keep filling
END_IF
IF iToC > DL_AFE_NMAX THEN       // 终点上越界 / the end above the domain
    iToC := DL_AFE_NMAX;         // 钳 255 续填（信息级 0743）/ clamp to the cap and keep filling
END_IF

// 段 3｜反向区间闸：零填充合法返回（边界一）/ segment 3, the reversed range gate, a legal zero fill
IF iFromC > iToC THEN            // 起点 > 终点（含钳位后反向）/ the start above the end
    nFilled := DL_AFE_ZERO;      // 零填充 [个] / a zero fill
    FC_DL_ArrFillEx := TRUE;     // 合法返回 / return success
    RETURN;                      // 早退，数组零写回 / early return untouched
END_IF

// 段 4｜非有限闸（边界二：NaN 自反判 + Inf 差值自反判，R272）/ segment 4, the non finite gate
xNonFinite := (fVal <> fVal) OR ((fVal - fVal) <> 0.0); // NaN 或 ±Inf / NaN or infinity
IF (NOT bFillNaN) AND xNonFinite THEN // 未允许且非有限 / not allowed and non finite
    bValid  := FALSE;            // 拒绝填充（故障级 0744）/ refuse the fill
    nFilled := DL_AFE_ZERO;      // 填充数归零 [个] / zero the count
    FC_DL_ArrFillEx := FALSE;    // 返回失败 / return failure
    RETURN;                      // 早退，数组零写回 / early return untouched
END_IF

// 段 5｜闭区间顺序填充（边界三：上界已证 <= 255、下界已证 >= 0）/ segment 5, the ordered closed range fill
FOR k := iFromC TO iToC DO       // 有界遍历 / the bounded traversal
    arrDst[k] := fVal;           // 槽位写入 [工程单位] / write the slot
END_FOR

// 段 6｜统一出口 / segment 6, the unified outlet
nFilled := iToC - iFromC + 1;    // 实际填充数 [个] / the actually filled count
FC_DL_ArrFillEx := TRUE;         // 返回成功 / return success
END_FUNCTION

// ==============================================================================
// 组件名 Component  : FC_DL_ArrCopySeg
// 分类   Category   : DL_Base
// 前缀   Naming     : FC_DL_ ｜ b/n/i/f 类型前缀制（R265）
// 版本   Version    : 1.0.0
// 复杂度 Complexity  : 低
// 功能   Purpose    : 定长 LREAL 数组段拷贝：把源数组 [iSrcFrom ..] 起的
//                      nCnt 个元素拷到目标数组 [iDstFrom ..] 起；nCnt <= 0
//                      零拷贝合法；源 / 目标越界自动截断 nCnt，bTrunc 置位
//                      报告截断，nCopied 反映实际拷贝数（bValid 保持 TRUE）。
//                      供缓冲搬运 / 窗段平移 / 队列重组类调用方使用。
// 开源溯源 Origin    : 西门子 LGF 分类语义借鉴，clean-room 重写（LGF
//                      Data Handling「定长缓冲搬运（无动态内存）」分类学
//                      口径借鉴，只借骨不抄肉，实现零代码复制）
// 许可证 License    : MIT
// 参考   Reference  : IEC 61131-3:2013 §6.6.4 FOR 遍历与数组语义
// 平台   Platform   : 纯 IEC 61131-3（FOR / 数组 / 比较），三平台通用
// 依赖   Depends    : 无（零委托、零库件）
// 分工声明 Split     : FC_DL_ArrFillEx（常数填充）与本件互引；本件为数组段
//                      搬运（源是数组），彼件为常数填充（源是标量），语义
//                      正交（R216）。与 FC_DL_ArraySliceCopy（DL_MathData）
//                      分工：彼件从下标 0 起承接且对越域判故障早退，本件
//                      支持任意目标起点且对越界截断续行（bTrunc 报告），
//                      口径不同勿混用（R216）。
// 归属 Ownership     : 本件无 TYPE 声明；全部引脚为 IEC 标准原生类型。
// ------------------------------------------------------------------
// 边界 Boundary     :
//   一 零拷贝闸：nCnt <= 0 → nCopied = 0、bValid = TRUE、数组零写回
//      （合法语义不是故障）；
//   二 截断闸（逐项点名，R272）：iSrcFrom < 0 / iDstFrom < 0 钳 0 置
//      bTrunc；nCnt 超过源余量（255 - iSrcC）或目标余量（255 - iDstC）
//      时截到较小余量并置 bTrunc；起点越出容量（> 255）时余量为负、
//      nUse <= 0 → 零拷贝 + bTrunc（bValid 保持 TRUE，截断是信息级）；
//   三 重叠自检（中转缓冲两段式）：先把源段整段读入局部 afStaging，再
//      整段写回目标——arrSrc 与 arrDst 为同一数组且区间重叠的别名调用
//      也不产生撕裂 / 串写（快照语义，真实可达：调用方传同一数组做段
//      平移）；此为机制性防重叠，非永假防御；
//   四 拷贝序：读侧 / 写侧循环上界由段 2 截断闸证明 <= 255，下标越界
//      不可达；
//   五 纯函数：无记忆量、无定时器、无边沿实例，每调用重算；
//   六 无除法、无浮点比较；无全局、无外部变量、无物理地址。
// 错误码 Codes      :
//   16#0001_0745【信息级】段越界自动截断（起点钳位或 nCnt 截到余量，
//                bTrunc = TRUE、bValid = TRUE、nCopied 反映实际拷贝数）
//   注：本件引脚契约按任务定稿无独立 eErr 出口，截断语义经 bTrunc /
//   nCopied 双通道表达；零拷贝与截断为零的出口同形（bTrunc 区分），
//   不另设码（R90 反证句）。
// 验收 Acceptance   :
//   算法已证（脚本）：未跑 ｜ 编译器已证（三平台）：未跑
//   V1 源 [1..5]、iSrcFrom = 1、iDstFrom = 10、nCnt = 3 → 目标槽 10..12
//      为 [2,3,4]、nCopied = 3、bTrunc = FALSE
//   V2 nCnt = 0 / 负数 → nCopied = 0、bValid = TRUE、bTrunc = FALSE
//   V3 iSrcFrom = 250、nCnt = 10 → 截到 6、bTrunc = TRUE
//   V4 iSrcFrom = -3 → 钳 0 续拷、bTrunc = TRUE
//   V5 iDstFrom = 300 → nCopied = 0、bTrunc = TRUE
//   V6 别名调用：同一数组段平移 → 中转缓冲两段式无撕裂（V1 断言不变）
// 修订记录 Revision  :
//   2026-11-22  v1.0.0  R65 首版（批 1 · 序号 4，LGF Data Handling 补口）
// ==============================================================================
FUNCTION FC_DL_ArrCopySeg : BOOL
VAR_IN_OUT
    arrSrc : ARRAY[0..255] OF LREAL; // 源数组 [工程单位]，允许与目标同数组（别名调用走中转缓冲）/ the source array, may alias the target
    arrDst : ARRAY[0..255] OF LREAL; // 目标数组 [工程单位]，从 iDstFrom 起承接 / the target array receiving from iDstFrom
END_VAR
VAR_INPUT
    iSrcFrom : INT := 0;         // 源段起点 [下标]，负值钳 0 / the source start index, negative clamped
    iDstFrom : INT := 0;         // 目标段起点 [下标]，负值钳 0 / the target start index, negative clamped
    nCnt     : INT := 0;         // 请求拷贝数 [个]，<= 0 零拷贝合法 / the requested count, zero or less is a legal no op
END_VAR
VAR_OUTPUT
    nCopied : INT;               // 实际拷贝数 [个] / the actually copied count
    bValid  : BOOL;              // 结果可用 [-]，本件恒 TRUE（截断为信息级）/ the validity flag, always true here
    bTrunc  : BOOL;              // 截断报告 [-]，TRUE = 发生钳位或截断 / the truncation flag
END_VAR
VAR
    iSrcC     : INT;             // 钳位后的源起点 [下标] / the clamped source start
    iDstC     : INT;             // 钳位后的目标起点 [下标] / the clamped target start
    nAvail    : INT;             // 源 / 目标余量的较小值 [个] / the smaller of the two remainders
    nUse      : INT;             // 实际拷贝数暂存 [个] / the staged copy count
    k         : INT;             // 遍历索引 [下标] / the traversal index
    afStaging : ARRAY[0..255] OF LREAL; // 中转缓冲 [工程单位]，两段式防重叠撕裂 / the staging buffer for the overlap safe two stage copy
END_VAR
VAR CONSTANT
    DL_ACP_NMAX : INT := 255;    // 数组容量上界 [个]，与数组容量一致 / the capacity aligned with the array
    DL_ACP_ZERO : INT := 0;      // 整型零常量 [个] / the integer zero constant
END_VAR

// 段 1｜返回值与全部出口预置 + 中转缓冲清零（R45 四段式第一段）/ segment 1, the preset and the staging clear
FC_DL_ArrCopySeg := FALSE;       // 返回值预置假 / preset the return false
nCopied := DL_ACP_ZERO;          // 拷贝数预置零 [个] / preset the copied count zero
bValid  := TRUE;                 // 有效标志预置真（截断为信息级口径）/ preset valid
bTrunc  := FALSE;                // 截断标志预置假 / preset the truncation flag false
FOR k := DL_ACP_ZERO TO DL_ACP_NMAX DO // 中转缓冲全量预清零 / preset the staging buffer zero
    afStaging[k] := 0.0;         // 缓冲槽位显式清零 [工程单位] / clear the staging slot explicitly
END_FOR

// 段 2｜截断闸第一段：负起点钳 0 置 bTrunc（边界二，逐项点名）/ segment 2, the clamp of negative starts
iSrcC := iSrcFrom;               // 源起点接管 / take the source start
iDstC := iDstFrom;               // 目标起点接管 / take the target start
IF iSrcC < DL_ACP_ZERO THEN      // 源起点下越界 / the source start below the domain
    iSrcC := DL_ACP_ZERO;        // 钳 0 续拷（信息级 0745）/ clamp to zero and keep copying
    bTrunc := TRUE;              // 置截断报告 / raise the truncation flag
END_IF
IF iDstC < DL_ACP_ZERO THEN      // 目标起点下越界 / the target start below the domain
    iDstC := DL_ACP_ZERO;        // 钳 0 续拷（信息级 0745）/ clamp to zero and keep copying
    bTrunc := TRUE;              // 置截断报告 / raise the truncation flag
END_IF

// 段 3｜零拷贝闸（边界一：nCnt <= 0 合法，数组零写回）/ segment 3, the zero copy gate
IF nCnt <= DL_ACP_ZERO THEN      // 请求拷贝数非正 / the requested count non positive
    nCopied := DL_ACP_ZERO;      // 零拷贝 [个] / a zero copy
    FC_DL_ArrCopySeg := TRUE;    // 合法返回 / return success
    RETURN;                      // 早退，数组零写回 / early return untouched
END_IF

// 段 4｜截断闸第二段：nCnt 截到源 / 目标余量较小值（边界二）/ segment 4, the truncation to the smaller remainder
nAvail := DL_ACP_NMAX - iSrcC;   // 源余量 [个] / the source remainder
IF (DL_ACP_NMAX - iDstC) < nAvail THEN // 目标余量更小 / the target remainder smaller
    nAvail := DL_ACP_NMAX - iDstC; // 取目标余量 [个] / take the target remainder
END_IF
nUse := nCnt;                    // 请求拷贝数接管 [个] / take the requested count
IF iSrcC > DL_ACP_NMAX THEN      // 源起点越出容量 / the source start beyond the capacity
    bTrunc := TRUE;              // 置截断报告（余量为负，落零拷贝）/ raise the truncation flag
END_IF
IF iDstC > DL_ACP_NMAX THEN      // 目标起点越出容量 / the target start beyond the capacity
    bTrunc := TRUE;              // 置截断报告 / raise the truncation flag
END_IF
IF nUse > nAvail THEN            // 请求量超余量 / the request above the remainder
    nUse := nAvail;              // 截到余量（信息级 0745）/ truncate to the remainder
    bTrunc := TRUE;              // 置截断报告 / raise the truncation flag
END_IF
IF nUse <= DL_ACP_ZERO THEN      // 截断后为非正（起点越出容量路径）/ the truncated count non positive
    nCopied := DL_ACP_ZERO;      // 零拷贝 [个] / a zero copy
    FC_DL_ArrCopySeg := TRUE;    // 合法返回 / return success
    RETURN;                      // 早退，数组零写回 / early return untouched
END_IF

// 段 5｜中转缓冲承接源段（边界三：两段式第一段，读侧快照）/ segment 5, the staging takes the source segment
FOR k := DL_ACP_ZERO TO nUse - 1 DO // 有界遍历（上界 = nUse - 1 <= 254 已证）/ the bounded traversal
    afStaging[k] := arrSrc[iSrcC + k]; // 源段读入缓冲 [工程单位]（下标 <= 255 已证）/ read the source into the staging
END_FOR

// 段 6｜缓冲写回目标段（边界三：两段式第二段，写侧顺序落位）/ segment 6, the staging lands on the target
FOR k := DL_ACP_ZERO TO nUse - 1 DO // 有界遍历（上界同段 5 已证）/ the bounded traversal
    arrDst[iDstC + k] := afStaging[k]; // 缓冲整段写回目标 [工程单位]（下标 <= 255 已证）/ land the staging onto the target
END_FOR

// 段 7｜统一出口 / segment 7, the unified outlet
nCopied := nUse;                 // 实拷贝数出口 [个] / the copied count outlet
FC_DL_ArrCopySeg := TRUE;        // 返回成功 / return success
END_FUNCTION

// ==============================================================================
// 组件名 Component  : FC_DL_SortIndexInt
// 分类   Category   : DL_Base
// 前缀   Naming     : FC_DL_ ｜ b/n/f 类型前缀制（R265）
// 版本   Version    : 1.0.0
// 复杂度 Complexity  : 中
// 功能   Purpose    : INT 数组稳定索引排序：输出按值排序后的原下标排列，
//                      不改 arrSrc（只读纪律）；bDesc = FALSE 升序 /
//                      TRUE 降序；等值元素保持原下标先后（稳定性判据 =
//                      严格比较 + 不交换等值对）。nUsed 钳位 [0, 64]。
// 开源溯源 Origin    : 道莅原创（与 DL_MathData 的 FC_DL_SortIndexLReal
//                      同族自研语义，索引间接排序实现，零代码复制）
// 许可证 License    : MIT
// 参考   Reference  : IEC 61131-3:2013 §6.6.4 FOR / WHILE 遍历语义
// 平台   Platform   : 纯 IEC 61131-3（FOR / WHILE / 比较 / 数组），三平台通用
// 依赖   Depends    : 无（零委托、零库件）
// 分工声明 Split     : FC_DL_SortIndexLReal（LREAL 版索引排序）为本件同族
//                      件，两件类型口径不同、语义同源，互引声明（R216）；
//                      本件只出索引排列不改数据，读写纪律与彼件一致。
// 归属 Ownership     : 本件无 TYPE 声明；全部引脚为 IEC 标准原生类型。
// ------------------------------------------------------------------
// 边界 Boundary     :
//   一 计数域闸：nUsed < 0 → 恒等索引早退合法返回（nSorted = 0）；nUsed
//      > 64 → 钳 64 续排（信息级语义，本件无 eErr 出口，钳位场景出口与
//      正常截断排序同形、无独立通道可承载，不另设码，R90 反证句）；
//   二 稳定性判据写死下标序：升序用严格大于、降序用严格小于前移，相等
//      元素不交换（插入序即下标序），升 / 降两向稳定性自证；
//   三 索引写出前已证在 [0, nUse-1] 内（arrIdx 恒等预置 + 插入原地移动），
//      回钳量不复判越界（R241）；
//   四 WHILE 护栏计数 nGuard（上界 32000，远大于最坏比较次数 64*63/2 =
//      2016，且 nGuard 为 INT 不溢出），护栏命中强制退出内层（结构性
//      不可达兜底，不静默死循环）；
//   五 INT 元素无非有限面（NaN / Inf 不适用于整型），非有限闸 N/A；
//   六 nUsed = 0 / 1 退化直返恒等索引（arrIdx[i] = i），bValid = TRUE；
//   七 纯函数：无记忆量、无定时器、无边沿实例，每调用重算；
//   八 无除法；无全局、无外部变量、无物理地址。
// 错误码 Codes      :
//   16#0001_0746【信息级】nUsed 越域已钳位（< 0 恒等早退，> 64 钳 64 续排）
//   注：本件引脚契约按任务定稿无独立 eErr 出口，钳位语义为文档级。
// 验收 Acceptance   :
//   算法已证（脚本）：未跑 ｜ 编译器已证（三平台）：未跑
//   V1 值 3/1/2 → 升序索引 1/2/0；V2 值 2/2/1 → 升序索引 2/0/1（稳定性）
//   V3 值 2/2/1 → 降序索引 0/1/2（降序稳定性同向自证）
//   V4 nUsed = 0 / 1 → 恒等索引；V5 nUsed = 100 → 钳 64 续排
//   V6 调用后 arrSrc 原样（只读纪律）
// 修订记录 Revision  :
//   2026-11-22  v1.0.0  R65 首版（批 2 · 序号 5）
// ==============================================================================
FUNCTION FC_DL_SortIndexInt : BOOL
VAR_IN_OUT
    arrSrc : ARRAY[0..63] OF INT; // 待排序数值 [-]，只读纪律（不改调用方数组）/ the values to sort, read only
END_VAR
VAR_INPUT
    nUsed : INT := 0;            // 参与排序个数 [个]，合法域 0..64 / the count, legal zero to sixty four
    bDesc : BOOL := FALSE;       // 降序开关 [-]，FALSE 升序 / the descending switch, false is ascending
END_VAR
VAR_OUTPUT
    arrIdx  : ARRAY[0..63] OF INT; // 排序后索引排列（arrIdx[0] 为极值原下标）/ the sorted index permutation
    nSorted : INT;               // 实际排序个数 [个] / the actually sorted count
    bValid  : BOOL;              // 结果可用 [-] / the result usable flag
END_VAR
VAR
    k       : INT;               // 外层插入索引 [下标] / the outer insertion index
    m       : INT;               // 内层前移索引 [下标] / the inner shifting index
    nUse    : INT;               // 钳位后的个数 [个] / the clamped count
    nKey    : INT;               // 待插元素原下标暂存 [下标] / the key original index in staging
    nKeyVal : INT;               // 待插元素值暂存 [-] / the key value in staging
    nGuard  : INT;               // 护栏计数 [次] / the guard counter
END_VAR
VAR CONSTANT
    DL_SII_NMAX : INT := 64;     // 排序容量上界 [个]，与数组容量一致 / the capacity aligned with the array
    DL_SII_GMAX : INT := 32000;  // 护栏计数上界 [次]，大于最坏比较次数 2016 且 INT 不溢出 / the guard bound above the worst case
END_VAR

// 段 1｜返回值与全部出口预置 + 索引数组恒等预置（R45 / R254）/ segment 1, the preset and the identity preset
FC_DL_SortIndexInt := FALSE;     // 返回值预置假 / preset the return false
nSorted := 0;                    // 排序个数预置零 [个] / preset the sorted count zero
bValid  := FALSE;                // 有效标志预置假 / preset the validity false
nUse    := 0;                    // 个数预置零 [个] / preset the count zero
nKey    := 0;                    // 键下标预置零 [下标] / preset the key index zero
nKeyVal := 0;                    // 键值预置零 / preset the key value zero
nGuard  := 0;                    // 护栏预置零 [次] / preset the guard zero
FOR k := 0 TO DL_SII_NMAX - 1 DO // 索引数组全量预置恒等 / preset the index array to the identity
    arrIdx[k] := k;              // 恒等索引 / the identity index
END_FOR

// 段 2｜计数域闸（边界一：负数恒等早退，超容量钳位续排）/ segment 2, the count domain gate
IF nUsed < 0 THEN                // 负数非法 / a negative count
    bValid := TRUE;              // 空排列合法（arrIdx 已全量恒等）/ an empty permutation is legal
    FC_DL_SortIndexInt := TRUE;  // 返回成功 / return success
    RETURN;                      // 早退（信息级 0746 语义，文档级）/ early return
END_IF
nUse := nUsed;                   // 域内接管 / take the count
IF nUse > DL_SII_NMAX THEN       // 超容量 / above the capacity
    nUse := DL_SII_NMAX;         // 钳到容量（信息级 0746 语义）/ clamp to the capacity
END_IF

// 段 3｜稳定插入排序（索引间接，严格比较保稳定，边界二；护栏防死循环，边界四）/ segment 3, the stable insertion sort on the indices
FOR k := 1 TO nUse - 1 DO        // 有界外层 / the bounded outer loop
    nKey := arrIdx[k];           // 待插元素原下标 / the key original index
    nKeyVal := arrSrc[nKey];     // 待插元素值 / the key value
    m := k - 1;                  // 内层从前一位置起 / the inner scan starts here
    nGuard := 0;                 // 护栏清零 / reset the guard
    WHILE (m >= 0) AND (((NOT bDesc) AND (arrSrc[arrIdx[m]] > nKeyVal)) OR (bDesc AND (arrSrc[arrIdx[m]] < nKeyVal))) DO // 前驱按序更极才前移（严格比较，等值不交换，稳定性自证）/ shift while the predecessor is strictly more extreme
        arrIdx[m + 1] := arrIdx[m]; // 索引后移一位 / shift the index right
        m := m - 1;              // 内层前移 / step the inner scan left
        nGuard := nGuard + 1;    // 护栏计数推进 / advance the guard
        IF nGuard > DL_SII_GMAX THEN // 护栏命中（结构性不可达兜底）/ the guard tripped
            m := -1;             // 强制退出内层（不置码，结构兜底）/ force the inner loop out
        END_IF
    END_WHILE
    arrIdx[m + 1] := nKey;       // 键落位（m+1 已证在 [0, k] 内，边界三）/ the key lands with a proven bound
END_FOR

// 段 4｜出口（nUse = 0/1 时 arrIdx 已为恒等，边界六）/ segment 4, the outlet with the degenerate identity
nSorted := nUse;                 // 排序个数出口 [个] / the sorted count outlet
bValid := TRUE;                  // 结果可用 / the result usable
FC_DL_SortIndexInt := TRUE;      // 返回成功 / return success
END_FUNCTION

// ==============================================================================
// 组件名 Component  : FB_DL_HysteresisBandMon
// 分类   Category   : DL_Base
// 前缀   Naming     : FB_DL_ ｜ b/f/e 类型前缀制（R265）
// 版本   Version    : 1.0.0
// 复杂度 Complexity  : 低
// 功能   Purpose    : 区间状态监视（三带迟滞）：fIn 相对 [fLow, fHigh] 判
//                      eBelow / eIn / eAbove 三带，带界切换带 fHyst 迟滞
//                      （防临界抖动）；进 eBelow / eAbove 各发单拍沿脉冲。
// 文件互引声明 Split : FC_DL_Hysteresis（DL_MathData）为点值滞回计算
//                      （布尔输出 + 调用方持有状态），本件为区间状态监视
//                      （三带枚举 + 实例自持状态 + 沿脉冲），语义不同
//                      勿混用（R216 双向互引）。
// 开源溯源 Origin    : 道莅原创（三带迟滞区间监视为公开工程语义，本实现
//                      clean-room，未复制任何源码行）
// 许可证 License    : MIT
// 参考   Reference  : IEC 61131-3:2013 §6.6 ENUM + CASE 状态机语义
// 平台   Platform   : 纯 IEC 61131-3（ENUM + CASE / LREAL 比较），三平台通用
// 依赖   Depends    : 无（零委托、零库件；无定时器 / 边沿实例）
// 归属 Ownership     : E_DL_HbmZone / E_DL_HbmErr 属主为本文件（全库唯一
//                      定义，R264）；引用件只引用不重声明。
// ------------------------------------------------------------------
// 边界 Boundary     :
//   一 组态守卫（逐项点名，R272）：fLow >= fHigh、fHyst < 0、fHyst >=
//      (fHigh - fLow)、fLow / fHigh 非有限（NaN 自反判 + 幅值 1e30 上界）
//      任一成立 → eErr = eCfg、bErr = TRUE、eZone 强制安全中位 eIn、
//      沿脉冲清零（本拍重算，非锁存——组态修复下一拍即恢复）；
//   二 输入守卫：fIn 非有限 → eErr = eInput、bErr = TRUE、eZone 强制
//      安全中位 eIn、沿脉冲清零（eCfg 与 eInput 同拍并存时组态优先，
//      归因唯一）；
//   三 切换规则（对称迟滞）：eBelow → eIn 需 fIn > fLow + fHyst；
//      eIn → eBelow 需 fIn < fLow；eIn → eAbove 需 fIn > fHigh；
//      eAbove → eIn 需 fIn < fHigh - fHyst；跨带跳变（eBelow 直接越
//      fHigh）一步直达 eAbove（一步直达比两步过带更早暴露越界）；
//   四 沿脉冲单拍有效：bBelowEdge / bAboveEdge 以本拍前态快照为基准，
//      错误路径在沿计算前早退故恒 FALSE；
//   五 失能（bEn = FALSE）语义写死（R303 离相清零）：eZone 强制安全
//      中位 eIn、沿脉冲清零、bErr / eErr 清零（失能不是故障）；
//   六 CASE 带 ELSE 非法枚举兜底：强制回 eIn + eErr = eCfg（eErr 枚举
//      无非法态成员，按 R90 反证句归并组态族——非法态与组态非法出口
//      组合同为 eIn + bErr，现有输出不可区分，故合并一码）；
//   七 无定时器 / 无边沿实例（周期安全规则 N/A）；无除法；
//      无全局、无外部变量、无物理地址。
// 错误码 Codes      :
//   16#0001_0747【信息级】组态非法（eErr = eCfg 通道，bErr 置位，eZone
//                强制安全中位 eIn，不锁存）
//   16#0001_0748【信息级】输入非有限（eErr = eInput 通道，bErr 置位，
//                eZone 强制安全中位 eIn，不锁存）
//   注：本件 eErr 为枚举出口（引脚契约按任务定稿），上述数值码位为
//   文档级对照；两码分立依据：eCfg 组态即刻判（处置人 = 组态工程师），
//   eInput 需运行期输入到达（处置人 = 仪表），R90 分立。
// 验收 Acceptance   :
//   算法已证（脚本）：未跑 ｜ 编译器已证（三平台）：未跑
//   V1 fLow=0/fHigh=100/fHyst=5：fIn=-1 → eBelow；fIn=50 → eIn（进带脉冲无）
//   V2 eBelow 态 fIn=6（> fLow+fHyst）→ eIn；fIn=3（< fLow+fHyst）→ 保持
//   V3 eIn 态 fIn=99 → eAbove（bAboveEdge 单拍）；fIn=94（< fHigh-fHyst）→ eIn
//   V4 fIn 跳变 -5 → 105：eBelow 一步直达 eAbove（单拍 bAboveEdge）
//   V5 fLow >= fHigh → eCfg + eZone = eIn；fIn = NaN → eInput + eZone = eIn
//   V6 bEn = FALSE → eZone = eIn、全出口清零（R303）
//   V7 非法枚举态（强改 _eZone）→ ELSE 兜底回 eIn + eCfg
// 修订记录 Revision  :
//   2026-11-22  v1.0.0  R65 首版（批 2 · 序号 6）
// ==============================================================================
TYPE E_DL_HbmZone :
(
    eBelow := 0,  // 下带：fIn 低于下带界 / below, the input under the lower band edge
    eIn    := 10, // 中带：fIn 在带内（安全中位）/ inside, the safe middle zone
    eAbove := 20  // 上带：fIn 高于上带界 / above, the input over the upper band edge
);
END_TYPE

TYPE E_DL_HbmErr :
(
    eNone  := 0,  // 无错 / no error
    eCfg   := 10, // 组态非法（fLow / fHigh / fHyst 域非法）/ an illegal configuration
    eInput := 20  // 输入非有限（fIn 为 NaN / Inf / 超幅值）/ a non finite input
);
END_TYPE

FUNCTION_BLOCK FB_DL_HysteresisBandMon
VAR_INPUT
    fIn   : LREAL;               // 监视输入 [工程单位] / the monitored input
    fLow  : LREAL := 0.0;        // 区间下界 [工程单位]，须 < fHigh / the lower band edge
    fHigh : LREAL := 100.0;      // 区间上界 [工程单位]，须 > fLow / the upper band edge
    fHyst : LREAL := 0.0;        // 迟滞半带宽 [工程单位]，须 [0, fHigh - fLow) / the hysteresis half band
    bEn   : BOOL := TRUE;        // 使能 [-]，FALSE 时出口清零回中位（R303）/ the enable
END_VAR
VAR_OUTPUT
    eZone      : E_DL_HbmZone := E_DL_HbmZone.eIn; // 区间状态出口 [状态]（安全中位初值）/ the zone outlet, safe middle initial
    bBelowEdge : BOOL := FALSE;  // 进入下带沿脉冲 [-]，单拍有效 / the below entry edge pulse, single scan
    bAboveEdge : BOOL := FALSE;  // 进入上带沿脉冲 [-]，单拍有效 / the above entry edge pulse, single scan
    bErr       : BOOL := FALSE;  // 错误标志 [-]，eCfg / eInput 置位 / the error flag
    eErr       : E_DL_HbmErr := E_DL_HbmErr.eNone; // 错误码出口 [码] / the error code outlet
END_VAR
VAR
    _eZone     : E_DL_HbmZone := E_DL_HbmZone.eIn; // 内部状态寄存器 [状态] / the internal state register
    _eZonePrev : E_DL_HbmZone := E_DL_HbmZone.eIn; // 本拍前态快照 [状态]（沿判定基准）/ the previous zone snapshot, the edge baseline
    _bCfgBad   : BOOL;           // 组态非法标志（逐拍重算）/ the configuration fault flag
    _bInBad    : BOOL;           // 输入非有限标志（逐拍重算）/ the input fault flag
END_VAR
VAR CONSTANT
    DL_HBM_FMAX : LREAL := 1.0E30; // 非有限筛查幅值上限 [工程单位] / the finiteness screening cap
END_VAR

// 段 1｜单拍沿脉冲与错误出口预清零（R256 统一出口预置）/ segment 1, the single scan preset
bBelowEdge := FALSE;             // 下带沿脉冲预清零 / preset the below edge false
bAboveEdge := FALSE;             // 上带沿脉冲预清零 / preset the above edge false
bErr       := FALSE;             // 错误标志预清零 / preset the error flag false
eErr       := E_DL_HbmErr.eNone; // 错误码预置无错 / preset the code to none

// 段 2｜失能分支：出口清零回安全中位，不置错（R303 离相清零声明行）/ segment 2, the disabled branch
IF NOT bEn THEN                  // 失能 / disabled
    _eZone := E_DL_HbmZone.eIn;  // 强制安全中位 / force the safe middle
    eZone := _eZone;             // 状态出口 / the zone outlet
    bBelowEdge := FALSE;         // 沿脉冲清零 / clear the below edge
    bAboveEdge := FALSE;         // 沿脉冲清零 / clear the above edge
    bErr := FALSE;               // 失能不是故障 / a disabled device is not a fault
    eErr := E_DL_HbmErr.eNone;   // 失能不发码 / no code while disabled
    RETURN;                      // 早退 / early return
END_IF

// 段 3｜组态守卫（边界一：四判据逐项点名，R272）/ segment 3, the configuration guard
_bCfgBad := (fLow >= fHigh)                                  // 下界不低于上界 / the lower edge not under the upper
         OR (fHyst < 0.0)                                    // 迟滞为负 / a negative hysteresis
         OR (fHyst >= (fHigh - fLow))                        // 迟滞吞没整带 / the hysteresis swallowing the whole band
         OR (fLow <> fLow) OR ((fLow - fLow) <> 0.0) OR (ABS(fLow) > DL_HBM_FMAX)      // fLow 非有限 / fLow non finite
         OR (fHigh <> fHigh) OR ((fHigh - fHigh) <> 0.0) OR (ABS(fHigh) > DL_HBM_FMAX) // fHigh 非有限 / fHigh non finite
         OR (fHyst <> fHyst) OR ((fHyst - fHyst) <> 0.0) OR (ABS(fHyst) > DL_HBM_FMAX); // fHyst 非有限 / fHyst non finite
IF _bCfgBad THEN                 // 组态非法 / an illegal configuration
    _eZone := E_DL_HbmZone.eIn;  // 强制安全中位（边界一）/ force the safe middle
    eZone := _eZone;             // 状态出口 / the zone outlet
    bErr := TRUE;                // 错误标志置位 / raise the error flag
    eErr := E_DL_HbmErr.eCfg;    // 信息级 0747：组态非法 / the configuration code
    RETURN;                      // 早退（沿脉冲保持段 1 预清零）/ early return
END_IF

// 段 4｜输入守卫（边界二：NaN 自反判 + Inf 差值自反判 + 幅值上界）/ segment 4, the input guard
_bInBad := (fIn <> fIn) OR ((fIn - fIn) <> 0.0) OR (ABS(fIn) > DL_HBM_FMAX); // 输入非有限 / the input non finite
IF _bInBad THEN                  // 输入无效 / an invalid input
    _eZone := E_DL_HbmZone.eIn;  // 强制安全中位（边界二）/ force the safe middle
    eZone := _eZone;             // 状态出口 / the zone outlet
    bErr := TRUE;                // 错误标志置位 / raise the error flag
    eErr := E_DL_HbmErr.eInput;  // 信息级 0748：输入非有限 / the input code
    RETURN;                      // 早退（沿脉冲保持段 1 预清零）/ early return
END_IF

// 段 5｜三带状态机（ENUM + CASE + ELSE 兜底，边界三 / 六）/ segment 5, the three zone machine
_eZonePrev := _eZone;            // 本拍前态快照（沿判定基准，边界四）/ snapshot the previous zone
CASE _eZone OF
    E_DL_HbmZone.eBelow:         // 下带 / the below zone
        IF fIn > fHigh THEN      // 跨带跳变直达上界之上（边界三一步直达）/ a jump beyond the upper edge
            _eZone := E_DL_HbmZone.eAbove; // 一步迁入上带 / straight to the above zone
        ELSIF fIn > (fLow + fHyst) THEN // 越过下带迟滞恢复线 / over the lower recovery line
            _eZone := E_DL_HbmZone.eIn;    // 迁入中带 / enter the inside zone
        END_IF
    E_DL_HbmZone.eIn:            // 中带 / the inside zone
        IF fIn < fLow THEN       // 跌破下界（严格小于，边界三）/ under the lower edge
            _eZone := E_DL_HbmZone.eBelow; // 迁入下带 / enter the below zone
        ELSIF fIn > fHigh THEN   // 越过上界（严格大于）/ over the upper edge
            _eZone := E_DL_HbmZone.eAbove; // 迁入上带 / enter the above zone
        END_IF
    E_DL_HbmZone.eAbove:         // 上带 / the above zone
        IF fIn < fLow THEN       // 跨带跳变跌破下界 / a jump under the lower edge
            _eZone := E_DL_HbmZone.eBelow; // 一步迁入下带 / straight to the below zone
        ELSIF fIn < (fHigh - fHyst) THEN // 跌破上带迟滞恢复线 / under the upper recovery line
            _eZone := E_DL_HbmZone.eIn;    // 迁入中带 / enter the inside zone
        END_IF
    ELSE                         // 非法枚举值拦截（边界六：回中位 + 组态族合并码，R90 反证句见码表）/ the illegal enumeration guard
        _eZone := E_DL_HbmZone.eIn; // 强制回安全中位 / force back to the safe middle
        bErr := TRUE;            // 错误标志置位（禁静默）/ raise the error flag
        eErr := E_DL_HbmErr.eCfg; // 归并组态族一码（出口同形不可区分，R90）/ merged into the configuration code
END_CASE

// 段 6｜沿脉冲与状态出口（边界四：基准 = 本拍前态快照，单拍有效）/ segment 6, the edges and the zone outlet
bBelowEdge := (_eZone = E_DL_HbmZone.eBelow) AND (_eZonePrev <> E_DL_HbmZone.eBelow); // 进入下带沿 / the below entry edge
bAboveEdge := (_eZone = E_DL_HbmZone.eAbove) AND (_eZonePrev <> E_DL_HbmZone.eAbove); // 进入上带沿 / the above entry edge
eZone := _eZone;                 // 状态出口（名实双出口同源，R191）/ the zone outlet
END_FUNCTION_BLOCK

// ==============================================================================
// 组件名 Component  : FC_DL_AngleUnitConvert
// 分类   Category   : DL_MathData
// 前缀   Naming     : FC_DL_ ｜ b/f/e 类型前缀制（R265）
// 版本   Version    : 1.0.0
// 复杂度 Complexity  : 低
// 功能   Purpose    : 角度单位换算（度 / 弧度 / 梯度）：统一转 rad 中间量
//                      再转目标单位，任意两单位直换（deg → grad 系数
//                      200/180 经 rad 中转自动成立）。非有限输入拒绝
//                      （bValid = FALSE、fOut = 0.0）。
// 开源溯源 Origin    : 道莅原创（角度单位定义为公开计量常识，本实现
//                      clean-room，未复制任何源码行；与 TempUnitConvert /
//                      PressUnitConvert / FlowUnitConvert 同族单位换算
//                      组织口径）
// 许可证 License    : MIT
// 参考   Reference  : IEC 61131-3:2013 §6.6.2 CASE 语义；角度单位换算公开
//                      计量定义（借定义，不抄实现）
// 平台   Platform   : 纯 IEC 61131-3（CASE / LREAL 四则），三平台通用
// 依赖   Depends    : 无（零委托、零库件；换算系数常量预乘，运行期零除法）
// 分工声明 Split     : FC_DL_AngleDiffWrap（角差归一）与 FC_DL_WrapAngleDeg
//                      （角度回绕）与本件互引；本件只做单位换算（不改
//                      角度主值、不回绕），归一 / 回绕语义归各自属主（R216）。
// 归属 Ownership     : E_DL_AngUnit 属主为本文件（全库唯一定义，R264）；
//                      引用件只引用不重声明。
// ------------------------------------------------------------------
// 边界 Boundary     :
//   一 非有限闸：fVal 为 NaN（自反判 x <> x）或 ±Inf（差值自反判
//      (x - x) <> (x - x)）或幅值越 1e30 上界 → bValid = FALSE、
//      fOut = 0.0 早退（故障级 0749，R272 非有限防护）；
//   二 零除法面：四向系数全部预乘为常量（PI/180、180/PI、PI/200、
//      200/PI 编译期落定），运行期无除法（除零面结构性消除）；
//   三 枚举闸：eFrom / eTo 非法枚举值（CASE ELSE 兜底）→ bValid =
//      FALSE、fOut = 0.0 早退（与 0749 同形出口合并一码，R90 反证句：
//      现有输出组合不可区分两场景）；
//   四 纯函数：无记忆量、无定时器、无边沿实例，每调用重算；
//   五 无全局、无外部变量、无物理地址。
// 错误码 Codes      :
//   16#0001_0749【故障级】输入非有限或枚举非法（bValid = FALSE、
//                fOut = 0.0 早退）
//   注：本件引脚契约按任务定稿无独立 eErr 出口，故障语义经
//   bValid = FALSE + fOut = 0.0 组合表达。
// 验收 Acceptance   :
//   算法已证（脚本）：未跑 ｜ 编译器已证（三平台）：未跑
//   V1 180 deg → rad = 3.14159265358979；V2 1 rad → deg = 57.2957795
//   V3 200 grad → rad = 3.14159265358979；V4 180 deg → grad = 200（200/180 系数）
//   V5 fVal = NaN → bValid = FALSE、fOut = 0.0
//   V6 eFrom 非法枚举 → bValid = FALSE、fOut = 0.0
// 修订记录 Revision  :
//   2026-11-22  v1.0.0  R65 首版（批 2 · 序号 7）
// ==============================================================================
TYPE E_DL_AngUnit :
(
    eDeg  := 0, // 度 [deg]，一周 360 / degrees, 360 per turn
    eRad  := 1, // 弧度 [rad]，一周 2*PI / radians, two pi per turn
    eGrad := 2  // 梯度 [grad]，一周 400 / gradians, 400 per turn
);
END_TYPE

FUNCTION FC_DL_AngleUnitConvert : BOOL
VAR_INPUT
    fVal  : LREAL;               // 输入角值 [源单位] / the input angle in the source unit
    eFrom : E_DL_AngUnit;        // 源单位枚举 [单位] / the source unit
    eTo   : E_DL_AngUnit;        // 目标单位枚举 [单位] / the target unit
END_VAR
VAR_OUTPUT
    fOut   : LREAL;              // 输出角值 [目标单位]，无效时 0.0 / the output angle in the target unit, zero when invalid
    bValid : BOOL;               // 结果可用 [-]，非有限或枚举非法为 FALSE / the validity flag
END_VAR
VAR
    fRad : LREAL;                // 中间弧度量 [rad]（统一中转）/ the intermediate radian value
END_VAR
VAR CONSTANT
    DL_AUC_D2R  : LREAL := 0.0174532925199433;   // 度 → 弧度系数 [rad/deg]，PI/180 预乘 / the deg to rad factor, pi over one eighty
    DL_AUC_R2D  : LREAL := 57.2957795130823;     // 弧度 → 度系数 [deg/rad]，180/PI 预乘 / the rad to deg factor
    DL_AUC_G2R  : LREAL := 0.0157079632679490;   // 梯度 → 弧度系数 [rad/grad]，PI/200 预乘 / the grad to rad factor, pi over two hundred
    DL_AUC_R2G  : LREAL := 63.6619772367581;     // 弧度 → 梯度系数 [grad/rad]，200/PI 预乘 / the rad to grad factor
    DL_AUC_FMAX : LREAL := 1.0E30;               // 非有限筛查幅值上限 [源单位] / the finiteness screening cap
END_VAR

// 段 1｜返回值与全部出口预置（R45 四段式第一段）/ segment 1, the preset of the return and all outlets
FC_DL_AngleUnitConvert := FALSE; // 返回值预置假 / preset the return false
fOut   := 0.0;                   // 输出预置零 [目标单位] / preset the output zero
bValid := FALSE;                 // 有效标志预置假 / preset the validity false
fRad   := 0.0;                   // 中间量预置零 [rad] / preset the intermediate zero

// 段 2｜非有限闸（边界一：NaN 自反判 + Inf 差值自反判 + 幅值上界，R272）/ segment 2, the non finite gate
IF (fVal <> fVal) OR ((fVal - fVal) <> 0.0) OR (ABS(fVal) > DL_AUC_FMAX) THEN // 输入非有限 / the input non finite
    fOut   := 0.0;               // 输出归零 [目标单位] / zero the output
    bValid := FALSE;             // 故障级 0749：拒绝换算 / refuse the conversion
    RETURN;                      // 早退 / early return
END_IF

// 段 3｜源单位归一到 rad（边界三：CASE 带 ELSE 兜底）/ segment 3, the source unit normalization to radians
CASE eFrom OF
    E_DL_AngUnit.eDeg:           // 度 → rad / degrees to radians
        fRad := fVal * DL_AUC_D2R; // 乘 PI/180 系数 [rad] / multiply the deg to rad factor
    E_DL_AngUnit.eRad:           // 弧度直通 / radians pass through
        fRad := fVal;            // 中转量即输入 [rad] / the intermediate is the input
    E_DL_AngUnit.eGrad:          // 梯度 → rad / gradians to radians
        fRad := fVal * DL_AUC_G2R; // 乘 PI/200 系数 [rad] / multiply the grad to rad factor
    ELSE                         // 非法枚举拦截（边界三）/ an illegal enumeration
        fOut   := 0.0;           // 输出归零 / zero the output
        bValid := FALSE;         // 故障级 0749 同形出口（R90 合并）/ the merged fault outlet
        RETURN;                  // 早退 / early return
END_CASE

// 段 4｜rad 转目标单位（边界三：CASE 带 ELSE 兜底）/ segment 4, the radians to the target unit
CASE eTo OF
    E_DL_AngUnit.eDeg:           // rad → 度 / radians to degrees
        fOut := fRad * DL_AUC_R2D; // 乘 180/PI 系数 [deg] / multiply the rad to deg factor
    E_DL_AngUnit.eRad:           // rad 直通 / radians pass through
        fOut := fRad;            // 输出即中转量 [rad] / the output is the intermediate
    E_DL_AngUnit.eGrad:          // rad → 梯度 / radians to gradians
        fOut := fRad * DL_AUC_R2G; // 乘 200/PI 系数（deg → grad 经此链自动得 200/180）[grad] / the rad to grad factor
    ELSE                         // 非法枚举拦截（边界三）/ an illegal enumeration
        fOut   := 0.0;           // 输出归零 / zero the output
        bValid := FALSE;         // 故障级 0749 同形出口（R90 合并）/ the merged fault outlet
        RETURN;                  // 早退 / early return
END_CASE

// 段 5｜统一出口 / segment 5, the unified outlet
bValid := TRUE;                  // 结果可用 / the result usable
FC_DL_AngleUnitConvert := TRUE;  // 返回成功 / return success
END_FUNCTION

// ==============================================================================
// 组件名 Component  : FC_DL_TankVolumeHoriCyl
// 分类   Category   : DL_Process
// 前缀   Naming     : FC_DL_ ｜ b/f 类型前缀制（R265）
// 版本   Version    : 1.0.0
// 复杂度 Complexity  : 中
// 功能   Purpose    : 卧式圆柱罐液位 - 体积几何解析换算：弦高 → 弓形面积
//                      → 体积（fVol = L * (r²*acos((r-h)/r) − (r−h)*
//                      sqrt(max(0, 2rh − h²)))），h = fLevel 钳位 [0, 2r]；
//                      百分比出口按满罐体积归一。纵坡参数 fTiltDeg 本版
//                      按平面近似支持（> 0 时置 bApprox 提示近似）。
// 文件互引声明 Split : FB_DL_TankLevelStrapping（DL_Process）为查表标定法
//                      （折点表 + 标定核对），本件为几何解析法（公式直算，
//                      零折点依赖），两法勿混用——有标定表用查表件，无表
//                      用本件（R216 双向互引）。
// 开源溯源 Origin    : 道莅原创（弓形面积为公开几何公式，本实现 clean-room，
//                      未复制任何源码行）
// 许可证 License    : MIT
// 参考   Reference  : IEC 61131-3:2013 §6.6.2 函数语义；ACOS / SQRT 为 IEC
//                      标准数学函数；弓形面积公开几何公式（借定义，不抄实现）
// 平台   Platform   : 纯 IEC 61131-3（LREAL 四则 / ACOS / SQRT），三平台通用
// 依赖   Depends    : 无（零委托、零库件；ACOS / SQRT 为 IEC 标准函数）
// 归属 Ownership     : 本件无 TYPE 声明；全部引脚为 IEC 标准原生类型。
// ------------------------------------------------------------------
// 边界 Boundary     :
//   一 组态 / 输入闸（逐项点名，R272）：fDiam <= 0、fLength <= 0、
//      fDiam / fLength / fLevel 任一非有限（NaN 自反判 + Inf 差值自反判 +
//      幅值 1e30 上界）→ bValid = FALSE、双出口归零早退（故障级 303A）；
//   二 液位钳位：h 钳 [0, 2r]（负值钳 0、超高罐顶钳 2r，安全侧归一，
//      信息级 303C 文档语义——本件无 eErr 出口，钳位出口与正常出口
//      同形无独立通道，不另设出口位，R90 反证句）；
//   三 acos 定义域防护：(r - h) / r 钳 [-1, 1]（边界二钳位后 h/r 在
//      [0, 1]，q = 1 - h/r 在 [0, 1]，钳位为防御性双保险，防浮点边缘
//      越域）；除法分母 r > 0 已由组态闸证明；
//   四 被开方数 max(0, 2rh − h²)：h 在 [0, 2r] 已证非负，再叠 max(0,·)
//      双保险，SQRT 入参恒非负；
//   五 百分比分母防零：fVfull = PI*r²*L，由组态闸（fDiam > 0 → r > 0、
//      fLength > 0）证明 fVfull > 0，除法安全（反证句写死）；
//   六 纵坡近似口径：fTiltDeg > 0 → bApprox = TRUE（平面近似，体积按
//      平罐公式给出）；fTiltDeg 非有限 → 同置 bApprox = TRUE 并按 0
//      处理（信息级 303B）；
//   七 结果非有限防御：体积 / 百分比出口算后复检非有限（NaN / Inf /
//      幅值上界），越限即 bValid = FALSE、双出口归零（R273 连续量出口
//      非有限防护）；
//   八 纯函数：无记忆量、无定时器、无边沿实例，每调用重算；
//   九 除法仅两处（h/r 与 fVolM3/fVfull），分母已证非零；无全局、
//      无外部变量、无物理地址。
// 错误码 Codes      :
//   16#0006_303A【故障级】组态 / 输入非法（fDiam / fLength 域非法或任一
//                引脚非有限），bValid = FALSE、双出口归零早退
//   16#0006_303B【信息级】纵坡非零（或非有限按 0 处理），平面近似口径
//                （bApprox = TRUE 通道）
//   16#0006_303C【信息级】液位越界已钳位 [0, 2r]（静默安全侧归一，
//                文档级语义，无独立出口通道）
//   注：本件引脚契约按任务定稿无独立 eErr 出口，故障语义经 bValid /
//   bApprox / 双出口组合表达。
// 验收 Acceptance   :
//   算法已证（脚本）：未跑 ｜ 编译器已证（三平台）：未跑
//   V1 r=1、L=2、h=0 → 体积 0；h=2r → 满罐 PI*r²*L ≈ 6.283 m³、fPct = 100
//   V2 r=1、L=2、h=1（半罐）→ 弓形 = 半圆面积 PI/2 → 体积 ≈ 3.1416、fPct = 50
//   V3 fLevel = -0.5 → 钳 0；fLevel = 5（> 2r）→ 钳 2r
//   V4 fDiam = 0 / 负 → bValid = FALSE；fLevel = NaN → bValid = FALSE
//   V5 fTiltDeg = 3 → bApprox = TRUE（体积仍按平面近似给出）
//   V6 fTiltDeg = NaN → bApprox = TRUE、按 0 处理
// 修订记录 Revision  :
//   2026-11-22  v1.0.0  R65 首版（批 3 · 序号 8）
// ==============================================================================
FUNCTION FC_DL_TankVolumeHoriCyl : BOOL
VAR_INPUT
    fLevel   : LREAL;            // 液位高度 [m]，罐底为 0 / the liquid level, the tank bottom is zero
    fDiam    : LREAL;            // 罐内径 [m]，须 > 0 / the inner diameter, above zero
    fLength  : LREAL;            // 罐筒体长度 [m]，须 > 0 / the shell length, above zero
    fTiltDeg : LREAL := 0.0;     // 纵坡 [deg]，本版平面近似，> 0 置 bApprox / the longitudinal tilt, plane approximation
END_VAR
VAR_OUTPUT
    fVolM3  : LREAL;             // 折算体积 [m³]，无效时 0.0 / the converted volume, zero when invalid
    fPct    : LREAL;             // 体积百分比 [%]，按满罐归一 / the volume percent of the full tank
    bValid  : BOOL;              // 结果可用 [-] / the result usable flag
    bApprox : BOOL;              // 近似口径提示 [-]，纵坡非零 / the approximation flag, a nonzero tilt
END_VAR
VAR
    r         : LREAL;           // 罐半径 [m] / the tank radius
    h         : LREAL;           // 钳位后弦高 [m] / the clamped chord height
    q         : LREAL;           // acos 入参（(r-h)/r）[-] / the acos argument
    fUnder    : LREAL;           // 被开方数 2rh − h² [m²] / the radicand
    fSegArea  : LREAL;           // 弓形截面积 [m²] / the circular segment area
    fVfull    : LREAL;           // 满罐体积 [m³] / the full tank volume
    bTiltBad  : BOOL;            // 纵坡非有限标志 [-] / the tilt fault flag
END_VAR
VAR CONSTANT
    DL_TVC_PI   : LREAL := 3.14159265358979; // 圆周率 [-] / the pi constant
    DL_TVC_FMAX : LREAL := 1.0E30;           // 非有限筛查幅值上限 [m] / the finiteness screening cap
END_VAR

// 段 1｜返回值与全部出口预置（R45 四段式第一段）/ segment 1, the preset of the return and all outlets
FC_DL_TankVolumeHoriCyl := FALSE; // 返回值预置假 / preset the return false
fVolM3  := 0.0;                  // 体积出口预置零 [m³] / preset the volume zero
fPct    := 0.0;                  // 百分比出口预置零 [%] / preset the percent zero
bValid  := FALSE;                // 有效标志预置假 / preset the validity false
bApprox := FALSE;                // 近似提示预置假 / preset the approximation flag false

// 段 2｜组态 / 输入闸（边界一：域 + 非有限逐项点名，R272）/ segment 2, the configuration and input gate
IF (fDiam <= 0.0) OR (fLength <= 0.0)                             // 几何域非法 / an illegal geometry
OR (fLevel <> fLevel) OR ((fLevel - fLevel) <> 0.0) OR (ABS(fLevel) > DL_TVC_FMAX)   // fLevel 非有限 / fLevel non finite
OR (fDiam <> fDiam) OR ((fDiam - fDiam) <> 0.0) OR (ABS(fDiam) > DL_TVC_FMAX)        // fDiam 非有限 / fDiam non finite
OR (fLength <> fLength) OR ((fLength - fLength) <> 0.0) OR (ABS(fLength) > DL_TVC_FMAX) THEN // fLength 非有限 / fLength non finite
    fVolM3 := 0.0;               // 体积归零 [m³] / zero the volume
    fPct   := 0.0;               // 百分比归零 [%] / zero the percent
    bValid := FALSE;             // 故障级 303A：拒绝计算 / refuse the calculation
    RETURN;                      // 早退 / early return
END_IF

// 段 3｜纵坡近似口径（边界六：> 0 置近似，非有限按 0 处理并置近似）/ segment 3, the tilt approximation flag
bTiltBad := (fTiltDeg <> fTiltDeg) OR ((fTiltDeg - fTiltDeg) <> 0.0) OR (ABS(fTiltDeg) > DL_TVC_FMAX); // 纵坡非有限 / the tilt non finite
IF (fTiltDeg > 0.0) OR bTiltBad THEN // 纵坡生效或无效 / the tilt active or invalid
    bApprox := TRUE;             // 信息级 303B：平面近似口径 / the approximation flag raised
END_IF

// 段 4｜半径与液位钳位（边界二：h 钳 [0, 2r]）/ segment 4, the radius and the level clamp
r := fDiam / 2.0;                // 半径 [m]（分母 2.0 为常量，零除面消除）/ the radius, a constant divisor
h := fLevel;                     // 弦高接管 [m] / take the level as the chord height
IF h < 0.0 THEN                  // 液位低于罐底 / the level under the bottom
    h := 0.0;                    // 钳 0（信息级 303C）/ clamp to zero
END_IF
IF h > (2.0 * r) THEN            // 液位超过罐顶 / the level over the top
    h := 2.0 * r;                // 钳 2r（信息级 303C）/ clamp to the full bore
END_IF

// 段 5｜弓形面积解析（边界三 / 四：acos 定义域钳位 + 被开方数非负双保险）/ segment 5, the segment area
q := 1.0 - (h / r);              // acos 入参 (r - h)/r（分母 r > 0 已由组态闸证明）/ the acos argument, the divisor proven above zero
IF q > 1.0 THEN                  // 上越域防御（浮点边缘双保险）/ an upper domain defense
    q := 1.0;                    // 钳回 1.0 / clamp to one
END_IF
IF q < -1.0 THEN                 // 下越域防御 / a lower domain defense
    q := -1.0;                   // 钳回 -1.0 / clamp to minus one
END_IF
fUnder := (2.0 * r * h) - (h * h); // 被开方数 2rh − h² [m²] / the radicand
IF fUnder < 0.0 THEN             // 浮点边缘微负防御（边界四）/ a tiny negative defense
    fUnder := 0.0;               // 钳 0（max(0, ·) 口径）/ clamp to zero
END_IF
fSegArea := (r * r * ACOS(q)) - ((r - h) * SQRT(fUnder)); // 弓形面积公式 [m²] / the segment area formula

// 段 6｜体积与百分比折算（边界五：分母 fVfull > 0 反证已写死）/ segment 6, the volume and the percent
fVolM3 := fLength * fSegArea;    // 体积 = 长度 × 弓形面积 [m³] / the volume as length times the segment area
fVfull := DL_TVC_PI * r * r * fLength; // 满罐体积 [m³]（r > 0 与 L > 0 已证）/ the full volume, proven above zero
fPct   := (fVolM3 / fVfull) * 100.0;   // 百分比 [%]（分母已证非零）/ the percent, the divisor proven

// 段 7｜结果非有限防御（边界七：连续量出口 R273 防护）/ segment 7, the result finiteness defense
IF (fVolM3 <> fVolM3) OR ((fVolM3 - fVolM3) <> 0.0) OR (ABS(fVolM3) > DL_TVC_FMAX) THEN // 体积非有限 / a non finite volume
    fVolM3 := 0.0;               // 体积归零 [m³] / zero the volume
    fPct   := 0.0;               // 百分比归零 [%] / zero the percent
    bValid := FALSE;             // 拒绝输出 / refuse the output
    RETURN;                      // 早退 / early return
END_IF

// 段 8｜统一出口 / segment 8, the unified outlet
bValid := TRUE;                  // 结果可用 / the result usable
FC_DL_TankVolumeHoriCyl := TRUE; // 返回成功 / return success
END_FUNCTION

