// 组件名 Component  : FB_DL_PneuCylinderDiag
// 分类   Category   : DL_Device
// 前缀   Naming     : FB_DL_ ｜ b/e/t 类型前缀制（R265）
// 版本   Version    : 1.0.0
// 复杂度 Complexity  : 中
// 功能   Purpose    : 气缸纯诊断件（不控线圈）：跟踪指令沿与到位反馈的
//                      一致性——伸出 / 缩回超时（tExtTo / tRetTo）、双传感
//                      器矛盾（bFbExt 与 bFbRet 同真，物理不可能）、中途
//                      无进展（运动相中两反馈皆无持续 tStall）三族故障
//                      锁存；bReset 上升沿解锁回 eIdle。供既有气缸控制
//                      件外挂诊断层，不替代控制件。
// 开源溯源 Origin    : 道莅原创（与 FB_DL_PneumaticCylinder 的控制 + 自检
//                      一体件分工：本件为纯诊断外挂，判据独立实现
//                      clean-room，零代码复制）
// 许可证 License    : MIT
// 参考   Reference  : IEC 61131-3:2013 §6.6 ENUM + CASE 状态机 / TON /
//                      R_TRIG 语义；气缸「指令 - 反馈」一致性监视公开
//                      工程口径（借语义，不抄文）
// 平台   Platform   : 纯 IEC 61131-3（TON / R_TRIG / ENUM+CASE），三平台通用
// 依赖   Depends    : 仅 Standard.library（TON / R_TRIG 属标准件）
// 分工声明 Split     : FB_DL_PneumaticCylinder（控制件，含线圈输出与互锁）
//                      与本件互引；本件零控制出口（不下发线圈），只做
//                      指令 - 反馈一致性诊断；控制语义归彼件（R216）。
// 归属 Ownership     : E_DL_PcdSt / E_DL_PcdErr 属主为本文件（全库唯一
//                      定义，R264）；引用件只引用不重声明。
// ------------------------------------------------------------------
// 边界 Boundary     :
//   一 TON / R_TRIG 段 0 无条件刷新（禁入分支，R7）；监视 TON 串故障锁存
//      门控（FB50-1：锁存期 IN 强制 FALSE，复位同拍不重锁）；
//   二 推进判据与超时计时不同源（R300）：推进判据 = 到位反馈电平
//      （bFbExt / bFbRet），超时计时 = 状态驻留时长（tonExtTo / tonRetTo
//      基于相而非反馈），互不共源；无进展窗 tStall 为独立第三窗
//      （判据 = 两反馈皆无），与超时窗互不共源；
//   三 同拍双窗配比约束（写死）：tStall 须 < min(tExtTo, tRetTo)——
//      双反馈皆无场景下若 tStall >= 超时窗，超时窗先到，eMidStall 永不可
//      到达（配比声明，调用方改参须维持）；反馈部分在场（如 bFbRet 恒
//      真卡滞）时无进展窗被门控让路，由超时窗接管（判据互斥分层）；
//   四 故障归因唯一（R190）：eSenConflict / eMidStall / eTimeoutExt /
//      eTimeoutRet 各有独立码位与独立触发判据，禁止共用枚举成员；
//   五 eMidStall 无独立驻留相（E_DL_PcdSt 契约定稿）：锁存后冻结当前
//      运动相驻留（bErr = TRUE + eErr = eMidStall 双通道表达），迁移被
//      锁存闸（段 6）拦截至复位沿，语义在头注与码表双声明；
//   六 失败锁存 _bFaultLatch：解除式可达自证（R152）——bReset 上升沿
//      清锁存回 eIdle（输入引脚恒可达，无「置位即永久」路径）；
//   七 失能（bEn = FALSE）语义写死（R303 离相清零）：状态回 eIdle、
//      故障锁存 / 码锁存清零、bErr / bTimeout 清零（失能不是故障）；
//   八 首拍 _bInit 全量初始化（R310）；非法枚举态兜底落 eConflict +
//      eSenConflict 合并码（R90 反证句：E_DL_PcdErr 无非法态成员，非法态
//      与传感器矛盾的出口组合同为 eConflict + bErr，现有输出不可区分，
//      故合并；数值对照码 0730 见码表）；
//   九 无浮点量、无除法；无全局、无外部变量、无物理地址。
// 错误码 Codes      :
//   16#0003_0730【故障级】非法状态拦截（ELSE 兜底，经 eSenConflict 枚举
//                通道合并表达，R90 合并反证句见边界八）
//   16#0003_0731【故障级】传感器矛盾（bFbExt 与 bFbRet 同真，物理不可能）
//                → eSenConflict，锁存至复位沿
//   16#0003_0732【故障级】伸出超时（eExtending 相驻留超 tExtTo 未到位）
//                → eTimeoutExt，锁存至复位沿
//   16#0003_0733【故障级】缩回超时（eRetracting 相驻留超 tRetTo 未到位）
//                → eTimeoutRet，锁存至复位沿
//   16#0003_0734【故障级】中途无进展（运动相两反馈皆无持续 tStall）
//                → eMidStall，锁存至复位沿（冻结当前相驻留）
//   注：eErr 为枚举出口（引脚契约按任务定稿），上述数值码位为文档级
//   对照；tExtTo / tRetTo / tStall <= 0 时对应窗禁用（诊断关闭，非故障）。
// 验收 Acceptance   :
//   算法已证（脚本）：未跑 ｜ 编译器已证（三平台）：未跑
//   V1 bCmdExt 沿 + bFbExt 3s 内到位 → eExtOk、无码
//   V2 bCmdExt 沿、bFbExt 永不到 → tExtTo 到 → eExtTo + eTimeoutExt 锁存
//   V3 运动相 bFbExt 与 bFbRet 同真 → eConflict + eSenConflict 锁存
//   V4 运动相两反馈皆无超 tStall（< 超时窗）→ eMidStall 锁存、冻结驻留
//   V5 故障态 bReset 上升沿 → 解锁回 eIdle（锁存解除可达向量）
//   V6 bEn = FALSE → eIdle + 全出口清零（R303）
//   V7 非法枚举态（强改 _eState）→ ELSE 兜底落 eConflict + 0730
//   V8 tStall = T#0S → 无进展窗禁用（仅超时窗判定）
// 修订记录 Revision  :
//   2026-11-22  v1.0.0  R65 首版（批 4 · 序号 10）
// ==============================================================================
TYPE E_DL_PcdSt :
(
    eIdle       := 0,  // 空闲：等指令 / idle, waiting for the command
    eExtending  := 10, // 伸出动作中：等伸出到位反馈 / extending, waiting for the extended feedback
    eRetracting := 20, // 缩回动作中：等缩回到位反馈 / retracting, waiting for the retracted feedback
    eExtOk      := 30, // 伸出到位确认 / the extended position confirmed
    eRetOk      := 40, // 缩回到位确认 / the retracted position confirmed
    eExtTo      := 50, // 伸出超时锁存驻留（复位沿解除）/ the extend timeout dwelling, released by the reset edge
    eRetTo      := 60, // 缩回超时锁存驻留（复位沿解除）/ the retract timeout dwelling, released by the reset edge
    eConflict   := 70  // 传感器矛盾锁存驻留（复位沿解除）/ the sensor conflict dwelling, released by the reset edge
);
END_TYPE

TYPE E_DL_PcdErr :
(
    eNone        := 0,  // 无错 / no error
    eSenConflict := 10, // 传感器矛盾（含非法态拦截合并通道，边界八）/ the sensor conflict, also the illegal state channel
    eMidStall    := 20, // 中途无进展 / the mid stroke stall
    eTimeoutExt  := 30, // 伸出超时 / the extend timeout
    eTimeoutRet  := 40  // 缩回超时 / the retract timeout
);
END_TYPE

FUNCTION_BLOCK FB_DL_PneuCylinderDiag
VAR_INPUT
    bCmdExt : BOOL := FALSE;     // 伸出指令 [-]，上升沿生效 / the extend command, rising edge effective
    bCmdRet : BOOL := FALSE;     // 缩回指令 [-]，上升沿生效 / the retract command, rising edge effective
    bFbExt  : BOOL := FALSE;     // 伸出到位反馈 [-] / the extended position feedback
    bFbRet  : BOOL := FALSE;     // 缩回到位反馈 [-] / the retracted position feedback
    bEn     : BOOL := TRUE;      // 使能 [-]，FALSE 时出口清零回 eIdle（R303）/ the enable
    tExtTo  : TIME := T#5S;      // 伸出到位超时窗 [毫秒]，T#0S = 禁用 / the extend timeout, zero disables
    tRetTo  : TIME := T#5S;      // 缩回到位超时窗 [毫秒]，T#0S = 禁用 / the retract timeout, zero disables
    tStall  : TIME := T#2S;      // 无进展窗 [毫秒]，须 < min(tExtTo, tRetTo)（边界三配比），T#0S = 禁用 / the stall window with the ratio rule
    bReset  : BOOL := FALSE;     // 故障复位电平，上升沿清锁存回 eIdle（边界六解除式）/ the fault reset level
END_VAR
VAR_OUTPUT
    eSt      : E_DL_PcdSt := E_DL_PcdSt.eIdle;  // 状态机出口 [状态] / the state outlet
    bErr     : BOOL := FALSE;    // 故障锁存中 [-]，TRUE = 需复位 / the fault latched flag
    eErr     : E_DL_PcdErr := E_DL_PcdErr.eNone; // 故障码出口 [码]（锁存回放）/ the error code outlet
    bTimeout : BOOL := FALSE;    // 超时驻留指示 [-]，eExtTo / eRetTo 相为 TRUE / the timeout dwelling indicator
END_VAR
VAR
    _bInit       : BOOL := FALSE; // 首拍初始化标志（R310）/ the first scan flag
    _eState      : E_DL_PcdSt := E_DL_PcdSt.eIdle; // 内部状态寄存器 [状态] / the internal state register
    _bFaultLatch : BOOL := FALSE; // 故障锁存副本 [-]（仅复位沿清除）/ the fault latch copy
    _eErrLatch   : E_DL_PcdErr := E_DL_PcdErr.eNone; // 故障码锁存 [码]（复位沿清除，FB33-1）/ the latched error code
    rtCmdExt     : R_TRIG;        // 伸出指令沿实例，段 0 无条件刷新（R7）/ the extend command edge refreshed unconditionally
    rtCmdRet     : R_TRIG;        // 缩回指令沿实例，段 0 无条件刷新 / the retract command edge refreshed unconditionally
    rtReset      : R_TRIG;        // 复位沿实例，段 0 无条件刷新 / the reset edge instance refreshed unconditionally
    tonExtTo     : TON;           // 伸出超时窗定时器，段 0 无条件刷新 / the extend timeout timer refreshed unconditionally
    tonRetTo     : TON;           // 缩回超时窗定时器，段 0 无条件刷新 / the retract timeout timer refreshed unconditionally
    tonStall     : TON;           // 无进展窗定时器，段 0 无条件刷新 / the stall window timer refreshed unconditionally
END_VAR
VAR CONSTANT
    DL_PCD_TIME0 : TIME := T#0S; // 时间零常量 [毫秒] / the time zero constant
END_VAR

// 段 0｜定时器与沿检测实例无条件周期刷新（禁入分支，R7；监视 TON 串锁存门控，FB50-1）/ segment 0, the unconditional refresh
rtCmdExt(CLK := bCmdExt);        // 伸出指令沿 / the extend command edge
rtCmdRet(CLK := bCmdRet);        // 缩回指令沿 / the retract command edge
rtReset(CLK := bReset);          // 复位沿 / the reset edge
tonExtTo(IN := bEn AND (_eState = E_DL_PcdSt.eExtending) AND (NOT _bFaultLatch) AND (tExtTo > DL_PCD_TIME0), PT := tExtTo); // 伸出超时计时（R300：基于相驻留，与到位反馈判据不同源；窗零禁用）/ the extend timeout, state sourced per R300
tonRetTo(IN := bEn AND (_eState = E_DL_PcdSt.eRetracting) AND (NOT _bFaultLatch) AND (tRetTo > DL_PCD_TIME0), PT := tRetTo); // 缩回超时计时（同前不同源口径）/ the retract timeout, state sourced per R300
tonStall(IN := bEn AND (NOT _bFaultLatch) AND ((_eState = E_DL_PcdSt.eExtending) OR (_eState = E_DL_PcdSt.eRetracting)) AND (NOT bFbExt) AND (NOT bFbRet) AND (tStall > DL_PCD_TIME0), PT := tStall); // 无进展计时（判据 = 两反馈皆无，R300 独立第三源；反馈部分在场让路超时窗，边界三）/ the stall window on the no feedback premise

// 段 1｜首拍初始化（R310）/ segment 1, the first scan init
IF NOT _bInit THEN               // 首拍一拍 / the first scan
    _bInit := TRUE;              // 置首拍标志 / raise the first scan flag
    _eState := E_DL_PcdSt.eIdle; // 状态显式落空闲 / place the state to idle
    _bFaultLatch := FALSE;       // 故障锁存显式清零 / clear the fault latch explicitly
    _eErrLatch := E_DL_PcdErr.eNone; // 码锁存显式清零 / clear the latched code explicitly
END_IF

// 段 2｜复位沿作用域（R311：清双锁存 + 迁空闲）/ segment 2, the reset edge scope
IF rtReset.Q THEN                // 复位沿 / the reset edge
    _bFaultLatch := FALSE;       // 清故障锁存（唯一解除路径，边界六自证可达）/ clear the fault latch
    _eErrLatch := E_DL_PcdErr.eNone; // 清码锁存 / clear the latched code
    _eState := E_DL_PcdSt.eIdle; // 迁回空闲 / back to idle
END_IF

// 段 3｜失能分支：强制 eIdle + 全出口清零，不 faults（R303 离相清零声明行）/ segment 3, the disabled branch
IF NOT bEn THEN                  // 失能 / disabled
    _eState := E_DL_PcdSt.eIdle; // 强制空闲 / force the idle
    _bFaultLatch := FALSE;       // 清故障锁存（使能断开 ≠ 气缸故障）/ clear the fault latch
    _eErrLatch := E_DL_PcdErr.eNone; // 清码锁存 / clear the latched code
    eSt := _eState;              // 状态出口 / the state outlet
    bErr := FALSE;               // 故障位复位 / the fault bit resets
    eErr := E_DL_PcdErr.eNone;   // 码出口复位 / the code outlet resets
    bTimeout := FALSE;           // 超时指示复位 / the timeout indicator resets
    RETURN;                      // 早退 / early return
END_IF

// 段 4｜传感器矛盾全局闸（最高优先级，R190 归因唯一独立码；锁存期不重置）/ segment 4, the sensor conflict gate
IF bFbExt AND bFbRet AND (NOT _bFaultLatch) THEN // 双反馈同真（物理不可能，真实可达：接线错 / 磁开失效）/ both feedbacks true
    _bFaultLatch := TRUE;        // 锁存故障 / latch the fault
    _eErrLatch := E_DL_PcdErr.eSenConflict; // 故障级 0731：传感器矛盾 / the conflict code
    _eState := E_DL_PcdSt.eConflict; // 迁入矛盾驻留相 / enter the conflict phase
END_IF

// 段 5｜主状态机（ENUM + CASE + ELSE 兜底；锁存期冻结禁迁移；本拍合法事件优先于超时，R275）/ segment 5, the main machine frozen on the latch
IF NOT _bFaultLatch THEN         // 未锁存才推进（故障态 / 冻结相驻留，边界五）/ advance only without a latch
    CASE _eState OF
        E_DL_PcdSt.eIdle:        // 空闲相 / the idle phase
            IF rtCmdExt.Q THEN   // 事件优先：伸出指令沿（同拍双指令伸出优先，声明口径）/ the extend edge first
                _eState := E_DL_PcdSt.eExtending; // 迁入伸出相 / enter the extending phase
            ELSIF rtCmdRet.Q THEN // 缩回指令沿 / the retract edge
                _eState := E_DL_PcdSt.eRetracting; // 迁入缩回相 / enter the retracting phase
            END_IF
        E_DL_PcdSt.eExtending:   // 伸出相（本拍合法事件优先：到位先消化，再消化反向沿与超时窗，R275）/ the extending phase, the event before the timeout
            IF bFbExt THEN       // 到位反馈（推进判据，R300 反馈源）/ the extended feedback, the advance criterion
                _eState := E_DL_PcdSt.eExtOk; // 迁入伸出到位确认相 / enter the extended confirmed phase
            ELSIF rtCmdRet.Q THEN // 反向指令沿（中途反向合法）/ the reverse edge
                _eState := E_DL_PcdSt.eRetracting; // 迁入缩回相 / enter the retracting phase
            ELSIF tonExtTo.Q THEN // 伸出超窗（故障级 0732）/ the extend timeout
                _bFaultLatch := TRUE; // 锁存故障 / latch the fault
                _eErrLatch := E_DL_PcdErr.eTimeoutExt; // 故障码 / the extend timeout code
                _eState := E_DL_PcdSt.eExtTo; // 迁入超时驻留相 / enter the timeout dwelling phase
            ELSIF tonStall.Q THEN // 无进展超窗（故障级 0734；冻结当前相驻留，边界五）/ the stall, frozen dwelling
                _bFaultLatch := TRUE; // 锁存故障 / latch the fault
                _eErrLatch := E_DL_PcdErr.eMidStall; // 故障码 / the stall code
            END_IF               // 状态保持 eExtending（锁存闸冻结迁移，语义双声明）
        E_DL_PcdSt.eRetracting:  // 缩回相（同拍序与伸出相一致，R275）/ the retracting phase with the same event order
            IF bFbRet THEN       // 到位反馈（推进判据，R300 反馈源）/ the retracted feedback
                _eState := E_DL_PcdSt.eRetOk; // 迁入缩回到位确认相 / enter the retracted confirmed phase
            ELSIF rtCmdExt.Q THEN // 反向指令沿 / the reverse edge
                _eState := E_DL_PcdSt.eExtending; // 迁入伸出相 / enter the extending phase
            ELSIF tonRetTo.Q THEN // 缩回超窗（故障级 0733）/ the retract timeout
                _bFaultLatch := TRUE; // 锁存故障 / latch the fault
                _eErrLatch := E_DL_PcdErr.eTimeoutRet; // 故障码 / the retract timeout code
                _eState := E_DL_PcdSt.eRetTo; // 迁入超时驻留相 / enter the timeout dwelling phase
            ELSIF tonStall.Q THEN // 无进展超窗（故障级 0734；冻结当前相驻留，边界五）/ the stall, frozen dwelling
                _bFaultLatch := TRUE; // 锁存故障 / latch the fault
                _eErrLatch := E_DL_PcdErr.eMidStall; // 故障码 / the stall code
            END_IF               // 状态保持 eRetracting（锁存闸冻结迁移，语义双声明）
        E_DL_PcdSt.eExtOk:       // 伸出到位确认相（位置随反馈电平同步）/ the extended confirmed phase
            IF bFbRet AND (NOT bFbExt) THEN // 反馈切换到缩回侧 / the feedback moved to the retracted side
                _eState := E_DL_PcdSt.eRetOk; // 同步缩回确认 / sync to the retracted confirmed
            ELSIF (NOT bFbExt) AND (NOT bFbRet) THEN // 双反馈皆失（物理中途态）/ both feedbacks lost
                _eState := E_DL_PcdSt.eIdle; // 回空闲重新同步 / back to idle for a resync
            ELSIF rtCmdRet.Q THEN // 缩回指令沿 / the retract edge
                _eState := E_DL_PcdSt.eRetracting; // 迁入缩回相 / enter the retracting phase
            END_IF
        E_DL_PcdSt.eRetOk:       // 缩回到位确认相（位置随反馈电平同步）/ the retracted confirmed phase
            IF bFbExt AND (NOT bFbRet) THEN // 反馈切换到伸出侧 / the feedback moved to the extended side
                _eState := E_DL_PcdSt.eExtOk; // 同步伸出确认 / sync to the extended confirmed
            ELSIF (NOT bFbExt) AND (NOT bFbRet) THEN // 双反馈皆失 / both feedbacks lost
                _eState := E_DL_PcdSt.eIdle; // 回空闲重新同步 / back to idle for a resync
            ELSIF rtCmdExt.Q THEN // 伸出指令沿 / the extend edge
                _eState := E_DL_PcdSt.eExtending; // 迁入伸出相 / enter the extending phase
            END_IF
        E_DL_PcdSt.eExtTo:       // 伸出超时驻留相（解除由段 2 复位沿承担）/ the extend timeout dwelling, released by the reset edge
            ;                    // 驻留语义由注释表达（禁自赋值死语句，R261）/ the dwell is expressed by this comment
        E_DL_PcdSt.eRetTo:       // 缩回超时驻留相（同前驻留口径）/ the retract timeout dwelling
            ;                    // 驻留语义由注释表达 / the dwell is expressed by this comment
        E_DL_PcdSt.eConflict:    // 传感器矛盾驻留相（同前驻留口径）/ the conflict dwelling
            ;                    // 驻留语义由注释表达 / the dwell is expressed by this comment
        ELSE                     // 非法枚举值拦截（边界八：合并 eSenConflict 通道，R90 反证句见码表）/ the illegal enumeration guard
            _bFaultLatch := TRUE; // 锁存故障 / latch the fault
            _eErrLatch := E_DL_PcdErr.eSenConflict; // 故障级 0730（合并通道，R90）/ the merged conflict channel
            _eState := E_DL_PcdSt.eConflict; // 落矛盾驻留相 / force the conflict phase
    END_CASE
END_IF

// 段 6｜统一出口（名实双出口同源，R191）/ segment 6, the unified outlet
eSt := _eState;                  // 状态出口 / the state outlet
bErr := _bFaultLatch;            // 故障位与锁存同源 / the fault bit from the latch
eErr := _eErrLatch;              // 码出口与锁存同源（锁存回放）/ the code outlet from the latch
bTimeout := (_eState = E_DL_PcdSt.eExtTo) OR (_eState = E_DL_PcdSt.eRetTo); // 超时驻留指示与状态同源 / the timeout indicator from the state
END_FUNCTION_BLOCK

//==============================================================================
// 功能块：FB_DL_ConveyorAccumGateSeq ｜ 中文名称：输送线积放闸门三态序列编排
// 所属子库：DL_Process ｜ 版本：v1.0.0 ｜ 日期：2026-11-23
// 兼容：CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop（纯 IEC 61131-3 第 3 版，零方言）
// 功能描述：积放/释放/满流三态编排：积放相闸门关闭、物料在积放位堆积；
//           积放位满且下游可收 → 释放相（闸门开，按 tKick 节拍向下游发
//           bDownKick 联动脉冲）；积放位满且下游不可收 → 满流相（闸门关 +
//           bUpstreamStop 请求上游节拍停止，信息级留痕）。闸门开启设最小
//           开门时长防阀/闸颤振；释放完成回积放或待机。下游节拍联动由
//           自复位周期窗 TON 生成（IN := NOT tonXxx.Q，R188 口径）。
// 开源溯源 (Origin)：原创实现（s9-conv 输送工程惯例深化，零外部源码行，
//           clean-room 独立编写）
// 公开接口清单：输入 bEn / bUpstreamRun / bFullSens / bDownReady /
//               tMinGate / tKick；
//               输出 bGateOpen / bUpstreamStop / bDownKick / eState /
//               uErrCode / bValid
// 单位表：tMinGate[ms] / tKick[ms]，其余 BOOL 引脚无量纲
// 输入契约：bFullSens 为积放位满传感，bDownReady 为下游可收声明，均经
//           IO 映射层注入；tMinGate 防闸门颤振下限；tKick 节拍周期。
// 输出契约：bGateOpen 请求级闸门开指令（执行器驱动须上层联锁）；
//           bDownKick 单拍节拍脉冲；uErrCode 信息级不锁存；
//           bValid 恒 TRUE（本件无故障级条件）。
// 错误码表：16#0005_3050 信息级（满流节拍停止请求激活，不置 bError）/
//           16#0005_3051 信息级（非法状态兜底入安全侧待机，不置 bError）/
//           16#0005_3052 预留禁用（不得挪用）
// 状态机：E_DL_AccumGateState（本文件唯一定义，全库唯一属主）：
//           eIdle = 0 / eAccumulating = 10 / eFullStop = 20 / eReleasing = 30
// 边界行为：① 闸门默认关（所有相默认值安全侧），开门仅释放相声明；
//           ② 最小开门时长未满不关门（防颤振）；
//           ③ 节拍脉冲 TON 自复位（IN := NOT tonKick.Q），每拍无条件刷新；
//           ④ 撤使能任意相回待机且闸门关（门控挂状态量）；
//           ⑤ CASE 带 ELSE 非法态兜底回 eIdle（信息级留痕）；
//           ⑥ 本件无故障级条件，不设 bError（码表与实现对齐，不虚声明）。
// 修订历史：v1.0.0 2026-11-23 首版（R73 派单 · 批 2 · 序 6）
//==============================================================================

(*------------------------------------------------------------------------------
 * 枚举: E_DL_AccumGateState（归属本功能块，同文件发布，全库唯一属主）
 * 含义: 积放闸门序列相位，成员与 CASE 标签双向完备。
 *-----------------------------------------------------------------------------*)
TYPE E_DL_AccumGateState :
(
    eIdle         := 0,   // 待机：闸门关，等使能与上游 / Idle, gate closed
    eAccumulating := 10,  // 积放中：闸门关，物料堆积 / Accumulating, gate closed, stock piling
    eFullStop     := 20,  // 满流：闸门关 + 上游节拍停止请求 / Full, gate closed and upstream stop requested
    eReleasing    := 30   // 释放中：闸门开 + 下游节拍联动脉冲 / Releasing, gate open with downstream kick pulses
);
END_TYPE

(*==============================================================================
 * 功能块: FB_DL_ConveyorAccumGateSeq
 * 调用约定: 每个扫描周期无条件调用一次；实例状态全部驻留于私有变量。
 * 调用示例: accumGate(bEn := bLineEn, bUpstreamRun := bConvUpRun,
 *                     bFullSens := bAccumFull, bDownReady := bDownCS,
 *                     tMinGate := T#2S, tKick := T#1S);
 *          bGateOpen 驱动闸门电磁阀（经输出映射层），bDownKick 作下游
 *          节拍联动脉冲接入下游段使能合取。
 * 组装说明: ① 闸门驱动输出须在上层输出映射层复加机械限位联锁，本件
 *             bGateOpen 属请求级信号（红线 R2：零物理地址）；
 *           ② bFullSens / bDownReady 传感引脚经 PRG_IoMapping 读入注入；
 *           ③ tKick 节拍脉冲为单拍有效量，上层沿检测可省（直接作使能
 *             窗合取），如需展宽请串 FB_DL_PulseStretch；
 *           ④ 多级积放串联时，本级 bDownReady 取下级 accumGate.bGateOpen
 *             的取反（下级开门期间本级视为不可收）。
 *==============================================================================*)
FUNCTION_BLOCK FB_DL_ConveyorAccumGateSeq
VAR_INPUT
    bEn          : BOOL := FALSE;     // 使能（FALSE 任意相回待机）/ Enable, FALSE returns to idle from any phase
    bUpstreamRun : BOOL := FALSE;     // 上游段运行中 / Upstream section running
    bFullSens    : BOOL := FALSE;     // 积放位满传感器 / Accumulation zone full sensor
    bDownReady   : BOOL := FALSE;     // 下游可接收声明 / Downstream ready to receive
    tMinGate     : TIME := T#2S;      // 最小开门时长 [ms]，防闸门颤振 / Minimum gate-open duration [ms], anti-chatter
    tKick        : TIME := T#1S;      // 下游节拍联动脉冲周期 [ms] / Downstream kick pulse period [ms]
END_VAR
VAR_OUTPUT
    bGateOpen    : BOOL;              // 闸门开指令（仅释放相）/ Gate open command, releasing phase only
    bUpstreamStop: BOOL;              // 上游节拍停止请求（满流相）/ Upstream stop request, full phase
    bDownKick    : BOOL;              // 下游节拍联动脉冲（单拍有效）/ Downstream kick pulse, single-scan
    eState       : E_DL_AccumGateState; // 序列当前相位 / Current sequence phase
    uErrCode     : UDINT;             // 信息级码，0 = 无信息 / Info-level code, 0 = none
    bValid       : BOOL;              // 输出可用标志 / Outputs usable flag
END_VAR
VAR
    tonMinGate   : TON;               // 最小开门时长定时器，每拍无条件刷新 / Minimum gate-open timer, refreshed every scan
    tonKick      : TON;               // 节拍脉冲自复位定时器，每拍无条件刷新 / Kick pulse self-reset timer, refreshed every scan
END_VAR
VAR CONSTANT
    DL_CG_CODE_FULL : UDINT := 16#0005_3050; // 信息级：满流停止请求码 / Info code: full-flow stop request
    DL_CG_CODE_ILL  : UDINT := 16#0005_3051; // 信息级：非法状态兜底码 / Info code: illegal state fallback
END_VAR

// ---- 段 1｜定时器无条件刷新（红线 R7：禁入条件分支；tonKick 自复位 R188）----
tonMinGate(IN := (eState = E_DL_AccumGateState.eReleasing), PT := tMinGate); // 开门计时按相断输入 / Gate timer input per phase
tonKick(IN := (eState = E_DL_AccumGateState.eReleasing)
        AND bDownReady AND NOT tonKick.Q, PT := tKick); // 周期窗自复位（R188 口径）/ Self-resetting window per R188

// ---- 段 2｜出口默认值：入口即赋安全侧确定值 ----
bGateOpen     := FALSE;             // 闸门默认关（安全侧）/ Gate preset closed, safe side
bUpstreamStop := FALSE;             // 上游停止请求默认 FALSE / Upstream stop preset FALSE
bDownKick     := FALSE;             // 节拍脉冲默认 FALSE（相内重映射）/ Kick pulse preset FALSE
uErrCode      := 16#0000_0000;      // 信息码每拍重算（信息级不锁存）/ Info code recomputed, never latched
bValid        := TRUE;              // 可用标志默认 TRUE / Usable flag preset TRUE

// ---- 段 3｜序列状态机（CASE 带 ELSE；满流先于释放判决防抢跑）----
CASE eState OF
    E_DL_AccumGateState.eIdle:        // 待机相：闸门关，等使能
        IF bEn AND bUpstreamRun THEN
            eState := E_DL_AccumGateState.eAccumulating; // 进入积放相 / Enter accumulating
        END_IF

    E_DL_AccumGateState.eAccumulating:// 积放相：闸门关，堆积至满
        IF NOT (bEn AND bUpstreamRun) THEN
            eState := E_DL_AccumGateState.eIdle; // 撤条件回待机 / Conditions lost, back to idle
        ELSIF bFullSens THEN
            IF bDownReady THEN        // 满且下游可收 → 释放（满流先判下游）/ Full and downstream ready, release first
                eState := E_DL_AccumGateState.eReleasing;
            ELSE                      // 满且下游不可收 → 满流停止请求 / Full and not ready, full-stop
                eState := E_DL_AccumGateState.eFullStop;
            END_IF
        END_IF

    E_DL_AccumGateState.eFullStop:    // 满流相：闸门关 + 上游停止请求（信息级）
        bUpstreamStop := TRUE;        // 上游节拍停止请求 / Upstream stop request
        uErrCode := DL_CG_CODE_FULL;  // 信息级留痕（每拍重算，不置 bError）/ Info trace, no fault flag
        IF bDownReady THEN            // 下游恢复可收 → 转释放 / Downstream ready, go release
            eState := E_DL_AccumGateState.eReleasing;
        ELSIF NOT bFullSens THEN      // 积放位已不满（上游停后消化）→ 回积放 / Zone drained, back to accumulating
            eState := E_DL_AccumGateState.eAccumulating;
        END_IF

    E_DL_AccumGateState.eReleasing:   // 释放相：闸门开 + 节拍联动脉冲
        bGateOpen := TRUE;            // 闸门开声明 / Gate open declared
        bDownKick := tonKick.Q AND bDownReady; // 节拍联动脉冲（单拍有效）/ Kick pulse, single-scan
        IF NOT bEn THEN
            eState := E_DL_AccumGateState.eIdle; // 撤使能回待机 / Disable, back to idle
        ELSIF tonMinGate.Q AND (NOT bFullSens) THEN
            IF bUpstreamRun THEN
                eState := E_DL_AccumGateState.eAccumulating; // 释放完回积放 / Done, back to accumulating
            ELSE
                eState := E_DL_AccumGateState.eIdle; // 释放完且上游停回待机 / Done and upstream stopped, back to idle
            END_IF
        ELSIF (NOT bDownReady) AND tonMinGate.Q THEN
            eState := E_DL_AccumGateState.eFullStop; // 下游中途不可收 → 满流 / Downstream lost, go full-stop
        END_IF

    ELSE                              // 非法状态兜底（R21：CASE 必带 ELSE）
        eState   := E_DL_AccumGateState.eIdle; // 拦截非法值回待机（安全侧闸门关）/ Catch illegal value to idle, gate closed
        uErrCode := DL_CG_CODE_ILL;   // 信息级兜底留痕（不置 bError）/ Info-level fallback trace
END_CASE

// ---- 段 4｜统一出口：撤使能兜底（门控挂状态量）----
IF NOT bEn THEN
    IF eState <> E_DL_AccumGateState.eIdle THEN
        eState := E_DL_AccumGateState.eIdle; // 回待机 / Back to idle
    END_IF
    bGateOpen := FALSE;               // 闸门强制关 / Gate forced closed
    bUpstreamStop := FALSE;           // 停止请求撤除 / Stop request withdrawn
END_IF
END_FUNCTION_BLOCK

//==============================================================================
// 函数：FC_DL_MovingRangeCalc ｜ 中文名称：滑动极差（相邻样本差）原子计算
// 所属子库：DL_MathData ｜ 版本：v1.0.0 ｜ 日期：2026-11-23
// 兼容：CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop / Machine Expert（纯标准库）
// 功能描述：SPC 判稳前置原子：MR = |x_i − x_(i−1)|，相邻两样本的极差。
//           无状态原子：本拍新样本与上一拍样本由调用方传入，本件不驻留
//           历史样本（滑动窗管理属上层 FB，职责边界见头注释）。
// 开源溯源 (Origin)：原创实现（t2-1-lgf-measurement 测量链语义深化，零外部
//           源码行，clean-room 独立编写）
// 公开接口清单：输入 fNewSample / fPrevSample；输出 fRange / bValid
// 单位表：fNewSample / fPrevSample / 返回值 [工程单位随调用方，差值不改单位]
// 输入契约：两样本须同一工程单位同一测点（跨测点差值无物理意义）；调用方
//           负责滑动窗历史驻留与回传节奏。
// 输出契约：返回值为极差（恒非负）；bValid = FALSE 拍返回哨兵 0.0，
//           调用方禁将哨兵值计入 SPC 控制图样本。
// 错误码表：纯函数无状态机码轨；无效输入经 bValid = FALSE 表达（哨兵返回
//           0.0），本件不占用 16#0001 段码位（邻件免让位）
// 状态机：N/A（纯函数，无状态，可重入）
// 边界行为：① 任一输入非有限（NaN 自反判 + 幅值上限判）→ bValid := FALSE、
//           哨兵 0.0 返回；② 极差恒非负（ABS 内建保证）；③ 无除法无域闸。
// 修订历史：v1.0.0 2026-11-23 首版（R73 派单 · 批 2 · 序 7）
//==============================================================================

(*------------------------------------------------------------------------------
 * 调用示例：fMR := FC_DL_MovingRangeCalc(fNewSample := x_i,
 *                                        fPrevSample := x_im1,
 *                                        bValid => bOk);
 * 注意：滑动窗历史驻留在上层 FB，本件只做相邻差值，两拍调用间无状态。
 * 组装说明：① 上层滑动窗管理件持有 x_(i−1) 并在下一拍回传 fPrevSample，
 *             本件零跨拍状态、可重入；
 *           ② 连续多拍极差进入 SPC 控制图判稳判据前，须校 bValid；
 *           ③ 本件输出单位与输入工程单位一致（差值不改单位）。
 *-----------------------------------------------------------------------------*)
FUNCTION FC_DL_MovingRangeCalc : LREAL
VAR_INPUT
    fNewSample  : LREAL;               // 本拍新样本 [工程单位随调用方] / New sample this scan [unit per caller]
    fPrevSample : LREAL;               // 上一拍样本 [工程单位随调用方] / Previous sample [unit per caller]
END_VAR
VAR_OUTPUT
    bValid      : BOOL;                // 结果有效标志，FALSE 时返回哨兵 0.0 / Result validity flag
END_VAR
VAR CONSTANT
    DL_MR_INF   : LREAL := 1.7976931348623157E308; // LREAL 幅值上限 / LREAL magnitude ceiling
    DL_MR_ZERO  : LREAL := 0.0;        // 无效哨兵返回值 / Sentinel return for invalid
END_VAR

// ---- 段 1｜出口默认值（纯函数无实例，无定时器/沿刷新义务）----
bValid := FALSE;                      // 缺省无效 / Invalid by default

// ---- 段 2｜输入防御：非有限值（NaN 自反判 + Inf 幅值判，R79）----
IF (fNewSample <> fNewSample) OR (ABS(fNewSample) > DL_MR_INF)
   OR (fPrevSample <> fPrevSample) OR (ABS(fPrevSample) > DL_MR_INF) THEN
    FC_DL_MovingRangeCalc := DL_MR_ZERO; // 无效输入：哨兵零返回，不进入运算 / Invalid input, sentinel zero return
    RETURN;                            // 结构早退 / early exit
END_IF

// ---- 段 3｜极差主体：MR = |x_i − x_(i−1)|，恒非负 ----
FC_DL_MovingRangeCalc := ABS(fNewSample - fPrevSample); // 滑动极差 / Moving range
bValid := TRUE;                       // 全部防御通过：结果有效 / Result valid
END_FUNCTION

//==============================================================================
// 函数：FC_DL_PressureAltitudeCalc ｜ 中文名称：ISA 标准大气气压↔海拔双向换算
// 所属子库：DL_MathData ｜ 版本：v1.0.1 ｜ 日期：2026-11-23
// 兼容：CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop / Machine Expert（纯标准库）
// 功能描述：ISA 对流层（0~11 km）标准大气双向换算。正解（海拔→气压）：
//           p = p0·(1 − L·h/T0)^(g/(R·L))；反解（气压→海拔）：
//           h = (T0/L)·(1 − (p/p0)^(R·L/g))。常量取 ISA 公开口径：
//           p0 = 101325 Pa、T0 = 288.15 K、L = 0.0065 K/m、
//           g = 9.80665 m/s2、R = 287.05287 J/(kg·K)。
// 开源溯源 (Origin)：原创实现（t1-2-oscat-building 建筑环境语义借用，ISA
//           公开公式，零外部源码行，clean-room 独立编写）
// 公开接口清单：输入 eMode / fValue；输出 fResult / bValid
// 错误码表：纯函数无状态机码轨；无效输入经 bValid = FALSE 表达（哨兵返回
//           0.0），本件不占用 16#0001 段码位（邻件免让位）
// 状态机：E_DL_PressAltMode（本文件唯一定义，全库唯一属主）：
//           eAltToPress = 0 / ePressToAlt = 1；枚举非法值走 CASE ELSE 兜底
// 边界行为：① 海拔域 [-500, 11000] m（ISA 对流层有效域，域外不外推）；
//           ② 气压域 [22632, 107477.5] Pa（对流层两端标准值，域外不外推；
//             −500 m 端值 R73 按公式订正）；
//           ③ L 恒非零为 ISA 常量，仍按纪律做非零断言常量（编译期保护）；
//           ④ 非有限输入（NaN 自反判 + 幅值判）→ 哨兵 0.0 返回；
//           ⑤ 枚举非法值 → CASE ELSE 哨兵返回。
// 修订历史：v1.0.0 2026-11-23 首版（R73 派单 · 批 2 · 序 8）
//           v1.0.1 2026-11-23 R73 返修：DL_PA_PMAX 按 ISA 标准大气公式订正
//           为 −500 m 对应值 107477.5 Pa（原 108900.0 与公式不符），边界
//           行为②同步订正。
//==============================================================================

(*------------------------------------------------------------------------------
 * 枚举: E_DL_PressAltMode（归属本函数，同文件发布，全库唯一属主）
 * 含义: 换算方向选择，成员与 CASE 标签双向完备。
 *-----------------------------------------------------------------------------*)
TYPE E_DL_PressAltMode :
(
    eAltToPress  := 0,  // 正解：输入海拔 [米]，输出气压 [帕] / Forward: altitude in, pressure out
    ePressToAlt  := 1   // 反解：输入气压 [帕]，输出海拔 [米] / Inverse: pressure in, altitude out
);
END_TYPE

(*------------------------------------------------------------------------------
 * 调用示例：fP := FC_DL_PressureAltitudeCalc(
 *             eMode := E_DL_PressAltMode.eAltToPress, fValue := 1500.0,
 *             bValid => bOk);
 * 注意：仅当 bValid = TRUE 时结果可进入判据；域外输入拒绝不外推。
 *-----------------------------------------------------------------------------*)
FUNCTION FC_DL_PressureAltitudeCalc : LREAL
VAR_INPUT
    eMode    : E_DL_PressAltMode;      // 换算方向枚举 [—] / Conversion direction enum
    fValue   : LREAL;                  // 输入量：海拔 [米] 或气压 [帕]，按 eMode 解释 / Input value, altitude [m] or pressure [Pa] per eMode
END_VAR
VAR_OUTPUT
    bValid   : BOOL;                   // 结果有效标志，FALSE 时返回哨兵 0.0 / Result validity flag
END_VAR
VAR CONSTANT
    DL_PA_P0   : LREAL := 101325.0;    // 海平面标准气压 [帕] / ISA sea-level standard pressure [Pa]
    DL_PA_T0   : LREAL := 288.15;      // 海平面标准温度 [开尔文] / ISA sea-level standard temperature [K]
    DL_PA_L    : LREAL := 0.0065;      // 对流层温度直减率 [开尔文每米] / ISA tropospheric lapse rate [K per m]
    DL_PA_G    : LREAL := 9.80665;     // 标准重力加速度 [米每平方秒] / Standard gravity [m per s2]
    DL_PA_R    : LREAL := 287.05287;   // 干空气气体常数 [焦每千克每开尔文] / Dry-air gas constant [J per kg per K]
    DL_PA_HMIN : LREAL := -500.0;      // 海拔有效下限 [米]（域外不外推）/ Altitude valid floor [m], no extrapolation
    DL_PA_HMAX : LREAL := 11000.0;     // 海拔有效上限 [米]（对流层顶）/ Altitude valid ceiling [m], tropopause
    DL_PA_PMIN : LREAL := 22632.0;     // 气压有效下限 [帕]（11 km 标准值）/ Pressure valid floor [Pa], 11 km ISA value
    DL_PA_PMAX : LREAL := 107477.5;    // 气压有效上限 [帕]（-500 m ISA 标准值，R73 订正：原 108900.0 与公式不符）/ Pressure valid ceiling [Pa], ISA value at -500 m, corrected
    DL_PA_EXP1 : LREAL := 5.2558797;   // 正解指数 g/(R·L) 预算值 [1] / Forward exponent g/(R*L), precomputed
    DL_PA_EXP2 : LREAL := 0.190263236; // 反解指数 R·L/g 预算值 [1] / Inverse exponent R*L/g, precomputed
    DL_PA_INF  : LREAL := 1.7976931348623157E308; // LREAL 幅值上限 / LREAL magnitude ceiling
    DL_PA_ZERO : LREAL := 0.0;         // 无效哨兵返回值 / Sentinel return for invalid
END_VAR

// ---- 段 1｜出口默认值（纯函数无实例，无定时器/沿刷新义务）----
bValid := FALSE;                      // 缺省无效 / Invalid by default

// ---- 段 2｜输入防御：非有限值（NaN 自反判 + Inf 幅值判，R79）----
IF (fValue <> fValue) OR (ABS(fValue) > DL_PA_INF) THEN
    FC_DL_PressureAltitudeCalc := DL_PA_ZERO; // 无效输入：哨兵零返回 / Invalid input, sentinel zero return
    RETURN;                            // 结构早退 / early exit
END_IF

// ---- 段 3｜双向换算主体（CASE 带 ELSE；域闸拒绝不外推）----
CASE eMode OF
    E_DL_PressAltMode.eAltToPress:     // 正解：海拔 → 气压
        IF (fValue < DL_PA_HMIN) OR (fValue > DL_PA_HMAX) THEN
            FC_DL_PressureAltitudeCalc := DL_PA_ZERO; // 海拔域外拒绝（哨兵零）/ Altitude out of range, refused
            RETURN;                    // 结构早退 / early exit
        END_IF
        FC_DL_PressureAltitudeCalc := DL_PA_P0
            * EXPT((1.0 - DL_PA_L * fValue / DL_PA_T0), DL_PA_EXP1); // 标准大气压 [帕] / ISA standard pressure [Pa]

    E_DL_PressAltMode.ePressToAlt:     // 反解：气压 → 海拔
        IF (fValue < DL_PA_PMIN) OR (fValue > DL_PA_PMAX) THEN
            FC_DL_PressureAltitudeCalc := DL_PA_ZERO; // 气压域外拒绝（哨兵零）/ Pressure out of range, refused
            RETURN;                    // 结构早退 / early exit
        END_IF
        FC_DL_PressureAltitudeCalc := (DL_PA_T0 / DL_PA_L)
            * (1.0 - EXPT((fValue / DL_PA_P0), DL_PA_EXP2)); // 标准海拔 [米] / ISA standard altitude [m]

    ELSE                               // 枚举非法值兜底（R21：CASE 必带 ELSE）
        FC_DL_PressureAltitudeCalc := DL_PA_ZERO; // 非法枚举：哨兵零返回 / Illegal enum, sentinel zero return
        RETURN;                        // 结构早退 / early exit
END_CASE

bValid := TRUE;                       // 全部防御通过：结果有效 / Result valid
END_FUNCTION

//==============================================================================
// 函数：FC_DL_TorqueUnitConvert ｜ 中文名称：转矩单位换算（枚举选路 + 域闸）
// 所属子库：DL_MathData ｜ 版本：v1.0.0 ｜ 日期：2026-11-23
// 兼容：CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop / Machine Expert（纯标准库）
// 功能描述：转矩单位双向换算原子：N·m ↔ kgf·m ↔ lb·ft。换算因子取国际
//           公开口径：1 kgf·m = 9.80665 N·m；1 lb·ft = 1.35582 N·m。
//           允许带符号输入（正/负转矩均合法），换算为纯线性乘法。
// 开源溯源 (Origin)：候选队列 MS_TO_KMH（oscatBasic，MIT 许可，
//           https://github.com/tkucic/brOscatLib/blob/main/oscatBasic/MS_TO_KMH.st）
//           ——单位换算族行为定义参考；原名 MS_TO_KMH → 道莅
//           FC_DL_TorqueUnitConvert，clean-room 独立重写（枚举选路 + 域闸
//           增强为道莅防御规范增量，零源码行复制）
// 公开接口清单：输入 eMode / fValue；输出 fResult / bValid
// 错误码表：纯函数无状态机码轨；无效输入经 bValid = FALSE 表达（哨兵返回
//           0.0），本件不占用 16#0001 段码位（邻件免让位）
// 状态机：E_DL_TorqueUnit（本文件唯一定义，全库唯一属主）：
//           eNmToKgm = 0 / eKgmToNm = 1 / eNmToLbFt = 2 / eLbFtToNm = 3；
//           枚举非法值走 CASE ELSE 兜底
// 边界行为：① 任一输入非有限 → 哨兵 0.0 返回；
//           ② 幅值越 LREAL 可表域 → 哨兵 0.0 返回；
//           ③ 枚举非法值 → CASE ELSE 哨兵返回；
//           ④ 纯线性乘法无除法（乘法因子均为常量非零）。
// 修订历史：v1.0.0 2026-11-23 首版（R73 派单 · 批 3 · 序 11）
//==============================================================================

(*------------------------------------------------------------------------------
 * 枚举: E_DL_TorqueUnit（归属本函数，同文件发布，全库唯一属主）
 * 含义: 换算方向选择，成员与 CASE 标签双向完备。
 *-----------------------------------------------------------------------------*)
TYPE E_DL_TorqueUnit :
(
    eNmToKgm  := 0,   // 牛米 → 千克力米 / N·m to kgf·m
    eKgmToNm  := 1,   // 千克力米 → 牛米 / kgf·m to N·m
    eNmToLbFt := 2,   // 牛米 → 磅英尺 / N·m to lb·ft
    eLbFtToNm := 3    // 磅英尺 → 牛米 / lb·ft to N·m
);
END_TYPE

(*------------------------------------------------------------------------------
 * 调用示例：fT := FC_DL_TorqueUnitConvert(
 *             eMode := E_DL_TorqueUnit.eNmToKgm, fValue := 25.0,
 *             bValid => bOk);
 * 注意：仅当 bValid = TRUE 时结果可进入判据；带符号转矩均合法。
 *-----------------------------------------------------------------------------*)
FUNCTION FC_DL_TorqueUnitConvert : LREAL
VAR_INPUT
    eMode    : E_DL_TorqueUnit;        // 换算方向枚举 [—] / Conversion direction enum
    fValue   : LREAL;                  // 输入转矩值 [源单位]，带符号合法 / Torque value [source unit], signed allowed
END_VAR
VAR_OUTPUT
    bValid   : BOOL;                   // 结果有效标志，FALSE 时返回哨兵 0.0 / Result validity flag
END_VAR
VAR CONSTANT
    DL_TQ_KGM  : LREAL := 9.80665;     // 千克力米→牛米因子 [牛米每千克力米] / kgf·m to N·m factor
    DL_TQ_LBFT : LREAL := 1.35582;     // 磅英尺→牛米因子 [牛米每磅英尺] / lb·ft to N·m factor
    DL_TQ_INF  : LREAL := 1.7976931348623157E308; // LREAL 幅值上限 / LREAL magnitude ceiling
    DL_TQ_ZERO : LREAL := 0.0;         // 无效哨兵返回值 / Sentinel return for invalid
END_VAR

// ---- 段 1｜出口默认值（纯函数无实例，无定时器/沿刷新义务）----
bValid := FALSE;                      // 缺省无效 / Invalid by default

// ---- 段 2｜输入防御：非有限值（NaN 自反判 + Inf 幅值判，R79）----
IF (fValue <> fValue) OR (ABS(fValue) > DL_TQ_INF) THEN
    FC_DL_TorqueUnitConvert := DL_TQ_ZERO; // 无效输入：哨兵零返回 / Invalid input, sentinel zero return
    RETURN;                            // 结构早退 / early exit
END_IF

// ---- 段 3｜换算主体（CASE 带 ELSE；纯线性乘法，因子常量非零）----
CASE eMode OF
    E_DL_TorqueUnit.eNmToKgm:          // 牛米 → 千克力米（除以因子，幅值只减不溢）
        FC_DL_TorqueUnitConvert := fValue / DL_TQ_KGM; // 千克力米 [kgf·m] / kgf·m result

    E_DL_TorqueUnit.eKgmToNm:          // 千克力米 → 牛米（乘因子，幅值放大先闸）
        IF ABS(fValue) > (DL_TQ_INF / DL_TQ_KGM) THEN
            FC_DL_TorqueUnitConvert := DL_TQ_ZERO; // 乘积越表域哨兵返回（预检防 Inf 污染）/ Product would overflow, sentinel return
            RETURN;                    // 结构早退 / early exit
        END_IF
        FC_DL_TorqueUnitConvert := fValue * DL_TQ_KGM; // 牛米 [N·m] / N·m result

    E_DL_TorqueUnit.eNmToLbFt:         // 牛米 → 磅英尺（除以因子，幅值只减不溢）
        FC_DL_TorqueUnitConvert := fValue / DL_TQ_LBFT; // 磅英尺 [lb·ft] / lb·ft result

    E_DL_TorqueUnit.eLbFtToNm:         // 磅英尺 → 牛米（乘因子，幅值放大先闸）
        IF ABS(fValue) > (DL_TQ_INF / DL_TQ_LBFT) THEN
            FC_DL_TorqueUnitConvert := DL_TQ_ZERO; // 乘积越表域哨兵返回（预检防 Inf 污染）/ Product would overflow, sentinel return
            RETURN;                    // 结构早退 / early exit
        END_IF
        FC_DL_TorqueUnitConvert := fValue * DL_TQ_LBFT; // 牛米 [N·m] / N·m result

    ELSE                               // 枚举非法值兜底（R21：CASE 必带 ELSE）
        FC_DL_TorqueUnitConvert := DL_TQ_ZERO; // 非法枚举：哨兵零返回 / Illegal enum, sentinel zero return
        RETURN;                        // 结构早退 / early exit
END_CASE

bValid := TRUE;                       // 全部防御通过：结果有效 / Result valid
END_FUNCTION

//==============================================================================
// 函数：FC_DL_BitRotateEx ｜ 中文名称：位串循环移位（跨位回卷）
// 所属子库：DL_Base ｜ 版本：v1.0.0 ｜ 日期：2026-11-23
// 兼容：CODESYS V3.5+ / TwinCAT 3 / 汇川 InoProShop（纯标准库 SHL/SHR 组合）
// 功能描述：位串循环移位原子：左/右方向 × 8/16/32 位宽度域内回卷。
//           实现口径：SHL(x,n) OR SHR(x,w−n) 组合回卷，n 先归一到
//           [0, w−1]（负移位量取模回卷，禁 SHL(x,位宽) 未定义行为——
//           移位量归一后为 0 时直通返回原值，落位组合分支的移位量恒在
//           1..w−1 安全域）。与 ShlEx/ShrEx 邻件分工：那两件做饱和/截断
//           单向移位，本件只做回卷循环移位，互不替代。
// 开源溯源 (Origin)：原创实现（t0-std-wrapper 包装族补口，零外部源码行，
//           clean-room 独立编写；与 ShlEx/ShrEx 邻件分工已在头注释声明）
// 公开接口清单：输入 dwVal / nShift / eDir / eWidth；输出 dwRotated / bValid
// 错误码表：纯函数无状态机码轨；无效输入经 bValid = FALSE 表达（哨兵返回
//           0.0），本件不占用 16#0001 段码位（邻件免让位）
// 状态机：E_DL_RotDir / E_DL_RotWidth（本文件唯一定义，全库唯一属主）：
//           方向 eLeft = 0 / eRight = 1；宽度 eW8 = 8 / eW16 = 16 / eW32 = 32
// 边界行为：① 移位量任意整数（含负值）先 MOD 归一到 [0, w−1]；
//           ② 归一后为 0 直通返回原值（组合分支移位量恒 1..w−1，禁
//             SHL(x,位宽) 未定义行为）；
//           ③ 宽度域外（非 8/16/32）→ 哨兵 0.0 返回；
//           ④ 回卷结果按宽度掩码截取（高位残留清零）。
// 修订历史：v1.0.0 2026-11-23 首版（R73 派单 · 批 3 · 序 12）
//==============================================================================

(*------------------------------------------------------------------------------
 * 枚举: E_DL_RotDir / E_DL_RotWidth（归属本函数，同文件发布，全库唯一属主）
 * 含义: 移位方向与位串宽度域，成员与 CASE 标签双向完备。
 *-----------------------------------------------------------------------------*)
TYPE E_DL_RotDir :
(
    eLeft  := 0,   // 左循环移位 / Rotate left
    eRight := 1    // 右循环移位 / Rotate right
);
END_TYPE

TYPE E_DL_RotWidth :
(
    eW8  := 8,     // 8 位宽度域 / 8-bit width domain
    eW16 := 16,    // 16 位宽度域 / 16-bit width domain
    eW32 := 32     // 32 位宽度域 / 32-bit width domain
);
END_TYPE

(*------------------------------------------------------------------------------
 * 调用示例：dwR := FC_DL_BitRotateEx(dwVal := 16#0000_00A1,
 *             nShift := 3, eDir := E_DL_RotDir.eLeft,
 *             eWidth := E_DL_RotWidth.eW8, bValid => bOk);
 * 注意：移位量先归一回卷，任意整数（含负）均合法；宽度域外拒绝。
 *-----------------------------------------------------------------------------*)
FUNCTION FC_DL_BitRotateEx : DWORD
VAR_INPUT
    dwVal   : DWORD;                   // 输入位串 [—] / Input bit pattern
    nShift  : DINT;                    // 移位量 [位]，任意整数（含负，取模回卷）/ Shift amount [bits], any integer, wrapped by modulo
    eDir    : E_DL_RotDir;             // 移位方向枚举 [—] / Rotation direction enum
    eWidth  : E_DL_RotWidth;           // 位串宽度域枚举 [位] / Width domain enum [bits]
END_VAR
VAR_OUTPUT
    bValid  : BOOL;                    // 结果有效标志，FALSE 时返回哨兵 0.0 / Result validity flag
END_VAR
VAR
    nW      : DINT;                    // 生效宽度 [位] / Effective width [bits]
    nEff    : DINT;                    // 归一后移位量 [位]，域 0..w−1 / Normalized shift [bits], range 0..w-1
    dwMask  : DWORD;                   // 宽度掩码 / Width mask
    dwLo    : DWORD;                   // 回卷低位段 / Wrapped low segment
    dwHi    : DWORD;                   // 回卷高位段 / Wrapped high segment
END_VAR
VAR CONSTANT
    DW_ROT_SENTINEL : DWORD := 16#0000_0000; // 无效哨兵返回值 / Sentinel return for invalid
END_VAR

// ---- 段 1｜出口默认值（纯函数无实例，无定时器/沿刷新义务）----
bValid := FALSE;                      // 缺省无效 / Invalid by default

// ---- 段 2｜宽度域解析（CASE 带 ELSE；非法宽度拒绝）----
CASE eWidth OF
    E_DL_RotWidth.eW8:                 // 8 位域：掩码低 8 位 / 8-bit domain
        nW     := 8;                   // 生效宽度 [位] / Effective width
        dwMask := 16#0000_00FF;        // 宽度掩码 / Width mask
    E_DL_RotWidth.eW16:                // 16 位域：掩码低 16 位 / 16-bit domain
        nW     := 16;                  // 生效宽度 [位] / Effective width
        dwMask := 16#0000_FFFF;        // 宽度掩码 / Width mask
    E_DL_RotWidth.eW32:                // 32 位域：全掩码 / 32-bit domain
        nW     := 32;                  // 生效宽度 [位] / Effective width
        dwMask := 16#FFFF_FFFF;        // 宽度掩码 / Width mask
    ELSE                               // 枚举非法值兜底（R21：CASE 必带 ELSE）
        FC_DL_BitRotateEx := DW_ROT_SENTINEL; // 非法宽度：哨兵零返回 / Illegal width, sentinel zero return
        RETURN;                        // 结构早退 / early exit
END_CASE

// ---- 段 3｜移位量归一：MOD 取模 + 双侧回卷（负移位量合法）----
nEff := nShift MOD nW;                // 先取模（可能为负，DINT MOD 语义随被除数）/ Modulo first, may be negative
IF nEff < 0 THEN
    nEff := nEff + nW;                // 负移位量回卷到 [0, w−1] / Negative shift wrapped up
END_IF

// ---- 段 4｜回卷主体：移位量 0 直通；组合分支移位量恒 1..w−1 安全域 ----
IF nEff = 0 THEN
    FC_DL_BitRotateEx := dwVal AND dwMask; // 零移位直通（掩码截取）/ Zero shift pass-through, masked
ELSE
    IF eDir = E_DL_RotDir.eLeft THEN  // 左循环：高段出环回低位
        dwHi := SHL(dwVal AND dwMask, DINT_TO_UINT(nEff));        // 左移高位段（标准显式转换 R10）/ Left-shifted high segment, standard explicit cast
        dwLo := SHR(dwVal AND dwMask, DINT_TO_UINT(nW - nEff));   // 出环段回卷到低位 / Wrapped-out segment to low bits
        FC_DL_BitRotateEx := (dwHi OR dwLo) AND dwMask; // 回卷合成 + 掩码截取 / Rotated blend, masked
    ELSE                              // 右循环（含枚举非法值并入右旋，方向枚举仅两员）
        dwLo := SHR(dwVal AND dwMask, DINT_TO_UINT(nEff));        // 右移低位段 / Right-shifted low segment
        dwHi := SHL(dwVal AND dwMask, DINT_TO_UINT(nW - nEff));   // 出环段回卷到高位 / Wrapped-out segment to high bits
        FC_DL_BitRotateEx := (dwHi OR dwLo) AND dwMask; // 回卷合成 + 掩码截取 / Rotated blend, masked
    END_IF
END_IF
bValid := TRUE;                       // 全部防御通过：结果有效 / Result valid
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_ShuttleStrokeTimeEst
  分类   : DL_Process
  功能   : 穿梭车单行程时间估算，按梯形速度曲线求加速巡航减速时间并叠加装卸换向时间
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      输入 rDist_m / rAcc / rVmax / rTLoad 均为物理量，行尾注释带工程单位。
      输出 rCycle_s 为单行程总时间；bValid 仅在全部输入合法且分支计算完成时为 TRUE。
      曲线判据：行程 >= 加速段+减速段距离（Vmax^2/Acc）时走梯形，否则走三角波形。
  ============================================================
*)
FUNCTION FC_DL_ShuttleStrokeTimeEst : BOOL
VAR_INPUT
    bEnable  : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr     : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rDist_m  : REAL; // 单行程距离 [m] / single stroke distance [m]
    rAcc     : REAL; // 加速度 [m/s2] / acceleration [metre per second squared]
    rVmax    : REAL; // 最高速度 [m/s] / maximum speed [metre per second]
    rTLoad   : REAL; // 装卸与换向附加时间 [s] / load unload and reversal time [s]
END_VAR
VAR_OUTPUT
    rCycle_s : REAL; // 单行程总时间 [s] / total single stroke time [s]
    bValid   : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS   : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
END_VAR
VAR
    _bFin     : BOOL := FALSE; // 输入有限性判定汇总 / aggregated finiteness verdict of the inputs
    _rCrit    : REAL := 0.0;   // 梯形曲线临界距离 [m] / critical distance of the trapezoidal profile [m]
    _rAccDist : REAL := 0.0;   // 加速段与减速段距离之和 [m] / sum of acceleration and deceleration distance [m]
    _rT       : REAL := 0.0;   // 纯运动段耗时 [s] / pure motion time [s]
END_VAR

    // 段 1｜出口预置：先置零再置无效，任何提前返回都不会留下上一拍残值
    rCycle_s := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸：自反判 NaN，绝对值上界判 Inf，两条缺一不可
    _bFin := (rDist_m = rDist_m) AND (ABS(rDist_m) <= DL_R_MAX) AND (rAcc = rAcc) AND (ABS(rAcc) <= DL_R_MAX) AND (rVmax = rVmax) AND (ABS(rVmax) <= DL_R_MAX) AND (rTLoad = rTLoad) AND (ABS(rTLoad) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：加速度与最高速必须严格为正，否则后续必除零
    IF (ABS(rAcc) <= DL_EPS) OR (ABS(rVmax) <= DL_EPS) THEN
        RETURN;
    END_IF;
    IF (rDist_m < 0.0) OR (rAcc < 0.0) OR (rVmax < 0.0) OR (rTLoad < 0.0) THEN
        RETURN;
    END_IF;
    // 段 5｜临界距离：Vmax^2/Acc 即加速段加减速段总路程
    _rAccDist := rVmax * rVmax / rAcc;
    _rCrit := _rAccDist;
    // 段 6｜分支求纯运动时间
    IF rDist_m >= _rCrit THEN
        _rT := rDist_m / rVmax + rVmax / rAcc; // 梯形：全程含匀速段
    ELSE
        _rT := 2.0 * SQRT(rDist_m / rAcc); // 三角形：未达最高速即开始减速
    END_IF;
    // 段 7｜叠加装卸换向时间并落定
    rCycle_s := _rT + rTLoad;
    bValid := TRUE;
    FC_DL_ShuttleStrokeTimeEst := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_ShuttleAisleLockChk
  分类   : DL_Process
  功能   : 穿梭车巷道互锁裁决，按请求巷道与两车当前巷道及忙碌状态给出放行或拒绝码
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      拒绝码 iDenyCode 语义：0=允许放行，1=已有单车占用该巷道，2=双车同时冲突，3=请求巷道号非法。
      巷道号非法属业务级判定而非计算失败，因此 bValid 仍为 TRUE，由 iDenyCode=3 表达。
      bGrant 仅在 iDenyCode=0 时为 TRUE，两者同源赋值，不存在对立表述。
  ============================================================
*)
FUNCTION FC_DL_ShuttleAisleLockChk : BOOL
VAR_INPUT
    bEnable    : BOOL; // 使能：TRUE 时裁决 / Enable: TRUE to arbitrate
    bErr       : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    iAisleReq  : INT;  // 请求巷道号 [无量纲序号] / requested aisle number [dimensionless index]
    iAisleOwn1 : INT;  // 一号车当前所在巷道号 [无量纲序号] / aisle currently held by car one [dimensionless index]
    iAisleOwn2 : INT;  // 二号车当前所在巷道号 [无量纲序号] / aisle currently held by car two [dimensionless index]
    bCar1Busy  : BOOL; // 一号车忙碌标志，TRUE 表示其占位有效 / car one busy flag, TRUE means its hold is effective
    bCar2Busy  : BOOL; // 二号车忙碌标志，TRUE 表示其占位有效 / car two busy flag, TRUE means its hold is effective
END_VAR
VAR_OUTPUT
    bGrant     : BOOL; // 放行请求：TRUE 表示允许进入请求巷道 / grant flag, TRUE allows entering the requested aisle
    iDenyCode  : INT;  // 拒绝码：0 允许 / 1 一车占用 / 2 双车冲突 / 3 巷道号非法 / deny code 0 allow 1 single hold 2 double conflict 3 illegal aisle
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_AISLE_MIN : INT := 1;  // 合法巷道号下界 [无量纲序号] / lower bound of a legal aisle number [dimensionless index]
    DL_AISLE_MAX : INT := 64; // 合法巷道号上界 [无量纲序号] / upper bound of a legal aisle number [dimensionless index]
END_VAR
VAR
    _iConf : INT := 0; // 与请求巷道冲突的忙碌车数量 [台] / number of busy cars conflicting with the request [unit]
END_VAR

    // 段 1｜出口预置：放行先置 FALSE，拒绝码先置 0，避免上一拍残值被误用
    bGrant := FALSE;
    iDenyCode := 0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜请求巷道号域闸：越界属业务级非法，给出 3 号码后放行位保持 FALSE
    IF (iAisleReq < DL_AISLE_MIN) OR (iAisleReq > DL_AISLE_MAX) THEN
        iDenyCode := 3;
        bValid := TRUE;
        FC_DL_ShuttleAisleLockChk := bValid;
        RETURN;
    END_IF;
    // 段 4｜冲突计数：仅忙碌且巷道号相等的车计入冲突
    _iConf := 0;
    IF bCar1Busy AND (iAisleOwn1 = iAisleReq) THEN
        _iConf := _iConf + 1;
    END_IF;
    IF bCar2Busy AND (iAisleOwn2 = iAisleReq) THEN
        _iConf := _iConf + 1;
    END_IF;
    // 段 5｜按冲突数裁决
    IF _iConf = 0 THEN
        iDenyCode := 0;
        bGrant := TRUE;
    ELSIF _iConf = 1 THEN
        iDenyCode := 1;
        bGrant := FALSE;
    ELSE
        iDenyCode := 2;
        bGrant := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_ShuttleAisleLockChk := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_LifterCycleTimeEst
  分类   : DL_Process
  功能   : 提升机单循环节拍估算，由层高与层数求往复升降时间并叠加开关门与货叉时间
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      单循环 = 2*(层高*(层数-1)/提升速度) + 2*开关门时间 + 2*货叉时间，即一取一放完整往复。
      层数要求 >= 2，层数 1 时无层间位移，节拍模型不成立，直接判无效。
      rCap 由 3600/rCycle 折算，rCycle 非正时不做除法，仅保留时间输出并判无效。
  ============================================================
*)
FUNCTION FC_DL_LifterCycleTimeEst : BOOL
VAR_INPUT
    bEnable   : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr      : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rLiftH    : REAL; // 层间高度 [m] / height between two adjacent levels [m]
    iLayers   : INT;  // 货架总层数 [层] / total number of levels [level]
    rVlift    : REAL; // 提升额定速度 [m/s] / rated lifting speed [metre per second]
    rTdoor    : REAL; // 单次开关门时间 [s] / door open close time for one operation [s]
    rTfork    : REAL; // 单次货叉伸缩时间 [s] / fork extend retract time for one operation [s]
END_VAR
VAR_OUTPUT
    rCycle_s  : REAL; // 单循环节拍时间 [s] / single cycle time [s]
    rCap      : REAL; // 折算产能 [件/小时] / equivalent capacity [piece per hour]
    bValid    : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_SEC_H   : REAL := 3600.0;  // 每小时秒数 [s/h] / seconds per hour [second per hour]
    DL_TWO     : REAL := 2.0;     // 往复行程倍数 [无量纲] / round trip multiplier [dimensionless]
END_VAR
VAR
    _bFin    : BOOL := FALSE; // 输入有限性判定汇总 / aggregated finiteness verdict of the inputs
    _rTravel : REAL := 0.0;   // 单程升降时间 [s] / one way travel time [s]
    _rLayers : REAL := 0.0;   // 层数折算实数 [无量纲] / level count cast to real [dimensionless]
END_VAR

    // 段 1｜出口预置
    rCycle_s := 0.0;
    rCap := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rLiftH = rLiftH) AND (ABS(rLiftH) <= DL_R_MAX) AND (rVlift = rVlift) AND (ABS(rVlift) <= DL_R_MAX) AND (rTdoor = rTdoor) AND (ABS(rTdoor) <= DL_R_MAX) AND (rTfork = rTfork) AND (ABS(rTfork) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：速度必须严格为正，层数必须 >= 2，时间与层高不得为负
    IF ABS(rVlift) <= DL_EPS THEN
        RETURN;
    END_IF;
    IF iLayers < 2 THEN
        RETURN;
    END_IF;
    IF (rLiftH < 0.0) OR (rVlift < 0.0) OR (rTdoor < 0.0) OR (rTfork < 0.0) THEN
        RETURN;
    END_IF;
    // 段 5｜单程升降时间：层数减一得到层间跨距个数
    _rLayers := INT_TO_REAL(iLayers);
    _rTravel := rLiftH * (_rLayers - 1.0) / rVlift;
    // 段 6｜单循环时间：升降往复加两次开关门加两次货叉
    rCycle_s := DL_TWO * _rTravel + DL_TWO * rTdoor + DL_TWO * rTfork;
    // 段 7｜产能折算：必须再次确认周期严格为正才允许做除法
    IF rCycle_s > DL_EPS THEN
        rCap := DL_SEC_H / rCycle_s;
    ELSE
        rCap := 0.0;
        bValid := FALSE;
        FC_DL_LifterCycleTimeEst := bValid;
        RETURN;
    END_IF;
    bValid := TRUE;
    FC_DL_LifterCycleTimeEst := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_StocktakeVarianceCalc
  分类   : DL_Process
  功能   : 盘点差异计算，由账面数与实盘数求数量差、差异率与差异金额
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      数量差 = 实盘 - 账面，为正表示盘盈，为负表示盘亏。
      账面为 0 时差异率在数学上无定义，本实现置 0 并置 bBookZero 告警；
      此时数量差与差异金额仍然有效，故 bValid 仍为 TRUE，语义由 bBookZero 单独表达。
      数量差内部用 DINT 承载，防止 INT 减法溢出，落定前做双侧饱和。
  ============================================================
*)
FUNCTION FC_DL_StocktakeVarianceCalc : BOOL
VAR_INPUT
    bEnable     : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr        : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    iBookQty    : INT;  // 账面库存数量 [件] / book quantity [piece]
    iActualQty  : INT;  // 实盘库存数量 [件] / actual counted quantity [piece]
    rUnitVal    : REAL; // 物料单价 [元/件] / unit value [currency per piece]
END_VAR
VAR_OUTPUT
    iDiffQty    : INT;  // 数量差异，实盘减账面 [件] / quantity difference actual minus book [piece]
    rDiffPct    : REAL; // 差异率，取绝对值后除账面 [%] / variance rate of the absolute difference over the book [percent]
    rDiffValue  : REAL; // 差异金额 [元] / variance value [currency]
    bBookZero   : BOOL; // 账面为零告警：TRUE 表示差异率无意义 / book zero alarm, TRUE means the rate is meaningless
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_I_MAX   : DINT := 32767;   // INT 类型可表上界 [件] / representable upper bound of INT [piece]
    DL_I_MIN   : DINT := -32768;  // INT 类型可表下界 [件] / representable lower bound of INT [piece]
    DL_PCT     : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
END_VAR
VAR
    _bFin   : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _diDiff : DINT := 0;     // 数量差中间量，DINT 防溢出 [件] / intermediate difference in DINT to avoid overflow [piece]
    _rBook  : REAL := 0.0;   // 账面折算实数 [件] / book quantity cast to real [piece]
    _rAbs   : REAL := 0.0;   // 差异绝对值 [件] / absolute difference [piece]
END_VAR

    // 段 1｜出口预置
    iDiffQty := 0;
    rDiffPct := 0.0;
    rDiffValue := 0.0;
    bBookZero := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸：单价参与金额换算，必须有限
    _bFin := (rUnitVal = rUnitVal) AND (ABS(rUnitVal) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：单价允许为零（赠品），不允许为负
    IF rUnitVal < 0.0 THEN
        RETURN;
    END_IF;
    // 段 5｜数量差：DINT 承载后双侧饱和回 INT
    _diDiff := INT_TO_DINT(iActualQty) - INT_TO_DINT(iBookQty);
    IF _diDiff > DL_I_MAX THEN
        _diDiff := DL_I_MAX;
    ELSIF _diDiff < DL_I_MIN THEN
        _diDiff := DL_I_MIN;
    END_IF;
    iDiffQty := DINT_TO_INT(_diDiff);
    rDiffValue := DINT_TO_REAL(_diDiff) * rUnitVal;
    // 段 6｜差异率：账面为零时置 0 并告警，不做除法
    _rBook := INT_TO_REAL(iBookQty);
    IF ABS(_rBook) <= DL_EPS THEN
        rDiffPct := 0.0;
        bBookZero := TRUE;
        bValid := TRUE;
        FC_DL_StocktakeVarianceCalc := bValid;
        RETURN;
    END_IF;
    _rAbs := ABS(DINT_TO_REAL(_diDiff));
    rDiffPct := _rAbs / _rBook * DL_PCT;
    bValid := TRUE;
    FC_DL_StocktakeVarianceCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_BeamToppleRiskChk
  分类   : DL_Process
  功能   : 横梁倾覆风险校核，按重心偏心放大力矩后折算横梁承载利用率并给出风险位
  复杂度 : C1
  版本   : 1.0.1
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      偏心系数 = 1 + |重心偏移|/横梁深度（v1.0.1 取绝对值：负偏移同样放大倾覆风险，
      修正原带符号实现导致负偏移时利用率被低估、风险漏报的缺陷），偏心为零时系数为 1。
      |重心偏移| > 梁深/2 视为不可信组态，直接置 bValid=FALSE 返回。
      有效载荷 = 载荷 * 偏心系数；利用率超过 85% 即判倾覆风险。
      利用率不做 100% 上限截断，超过 100% 的信息对诊断有价值，由调用侧自行显示。
  ============================================================
*)
FUNCTION FC_DL_BeamToppleRiskChk : BOOL
VAR_INPUT
    bEnable      : BOOL; // 使能：TRUE 时校核 / Enable: TRUE to check
    bErr         : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rLoadKg      : REAL; // 实际载荷质量 [kg] / actual load mass [kg]
    rBeamCapKg   : REAL; // 横梁额定承载质量 [kg] / rated load capacity of the beam [kg]
    rCgOffset_mm : REAL; // 载荷重心相对横梁中心的偏移 [mm] / load centre of gravity offset from the beam centre [mm]
    rBeamDepth_mm : REAL; // 横梁截面深度 [mm] / beam section depth [mm]
END_VAR
VAR_OUTPUT
    rEccFactor : REAL; // 偏心放大系数 [无量纲] / eccentricity amplification factor [dimensionless]
    rEffLoadKg : REAL; // 折算有效载荷质量 [kg] / equivalent effective load mass [kg]
    rUtilPct   : REAL; // 承载利用率 [%] / utilisation of the rated capacity [percent]
    bRisk      : BOOL; // 倾覆风险：TRUE 表示利用率超过门限 / topple risk, TRUE when utilisation exceeds the limit
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX    : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS      : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_RISK_PCT : REAL := 85.0;   // 倾覆风险门限 [%] / topple risk threshold [percent]
    DL_PCT      : REAL := 100.0;  // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
END_VAR

    // 段 1｜出口预置
    rEccFactor := 1.0;
    rEffLoadKg := 0.0;
    rUtilPct := 0.0;
    bRisk := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rLoadKg = rLoadKg) AND (ABS(rLoadKg) <= DL_R_MAX) AND (rBeamCapKg = rBeamCapKg) AND (ABS(rBeamCapKg) <= DL_R_MAX) AND (rCgOffset_mm = rCgOffset_mm) AND (ABS(rCgOffset_mm) <= DL_R_MAX) AND (rBeamDepth_mm = rBeamDepth_mm) AND (ABS(rBeamDepth_mm) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：承载与横梁深度必须为正，载荷不得为负
    IF (ABS(rBeamCapKg) <= DL_EPS) OR (ABS(rBeamDepth_mm) <= DL_EPS) THEN
        RETURN;
    END_IF;
    IF (rBeamCapKg < 0.0) OR (rLoadKg < 0.0) OR (rBeamDepth_mm < 0.0) THEN
        RETURN;
    END_IF;
    // 段 4b｜偏心量域闸：|偏移| 超过梁深一半即视为不可信组态，直接置无效退出（R81 闸席 FAIL(LOGIC) 修法）
    IF ABS(rCgOffset_mm) > (rBeamDepth_mm * 0.5) THEN
        RETURN;
    END_IF;
    // 段 5｜偏心放大系数：取偏移绝对值，负偏移（重心偏向另一侧）同样放大倾覆风险 / use absolute offset
    rEccFactor := 1.0 + ABS(rCgOffset_mm) / rBeamDepth_mm;
    // 段 6｜有效载荷与利用率
    rEffLoadKg := rLoadKg * rEccFactor;
    rUtilPct := rEffLoadKg / rBeamCapKg * DL_PCT;
    // 段 7｜风险位：严格大于门限才置位，等于门限视为可控
    IF rUtilPct > DL_RISK_PCT THEN
        bRisk := TRUE;
    ELSE
        bRisk := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_BeamToppleRiskChk := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_CellOccupyRateCalc
  分类   : DL_Process
  功能   : 货位占用率计算，扣除封存货位后按可用货位求占用百分比与空闲数
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      可用货位 = 总货位 - 封存货位；占用率 = 已用 / 可用 * 100。
      可用货位 <= 0 时占用率无定义，直接判无效，不输出替代值。
      空闲货位 = 可用 - 已用，小于 0 表示超占（数据异常），本实现按 0 截断并保持比例可算。
      中间量用 DINT 承载，避免 INT 减法溢出。
  ============================================================
*)
FUNCTION FC_DL_CellOccupyRateCalc : BOOL
VAR_INPUT
    bEnable       : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr          : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    iCellTotal    : INT;  // 货位总数量 [个] / total number of storage cells [unit]
    iCellUsed     : INT;  // 已占用货位数量 [个] / number of occupied cells [unit]
    iCellBlocked  : INT;  // 封存禁用货位数量 [个] / number of blocked or disabled cells [unit]
END_VAR
VAR_OUTPUT
    rOccupyPct : REAL; // 可用货位占用率 [%] / occupancy rate over the available cells [percent]
    iCellFree  : INT;  // 空闲货位数量，负值按 0 截断 [个] / free cell count, negative clamped to zero [unit]
    iCellAvail : INT;  // 扣除封存后的可用货位数量 [个] / available cell count after removing blocked cells [unit]
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS   : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PCT   : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
END_VAR
VAR
    _diAvail : DINT := 0; // 可用货位中间量，DINT 防溢出 [个] / intermediate available count in DINT [unit]
    _diFree  : DINT := 0; // 空闲货位中间量，DINT 防溢出 [个] / intermediate free count in DINT [unit]
    _rAvail  : REAL := 0.0; // 可用货位折算实数 [个] / available count cast to real [unit]
END_VAR

    // 段 1｜出口预置
    rOccupyPct := 0.0;
    iCellFree := 0;
    iCellAvail := 0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜域闸：总数必须为正，已用与封存不得为负
    IF iCellTotal <= 0 THEN
        RETURN;
    END_IF;
    IF (iCellUsed < 0) OR (iCellBlocked < 0) THEN
        RETURN;
    END_IF;
    // 段 4｜可用货位：总数减封存
    _diAvail := INT_TO_DINT(iCellTotal) - INT_TO_DINT(iCellBlocked);
    // 段 5｜可用货位非正闸：此时占用率无定义，判无效
    IF _diAvail <= 0 THEN
        bValid := FALSE;
        FC_DL_CellOccupyRateCalc := bValid;
        RETURN;
    END_IF;
    iCellAvail := DINT_TO_INT(_diAvail);
    // 段 6｜空闲货位：超占按 0 截断
    _diFree := _diAvail - INT_TO_DINT(iCellUsed);
    IF _diFree < 0 THEN
        _diFree := 0;
    END_IF;
    iCellFree := DINT_TO_INT(_diFree);
    // 段 7｜占用率
    _rAvail := DINT_TO_REAL(_diAvail);
    IF ABS(_rAvail) <= DL_EPS THEN
        RETURN;
    END_IF;
    rOccupyPct := INT_TO_REAL(iCellUsed) / _rAvail * DL_PCT;
    bValid := TRUE;
    FC_DL_CellOccupyRateCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_ForkExtendSafeChk
  分类   : DL_Process
  功能   : 货叉伸出安全校核，同时校验通道余量是否足够与货位对齐误差是否在容差内
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      安全判据必须两条同时满足：需伸量 <= 通道余量 - 安全余量，且对齐误差绝对值 <= 容差。
      余量 rMargin_mm = 通道余量 - 安全余量 - 需伸量，为负表示越界，正值表示剩余空间。
      任一条不满足即 bSafe=FALSE，同时 bValid 仍为 TRUE，因为判定结论本身是确定的。
  ============================================================
*)
FUNCTION FC_DL_ForkExtendSafeChk : BOOL
VAR_INPUT
    bEnable        : BOOL; // 使能：TRUE 时校核 / Enable: TRUE to check
    bErr           : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rForkExt_mm    : REAL; // 本次需要伸出的货叉长度 [mm] / required fork extension for this cycle [mm]
    rAisleClear_mm : REAL; // 巷道侧向可用余量 [mm] / available lateral clearance in the aisle [mm]
    rAlignErr_mm   : REAL; // 货位对齐误差，带正负号 [mm] / cell alignment error with sign [mm]
    rAlignTol_mm   : REAL; // 允许的对齐误差容差 [mm] / permitted alignment tolerance [mm]
    rSafeMargin_mm : REAL; // 需保留的安全余量 [mm] / safety margin that must be preserved [mm]
END_VAR
VAR_OUTPUT
    bSafe      : BOOL; // 伸出安全：TRUE 表示两条判据同时满足 / extension safe, TRUE when both criteria hold
    rMargin_mm : REAL; // 伸出后剩余余量，负值表示越界 [mm] / remaining margin after extension, negative means overrun [mm]
    bAlignOk   : BOOL; // 对齐合格：TRUE 表示误差在容差内 / alignment acceptable, TRUE when the error is within tolerance
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS   : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_ZERO  : REAL := 0.0;     // 零值常量 [无量纲] / zero constant [dimensionless]
END_VAR
VAR
    _bFin    : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rAllow  : REAL := 0.0;   // 扣掉安全余量后的可伸长度 [mm] / allowable extension after removing the safety margin [mm]
    _rAbsErr : REAL := 0.0;   // 对齐误差绝对值 [mm] / absolute alignment error [mm]
END_VAR

    // 段 1｜出口预置：安全位保守置 FALSE，余量置零
    bSafe := FALSE;
    rMargin_mm := 0.0;
    bAlignOk := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rForkExt_mm = rForkExt_mm) AND (ABS(rForkExt_mm) <= DL_R_MAX) AND (rAisleClear_mm = rAisleClear_mm) AND (ABS(rAisleClear_mm) <= DL_R_MAX) AND (rAlignErr_mm = rAlignErr_mm) AND (ABS(rAlignErr_mm) <= DL_R_MAX) AND (rAlignTol_mm = rAlignTol_mm) AND (ABS(rAlignTol_mm) <= DL_R_MAX) AND (rSafeMargin_mm = rSafeMargin_mm) AND (ABS(rSafeMargin_mm) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：需伸量、通道余量、容差、安全余量均不得为负
    IF (rForkExt_mm < DL_ZERO) OR (rAisleClear_mm < DL_ZERO) OR (rAlignTol_mm < DL_ZERO) OR (rSafeMargin_mm < DL_ZERO) THEN
        RETURN;
    END_IF;
    // 段 5｜可伸长度与剩余余量
    _rAllow := rAisleClear_mm - rSafeMargin_mm;
    rMargin_mm := _rAllow - rForkExt_mm;
    // 段 6｜两条判据
    _rAbsErr := ABS(rAlignErr_mm);
    IF _rAbsErr <= rAlignTol_mm THEN
        bAlignOk := TRUE;
    ELSE
        bAlignOk := FALSE;
    END_IF;
    IF (rForkExt_mm <= _rAllow) AND bAlignOk THEN
        bSafe := TRUE;
    ELSE
        bSafe := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_ForkExtendSafeChk := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_BinLabelCheckSum
  分类   : DL_Process
  功能   : 货位标号校验和计算，按长度与分隔符数量生成模 36 校验位并校验格式合法性
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      简化口径：不作 ASCII 码位转换，仅统计长度、连字符数量与空格数量参与校验和，
      以避免依赖各平台私有 STRING 转数值函数。这是本组件的既定设计口径，非降级实现。
      校验和 = 长度 + 连字符数*3 + 空格数*7；校验位 = 校验和 MOD 36。
      格式合法 = 长度落在 4~32 之间，且至少含 1 位数字，且连字符与空格各不超过 4 个。
      字符扫描用标准 FIND/DELETE 迭代，并设扫描次数上限，杜绝异常串导致的死循环。
  ============================================================
*)
FUNCTION FC_DL_BinLabelCheckSum : BOOL
VAR_INPUT
    bEnable : BOOL;         // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr    : BOOL;         // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    sLabel  : STRING[32];   // 待校验的货位标号文本 [文本] / label text to be verified [text]
END_VAR
VAR_OUTPUT
    iSum       : INT;  // 校验和整数 [无量纲计数] / checksum integer [dimensionless count]
    iChkDigit  : INT;  // 校验位，校验和对 36 取模 [0~35] / check digit, checksum modulo 36 [0 to 35]
    iLabelLen  : INT;  // 标号实际长度 [字符] / actual label length [character]
    bFormatOk  : BOOL; // 格式合法：TRUE 表示长度与字符构成符合约定 / format legal, TRUE when length and characters match the rule
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_LEN_MIN  : INT := 4;  // 标号最小长度 [字符] / minimum label length [character]
    DL_LEN_MAX  : INT := 32; // 标号最大长度 [字符] / maximum label length [character]
    DL_MOD_BASE : INT := 36; // 校验位取模基数 [无量纲] / modulus base of the check digit [dimensionless]
    DL_SCAN_MAX : INT := 64; // 单类字符扫描次数上限，防死循环 [次] / scan iteration limit per character class [time]
    DL_SEP_MAX  : INT := 4;  // 分隔符允许的最多出现次数 [次] / maximum allowed separator occurrences [time]
    DL_W_LEN    : INT := 1;  // 长度项权重 [无量纲] / weight of the length term [dimensionless]
    DL_W_DASH   : INT := 3;  // 连字符项权重 [无量纲] / weight of the hyphen term [dimensionless]
    DL_W_SPACE  : INT := 7;  // 空格项权重 [无量纲] / weight of the space term [dimensionless]
END_VAR
VAR
    _sTmp      : STRING[32]; // 扫描用工作副本 [文本] / working copy used for scanning [text]
    _iPos      : INT := 0;   // 最近一次查找命中位置，0 表示未命中 [字符位序] / last match position, zero means no match [character index]
    _iDash     : INT := 0;   // 连字符出现次数 [次] / number of hyphen occurrences [time]
    _iSpace    : INT := 0;   // 空格出现次数 [次] / number of space occurrences [time]
    _iGuard    : INT := 0;   // 扫描次数看门狗计数 [次] / watchdog counter of scan iterations [time]
    _bHasDigit : BOOL := FALSE; // 至少含一位数字的判定结果 / verdict of containing at least one digit
END_VAR

    // 段 1｜出口预置
    iSum := 0;
    iChkDigit := 0;
    iLabelLen := 0;
    bFormatOk := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜长度闸
    iLabelLen := LEN(sLabel);
    IF iLabelLen < DL_LEN_MIN THEN
        RETURN;
    END_IF;
    IF iLabelLen > DL_LEN_MAX THEN
        RETURN;
    END_IF;
    // 段 4｜统计连字符数量：逐次定位后删除该字符，直至不再命中
    _sTmp := sLabel;
    _iDash := 0;
    _iGuard := 0;
    _iPos := FIND(_sTmp, '-');
    WHILE _iPos > 0 DO
        _iDash := _iDash + 1;
        _sTmp := DELETE(_sTmp, _iPos, 1);
        _iGuard := _iGuard + 1;
        IF _iGuard > DL_SCAN_MAX THEN
            EXIT;
        END_IF;
        _iPos := FIND(_sTmp, '-');
    END_WHILE;
    // 段 5｜统计空格数量
    _sTmp := sLabel;
    _iSpace := 0;
    _iGuard := 0;
    _iPos := FIND(_sTmp, ' ');
    WHILE _iPos > 0 DO
        _iSpace := _iSpace + 1;
        _sTmp := DELETE(_sTmp, _iPos, 1);
        _iGuard := _iGuard + 1;
        IF _iGuard > DL_SCAN_MAX THEN
            EXIT;
        END_IF;
        _iPos := FIND(_sTmp, ' ');
    END_WHILE;
    // 段 6｜数字存在性：逐字符常量查找，命中任一即为真
    _bHasDigit := (FIND(sLabel, '0') > 0) OR (FIND(sLabel, '1') > 0) OR (FIND(sLabel, '2') > 0) OR (FIND(sLabel, '3') > 0) OR (FIND(sLabel, '4') > 0) OR (FIND(sLabel, '5') > 0) OR (FIND(sLabel, '6') > 0) OR (FIND(sLabel, '7') > 0) OR (FIND(sLabel, '8') > 0) OR (FIND(sLabel, '9') > 0);
    // 段 7｜校验和与校验位
    iSum := iLabelLen * DL_W_LEN + _iDash * DL_W_DASH + _iSpace * DL_W_SPACE;
    IF iSum < 0 THEN
        iSum := 0;
    END_IF;
    iChkDigit := iSum MOD DL_MOD_BASE;
    // 段 8｜格式合法性
    IF _bHasDigit AND (_iDash <= DL_SEP_MAX) AND (_iSpace <= DL_SEP_MAX) THEN
        bFormatOk := TRUE;
    ELSE
        bFormatOk := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_BinLabelCheckSum := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_FoamSuppressDutyCalc
  分类   : DL_Process
  功能   : 抑泡剂投加占空比计算，按液位抬高、灌装速率与基准投加量合成占空比并限幅
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      占空比 = 基准投加量 * (1 + 液位/100) * 灌装速率 / 100，结果限幅到 0~100。
      液位越高泡沫越易生成，故以液位对基准投加量做上浮修正；限幅保证输出可直接驱动 PWM。
  ============================================================
*)
FUNCTION FC_DL_FoamSuppressDutyCalc : BOOL
VAR_INPUT
    bEnable    : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr       : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rLevelPct  : REAL; // 当前液位百分比 [%] / current liquid level [percent]
    rFillRate  : REAL; // 灌装体积速率 [L/min] / filling volumetric rate [litre per minute]
    rDoseBase  : REAL; // 基准投加量 [mL/L] / base dosing quantity [millilitre per litre]
END_VAR
VAR_OUTPUT
    rDutyPct     : REAL; // 抑泡投加占空比，限幅 0~100 [%] / foam suppression duty cycle clamped to 0 to 100 [percent]
    rDoseRawPct  : REAL; // 限幅前的原始占空比 [%] / raw duty cycle before clamping [percent]
    bClamped     : BOOL; // 限幅生效：TRUE 表示输出被截断 / clamping active, TRUE means the output was truncated
    bValid       : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX  : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS    : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PCT    : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_DUTY_HI : REAL := 100.0;  // 占空比上限 [%] / duty cycle upper limit [percent]
    DL_DUTY_LO : REAL := 0.0;    // 占空比下限 [%] / duty cycle lower limit [percent]
    DL_LEVEL_HI : REAL := 100.0; // 液位允许上限 [%] / permitted upper bound of the level [percent]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rLvl : REAL := 0.0;   // 液位修正系数 [无量纲] / level correction factor [dimensionless]
END_VAR

    // 段 1｜出口预置
    rDutyPct := 0.0;
    rDoseRawPct := 0.0;
    bClamped := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rLevelPct = rLevelPct) AND (ABS(rLevelPct) <= DL_R_MAX) AND (rFillRate = rFillRate) AND (ABS(rFillRate) <= DL_R_MAX) AND (rDoseBase = rDoseBase) AND (ABS(rDoseBase) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：液位 0~100，速率与投加量不得为负
    IF (rLevelPct < DL_DUTY_LO) OR (rLevelPct > DL_LEVEL_HI) THEN
        RETURN;
    END_IF;
    IF (rFillRate < DL_DUTY_LO) OR (rDoseBase < DL_DUTY_LO) THEN
        RETURN;
    END_IF;
    // 段 5｜主体合成：液位越高修正系数越大
    _rLvl := 1.0 + rLevelPct / DL_PCT;
    rDoseRawPct := rDoseBase * _rLvl * rFillRate / DL_PCT;
    // 段 6｜限幅并记录截断标志
    IF rDoseRawPct > DL_DUTY_HI THEN
        rDutyPct := DL_DUTY_HI;
        bClamped := TRUE;
    ELSIF rDoseRawPct < DL_DUTY_LO THEN
        rDutyPct := DL_DUTY_LO;
        bClamped := TRUE;
    ELSE
        rDutyPct := rDoseRawPct;
        bClamped := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_FoamSuppressDutyCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_RinseWaterVolumeCalc
  分类   : DL_Process
  功能   : 冲洗水量计算，由管径管长求管容并按冲洗次数与残留系数折算总耗水量
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      管容 = pi * (内径/2000)^2 * 管长 * 1000，内径由 mm 先折 m 再折 L，单位链不可省略。
      总水量 = 管容 * 冲洗次数 * (1 + 残留系数)；残留系数限定 0~1。
  ============================================================
*)
FUNCTION FC_DL_RinseWaterVolumeCalc : BOOL
VAR_INPUT
    bEnable       : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr          : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rPipeLen_m    : REAL; // 管道长度 [m] / pipe length [metre]
    rPipeDia_mm   : REAL; // 管道内径 [mm] / pipe inner diameter [millimetre]
    iRinseCount   : INT;  // 冲洗次数 [次] / number of rinse cycles [time]
    rResidFactor  : REAL; // 残留附加系数 [无量纲] / residual surcharge factor [dimensionless]
END_VAR
VAR_OUTPUT
    rPipeVol_L  : REAL; // 单管容积 [L] / single pipe volume [litre]
    rTotalVol_L : REAL; // 全次数冲洗总水量 [L] / total rinse water volume over all cycles [litre]
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_PI      : REAL := 3.14159265; // 圆周率 [无量纲] / circular constant [dimensionless]
    DL_R_MAX   : REAL := 3.0E38;     // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12;    // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_MM_TO_M : REAL := 2000.0;     // 直径毫米折半径米的除数 [无量纲] / divisor converting diameter in mm into radius in m [dimensionless]
    DL_M3_TO_L : REAL := 1000.0;     // 立方米折升系数 [L/m3] / cubic metre to litre factor [litre per cubic metre]
    DL_ONE     : REAL := 1.0;        // 单位常量 [无量纲] / unity constant [dimensionless]
    DL_MAX_RINSE : INT := 100;       // 冲洗次数上限 [次] / upper bound of the rinse count [time]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rRad  : REAL := 0.0;   // 管道内半径 [m] / pipe inner radius [metre]
    _rArea : REAL := 0.0;   // 管道过流截面积 [m2] / pipe flow cross section area [square metre]
    _rCnt  : REAL := 0.0;   // 冲洗次数折算实数 [次] / rinse count cast to real [time]
END_VAR

    // 段 1｜出口预置
    rPipeVol_L := 0.0;
    rTotalVol_L := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rPipeLen_m = rPipeLen_m) AND (ABS(rPipeLen_m) <= DL_R_MAX) AND (rPipeDia_mm = rPipeDia_mm) AND (ABS(rPipeDia_mm) <= DL_R_MAX) AND (rResidFactor = rResidFactor) AND (ABS(rResidFactor) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：管长非负、管径严格为正、冲洗次数 1~100、残留系数 0~1
    IF (rPipeLen_m < 0.0) OR (ABS(rPipeDia_mm) <= DL_EPS) OR (rPipeDia_mm < 0.0) THEN
        RETURN;
    END_IF;
    IF (iRinseCount < 1) OR (iRinseCount > DL_MAX_RINSE) THEN
        RETURN;
    END_IF;
    IF (rResidFactor < 0.0) OR (rResidFactor > DL_ONE) THEN
        RETURN;
    END_IF;
    // 段 5｜截面积与单管容积
    _rRad := rPipeDia_mm / DL_MM_TO_M;
    _rArea := DL_PI * _rRad * _rRad;
    rPipeVol_L := _rArea * rPipeLen_m * DL_M3_TO_L;
    // 段 6｜总水量
    _rCnt := INT_TO_REAL(iRinseCount);
    rTotalVol_L := rPipeVol_L * _rCnt * (DL_ONE + rResidFactor);
    bValid := TRUE;
    FC_DL_RinseWaterVolumeCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_SanitizeHoldTimeCalc
  分类   : DL_Process
  功能   : 消毒保持时间计算，按实际浓度折算浓度比并对温度系数修正后给出保持时间
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      温度系数 = 1 + (温度-20)*0.02，限幅 0.5~2.0，防止极端温度把时间推到无意义区间。
      保持时间 = 基准时间 * (基准浓度/实际浓度) * (1/温度系数)。
      浓度低于基准时比值大于 1，时间自动延长；浓度高于基准时时间缩短，符合消毒动力学方向。
  ============================================================
*)
FUNCTION FC_DL_SanitizeHoldTimeCalc : BOOL
VAR_INPUT
    bEnable      : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr         : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rConcPct     : REAL; // 实际消毒液浓度 [%] / actual sanitizer concentration [percent]
    rConcRefPct  : REAL; // 基准消毒液浓度 [%] / reference sanitizer concentration [percent]
    rHoldRef_min : REAL; // 基准浓度下的基准保持时间 [min] / reference hold time at the reference concentration [minute]
    rTempC       : REAL; // 实际消毒液温度 [摄氏度] / actual sanitizer temperature [degree Celsius]
END_VAR
VAR_OUTPUT
    rTempFactor : REAL; // 温度修正系数，限幅 0.5~2.0 [无量纲] / temperature correction factor clamped to 0.5 to 2.0 [dimensionless]
    rConcRatio  : REAL; // 浓度比，基准浓度除以实际浓度 [无量纲] / concentration ratio of reference over actual [dimensionless]
    rHold_min   : REAL; // 修正后的保持时间 [min] / corrected hold time [minute]
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX    : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS      : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_ONE      : REAL := 1.0;    // 单位常量 [无量纲] / unity constant [dimensionless]
    DL_TEMP_REF : REAL := 20.0;   // 温度基准点 [摄氏度] / temperature reference point [degree Celsius]
    DL_TEMP_K   : REAL := 0.02;   // 每摄氏度温度系数增量 [1/摄氏度] / temperature coefficient increment per degree Celsius [per degree Celsius]
    DL_FACT_LO  : REAL := 0.5;    // 温度系数下限 [无量纲] / lower limit of the temperature factor [dimensionless]
    DL_FACT_HI  : REAL := 2.0;    // 温度系数上限 [无量纲] / upper limit of the temperature factor [dimensionless]
    DL_TEMP_MIN : REAL := -50.0;  // 允许温度下界 [摄氏度] / permitted lower bound of the temperature [degree Celsius]
    DL_TEMP_MAX : REAL := 150.0;  // 允许温度上界 [摄氏度] / permitted upper bound of the temperature [degree Celsius]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rInv  : REAL := 0.0;   // 温度系数的倒数，除法前先算后判 [无量纲] / reciprocal of the temperature factor computed before the guard [dimensionless]
END_VAR

    // 段 1｜出口预置：系数先置于 1，避免下游误用零
    rTempFactor := DL_ONE;
    rConcRatio := 0.0;
    rHold_min := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rConcPct = rConcPct) AND (ABS(rConcPct) <= DL_R_MAX) AND (rConcRefPct = rConcRefPct) AND (ABS(rConcRefPct) <= DL_R_MAX) AND (rHoldRef_min = rHoldRef_min) AND (ABS(rHoldRef_min) <= DL_R_MAX) AND (rTempC = rTempC) AND (ABS(rTempC) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：实际浓度严格为正、基准浓度非负、基准时间非负、温度在工程区间
    IF ABS(rConcPct) <= DL_EPS THEN
        RETURN;
    END_IF;
    IF (rConcPct < 0.0) OR (rConcRefPct < 0.0) OR (rHoldRef_min < 0.0) THEN
        RETURN;
    END_IF;
    IF (rTempC < DL_TEMP_MIN) OR (rTempC > DL_TEMP_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜温度系数与限幅
    rTempFactor := DL_ONE + (rTempC - DL_TEMP_REF) * DL_TEMP_K;
    IF rTempFactor > DL_FACT_HI THEN
        rTempFactor := DL_FACT_HI;
    ELSIF rTempFactor < DL_FACT_LO THEN
        rTempFactor := DL_FACT_LO;
    END_IF;
    // 段 6｜浓度比
    rConcRatio := rConcRefPct / rConcPct;
    // 段 7｜温度系数分母闸：先判零再取倒数，顺序不可颠倒
    IF ABS(rTempFactor) <= DL_EPS THEN
        RETURN;
    END_IF;
    _rInv := DL_ONE / rTempFactor;
    rHold_min := rHoldRef_min * rConcRatio * _rInv;
    bValid := TRUE;
    FC_DL_SanitizeHoldTimeCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_ConductivityDilutionCalc
  分类   : DL_Process
  功能   : 电导率稀释比计算，由母液与水的本底电导求目标浓度所需的稀释倍数与配水占比
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      稀释比 = (母液电导 - 水本底电导) / (目标电导 - 水本底电导)。
      目标电导不高于水本底时分母非正，物理上无法靠兑水达到，直接判无效。
      配水占比 = (1 - 1/稀释比) * 100，稀释比非正时同样判无效。
  ============================================================
*)
FUNCTION FC_DL_ConductivityDilutionCalc : BOOL
VAR_INPUT
    bEnable      : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr         : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rCondFeed    : REAL; // 母液电导率 [uS/cm] / feed solution conductivity [micro siemens per centimetre]
    rCondTarget  : REAL; // 目标电导率 [uS/cm] / target conductivity [micro siemens per centimetre]
    rCondWater   : REAL; // 稀释水本底电导率 [uS/cm] / background conductivity of the dilution water [micro siemens per centimetre]
END_VAR
VAR_OUTPUT
    rDilutionRatio : REAL; // 稀释倍数，母液体积的多少倍 [无量纲] / dilution ratio in multiples of the feed volume [dimensionless]
    rWaterPct      : REAL; // 配水中水所占体积百分比 [%] / volumetric percentage of water in the mixture [percent]
    bValid         : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS   : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_ONE   : REAL := 1.0;     // 单位常量 [无量纲] / unity constant [dimensionless]
    DL_PCT   : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_RATIO_MAX : REAL := 10000.0; // 稀释比合理上限，超限视为配比不可实现 [无量纲] / sanity upper bound of the dilution ratio [dimensionless]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rNum  : REAL := 0.0;   // 稀释比分子 [uS/cm] / numerator of the dilution ratio [micro siemens per centimetre]
    _rDen  : REAL := 0.0;   // 稀释比分母 [uS/cm] / denominator of the dilution ratio [micro siemens per centimetre]
END_VAR

    // 段 1｜出口预置
    rDilutionRatio := 0.0;
    rWaterPct := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rCondFeed = rCondFeed) AND (ABS(rCondFeed) <= DL_R_MAX) AND (rCondTarget = rCondTarget) AND (ABS(rCondTarget) <= DL_R_MAX) AND (rCondWater = rCondWater) AND (ABS(rCondWater) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：三者均不得为负，母液必须高于水本底
    IF (rCondFeed < 0.0) OR (rCondTarget < 0.0) OR (rCondWater < 0.0) THEN
        RETURN;
    END_IF;
    // 段 5｜分子分母组装
    _rNum := rCondFeed - rCondWater;
    _rDen := rCondTarget - rCondWater;
    // 段 6｜分母非正闸：兑水无法把电导降到水本底以下
    IF _rDen <= DL_EPS THEN
        RETURN;
    END_IF;
    // 段 7｜分子非正闸：母液不高于水本底时无稀释意义
    IF _rNum <= DL_EPS THEN
        RETURN;
    END_IF;
    rDilutionRatio := _rNum / _rDen;
    // 段 8｜稀释比合理区间闸，防止配比不可实现
    IF (rDilutionRatio < DL_ONE) OR (rDilutionRatio > DL_RATIO_MAX) THEN
        RETURN;
    END_IF;
    // 段 9｜配水占比
    rWaterPct := (DL_ONE - DL_ONE / rDilutionRatio) * DL_PCT;
    IF rWaterPct < 0.0 THEN
        rWaterPct := 0.0;
    END_IF;
    IF rWaterPct > DL_PCT THEN
        rWaterPct := DL_PCT;
    END_IF;
    bValid := TRUE;
    FC_DL_ConductivityDilutionCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_NozzleClogIndexCalc
  分类   : DL_Process
  功能   : 喷嘴堵塞指数计算，由额定与实测流量求流量偏差率并折算堵塞百分比与报警位
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      偏差率 = (额定流量 - 实测流量) / 额定流量 * 100，限幅 0~100。
      实测高于额定时偏差为负，属超流而非堵塞，按 0 截断，堵塞指数不会为负。
      堵塞报警门限 15%，严格大于才置位。喷嘴数量仅用于产线级统计，不参与单嘴指数。
  ============================================================
*)
FUNCTION FC_DL_NozzleClogIndexCalc : BOOL
VAR_INPUT
    bEnable     : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr        : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rFlowNom    : REAL; // 额定流量 [L/min] / rated flow [litre per minute]
    rFlowAct    : REAL; // 实测流量 [L/min] / measured flow [litre per minute]
    iNozzleCnt  : INT;  // 参与统计的喷嘴数量 [个] / number of nozzles in the survey [unit]
END_VAR
VAR_OUTPUT
    rDevPct    : REAL; // 限幅前的流量偏差率 [%] / raw flow deviation rate before clamping [percent]
    rClogPct   : REAL; // 堵塞指数，限幅 0~100 [%] / clogging index clamped to 0 to 100 [percent]
    bClogAlarm : BOOL; // 堵塞报警：TRUE 表示指数超过 15% / clog alarm, TRUE when the index exceeds 15 percent
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PCT     : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_ZERO    : REAL := 0.0;     // 零值常量 [无量纲] / zero constant [dimensionless]
    DL_ALARM_PCT : REAL := 15.0;  // 堵塞报警门限 [%] / clog alarm threshold [percent]
    DL_MAX_NOZ : INT := 512;      // 喷嘴数量合理上限 [个] / sanity upper bound of the nozzle count [unit]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
END_VAR

    // 段 1｜出口预置
    rDevPct := 0.0;
    rClogPct := 0.0;
    bClogAlarm := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rFlowNom = rFlowNom) AND (ABS(rFlowNom) <= DL_R_MAX) AND (rFlowAct = rFlowAct) AND (ABS(rFlowAct) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：额定流量严格为正，实测流量非负，喷嘴数量 1~512
    IF ABS(rFlowNom) <= DL_EPS THEN
        RETURN;
    END_IF;
    IF (rFlowNom < DL_ZERO) OR (rFlowAct < DL_ZERO) THEN
        RETURN;
    END_IF;
    IF (iNozzleCnt < 1) OR (iNozzleCnt > DL_MAX_NOZ) THEN
        RETURN;
    END_IF;
    // 段 5｜偏差率
    rDevPct := (rFlowNom - rFlowAct) / rFlowNom * DL_PCT;
    // 段 6｜限幅到 0~100
    IF rDevPct < DL_ZERO THEN
        rClogPct := DL_ZERO;
    ELSIF rDevPct > DL_PCT THEN
        rClogPct := DL_PCT;
    ELSE
        rClogPct := rDevPct;
    END_IF;
    // 段 7｜报警位
    IF rClogPct > DL_ALARM_PCT THEN
        bClogAlarm := TRUE;
    ELSE
        bClogAlarm := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_NozzleClogIndexCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_SipResidueVolumeEst
  分类   : DL_Process
  功能   : SIP 灭菌残留量估算，按主管坡度排空残量与盲管滞留量折算残留升数与占比
  复杂度 : C2
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      主管理论容 = pi * (内径/2000)^2 * 管长 * 1000 [L]。
      坡度排空残留 = 主管理论容 * SIN(坡度) * 0.5，系数 0.5 表示理想排空后仍滞留一半的坡度积液。
      盲管容 = pi * (内径/2000)^2 * 盲管总长 * 1000，按 15% 滞留计。
      残留占比 = 总残留 / 主管理论容 * 100，主管理论容非正时判无效。
  ============================================================
*)
FUNCTION FC_DL_SipResidueVolumeEst : BOOL
VAR_INPUT
    bEnable     : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr        : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rPipeLen_m  : REAL; // 主管长度 [m] / main pipe length [metre]
    rPipeDia_mm : REAL; // 管道内径 [mm] / pipe inner diameter [millimetre]
    rSlopeDeg   : REAL; // 主管安装坡度 [度] / installation slope of the main pipe [degree]
    rBlindLen_m : REAL; // 盲管总长度 [m] / total length of blind branches [metre]
END_VAR
VAR_OUTPUT
    rMainVol_L  : REAL; // 主管理论容积 [L] / theoretical main pipe volume [litre]
    rBlindVol_L : REAL; // 盲管理论容积 [L] / theoretical blind branch volume [litre]
    rResidueL   : REAL; // 估算残留总量 [L] / estimated total residue volume [litre]
    rResiduePct : REAL; // 残留占主管容积百分比 [%] / residue percentage over the main pipe volume [percent]
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_PI        : REAL := 3.14159265; // 圆周率 [无量纲] / circular constant [dimensionless]
    DL_R_MAX     : REAL := 3.0E38;     // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS       : REAL := 1.0E-12;    // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_MM_TO_M   : REAL := 2000.0;     // 直径毫米折半径米的除数 [无量纲] / divisor converting diameter in mm into radius in m [dimensionless]
    DL_M3_TO_L   : REAL := 1000.0;     // 立方米折升系数 [L/m3] / cubic metre to litre factor [litre per cubic metre]
    DL_DEG_TO_RAD : REAL := 0.0174533; // 度转弧度系数 [rad/度] / degree to radian factor [radian per degree]
    DL_SLOPE_K   : REAL := 0.5;        // 坡度排空滞留系数 [无量纲] / slope drainage retention factor [dimensionless]
    DL_BLIND_K   : REAL := 0.15;       // 盲管滞留系数 [无量纲] / blind branch retention factor [dimensionless]
    DL_PCT       : REAL := 100.0;      // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_SLOPE_MAX : REAL := 90.0;       // 坡度允许上限 [度] / permitted upper bound of the slope [degree]
END_VAR
VAR
    _bFin   : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rRad   : REAL := 0.0;   // 管道内半径 [m] / pipe inner radius [metre]
    _rArea  : REAL := 0.0;   // 管道过流截面积 [m2] / pipe flow cross section area [square metre]
    _rResM  : REAL := 0.0;   // 主管坡度排空残留 [L] / slope drainage residue of the main pipe [litre]
    _rResB  : REAL := 0.0;   // 盲管滞留残留 [L] / retained residue in blind branches [litre]
    _rSin   : REAL := 0.0;   // 坡度的正弦值 [无量纲] / sine of the slope angle [dimensionless]
END_VAR

    // 段 1｜出口预置
    rMainVol_L := 0.0;
    rBlindVol_L := 0.0;
    rResidueL := 0.0;
    rResiduePct := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rPipeLen_m = rPipeLen_m) AND (ABS(rPipeLen_m) <= DL_R_MAX) AND (rPipeDia_mm = rPipeDia_mm) AND (ABS(rPipeDia_mm) <= DL_R_MAX) AND (rSlopeDeg = rSlopeDeg) AND (ABS(rSlopeDeg) <= DL_R_MAX) AND (rBlindLen_m = rBlindLen_m) AND (ABS(rBlindLen_m) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸
    IF (rPipeLen_m < 0.0) OR (rBlindLen_m < 0.0) OR (ABS(rPipeDia_mm) <= DL_EPS) OR (rPipeDia_mm < 0.0) THEN
        RETURN;
    END_IF;
    IF (rSlopeDeg < 0.0) OR (rSlopeDeg > DL_SLOPE_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜截面积
    _rRad := rPipeDia_mm / DL_MM_TO_M;
    _rArea := DL_PI * _rRad * _rRad;
    // 段 6｜主管理与盲管容积
    rMainVol_L := _rArea * rPipeLen_m * DL_M3_TO_L;
    rBlindVol_L := _rArea * rBlindLen_m * DL_M3_TO_L;
    // 段 7｜主管理论容非正闸，同时保护后续占比除法
    IF ABS(rMainVol_L) <= DL_EPS THEN
        RETURN;
    END_IF;
    // 段 8｜残留量
    _rSin := SIN(rSlopeDeg * DL_DEG_TO_RAD);
    _rResM := rMainVol_L * _rSin * DL_SLOPE_K;
    _rResB := rBlindVol_L * DL_BLIND_K;
    rResidueL := _rResM + _rResB;
    // 段 9｜残留占比
    rResiduePct := rResidueL / rMainVol_L * DL_PCT;
    bValid := TRUE;
    FC_DL_SipResidueVolumeEst := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_FillValveSealWearEst
  分类   : DL_Process
  功能   : 灌装阀密封磨损估算，按循环数乘温度加速因子求等效循环并折算磨损百分比
  复杂度 : C2
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      温度加速因子 = 1 + MAX(0, 实测温度 - 基准温度) * 0.03，低于基准温度时不加速。
      等效循环 = DWORD_TO_REAL(循环数) * 温度加速因子，磨损 = 等效/额定 * 100，限幅 0~100。
      DWORD 规模较大，转 REAL 时尾数精度约 24 位，对磨损百分比的分辨率影响可忽略，本组件按此口径实现。
  ============================================================
*)
FUNCTION FC_DL_FillValveSealWearEst : BOOL
VAR_INPUT
    bEnable      : BOOL;  // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr         : BOOL;  // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    dwCycleCnt   : DWORD; // 阀累计动作循环数 [次] / accumulated valve actuation cycles [time]
    rTempC       : REAL;  // 实际工作温度 [摄氏度] / actual working temperature [degree Celsius]
    rTempRefC    : REAL;  // 额定基准温度 [摄氏度] / rated reference temperature [degree Celsius]
    dwRatedCycle : DWORD; // 密封件额定寿命循环数 [次] / rated life cycles of the seal [time]
END_VAR
VAR_OUTPUT
    rTempFactor : REAL; // 温度加速因子 [无量纲] / temperature acceleration factor [dimensionless]
    rEquivCyc   : REAL; // 温度折算后的等效循环数 [次] / equivalent cycle count after temperature weighting [time]
    rWearPct    : REAL; // 密封磨损百分比，限幅 0~100 [%] / seal wear percentage clamped to 0 to 100 [percent]
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX    : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS      : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_ONE      : REAL := 1.0;     // 单位常量 [无量纲] / unity constant [dimensionless]
    DL_ZERO     : REAL := 0.0;     // 零值常量 [无量纲] / zero constant [dimensionless]
    DL_PCT      : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_TEMP_K   : REAL := 0.03;    // 每摄氏度加速增量 [1/摄氏度] / acceleration increment per degree Celsius [per degree Celsius]
    DL_TEMP_MIN : REAL := -50.0;   // 允许温度下界 [摄氏度] / permitted lower bound of the temperature [degree Celsius]
    DL_TEMP_MAX : REAL := 200.0;   // 允许温度上界 [摄氏度] / permitted upper bound of the temperature [degree Celsius]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rOver : REAL := 0.0;   // 高于基准温度的超温量，负值归零 [摄氏度] / excess over the reference temperature, negative clamped to zero [degree Celsius]
    _rRated : REAL := 0.0;  // 额定循环数折算实数 [次] / rated cycle count cast to real [time]
END_VAR

    // 段 1｜出口预置：因子先置于 1，避免下游误用零
    rTempFactor := DL_ONE;
    rEquivCyc := 0.0;
    rWearPct := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸：温度参与换算，必须有限
    _bFin := (rTempC = rTempC) AND (ABS(rTempC) <= DL_R_MAX) AND (rTempRefC = rTempRefC) AND (ABS(rTempRefC) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：温度落在工程区间
    IF (rTempC < DL_TEMP_MIN) OR (rTempC > DL_TEMP_MAX) THEN
        RETURN;
    END_IF;
    IF (rTempRefC < DL_TEMP_MIN) OR (rTempRefC > DL_TEMP_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜额定寿命非零闸：额定为零时磨损无定义
    _rRated := DWORD_TO_REAL(dwRatedCycle);
    IF _rRated <= DL_EPS THEN
        RETURN;
    END_IF;
    // 段 6｜温度加速因子：仅超温部分计入加速
    _rOver := rTempC - rTempRefC;
    IF _rOver < DL_ZERO THEN
        _rOver := DL_ZERO;
    END_IF;
    rTempFactor := DL_ONE + _rOver * DL_TEMP_K;
    // 段 7｜等效循环
    rEquivCyc := DWORD_TO_REAL(dwCycleCnt) * rTempFactor;
    // 段 8｜磨损百分比与限幅
    rWearPct := rEquivCyc / _rRated * DL_PCT;
    IF rWearPct < DL_ZERO THEN
        rWearPct := DL_ZERO;
    END_IF;
    IF rWearPct > DL_PCT THEN
        rWearPct := DL_PCT;
    END_IF;
    bValid := TRUE;
    FC_DL_FillValveSealWearEst := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_BottleNeckLevelMargin
  分类   : DL_Process
  功能   : 瓶口液位余量计算，由瓶高瓶颈高与含泡沫液位求瓶口剩余空间并给出溢泡风险
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      余量 = 瓶高 - 瓶颈段高 - (液位 + 泡沫高)。
      瓶颈段高表示瓶口以下不可被液体占据的结构高度，必须先扣除。
      余量小于 5 mm 判溢泡风险；余量为负表示液体已侵入瓶颈段，风险必然成立。
  ============================================================
*)
FUNCTION FC_DL_BottleNeckLevelMargin : BOOL
VAR_INPUT
    bEnable     : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr        : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rBottleH_mm : REAL; // 瓶身总高 [mm] / total bottle height [millimetre]
    rLevel_mm   : REAL; // 当前液位高度，自瓶底起算 [mm] / current liquid level from the bottle bottom [millimetre]
    rNeckH_mm   : REAL; // 瓶颈段结构高度 [mm] / structural height of the neck section [millimetre]
    rFoamH_mm   : REAL; // 液面泡沫层高度 [mm] / foam layer height above the liquid surface [millimetre]
END_VAR
VAR_OUTPUT
    rFillTop_mm : REAL; // 含泡沫的液面顶部高度 [mm] / top height of the liquid including foam [millimetre]
    rMargin_mm  : REAL; // 瓶口剩余余量，负值表示侵入瓶颈 [mm] / remaining margin to the bottle mouth, negative means neck intrusion [millimetre]
    bOverflowRisk : BOOL; // 溢泡风险：TRUE 表示余量小于 5 mm / overflow risk, TRUE when the margin is below 5 millimetre
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_ZERO    : REAL := 0.0;     // 零值常量 [无量纲] / zero constant [dimensionless]
    DL_RISK_MM : REAL := 5.0;     // 溢泡风险余量门限 [mm] / overflow risk margin threshold [millimetre]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rAvail : REAL := 0.0;  // 扣除瓶颈后的可用灌注高度 [mm] / usable filling height after removing the neck [millimetre]
END_VAR

    // 段 1｜出口预置
    rFillTop_mm := 0.0;
    rMargin_mm := 0.0;
    bOverflowRisk := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rBottleH_mm = rBottleH_mm) AND (ABS(rBottleH_mm) <= DL_R_MAX) AND (rLevel_mm = rLevel_mm) AND (ABS(rLevel_mm) <= DL_R_MAX) AND (rNeckH_mm = rNeckH_mm) AND (ABS(rNeckH_mm) <= DL_R_MAX) AND (rFoamH_mm = rFoamH_mm) AND (ABS(rFoamH_mm) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：瓶高严格为正，其余高度不得为负
    IF rBottleH_mm <= DL_ZERO THEN
        RETURN;
    END_IF;
    IF (rLevel_mm < DL_ZERO) OR (rNeckH_mm < DL_ZERO) OR (rFoamH_mm < DL_ZERO) THEN
        RETURN;
    END_IF;
    // 段 5｜瓶颈段不得吞掉整个瓶高
    IF rNeckH_mm >= rBottleH_mm THEN
        RETURN;
    END_IF;
    // 段 6｜含泡沫的液面顶部与余量
    rFillTop_mm := rLevel_mm + rFoamH_mm;
    _rAvail := rBottleH_mm - rNeckH_mm;
    rMargin_mm := _rAvail - rFillTop_mm;
    // 段 7｜风险位
    IF rMargin_mm < DL_RISK_MM THEN
        bOverflowRisk := TRUE;
    ELSE
        bOverflowRisk := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_BottleNeckLevelMargin := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_ReceiverPressureDropCalc
  分类   : DL_Process
  功能   : 储气罐压降法流量估算，由起止压力与罐容时长求标准状态流量与压降速率
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      标准状态流量 = (起始压力 - 终止压力) * 罐容 / 时长 * 60，单位 Nm3/min，
      该式为忽略温度补偿的工程近似，仅在罐内温度稳定且压降不超过初始压力的前提下可用。
      压降速率 = (起始压力 - 终止压力) / 时长 * 3600，单位 bar/h。
      终止压力高于起始压力表示罐在充气而非放气，本组件判为不适用并置无效。
  ============================================================
*)
FUNCTION FC_DL_ReceiverPressureDropCalc : BOOL
VAR_INPUT
    bEnable   : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr      : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rP1_bar   : REAL; // 统计窗口起始压力 [bar] / pressure at the start of the window [bar]
    rP2_bar   : REAL; // 统计窗口终止压力 [bar] / pressure at the end of the window [bar]
    rVol_m3   : REAL; // 储气罐有效容积 [m3] / effective receiver volume [cubic metre]
    rDur_s    : REAL; // 统计窗口时长 [s] / duration of the window [second]
END_VAR
VAR_OUTPUT
    rFlow_nm3min : REAL; // 折算标准状态流量 [Nm3/min] / equivalent standard state flow [normal cubic metre per minute]
    rDropRate_barh : REAL; // 折算压降速率 [bar/h] / equivalent pressure drop rate [bar per hour]
    bValid    : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX  : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS    : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_S_PER_MIN : REAL := 60.0;   // 每分钟秒数 [s/min] / seconds per minute [second per minute]
    DL_S_PER_H   : REAL := 3600.0; // 每小时秒数 [s/h] / seconds per hour [second per hour]
    DL_DROP_MAX_PCT : REAL := 100.0; // 压降不得超过起始压力的百分比上限 [%] / pressure drop must not exceed this percentage of the start pressure [percent]
    DL_PCT    : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rDrop : REAL := 0.0;   // 窗口内压降 [bar] / pressure drop inside the window [bar]
END_VAR

    // 段 1｜出口预置
    rFlow_nm3min := 0.0;
    rDropRate_barh := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rP1_bar = rP1_bar) AND (ABS(rP1_bar) <= DL_R_MAX) AND (rP2_bar = rP2_bar) AND (ABS(rP2_bar) <= DL_R_MAX) AND (rVol_m3 = rVol_m3) AND (ABS(rVol_m3) <= DL_R_MAX) AND (rDur_s = rDur_s) AND (ABS(rDur_s) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：罐容与时长必须严格为正，压力不得为负
    IF (ABS(rVol_m3) <= DL_EPS) OR (ABS(rDur_s) <= DL_EPS) THEN
        RETURN;
    END_IF;
    IF (rVol_m3 < 0.0) OR (rDur_s < 0.0) OR (rP1_bar < 0.0) OR (rP2_bar < 0.0) THEN
        RETURN;
    END_IF;
    // 段 5｜压降必须为正，否则属充气工况，压降法不适用
    _rDrop := rP1_bar - rP2_bar;
    IF _rDrop <= DL_EPS THEN
        RETURN;
    END_IF;
    // 段 6｜压降相对起始压力不得越界，否则近似式失真
    IF rP1_bar > DL_EPS THEN
        IF _rDrop > rP1_bar * DL_DROP_MAX_PCT / DL_PCT THEN
            RETURN;
        END_IF;
    END_IF;
    // 段 7｜流量与压降速率
    rFlow_nm3min := _rDrop * rVol_m3 / rDur_s * DL_S_PER_MIN;
    rDropRate_barh := _rDrop / rDur_s * DL_S_PER_H;
    bValid := TRUE;
    FC_DL_ReceiverPressureDropCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_AirQualityClassifyCalc
  分类   : DL_Process
  功能   : 压缩空气质量等级判定，按 ISO 8573-1 分别评定露点含油与颗粒等级并取最严者
  复杂度 : C2
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      露点分级：<=-40 为 1 级，<=-20 为 2 级，<=+3 为 3 级，其余为 4 级。
      含油分级：<=0.01 为 1 级，<=0.1 为 2 级，<=1 为 3 级，其余为 4 级。
      颗粒等级由调用侧直接给出 1~4，本组件只做合法性校验。
      总等级取三者最大值（数字越大越差）；总等级 <=2 判定为合格。
  ============================================================
*)
FUNCTION FC_DL_AirQualityClassifyCalc : BOOL
VAR_INPUT
    bEnable       : BOOL; // 使能：TRUE 时判定 / Enable: TRUE to classify
    bErr          : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rDewPointC    : REAL; // 压力露点 [摄氏度] / pressure dew point [degree Celsius]
    rOil_mgm3     : REAL; // 含油量 [mg/m3] / oil content [milligram per cubic metre]
    iParticleClass : INT; // 颗粒等级 1~4 [级] / particle class from 1 to 4 [class]
END_VAR
VAR_OUTPUT
    iDewClass     : INT;  // 露点等级 1~4 [级] / dew point class from 1 to 4 [class]
    iOilClass     : INT;  // 含油等级 1~4 [级] / oil class from 1 to 4 [class]
    iQualityClass : INT;  // 综合等级取三者最大值 [级] / overall class taken as the maximum of the three [class]
    bPass         : BOOL; // 合格：TRUE 表示综合等级不差于 2 级 / pass, TRUE when the overall class is 2 or better
    bValid        : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX      : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS        : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_DEW_1      : REAL := -40.0;  // 1 级露点上限 [摄氏度] / upper bound of the class one dew point [degree Celsius]
    DL_DEW_2      : REAL := -20.0;  // 2 级露点上限 [摄氏度] / upper bound of the class two dew point [degree Celsius]
    DL_DEW_3      : REAL := 3.0;    // 3 级露点上限 [摄氏度] / upper bound of the class three dew point [degree Celsius]
    DL_OIL_1      : REAL := 0.01;   // 1 级含油上限 [mg/m3] / upper bound of the class one oil content [milligram per cubic metre]
    DL_OIL_2      : REAL := 0.1;    // 2 级含油上限 [mg/m3] / upper bound of the class two oil content [milligram per cubic metre]
    DL_OIL_3      : REAL := 1.0;    // 3 级含油上限 [mg/m3] / upper bound of the class three oil content [milligram per cubic metre]
    DL_CLS_MIN    : INT := 1;       // 等级下界 [级] / lower bound of a class [class]
    DL_CLS_MAX    : INT := 4;       // 等级上界 [级] / upper bound of a class [class]
    DL_PASS_MAX   : INT := 2;       // 合格允许的最差等级 [级] / worst class still accepted as a pass [class]
    DL_DEW_MIN    : REAL := -100.0; // 露点合理下界 [摄氏度] / sanity lower bound of the dew point [degree Celsius]
    DL_DEW_MAX    : REAL := 100.0;  // 露点合理上界 [摄氏度] / sanity upper bound of the dew point [degree Celsius]
    DL_OIL_MAX    : REAL := 100.0;  // 含油合理上界 [mg/m3] / sanity upper bound of the oil content [milligram per cubic metre]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
END_VAR

    // 段 1｜出口预置：等级先置最差 4 级，任何提前返回都不会误报合格
    iDewClass := DL_CLS_MAX;
    iOilClass := DL_CLS_MAX;
    iQualityClass := DL_CLS_MAX;
    bPass := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rDewPointC = rDewPointC) AND (ABS(rDewPointC) <= DL_R_MAX) AND (rOil_mgm3 = rOil_mgm3) AND (ABS(rOil_mgm3) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：露点与含油落在合理区间，颗粒等级 1~4
    IF (rDewPointC < DL_DEW_MIN) OR (rDewPointC > DL_DEW_MAX) THEN
        RETURN;
    END_IF;
    IF (rOil_mgm3 < 0.0) OR (rOil_mgm3 > DL_OIL_MAX) THEN
        RETURN;
    END_IF;
    IF (iParticleClass < DL_CLS_MIN) OR (iParticleClass > DL_CLS_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜露点分级
    IF rDewPointC <= DL_DEW_1 THEN
        iDewClass := 1;
    ELSIF rDewPointC <= DL_DEW_2 THEN
        iDewClass := 2;
    ELSIF rDewPointC <= DL_DEW_3 THEN
        iDewClass := 3;
    ELSE
        iDewClass := 4;
    END_IF;
    // 段 6｜含油分级
    IF rOil_mgm3 <= DL_OIL_1 THEN
        iOilClass := 1;
    ELSIF rOil_mgm3 <= DL_OIL_2 THEN
        iOilClass := 2;
    ELSIF rOil_mgm3 <= DL_OIL_3 THEN
        iOilClass := 3;
    ELSE
        iOilClass := 4;
    END_IF;
    // 段 7｜综合等级取最严
    iQualityClass := iDewClass;
    IF iOilClass > iQualityClass THEN
        iQualityClass := iOilClass;
    END_IF;
    IF iParticleClass > iQualityClass THEN
        iQualityClass := iParticleClass;
    END_IF;
    // 段 8｜合格判定
    IF iQualityClass <= DL_PASS_MAX THEN
        bPass := TRUE;
    ELSE
        bPass := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_AirQualityClassifyCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_DesiccantLifeEstimate
  分类   : DL_Process
  功能   : 干燥剂寿命估算，按累计吸湿量与温度降额后的有效容量求剩余寿命百分比
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      有效容量 = 额定吸附容量 * 温度降额系数，温度降额系数限定 0~1 区间且必须为正。
      剩余百分比 = (1 - 累计吸湿量/有效容量) * 100，限幅 0~100。
      剩余低于 20% 判更换到期；累计吸湿量超过有效容量时剩余按 0 截断，判定仍成立。
  ============================================================
*)
FUNCTION FC_DL_DesiccantLifeEstimate : BOOL
VAR_INPUT
    bEnable        : BOOL; // 使能：TRUE 时估算 / Enable: TRUE to estimate
    bErr           : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rMoistureLoad  : REAL; // 累计已吸附水汽质量 [g] / accumulated adsorbed moisture mass [gram]
    rCapG          : REAL; // 额定吸附容量 [g] / rated adsorption capacity [gram]
    rTempDerate    : REAL; // 温度降额系数，1 表示不降额 [无量纲] / temperature derating factor, one means no derating [dimensionless]
END_VAR
VAR_OUTPUT
    rEffCapG   : REAL; // 降额后的有效吸附容量 [g] / effective capacity after derating [gram]
    rLoadPct   : REAL; // 已消耗容量百分比 [%] / consumed capacity percentage [percent]
    rRemainPct : REAL; // 剩余寿命百分比，限幅 0~100 [%] / remaining life percentage clamped to 0 to 100 [percent]
    bReplaceDue : BOOL; // 更换到期：TRUE 表示剩余低于 20% / replacement due, TRUE when the remainder is below 20 percent
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_ONE     : REAL := 1.0;     // 单位常量 [无量纲] / unity constant [dimensionless]
    DL_ZERO    : REAL := 0.0;     // 零值常量 [无量纲] / zero constant [dimensionless]
    DL_PCT     : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_DUE_PCT : REAL := 20.0;    // 更换到期门限 [%] / replacement due threshold [percent]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rUse : REAL := 0.0;   // 容量占用比 [无量纲] / capacity usage ratio [dimensionless]
END_VAR

    // 段 1｜出口预置：剩余先置 0（最不利），防止下游误判为充足
    rEffCapG := 0.0;
    rLoadPct := 0.0;
    rRemainPct := 0.0;
    bReplaceDue := TRUE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rMoistureLoad = rMoistureLoad) AND (ABS(rMoistureLoad) <= DL_R_MAX) AND (rCapG = rCapG) AND (ABS(rCapG) <= DL_R_MAX) AND (rTempDerate = rTempDerate) AND (ABS(rTempDerate) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：容量严格为正，降额系数落在 0~1 且严格为正
    IF (ABS(rCapG) <= DL_EPS) OR (rCapG < DL_ZERO) THEN
        RETURN;
    END_IF;
    IF (ABS(rTempDerate) <= DL_EPS) OR (rTempDerate < DL_ZERO) OR (rTempDerate > DL_ONE) THEN
        RETURN;
    END_IF;
    IF rMoistureLoad < DL_ZERO THEN
        RETURN;
    END_IF;
    // 段 5｜有效容量：容量乘降额系数，乘积仍须严格为正才可作分母
    rEffCapG := rCapG * rTempDerate;
    IF rEffCapG <= DL_EPS THEN
        RETURN;
    END_IF;
    // 段 6｜占用比与剩余百分比
    _rUse := rMoistureLoad / rEffCapG;
    rLoadPct := _rUse * DL_PCT;
    rRemainPct := (DL_ONE - _rUse) * DL_PCT;
    // 段 7｜限幅
    IF rRemainPct < DL_ZERO THEN
        rRemainPct := DL_ZERO;
    END_IF;
    IF rRemainPct > DL_PCT THEN
        rRemainPct := DL_PCT;
    END_IF;
    IF rLoadPct < DL_ZERO THEN
        rLoadPct := DL_ZERO;
    END_IF;
    // 段 8｜更换到期判定
    IF rRemainPct < DL_DUE_PCT THEN
        bReplaceDue := TRUE;
    ELSE
        bReplaceDue := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_DesiccantLifeEstimate := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_MotorLoadFactorCalc
  分类   : DL_Process
  功能   : 电机负载率计算，由实测有功功率与功率因数求视在功率并折算负载率与过载位
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      视在功率 = 有功功率 / 功率因数，功率因数不高于 0.1 视为测量不可信，直接判无效。
      负载率 = 有功 / 额定有功 * 100，限幅 0~150；超过 100% 置过载位。
      限幅上限取 150% 而非 100%，是为了在过载时保留可区分的幅值信息。
  ============================================================
*)
FUNCTION FC_DL_MotorLoadFactorCalc : BOOL
VAR_INPUT
    bEnable   : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr      : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rP_kw     : REAL; // 实测有功功率 [kW] / measured active power [kilowatt]
    rPnom_kw  : REAL; // 电机额定有功功率 [kW] / rated active power of the motor [kilowatt]
    rCosPhi   : REAL; // 实测功率因数 [无量纲] / measured power factor [dimensionless]
END_VAR
VAR_OUTPUT
    rApparentKva : REAL; // 视在功率 [kVA] / apparent power [kilovolt ampere]
    rLoadPct     : REAL; // 负载率，限幅 0~150 [%] / load factor clamped to 0 to 150 [percent]
    bOverload    : BOOL; // 过载：TRUE 表示负载率超过 100% / overload, TRUE when the load factor exceeds 100 percent
    bValid       : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX     : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS       : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PF_MIN    : REAL := 0.1;    // 功率因数可信下界 [无量纲] / credible lower bound of the power factor [dimensionless]
    DL_PF_MAX    : REAL := 1.0;    // 功率因数物理上界 [无量纲] / physical upper bound of the power factor [dimensionless]
    DL_PCT       : REAL := 100.0;  // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_LOAD_HI   : REAL := 150.0;  // 负载率限幅上限 [%] / upper clamp of the load factor [percent]
    DL_LOAD_LO   : REAL := 0.0;    // 负载率限幅下限 [%] / lower clamp of the load factor [percent]
    DL_OVL_PCT   : REAL := 100.0;  // 过载门限 [%] / overload threshold [percent]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rRaw  : REAL := 0.0;   // 限幅前负载率 [%] / raw load factor before clamping [percent]
END_VAR

    // 段 1｜出口预置
    rApparentKva := 0.0;
    rLoadPct := 0.0;
    bOverload := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rP_kw = rP_kw) AND (ABS(rP_kw) <= DL_R_MAX) AND (rPnom_kw = rPnom_kw) AND (ABS(rPnom_kw) <= DL_R_MAX) AND (rCosPhi = rCosPhi) AND (ABS(rCosPhi) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：额定功率严格为正，有功功率非负，功率因数在可信区间
    IF (ABS(rPnom_kw) <= DL_EPS) OR (rPnom_kw < 0.0) THEN
        RETURN;
    END_IF;
    IF rP_kw < 0.0 THEN
        RETURN;
    END_IF;
    IF (rCosPhi <= DL_PF_MIN) OR (rCosPhi > DL_PF_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜视在功率
    rApparentKva := rP_kw / rCosPhi;
    // 段 6｜负载率与限幅
    _rRaw := rP_kw / rPnom_kw * DL_PCT;
    IF _rRaw < DL_LOAD_LO THEN
        rLoadPct := DL_LOAD_LO;
    ELSIF _rRaw > DL_LOAD_HI THEN
        rLoadPct := DL_LOAD_HI;
    ELSE
        rLoadPct := _rRaw;
    END_IF;
    // 段 7｜过载位用限幅前的真实值判定，避免限幅把过载信息吃掉
    IF _rRaw > DL_OVL_PCT THEN
        bOverload := TRUE;
    ELSE
        bOverload := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_MotorLoadFactorCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_CompressorDutyCycleCalc
  分类   : DL_Process
  功能   : 压缩机加载占空比与卸载能耗占比计算，用于评估空压站运行经济性
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      加载占空比 = 加载时间 / 统计窗口 * 100。
      卸载能耗占比 = 卸载功率*卸载时间 / (加载功率*加载时间 + 卸载功率*卸载时间) * 100。
      能耗分母为零表示窗口内既无加载也无卸载，占空比无法归一，判无效。
      加载时间加卸载时间超过统计窗口时数据自相矛盾，判无效而不是强行归一。
  ============================================================
*)
FUNCTION FC_DL_CompressorDutyCycleCalc : BOOL
VAR_INPUT
    bEnable      : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr         : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rLoadTime_s  : REAL; // 窗口内加载运行时间 [s] / loaded running time inside the window [second]
    rUnloadTime_s : REAL; // 窗口内卸载运行时间 [s] / unloaded running time inside the window [second]
    rIdleKw      : REAL; // 卸载空转功率 [kW] / unloaded idle power [kilowatt]
    rLoadKw      : REAL; // 加载运行功率 [kW] / loaded running power [kilowatt]
    rDur_s       : REAL; // 统计窗口总时长 [s] / total duration of the statistic window [second]
END_VAR
VAR_OUTPUT
    rDutyPct       : REAL; // 加载占空比，限幅 0~100 [%] / loading duty cycle clamped to 0 to 100 [percent]
    rIdleEnergyPct : REAL; // 卸载能耗占窗口总能耗比例，限幅 0~100 [%] / unloaded energy share of the window total clamped to 0 to 100 [percent]
    rTotalKwh      : REAL; // 窗口内折算总电量 [kWh] / equivalent total energy inside the window [kilowatt hour]
    bValid         : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PCT     : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_ZERO    : REAL := 0.0;     // 零值常量 [无量纲] / zero constant [dimensionless]
    DL_S_PER_H : REAL := 3600.0;  // 每小时秒数 [s/h] / seconds per hour [second per hour]
    DL_TOL_S   : REAL := 0.001;   // 时间窗超限判定容差 [s] / tolerance for the window overrun check [second]
END_VAR
VAR
    _bFin    : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rLoadKwh : REAL := 0.0;  // 加载段电量 [kWh] / energy of the loaded segment [kilowatt hour]
    _rIdleKwh : REAL := 0.0;  // 卸载段电量 [kWh] / energy of the unloaded segment [kilowatt hour]
    _rDen     : REAL := 0.0;  // 能耗占比分母 [kWh] / denominator of the energy share [kilowatt hour]
END_VAR

    // 段 1｜出口预置
    rDutyPct := 0.0;
    rIdleEnergyPct := 0.0;
    rTotalKwh := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rLoadTime_s = rLoadTime_s) AND (ABS(rLoadTime_s) <= DL_R_MAX) AND (rUnloadTime_s = rUnloadTime_s) AND (ABS(rUnloadTime_s) <= DL_R_MAX) AND (rIdleKw = rIdleKw) AND (ABS(rIdleKw) <= DL_R_MAX) AND (rLoadKw = rLoadKw) AND (ABS(rLoadKw) <= DL_R_MAX) AND (rDur_s = rDur_s) AND (ABS(rDur_s) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：统计窗口严格为正，时间与功率不得为负
    IF (ABS(rDur_s) <= DL_EPS) OR (rDur_s < DL_ZERO) THEN
        RETURN;
    END_IF;
    IF (rLoadTime_s < DL_ZERO) OR (rUnloadTime_s < DL_ZERO) OR (rIdleKw < DL_ZERO) OR (rLoadKw < DL_ZERO) THEN
        RETURN;
    END_IF;
    // 段 5｜加载加卸载不得超过窗口，超出部分属数据矛盾
    IF (rLoadTime_s + rUnloadTime_s) > (rDur_s + DL_TOL_S) THEN
        RETURN;
    END_IF;
    // 段 6｜加载占空比与限幅
    rDutyPct := rLoadTime_s / rDur_s * DL_PCT;
    IF rDutyPct < DL_ZERO THEN
        rDutyPct := DL_ZERO;
    END_IF;
    IF rDutyPct > DL_PCT THEN
        rDutyPct := DL_PCT;
    END_IF;
    // 段 7｜两段电量与总电量
    _rLoadKwh := rLoadKw * rLoadTime_s / DL_S_PER_H;
    _rIdleKwh := rIdleKw * rUnloadTime_s / DL_S_PER_H;
    rTotalKwh := _rLoadKwh + _rIdleKwh;
    // 段 8｜能耗占比分母闸
    _rDen := _rLoadKwh + _rIdleKwh;
    IF _rDen <= DL_EPS THEN
        RETURN;
    END_IF;
    rIdleEnergyPct := _rIdleKwh / _rDen * DL_PCT;
    IF rIdleEnergyPct < DL_ZERO THEN
        rIdleEnergyPct := DL_ZERO;
    END_IF;
    IF rIdleEnergyPct > DL_PCT THEN
        rIdleEnergyPct := DL_PCT;
    END_IF;
    bValid := TRUE;
    FC_DL_CompressorDutyCycleCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_DrainIntervalCalc
  分类   : DL_Process
  功能   : 自动排水间隔计算，由冷凝析水率与允许最大积水求排水周期并给出即时排水请求
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      排水间隔 = 允许最大积水 / 析水率 * 60，单位 min。
      间隔小于 10 min 表示积水速度已超出常规排放节奏，置 bDrainNow 请求连续排放。
      单次排水量仅用于校核排放能力是否覆盖间隔内的积水，不参与间隔公式。
  ============================================================
*)
FUNCTION FC_DL_DrainIntervalCalc : BOOL
VAR_INPUT
    bEnable      : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr         : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rCondRate    : REAL; // 冷凝析水率 [L/h] / condensate generation rate [litre per hour]
    rDrainVol_L  : REAL; // 单次排水动作排放量 [L] / volume released by one drain action [litre]
    rMaxHold_L   : REAL; // 允许的最大积水量 [L] / maximum permitted accumulated water [litre]
END_VAR
VAR_OUTPUT
    rInterval_min : REAL; // 建议排水间隔 [min] / recommended drain interval [minute]
    rWaterPerInt_L : REAL; // 单个间隔内积水总量 [L] / accumulated water within one interval [litre]
    bDrainNow   : BOOL; // 即时排水请求：TRUE 表示间隔小于 10 min / immediate drain request, TRUE when the interval is below 10 minutes
    bCapOk      : BOOL; // 排放能力充足：TRUE 表示单次排放量不小于间隔内积水量 / capacity adequate, TRUE when one drain covers the water of one interval
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX    : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS      : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_MIN_PER_H : REAL := 60.0;  // 每小时分钟数 [min/h] / minutes per hour [minute per hour]
    DL_NOW_MIN  : REAL := 10.0;   // 即时排水间隔门限 [min] / threshold of the immediate drain interval [minute]
    DL_TOL_L    : REAL := 1.0E-6; // 排放能力比较容差 [L] / tolerance of the drain capacity comparison [litre]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
END_VAR

    // 段 1｜出口预置
    rInterval_min := 0.0;
    rWaterPerInt_L := 0.0;
    bDrainNow := FALSE;
    bCapOk := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rCondRate = rCondRate) AND (ABS(rCondRate) <= DL_R_MAX) AND (rDrainVol_L = rDrainVol_L) AND (ABS(rDrainVol_L) <= DL_R_MAX) AND (rMaxHold_L = rMaxHold_L) AND (ABS(rMaxHold_L) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：析水率严格为正，积水量与单次排放量不得为负
    IF (ABS(rCondRate) <= DL_EPS) OR (rCondRate < 0.0) THEN
        RETURN;
    END_IF;
    IF (rMaxHold_L < 0.0) OR (rDrainVol_L < 0.0) THEN
        RETURN;
    END_IF;
    // 段 5｜排水间隔
    rInterval_min := rMaxHold_L / rCondRate * DL_MIN_PER_H;
    // 段 6｜间隔内积水量
    rWaterPerInt_L := rCondRate * rInterval_min / DL_MIN_PER_H;
    // 段 7｜排放能力校核：单次排放量须覆盖一个间隔的积水
    IF rDrainVol_L >= (rWaterPerInt_L - DL_TOL_L) THEN
        bCapOk := TRUE;
    ELSE
        bCapOk := FALSE;
    END_IF;
    // 段 8｜即时排水请求
    IF rInterval_min < DL_NOW_MIN THEN
        bDrainNow := TRUE;
    ELSE
        bDrainNow := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_DrainIntervalCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_IdleRunRatioCalc
  分类   : DL_Process
  功能   : 空转率与浪费电量计算，由总运行时间与加载时间求空转占比及折算电耗
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
