  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      空转时间 = 总运行时间 - 加载时间；空转率 = 空转时间 / 总运行时间 * 100。
      浪费电量 = 空转功率 * 空转时间 / 3600，单位 kWh。
      加载时间超过总运行时间属数据矛盾，本组件判无效，不做负数截断掩盖问题。
  ============================================================
*)
FUNCTION FC_DL_IdleRunRatioCalc : BOOL
VAR_INPUT
    bEnable     : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr        : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rRunTime_s  : REAL; // 总运行时间 [s] / total running time [second]
    rLoadTime_s : REAL; // 加载运行时间 [s] / loaded running time [second]
    rIdleKw     : REAL; // 空转状态功率 [kW] / idle state power [kilowatt]
END_VAR
VAR_OUTPUT
    rIdleTime_s : REAL; // 空转时间 [s] / idle time [second]
    rIdlePct    : REAL; // 空转率，限幅 0~100 [%] / idle ratio clamped to 0 to 100 [percent]
    rWastedKwh  : REAL; // 空转浪费电量 [kWh] / energy wasted while idling [kilowatt hour]
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PCT     : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_ZERO    : REAL := 0.0;     // 零值常量 [无量纲] / zero constant [dimensionless]
    DL_S_PER_H : REAL := 3600.0;  // 每小时秒数 [s/h] / seconds per hour [second per hour]
    DL_TOL_S   : REAL := 0.001;   // 时间比较容差 [s] / tolerance of the time comparison [second]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
END_VAR

    // 段 1｜出口预置
    rIdleTime_s := 0.0;
    rIdlePct := 0.0;
    rWastedKwh := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rRunTime_s = rRunTime_s) AND (ABS(rRunTime_s) <= DL_R_MAX) AND (rLoadTime_s = rLoadTime_s) AND (ABS(rLoadTime_s) <= DL_R_MAX) AND (rIdleKw = rIdleKw) AND (ABS(rIdleKw) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：总运行时间严格为正，加载时间与空转功率不得为负
    IF (ABS(rRunTime_s) <= DL_EPS) OR (rRunTime_s < DL_ZERO) THEN
        RETURN;
    END_IF;
    IF (rLoadTime_s < DL_ZERO) OR (rIdleKw < DL_ZERO) THEN
        RETURN;
    END_IF;
    // 段 5｜加载时间不得越过总运行时间
    IF rLoadTime_s > (rRunTime_s + DL_TOL_S) THEN
        RETURN;
    END_IF;
    // 段 6｜空转时间
    rIdleTime_s := rRunTime_s - rLoadTime_s;
    IF rIdleTime_s < DL_ZERO THEN
        rIdleTime_s := DL_ZERO;
    END_IF;
    // 段 7｜空转率与浪费电量
    rIdlePct := rIdleTime_s / rRunTime_s * DL_PCT;
    IF rIdlePct < DL_ZERO THEN
        rIdlePct := DL_ZERO;
    END_IF;
    IF rIdlePct > DL_PCT THEN
        rIdlePct := DL_PCT;
    END_IF;
    rWastedKwh := rIdleKw * rIdleTime_s / DL_S_PER_H;
    bValid := TRUE;
    FC_DL_IdleRunRatioCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_VacuumPadForceCalc
  分类   : DL_Device
  功能   : 真空吸盘吸附力计算，由吸盘直径与真空度求理论吸附力并按安全系数折算可用力
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      吸附力 F = (pi/4) * (直径/1000)^2 * (真空度*1000)，直径先由 mm 折 m，真空度由 kPa 折 Pa，结果单位 N。
      可用力 = 理论力 / 安全系数；安全系数工程常用 1.5~3，低于 1.0 视为参数错误。
      面积同时以 mm2 输出，便于与样本册的吸盘规格直接对照。
  ============================================================
*)
FUNCTION FC_DL_VacuumPadForceCalc : BOOL
VAR_INPUT
    bEnable  : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr     : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rDia_mm  : REAL; // 吸盘有效直径 [mm] / effective pad diameter [millimetre]
    rVacKpa  : REAL; // 工作真空度 [kPa] / working vacuum level [kilopascal]
    rSafety  : REAL; // 安全系数，常用 1.5~3 [无量纲] / safety factor, typically 1.5 to 3 [dimensionless]
END_VAR
VAR_OUTPUT
    rArea_mm2 : REAL; // 吸盘有效面积 [mm2] / effective pad area [square millimetre]
    rForceN   : REAL; // 理论吸附力 [N] / theoretical holding force [newton]
    rUsableN  : REAL; // 除以安全系数后的可用吸附力 [N] / usable holding force after the safety factor [newton]
    bValid    : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_PI      : REAL := 3.14159265; // 圆周率 [无量纲] / circular constant [dimensionless]
    DL_R_MAX   : REAL := 3.0E38;     // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12;    // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_MM_TO_M : REAL := 1000.0;     // 毫米折米系数 [mm/m] / millimetre to metre factor [millimetre per metre]
    DL_KPA_TO_PA : REAL := 1000.0;   // 千帕折帕系数 [Pa/kPa] / kilopascal to pascal factor [pascal per kilopascal]
    DL_QUARTER : REAL := 0.25;       // 四分之一，用于 pi/4 折算 [无量纲] / one quarter used for the pi over four term [dimensionless]
    DL_SAFE_MIN : REAL := 1.0;       // 安全系数下界 [无量纲] / lower bound of the safety factor [dimensionless]
    DL_SAFE_MAX : REAL := 10.0;      // 安全系数上界 [无量纲] / upper bound of the safety factor [dimensionless]
    DL_VAC_MAX : REAL := 101.3;      // 真空度物理上限，标准大气压 [kPa] / physical upper bound of the vacuum level, standard atmosphere [kilopascal]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rDia  : REAL := 0.0;   // 吸盘直径折算米 [m] / pad diameter in metre [metre]
    _rArea : REAL := 0.0;   // 吸盘有效面积 [m2] / effective pad area [square metre]
    _rPress : REAL := 0.0;  // 压差折算帕 [Pa] / differential pressure in pascal [pascal]
END_VAR

    // 段 1｜出口预置
    rArea_mm2 := 0.0;
    rForceN := 0.0;
    rUsableN := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rDia_mm = rDia_mm) AND (ABS(rDia_mm) <= DL_R_MAX) AND (rVacKpa = rVacKpa) AND (ABS(rVacKpa) <= DL_R_MAX) AND (rSafety = rSafety) AND (ABS(rSafety) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：直径严格为正且不超过 1 m，真空度为正且不超过大气压，安全系数在合理区间
    IF (ABS(rDia_mm) <= DL_EPS) OR (rDia_mm < 0.0) OR (rDia_mm > DL_MM_TO_M) THEN
        RETURN;
    END_IF;
    IF (ABS(rVacKpa) <= DL_EPS) OR (rVacKpa < 0.0) OR (rVacKpa > DL_VAC_MAX) THEN
        RETURN;
    END_IF;
    IF (rSafety < DL_SAFE_MIN) OR (rSafety > DL_SAFE_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜面积换算
    _rDia := rDia_mm / DL_MM_TO_M;
    _rArea := DL_PI * DL_QUARTER * _rDia * _rDia;
    rArea_mm2 := DL_PI * (rDia_mm * 0.5) * (rDia_mm * 0.5);
    // 段 6｜理论吸附力：面积乘压差
    _rPress := rVacKpa * DL_KPA_TO_PA;
    rForceN := _rArea * _rPress;
    // 段 7｜安全系数除前闸后再算可用力
    IF ABS(rSafety) <= DL_EPS THEN
        RETURN;
    END_IF;
    rUsableN := rForceN / rSafety;
    bValid := TRUE;
    FC_DL_VacuumPadForceCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_SuctionFlowEst
  分类   : DL_Device
  功能   : 真空抽吸流量估算，按喷嘴直径真空度与流量系数求可达到的抽吸体积流量
  复杂度 : C2
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      孔口流量式 Q = Cd * (pi/4) * (直径/1000)^2 * SQRT(2*压差/密度)，压差由 kPa 折 Pa，密度取 1.2 kg/m3。
      Q 的自然单位为 m3/s，乘以 60000/1000 即乘 60 后得到 L/min。
      该式为不可压缩孔口近似，仅在压比不进入临界区时可用，属工程估算而非精确标定。
  ============================================================
*)
FUNCTION FC_DL_SuctionFlowEst : BOOL
VAR_INPUT
    bEnable  : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr     : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rDia_mm  : REAL; // 抽吸喷嘴等效直径 [mm] / equivalent nozzle diameter [millimetre]
    rVacKpa  : REAL; // 工作真空度 [kPa] / working vacuum level [kilopascal]
    rCd      : REAL; // 流量系数，常用 0.6~0.85 [无量纲] / discharge coefficient, typically 0.6 to 0.85 [dimensionless]
END_VAR
VAR_OUTPUT
    rVel_ms   : REAL; // 孔口等效流速 [m/s] / equivalent orifice velocity [metre per second]
    rFlowLpm  : REAL; // 折算抽吸流量 [L/min] / equivalent suction flow [litre per minute]
    rFlowNm3h : REAL; // 折算标准状态流量 [Nm3/h] / equivalent normal flow [normal cubic metre per hour]
    bValid    : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_PI       : REAL := 3.14159265; // 圆周率 [无量纲] / circular constant [dimensionless]
    DL_R_MAX    : REAL := 3.0E38;     // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS      : REAL := 1.0E-12;    // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_MM_TO_M  : REAL := 1000.0;     // 毫米折米系数 [mm/m] / millimetre to metre factor [millimetre per metre]
    DL_KPA_TO_PA : REAL := 1000.0;    // 千帕折帕系数 [Pa/kPa] / kilopascal to pascal factor [pascal per kilopascal]
    DL_RHO      : REAL := 1.2;        // 空气密度 [kg/m3] / air density [kilogram per cubic metre]
    DL_QUARTER  : REAL := 0.25;       // 四分之一，用于 pi/4 折算 [无量纲] / one quarter used for the pi over four term [dimensionless]
    DL_M3S_TO_LPM : REAL := 60000.0;  // 立方米每秒折升每分系数（含 1/1000 体积换算）[无量纲] / cubic metre per second to litre per minute factor [dimensionless]
    DL_M3S_TO_NM3H : REAL := 3600.0;  // 立方米每秒折立方米每小时系数 [无量纲] / cubic metre per second to cubic metre per hour factor [dimensionless]
    DL_CD_MIN   : REAL := 0.1;        // 流量系数可信下界 [无量纲] / credible lower bound of the discharge coefficient [dimensionless]
    DL_CD_MAX   : REAL := 1.0;        // 流量系数物理上界 [无量纲] / physical upper bound of the discharge coefficient [dimensionless]
    DL_VAC_MAX  : REAL := 101.3;      // 真空度物理上限，标准大气压 [kPa] / physical upper bound of the vacuum level, standard atmosphere [kilopascal]
    DL_DIA_MAX  : REAL := 1000.0;     // 喷嘴直径合理上限 [mm] / sanity upper bound of the nozzle diameter [millimetre]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rDia  : REAL := 0.0;   // 喷嘴直径折算米 [m] / nozzle diameter in metre [metre]
    _rArea : REAL := 0.0;   // 喷嘴过流面积 [m2] / nozzle flow area [square metre]
    _rPress : REAL := 0.0;  // 压差折算帕 [Pa] / differential pressure in pascal [pascal]
    _rTerm : REAL := 0.0;   // 流速根号内被开方数 [m2/s2] / radicand of the velocity square root [square metre per square second]
    _rQm3s : REAL := 0.0;   // 体积流量 [m3/s] / volumetric flow [cubic metre per second]
END_VAR

    // 段 1｜出口预置
    rVel_ms := 0.0;
    rFlowLpm := 0.0;
    rFlowNm3h := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rDia_mm = rDia_mm) AND (ABS(rDia_mm) <= DL_R_MAX) AND (rVacKpa = rVacKpa) AND (ABS(rVacKpa) <= DL_R_MAX) AND (rCd = rCd) AND (ABS(rCd) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸
    IF (ABS(rDia_mm) <= DL_EPS) OR (rDia_mm < 0.0) OR (rDia_mm > DL_DIA_MAX) THEN
        RETURN;
    END_IF;
    IF (ABS(rVacKpa) <= DL_EPS) OR (rVacKpa < 0.0) OR (rVacKpa > DL_VAC_MAX) THEN
        RETURN;
    END_IF;
    IF (rCd < DL_CD_MIN) OR (rCd > DL_CD_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜面积与压差
    _rDia := rDia_mm / DL_MM_TO_M;
    _rArea := DL_PI * DL_QUARTER * _rDia * _rDia;
    _rPress := rVacKpa * DL_KPA_TO_PA;
    // 段 6｜开方前必须确认被开方数非负，密度分母已按常数保证为正
    _rTerm := 2.0 * _rPress / DL_RHO;
    IF _rTerm < 0.0 THEN
        RETURN;
    END_IF;
    rVel_ms := SQRT(_rTerm);
    // 段 7｜体积流量与单位折算
    _rQm3s := rCd * _rArea * rVel_ms;
    rFlowLpm := _rQm3s * DL_M3S_TO_LPM;
    rFlowNm3h := _rQm3s * DL_M3S_TO_NM3H;
    bValid := TRUE;
    FC_DL_SuctionFlowEst := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_SheetPeelForceCalc
  分类   : DL_Device
  功能   : 片材剥离力计算，由接触面积粘附强度与静电电压求剥离力并按剥离角折减
  复杂度 : C2
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      粘附分量 = 接触面积(m2) * 粘附强度(Pa)，面积由 mm2 乘 1e-6，强度由 kPa 乘 1000。
      静电分量 = 静电电压(kV) * 0.05，系数为工程经验折算，单位 N/kV。
      剥离角修正系数 = (1 + COS(角度)) / 2，归一到 0 度时为 1、90 度为 0.5、180 度为 0，便于跨机型比较。
      剥离力超过 50 N 判需要外部辅助剥离。
  ============================================================
*)
FUNCTION FC_DL_SheetPeelForceCalc : BOOL
VAR_INPUT
    bEnable       : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr          : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rArea_mm2     : REAL; // 片材与承载面接触面积 [mm2] / contact area between sheet and support [square millimetre]
    rAdhesion_kpa : REAL; // 单位面积粘附强度 [kPa] / adhesion strength per unit area [kilopascal]
    rStaticKv     : REAL; // 片材静电电位 [kV] / electrostatic potential of the sheet [kilovolt]
    rPeelAngleDeg : REAL; // 剥离角度，0 度表示垂直拉起 [度] / peel angle, zero means lifting perpendicular [degree]
END_VAR
VAR_OUTPUT
    rAdhesionN : REAL; // 粘附力分量 [N] / adhesion force component [newton]
    rStaticN   : REAL; // 静电力分量 [N] / electrostatic force component [newton]
    rAngleFactor : REAL; // 剥离角折减系数，0~1 [无量纲] / peel angle reduction factor from 0 to 1 [dimensionless]
    rPeelN     : REAL; // 综合剥离力 [N] / resultant peel force [newton]
    bNeedAssist : BOOL; // 需要辅助：TRUE 表示剥离力超过 50 N / assistance required, TRUE when the peel force exceeds 50 newton
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX     : REAL := 3.0E38;     // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS       : REAL := 1.0E-12;    // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_MM2_TO_M2 : REAL := 1.0E-6;     // 平方毫米折平方米系数 [m2/mm2] / square millimetre to square metre factor [square metre per square millimetre]
    DL_KPA_TO_PA : REAL := 1000.0;     // 千帕折帕系数 [Pa/kPa] / kilopascal to pascal factor [pascal per kilopascal]
    DL_KV_TO_N   : REAL := 0.05;       // 每千伏静电折算力 [N/kV] / electrostatic force per kilovolt [newton per kilovolt]
    DL_DEG_TO_RAD : REAL := 0.0174533; // 度转弧度系数 [rad/度] / degree to radian factor [radian per degree]
    DL_HALF      : REAL := 0.5;        // 二分之一，用于角度系数归一 [无量纲] / one half used to normalise the angle factor [dimensionless]
    DL_ONE       : REAL := 1.0;        // 单位常量 [无量纲] / unity constant [dimensionless]
    DL_ASSIST_N  : REAL := 50.0;       // 辅助剥离门限 [N] / assistance threshold [newton]
    DL_ANGLE_MAX : REAL := 180.0;      // 剥离角允许上限 [度] / permitted upper bound of the peel angle [degree]
    DL_STAT_MAX  : REAL := 1000.0;     // 静电电位合理上限 [kV] / sanity upper bound of the electrostatic potential [kilovolt]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rRad  : REAL := 0.0;   // 剥离角折算弧度 [rad] / peel angle in radian [radian]
END_VAR

    // 段 1｜出口预置
    rAdhesionN := 0.0;
    rStaticN := 0.0;
    rAngleFactor := 0.0;
    rPeelN := 0.0;
    bNeedAssist := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rArea_mm2 = rArea_mm2) AND (ABS(rArea_mm2) <= DL_R_MAX) AND (rAdhesion_kpa = rAdhesion_kpa) AND (ABS(rAdhesion_kpa) <= DL_R_MAX) AND (rStaticKv = rStaticKv) AND (ABS(rStaticKv) <= DL_R_MAX) AND (rPeelAngleDeg = rPeelAngleDeg) AND (ABS(rPeelAngleDeg) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：面积非负、粘附强度非负、静电位非负且合理、角度 0~180
    IF (rArea_mm2 < 0.0) OR (rAdhesion_kpa < 0.0) OR (rStaticKv < 0.0) OR (rStaticKv > DL_STAT_MAX) THEN
        RETURN;
    END_IF;
    IF (rPeelAngleDeg < 0.0) OR (rPeelAngleDeg > DL_ANGLE_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜两个力分量
    rAdhesionN := rArea_mm2 * DL_MM2_TO_M2 * rAdhesion_kpa * DL_KPA_TO_PA;
    rStaticN := rStaticKv * DL_KV_TO_N;
    // 段 6｜角度折减系数
    _rRad := rPeelAngleDeg * DL_DEG_TO_RAD;
    rAngleFactor := (DL_ONE + COS(_rRad)) * DL_HALF;
    IF rAngleFactor < 0.0 THEN
        rAngleFactor := 0.0;
    END_IF;
    IF rAngleFactor > DL_ONE THEN
        rAngleFactor := DL_ONE;
    END_IF;
    // 段 7｜综合剥离力
    rPeelN := (rAdhesionN + rStaticN) * rAngleFactor;
    // 段 8｜辅助判定
    IF rPeelN > DL_ASSIST_N THEN
        bNeedAssist := TRUE;
    ELSE
        bNeedAssist := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_SheetPeelForceCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_VacHoldDecayChk
  分类   : DL_Device
  功能   : 真空保持衰减校验，按保持时段内的真空度跌落求衰减率并给出泄漏报警
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      衰减率 = (起始真空度 - 当前真空度) / 保持时长，单位 kPa/s。
      当前真空度高于起始值属测量异常或补抽工况，衰减率按 0 处理并置 bSuspect 提示，不判泄漏。
      衰减率严格大于允许限值才置泄漏报警，等于限值视为边界可控。
  ============================================================
*)
FUNCTION FC_DL_VacHoldDecayChk : BOOL
VAR_INPUT
    bEnable     : BOOL; // 使能：TRUE 时校验 / Enable: TRUE to check
    bErr        : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rVacStart_kpa : REAL; // 保持时段起始真空度 [kPa] / vacuum level at the start of the hold phase [kilopascal]
    rVacNow_kpa : REAL; // 当前实测真空度 [kPa] / current measured vacuum level [kilopascal]
    rHoldTime_s : REAL; // 保持时段已持续时长 [s] / elapsed hold phase duration [second]
    rDecayLim   : REAL; // 允许的最大衰减率 [kPa/s] / permitted maximum decay rate [kilopascal per second]
END_VAR
VAR_OUTPUT
    rDecayRate : REAL; // 实测真空衰减率，负值按 0 处理 [kPa/s] / measured vacuum decay rate, negative clamped to zero [kilopascal per second]
    rDropKpa   : REAL; // 时段内真空度跌落量 [kPa] / vacuum drop within the hold phase [kilopascal]
    bLeakAlarm : BOOL; // 泄漏报警：TRUE 表示衰减率超过限值 / leak alarm, TRUE when the decay rate exceeds the limit
    bSuspect   : BOOL; // 数据可疑：TRUE 表示当前真空度高于起始值 / suspect data, TRUE when the current vacuum is above the start value
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_ZERO    : REAL := 0.0;     // 零值常量 [无量纲] / zero constant [dimensionless]
    DL_VAC_MAX : REAL := 101.3;   // 真空度物理上限，标准大气压 [kPa] / physical upper bound of the vacuum level, standard atmosphere [kilopascal]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
END_VAR

    // 段 1｜出口预置：报警位保守置 FALSE，可疑位先置 FALSE
    rDecayRate := 0.0;
    rDropKpa := 0.0;
    bLeakAlarm := FALSE;
    bSuspect := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rVacStart_kpa = rVacStart_kpa) AND (ABS(rVacStart_kpa) <= DL_R_MAX) AND (rVacNow_kpa = rVacNow_kpa) AND (ABS(rVacNow_kpa) <= DL_R_MAX) AND (rHoldTime_s = rHoldTime_s) AND (ABS(rHoldTime_s) <= DL_R_MAX) AND (rDecayLim = rDecayLim) AND (ABS(rDecayLim) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：保持时长严格为正，真空度与限值不得为负
    IF (ABS(rHoldTime_s) <= DL_EPS) OR (rHoldTime_s < DL_ZERO) THEN
        RETURN;
    END_IF;
    IF (rVacStart_kpa < DL_ZERO) OR (rVacNow_kpa < DL_ZERO) OR (rDecayLim < DL_ZERO) THEN
        RETURN;
    END_IF;
    IF (rVacStart_kpa > DL_VAC_MAX) OR (rVacNow_kpa > DL_VAC_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜跌落量与衰减率
    rDropKpa := rVacStart_kpa - rVacNow_kpa;
    IF rDropKpa < DL_ZERO THEN
        bSuspect := TRUE;
        rDropKpa := DL_ZERO;
        rDecayRate := DL_ZERO;
    ELSE
        bSuspect := FALSE;
        rDecayRate := rDropKpa / rHoldTime_s;
    END_IF;
    // 段 6｜泄漏报警
    IF rDecayRate > rDecayLim THEN
        bLeakAlarm := TRUE;
    ELSE
        bLeakAlarm := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_VacHoldDecayChk := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_PadWearIndexCalc
  分类   : DL_Device
  功能   : 吸盘磨损指数计算，综合泄漏增长率与直径磨耗量加权后给出更换到期判定
  复杂度 : C2
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      泄漏增长率 = (当前泄漏 - 新品泄漏) / 新品泄漏 * 100，新品泄漏低于 0.001 L/min 视为无基准判无效。
      磨损指数 = 0.7 * 泄漏增长率 + 0.3 * 直径磨耗 * 10，限幅 0~100。
      指数超过 70 判更换到期；负的泄漏增长（密封变好）按 0 截断，指数只反映劣化方向。
  ============================================================
*)
FUNCTION FC_DL_PadWearIndexCalc : BOOL
VAR_INPUT
    bEnable     : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr        : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rLeakNew    : REAL; // 新品基准泄漏量 [L/min] / leak rate of a new pad [litre per minute]
    rLeakNow    : REAL; // 当前实测泄漏量 [L/min] / currently measured leak rate [litre per minute]
    rDiaWear_mm : REAL; // 吸盘直径磨耗量 [mm] / diameter wear of the pad [millimetre]
END_VAR
VAR_OUTPUT
    rLeakPct  : REAL; // 泄漏增长率 [%] / leak growth rate [percent]
    rWearIdx  : REAL; // 综合磨损指数，限幅 0~100 [无量纲] / combined wear index clamped to 0 to 100 [dimensionless]
    bReplaceDue : BOOL; // 更换到期：TRUE 表示指数超过 70 / replacement due, TRUE when the index exceeds 70
    bValid    : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX     : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS       : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_LEAK_MIN  : REAL := 0.001;   // 新品泄漏基准的可信下界 [L/min] / credible lower bound of the new pad leak reference [litre per minute]
    DL_PCT       : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_W_LEAK    : REAL := 0.7;     // 泄漏项权重 [无量纲] / weight of the leak term [dimensionless]
    DL_W_DIA     : REAL := 0.3;     // 直径磨耗项权重 [无量纲] / weight of the diameter wear term [dimensionless]
    DL_DIA_GAIN  : REAL := 10.0;    // 直径磨耗放大倍数 [无量纲] / amplification of the diameter wear term [dimensionless]
    DL_IDX_HI    : REAL := 100.0;   // 指数限幅上限 [无量纲] / upper clamp of the index [dimensionless]
    DL_IDX_LO    : REAL := 0.0;     // 指数限幅下限 [无量纲] / lower clamp of the index [dimensionless]
    DL_DUE_IDX   : REAL := 70.0;    // 更换到期门限 [无量纲] / replacement due threshold [dimensionless]
    DL_DIA_MAX   : REAL := 200.0;   // 直径磨耗合理上限 [mm] / sanity upper bound of the diameter wear [millimetre]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rRaw : REAL := 0.0;   // 限幅前磨损指数 [无量纲] / raw wear index before clamping [dimensionless]
END_VAR

    // 段 1｜出口预置
    rLeakPct := 0.0;
    rWearIdx := 0.0;
    bReplaceDue := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rLeakNew = rLeakNew) AND (ABS(rLeakNew) <= DL_R_MAX) AND (rLeakNow = rLeakNow) AND (ABS(rLeakNow) <= DL_R_MAX) AND (rDiaWear_mm = rDiaWear_mm) AND (ABS(rDiaWear_mm) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：新品泄漏必须高于可信下界，当前泄漏与磨耗不得为负
    IF (ABS(rLeakNew) <= DL_EPS) OR (rLeakNew < DL_LEAK_MIN) THEN
        RETURN;
    END_IF;
    IF (rLeakNow < 0.0) OR (rDiaWear_mm < 0.0) OR (rDiaWear_mm > DL_DIA_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜泄漏增长率
    rLeakPct := (rLeakNow - rLeakNew) / rLeakNew * DL_PCT;
    IF rLeakPct < DL_IDX_LO THEN
        rLeakPct := DL_IDX_LO;
    END_IF;
    // 段 6｜加权合成与限幅
    _rRaw := DL_W_LEAK * rLeakPct + DL_W_DIA * rDiaWear_mm * DL_DIA_GAIN;
    IF _rRaw < DL_IDX_LO THEN
        rWearIdx := DL_IDX_LO;
    ELSIF _rRaw > DL_IDX_HI THEN
        rWearIdx := DL_IDX_HI;
    ELSE
        rWearIdx := _rRaw;
    END_IF;
    // 段 7｜更换到期判定用限幅前的真实指数判断方向
    IF _rRaw > DL_DUE_IDX THEN
        bReplaceDue := TRUE;
    ELSE
        bReplaceDue := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_PadWearIndexCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_VacuumGenDutyCalc
  分类   : DL_Device
  功能   : 真空发生器占空比计算，按单周期通电时长求占空比并折算压缩空气耗量
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      占空比 = 通电时长 / 循环周期 * 100，限幅 0~100。
      平均耗气量 = 额定耗气量 * 占空比 / 100，单位 L/min。
      通电时长超过循环周期属参数矛盾，判无效；周期为零则无法归一，同样判无效。
  ============================================================
*)
FUNCTION FC_DL_VacuumGenDutyCalc : BOOL
VAR_INPUT
    bEnable    : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr       : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rOnTime_s  : REAL; // 单周期内真空发生器通电时长 [s] / generator energised time within one cycle [second]
    rCycle_s   : REAL; // 循环周期总时长 [s] / total cycle duration [second]
    rAirCons   : REAL; // 通电状态下的额定耗气量 [L/min] / rated air consumption while energised [litre per minute]
END_VAR
VAR_OUTPUT
    rDutyPct   : REAL; // 真空发生器占空比，限幅 0~100 [%] / generator duty cycle clamped to 0 to 100 [percent]
    rAirUseLpm : REAL; // 折算平均耗气量 [L/min] / equivalent average air consumption [litre per minute]
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PCT     : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_ZERO    : REAL := 0.0;     // 零值常量 [无量纲] / zero constant [dimensionless]
    DL_TOL_S   : REAL := 0.001;   // 时长比较容差 [s] / tolerance of the duration comparison [second]
    DL_CYC_MAX : REAL := 86400.0; // 循环周期合理上限，一天 [s] / sanity upper bound of the cycle duration, one day [second]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
END_VAR

    // 段 1｜出口预置
    rDutyPct := 0.0;
    rAirUseLpm := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rOnTime_s = rOnTime_s) AND (ABS(rOnTime_s) <= DL_R_MAX) AND (rCycle_s = rCycle_s) AND (ABS(rCycle_s) <= DL_R_MAX) AND (rAirCons = rAirCons) AND (ABS(rAirCons) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：周期严格为正且不超过一天，通电时长与耗气量非负
    IF (ABS(rCycle_s) <= DL_EPS) OR (rCycle_s < DL_ZERO) OR (rCycle_s > DL_CYC_MAX) THEN
        RETURN;
    END_IF;
    IF (rOnTime_s < DL_ZERO) OR (rAirCons < DL_ZERO) THEN
        RETURN;
    END_IF;
    // 段 5｜通电时长不得越过周期
    IF rOnTime_s > (rCycle_s + DL_TOL_S) THEN
        RETURN;
    END_IF;
    // 段 6｜占空比与限幅
    rDutyPct := rOnTime_s / rCycle_s * DL_PCT;
    IF rDutyPct < DL_ZERO THEN
        rDutyPct := DL_ZERO;
    END_IF;
    IF rDutyPct > DL_PCT THEN
        rDutyPct := DL_PCT;
    END_IF;
    // 段 7｜平均耗气量
    rAirUseLpm := rAirCons * rDutyPct / DL_PCT;
    bValid := TRUE;
    FC_DL_VacuumGenDutyCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_SuctionCupCountCalc
  分类   : DL_Device
  功能   : 吸盘数量配置计算，按载荷重力与冗余倾覆系数求所需吸盘数并给出可行性判定
  复杂度 : C2
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      需求数 = 向上取整(载荷kg * 9.81 * 冗余系数 * 倾覆系数 / 单盘可用力N)。
      向上取整不调用 CEIL，而是先截断再按余量进位，且截断前先做实数上限兜底，防止 REAL_TO_INT 溢出。
      结果限幅 1~64；需求数超过 32 时可行性判 FALSE，表示超出常规单机吸盘阵列规模。
      需求数溢出上限时直接按 64 落定并判不可行，不做回绕。
  ============================================================
*)
FUNCTION FC_DL_SuctionCupCountCalc : BOOL
VAR_INPUT
    bEnable      : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr         : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rLoadKg      : REAL; // 被吸持工件质量 [kg] / mass of the workpiece to be held [kilogram]
    rPerCupN     : REAL; // 单个吸盘可用吸附力 [N] / usable holding force of one cup [newton]
    rRedundancy  : REAL; // 冗余系数，常用 1.2~2.0 [无量纲] / redundancy factor, typically 1.2 to 2.0 [dimensionless]
    rTiltFactor  : REAL; // 倾覆与动态系数 [无量纲] / tilt and dynamic factor [dimensionless]
END_VAR
VAR_OUTPUT
    rNeedRaw  : REAL; // 向上取整前的需求数 [个] / raw required count before rounding up [unit]
    iCupCnt   : INT;  // 配置吸盘数量，限幅 1~64 [个] / configured cup count clamped to 1 to 64 [unit]
    bFeasible : BOOL; // 可行：TRUE 表示数量不超过 32 个 / feasible, TRUE when the count does not exceed 32 [unit]
    bOverflow : BOOL; // 需求溢出：TRUE 表示需求数超出整数可表范围 / requirement overflow, TRUE when the requirement exceeds the integer range
    bValid    : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX     : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS       : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_G         : REAL := 9.81;    // 重力加速度 [m/s2] / gravitational acceleration [metre per second squared]
    DL_CUP_MIN   : INT := 1;        // 吸盘数量下界 [个] / lower bound of the cup count [unit]
    DL_CUP_MAX   : INT := 64;       // 吸盘数量上界 [个] / upper bound of the cup count [unit]
    DL_CUP_OK    : INT := 32;       // 常规阵列规模上限 [个] / upper bound of a conventional array [unit]
    DL_INT_SAFE  : REAL := 32000.0; // 实数转整数前的安全上限 [无量纲] / safe upper bound before converting a real into an integer [dimensionless]
    DL_RESID_TOL : REAL := 1.0E-6;  // 截断余量判定容差 [无量纲] / tolerance deciding the rounding carry [dimensionless]
    DL_RED_MIN   : REAL := 1.0;     // 冗余系数下界 [无量纲] / lower bound of the redundancy factor [dimensionless]
    DL_RED_MAX   : REAL := 5.0;     // 冗余系数上界 [无量纲] / upper bound of the redundancy factor [dimensionless]
    DL_TILT_MIN  : REAL := 1.0;     // 倾覆系数下界 [无量纲] / lower bound of the tilt factor [dimensionless]
    DL_TILT_MAX  : REAL := 5.0;     // 倾覆系数上界 [无量纲] / upper bound of the tilt factor [dimensionless]
    DL_LOAD_MAX  : REAL := 100000.0; // 工件质量合理上限 [kg] / sanity upper bound of the workpiece mass [kilogram]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _iTmp  : INT := 0;      // 截断后的临时整数 [个] / temporary integer after truncation [unit]
    _rRes  : REAL := 0.0;   // 截断余量 [个] / residual after truncation [unit]
END_VAR

    // 段 1｜出口预置：数量先置 1，可行位先置 FALSE
    rNeedRaw := 0.0;
    iCupCnt := DL_CUP_MIN;
    bFeasible := FALSE;
    bOverflow := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rLoadKg = rLoadKg) AND (ABS(rLoadKg) <= DL_R_MAX) AND (rPerCupN = rPerCupN) AND (ABS(rPerCupN) <= DL_R_MAX) AND (rRedundancy = rRedundancy) AND (ABS(rRedundancy) <= DL_R_MAX) AND (rTiltFactor = rTiltFactor) AND (ABS(rTiltFactor) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：单盘力严格为正，载荷非负且合理，两个系数落在工程区间
    IF (ABS(rPerCupN) <= DL_EPS) OR (rPerCupN < 0.0) THEN
        RETURN;
    END_IF;
    IF (rLoadKg < 0.0) OR (rLoadKg > DL_LOAD_MAX) THEN
        RETURN;
    END_IF;
    IF (rRedundancy < DL_RED_MIN) OR (rRedundancy > DL_RED_MAX) THEN
        RETURN;
    END_IF;
    IF (rTiltFactor < DL_TILT_MIN) OR (rTiltFactor > DL_TILT_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜需求数原值
    rNeedRaw := rLoadKg * DL_G * rRedundancy * rTiltFactor / rPerCupN;
    // 段 6｜临界零需求：无载荷时按最小 1 个配置，直接判定
    IF rNeedRaw <= DL_RESID_TOL THEN
        iCupCnt := DL_CUP_MIN;
        bFeasible := TRUE;
        bOverflow := FALSE;
        bValid := TRUE;
        FC_DL_SuctionCupCountCalc := bValid;
        RETURN;
    END_IF;
    // 段 7｜实数上限兜底：超界直接按上界落定并判不可行，杜绝 REAL_TO_INT 回头
    IF rNeedRaw >= DL_INT_SAFE THEN
        iCupCnt := DL_CUP_MAX;
        bFeasible := FALSE;
        bOverflow := TRUE;
        bValid := TRUE;
        FC_DL_SuctionCupCountCalc := bValid;
        RETURN;
    END_IF;
    // 段 8｜先截断再按余量进位，等价向上取整但不调用 CEIL
    _iTmp := REAL_TO_INT(rNeedRaw);
    _rRes := rNeedRaw - INT_TO_REAL(_iTmp);
    IF _rRes > DL_RESID_TOL THEN
        _iTmp := _iTmp + 1;
    END_IF;
    // 段 9｜限幅与可行性
    IF _iTmp < DL_CUP_MIN THEN
        _iTmp := DL_CUP_MIN;
    END_IF;
    IF _iTmp > DL_CUP_MAX THEN
        _iTmp := DL_CUP_MAX;
    END_IF;
    iCupCnt := _iTmp;
    IF _iTmp <= DL_CUP_OK THEN
        bFeasible := TRUE;
    ELSE
        bFeasible := FALSE;
    END_IF;
    bOverflow := FALSE;
    bValid := TRUE;
    FC_DL_SuctionCupCountCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_LineSpeedMatchRatio
  分类   : DL_Motion
  功能   : 主从线速匹配校验，由主从线速求实际速比并与设定速比比较给出偏差与匹配位
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      实际速比 = 从线速度 / 主线速度；偏差 = (实际速比 - 设定速比) / 设定速比 * 100。
      偏差绝对值不超过 2% 判匹配；主线静止时速比无定义，直接判无效而不是输出零速比。
  ============================================================
*)
FUNCTION FC_DL_LineSpeedMatchRatio : BOOL
VAR_INPUT
    bEnable    : BOOL; // 使能：TRUE 时校验 / Enable: TRUE to check
    bErr       : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rMasterMpm : REAL; // 主线线速度 [m/min] / master line speed [metre per minute]
    rSlaveMpm  : REAL; // 从线线速度 [m/min] / slave line speed [metre per minute]
    rRatioSet  : REAL; // 设定速比，从线相对主线 [无量纲] / set speed ratio of slave over master [dimensionless]
END_VAR
VAR_OUTPUT
    rRatioAct : REAL; // 实际速比 [无量纲] / actual speed ratio [dimensionless]
    rDevPct   : REAL; // 速比相对偏差 [%] / relative speed ratio deviation [percent]
    bMatch    : BOOL; // 匹配：TRUE 表示偏差绝对值不超过 2% / matched, TRUE when the absolute deviation is within 2 percent
    bValid    : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX   : REAL := 3.0E38;  // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS     : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PCT     : REAL := 100.0;   // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_TOL_PCT : REAL := 2.0;     // 速比匹配允许偏差 [%] / permitted ratio deviation for a match [percent]
    DL_RATIO_MAX : REAL := 100.0; // 速比合理上限 [无量纲] / sanity upper bound of the speed ratio [dimensionless]
    DL_SPEED_MAX : REAL := 10000.0; // 线速度合理上限 [m/min] / sanity upper bound of the line speed [metre per minute]
END_VAR
VAR
    _bFin   : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rAbsDev : REAL := 0.0;  // 偏差绝对值 [%] / absolute deviation [percent]
END_VAR

    // 段 1｜出口预置
    rRatioAct := 0.0;
    rDevPct := 0.0;
    bMatch := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rMasterMpm = rMasterMpm) AND (ABS(rMasterMpm) <= DL_R_MAX) AND (rSlaveMpm = rSlaveMpm) AND (ABS(rSlaveMpm) <= DL_R_MAX) AND (rRatioSet = rRatioSet) AND (ABS(rRatioSet) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：主线速度严格为正，从线速度非负，设定速比严格为正
    IF (ABS(rMasterMpm) <= DL_EPS) OR (rMasterMpm < 0.0) OR (rMasterMpm > DL_SPEED_MAX) THEN
        RETURN;
    END_IF;
    IF (rSlaveMpm < 0.0) OR (rSlaveMpm > DL_SPEED_MAX) THEN
        RETURN;
    END_IF;
    IF (ABS(rRatioSet) <= DL_EPS) OR (rRatioSet < 0.0) OR (rRatioSet > DL_RATIO_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜实际速比
    rRatioAct := rSlaveMpm / rMasterMpm;
    // 段 6｜相对偏差
    rDevPct := (rRatioAct - rRatioSet) / rRatioSet * DL_PCT;
    // 段 7｜匹配判定
    _rAbsDev := ABS(rDevPct);
    IF _rAbsDev <= DL_TOL_PCT THEN
        bMatch := TRUE;
    ELSE
        bMatch := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_LineSpeedMatchRatio := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_ChainWearElongation
  分类   : DL_Motion
  功能   : 链条磨损伸长率计算，由公称节距与实测节距求伸长百分比并给出更换到期判定
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      伸长率 = (实测节距 - 公称节距) / 公称节距 * 100。
      实测节距必须为多节平均后的值，节数少于 3 节时平均值不具代表性，判无效。
      伸长率超过 2.0% 判更换到期；实测小于公称（新链或测量误差）时伸长率为负，判定位保持 FALSE。
  ============================================================
*)
FUNCTION FC_DL_ChainWearElongation : BOOL
VAR_INPUT
    bEnable      : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr         : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rPitchNom_mm : REAL; // 公称节距 [mm] / nominal chain pitch [millimetre]
    rPitchAct_mm : REAL; // 实测节距，取多节平均 [mm] / measured pitch averaged over several links [millimetre]
    iLinkCnt     : INT;  // 参与平均的链节数量 [节] / number of links used in the average [link]
END_VAR
VAR_OUTPUT
    rElongPct   : REAL; // 链条磨损伸长率 [%] / chain wear elongation [percent]
    rPitchDelta_mm : REAL; // 实测与公称的节距差 [mm] / pitch difference between the measured and nominal value [millimetre]
    bReplaceDue : BOOL; // 更换到期：TRUE 表示伸长率超过 2.0% / replacement due, TRUE when the elongation exceeds 2.0 percent
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX    : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS      : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PCT      : REAL := 100.0;  // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_ELONG_MAX : REAL := 2.0;   // 更换到期伸长率门限 [%] / elongation threshold for the replacement [percent]
    DL_LINK_MIN : INT := 3;       // 平均所需最少链节数 [节] / minimum link count required by the average [link]
    DL_LINK_MAX : INT := 200;     // 链节数量合理上限 [节] / sanity upper bound of the link count [link]
    DL_PITCH_MAX : REAL := 1000.0; // 节距合理上限 [mm] / sanity upper bound of the pitch [millimetre]
END_VAR
VAR
    _bFin : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
END_VAR

    // 段 1｜出口预置
    rElongPct := 0.0;
    rPitchDelta_mm := 0.0;
    bReplaceDue := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rPitchNom_mm = rPitchNom_mm) AND (ABS(rPitchNom_mm) <= DL_R_MAX) AND (rPitchAct_mm = rPitchAct_mm) AND (ABS(rPitchAct_mm) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：公称节距严格为正且合理，实测节距非负且合理，链节数 3~200
    IF (ABS(rPitchNom_mm) <= DL_EPS) OR (rPitchNom_mm < 0.0) OR (rPitchNom_mm > DL_PITCH_MAX) THEN
        RETURN;
    END_IF;
    IF (rPitchAct_mm < 0.0) OR (rPitchAct_mm > DL_PITCH_MAX) THEN
        RETURN;
    END_IF;
    IF (iLinkCnt < DL_LINK_MIN) OR (iLinkCnt > DL_LINK_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜节距差与伸长率
    rPitchDelta_mm := rPitchAct_mm - rPitchNom_mm;
    rElongPct := rPitchDelta_mm / rPitchNom_mm * DL_PCT;
    // 段 6｜更换到期判定：仅正向伸长计入磨损
    IF rElongPct > DL_ELONG_MAX THEN
        bReplaceDue := TRUE;
    ELSE
        bReplaceDue := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_ChainWearElongation := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_RollerSlipRatioCalc
  分类   : DL_Motion
  功能   : 辊筒打滑率计算，由输送带速与辊面线速求相对打滑比例并给出打滑报警
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      打滑率 = (辊面线速 - 带速) / 辊面线速 * 100，限幅 -100~100。
      正值表示带速低于辊面速度即打滑，负值表示带速快于辊面速度即被拖动。
      打滑率绝对值超过 5% 置打滑报警；辊面线速为零时打滑率无定义，判无效。
  ============================================================
*)
FUNCTION FC_DL_RollerSlipRatioCalc : BOOL
VAR_INPUT
    bEnable    : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr       : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rBeltMpm   : REAL; // 输送带实际线速度 [m/min] / actual belt speed [metre per minute]
    rRollerMpm : REAL; // 辊筒表面线速度 [m/min] / roller surface speed [metre per minute]
END_VAR
VAR_OUTPUT
    rSlipPct   : REAL; // 打滑率，限幅 -100~100 [%] / slip ratio clamped between minus 100 and 100 [percent]
    bSlipAlarm : BOOL; // 打滑报警：TRUE 表示打滑率绝对值超过 5% / slip alarm, TRUE when the absolute slip ratio exceeds 5 percent
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX    : REAL := 3.0E38;   // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS      : REAL := 1.0E-12;  // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PCT      : REAL := 100.0;    // 百分数换算系数 [无量纲] / percentage scaling factor [dimensionless]
    DL_SLIP_HI  : REAL := 100.0;    // 打滑率限幅上限 [%] / upper clamp of the slip ratio [percent]
    DL_SLIP_LO  : REAL := -100.0;   // 打滑率限幅下限 [%] / lower clamp of the slip ratio [percent]
    DL_ALARM_PCT : REAL := 5.0;     // 打滑报警门限 [%] / slip alarm threshold [percent]
    DL_SPEED_MAX : REAL := 10000.0; // 线速度合理上限 [m/min] / sanity upper bound of the line speed [metre per minute]
END_VAR
VAR
    _bFin   : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rRaw   : REAL := 0.0;   // 限幅前打滑率 [%] / raw slip ratio before clamping [percent]
    _rAbs   : REAL := 0.0;   // 打滑率绝对值 [%] / absolute slip ratio [percent]
END_VAR

    // 段 1｜出口预置
    rSlipPct := 0.0;
    bSlipAlarm := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rBeltMpm = rBeltMpm) AND (ABS(rBeltMpm) <= DL_R_MAX) AND (rRollerMpm = rRollerMpm) AND (ABS(rRollerMpm) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：辊面线速严格为正，带速非负，两者均不超过合理上限
    IF (ABS(rRollerMpm) <= DL_EPS) OR (rRollerMpm < 0.0) OR (rRollerMpm > DL_SPEED_MAX) THEN
        RETURN;
    END_IF;
    IF (rBeltMpm < 0.0) OR (rBeltMpm > DL_SPEED_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜打滑率原值
    _rRaw := (rRollerMpm - rBeltMpm) / rRollerMpm * DL_PCT;
    // 段 6｜限幅
    IF _rRaw < DL_SLIP_LO THEN
        rSlipPct := DL_SLIP_LO;
    ELSIF _rRaw > DL_SLIP_HI THEN
        rSlipPct := DL_SLIP_HI;
    ELSE
        rSlipPct := _rRaw;
    END_IF;
    // 段 7｜报警判定
    _rAbs := ABS(rSlipPct);
    IF _rAbs > DL_ALARM_PCT THEN
        bSlipAlarm := TRUE;
    ELSE
        bSlipAlarm := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_RollerSlipRatioCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_SkateWheelLoadCalc
  分类   : DL_Motion
  功能   : 滑板轮载荷分配计算，按重心纵向偏移求前后轴占比并折算前轴单轮载荷
  复杂度 : C2
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      前轴占比 = 0.5 + 重心偏移 / 轴距，限幅 0.1~0.9，防止极端重心把全部载荷压到单轴。
      前轴总载 = 总重 * 前轴占比；前轴轮数按 (轮数+1)/2 取整，奇数轮时前轴多分 1 个轮。
      单轮载荷 = 前轴总载 / 前轴轮数；轮数不足 2 个或轴距为零时判无效。
  ============================================================
*)
FUNCTION FC_DL_SkateWheelLoadCalc : BOOL
VAR_INPUT
    bEnable      : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr         : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rTotalKg     : REAL; // 滑板与载荷总质量 [kg] / total mass of the skate and the load [kilogram]
    iWheelCnt    : INT;  // 滑板轮总数量 [个] / total number of skate wheels [unit]
    rCgOffset_mm : REAL; // 重心相对几何中心的前向偏移 [mm] / forward offset of the centre of gravity from the geometric centre [millimetre]
    rWheelBase_mm : REAL; // 前后轴距 [mm] / distance between the front and rear axles [millimetre]
END_VAR
VAR_OUTPUT
    rFrontShare : REAL; // 前轴载荷占比，限幅 0.1~0.9 [无量纲] / front axle load share clamped to 0.1 to 0.9 [dimensionless]
    rFrontKg    : REAL; // 前轴总载荷 [kg] / total load on the front axle [kilogram]
    iFrontWheelCnt : INT; // 前轴轮数量 [个] / number of wheels on the front axle [unit]
    rPerWheelKg : REAL; // 前轴单个轮的平均载荷 [kg] / average load of one front wheel [kilogram]
    bValid      : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX    : REAL := 3.0E38; // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS      : REAL := 1.0E-12; // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_HALF     : REAL := 0.5;    // 二分之一，均分基准占比 [无量纲] / one half, the balanced share baseline [dimensionless]
    DL_SHARE_LO : REAL := 0.1;    // 前轴占比下限 [无量纲] / lower clamp of the front share [dimensionless]
    DL_SHARE_HI : REAL := 0.9;    // 前轴占比上限 [无量纲] / upper clamp of the front share [dimensionless]
    DL_WHEEL_MIN : INT := 2;      // 轮数下界 [个] / lower bound of the wheel count [unit]
    DL_WHEEL_MAX : INT := 32;     // 轮数上界 [个] / upper bound of the wheel count [unit]
    DL_BASE_MAX : REAL := 10000.0; // 轴距合理上限 [mm] / sanity upper bound of the wheel base [millimetre]
    DL_MASS_MAX : REAL := 100000.0; // 总质量合理上限 [kg] / sanity upper bound of the total mass [kilogram]
    DL_TWO      : INT := 2;       // 取半数用的除数 [无量纲] / divisor used to obtain half of the wheel count [dimensionless]
    DL_ONE      : INT := 1;       // 奇数轮进位偏置 [个] / carry bias used for an odd wheel count [unit]
END_VAR
VAR
    _bFin    : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rShare  : REAL := 0.0;   // 限幅前前轴占比 [无量纲] / raw front share before clamping [dimensionless]
    _rFrontW : REAL := 0.0;   // 前轴轮数折算实数 [个] / front wheel count cast to real [unit]
END_VAR

    // 段 1｜出口预置：占比先置均分，避免下游误用零
    rFrontShare := DL_HALF;
    rFrontKg := 0.0;
    iFrontWheelCnt := 0;
    rPerWheelKg := 0.0;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rTotalKg = rTotalKg) AND (ABS(rTotalKg) <= DL_R_MAX) AND (rCgOffset_mm = rCgOffset_mm) AND (ABS(rCgOffset_mm) <= DL_R_MAX) AND (rWheelBase_mm = rWheelBase_mm) AND (ABS(rWheelBase_mm) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：轴距严格为正且合理，总质量非负且合理，轮数 2~32
    IF (ABS(rWheelBase_mm) <= DL_EPS) OR (rWheelBase_mm < 0.0) OR (rWheelBase_mm > DL_BASE_MAX) THEN
        RETURN;
    END_IF;
    IF (rTotalKg < 0.0) OR (rTotalKg > DL_MASS_MAX) THEN
        RETURN;
    END_IF;
    IF (iWheelCnt < DL_WHEEL_MIN) OR (iWheelCnt > DL_WHEEL_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜前轴占比与限幅
    _rShare := DL_HALF + rCgOffset_mm / rWheelBase_mm;
    IF _rShare < DL_SHARE_LO THEN
        rFrontShare := DL_SHARE_LO;
    ELSIF _rShare > DL_SHARE_HI THEN
        rFrontShare := DL_SHARE_HI;
    ELSE
        rFrontShare := _rShare;
    END_IF;
    // 段 6｜前轴轮数：奇数轮时前轴多分一个
    iFrontWheelCnt := (iWheelCnt + DL_ONE) / DL_TWO;
    IF iFrontWheelCnt < DL_ONE THEN
        iFrontWheelCnt := DL_ONE;
    END_IF;
    // 段 7｜前轴总载与单轮载荷
    rFrontKg := rTotalKg * rFrontShare;
    _rFrontW := INT_TO_REAL(iFrontWheelCnt);
    IF ABS(_rFrontW) <= DL_EPS THEN
        RETURN;
    END_IF;
    rPerWheelKg := rFrontKg / _rFrontW;
    bValid := TRUE;
    FC_DL_SkateWheelLoadCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_LaneDiverterAngleCalc
  分类   : DL_Motion
  功能   : 道岔转角计算，由包件宽度与道间距求最小偏转角并折算通过时间与速度许可
  复杂度 : C2
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      最小转角 = ATAN(包件宽度 / 道间距)，ATAN 以弧度返回，再除以 0.0174533 折算为度。
      通过时间 = (包件长度/1000) / (线速度/60)，即长度折米后除以速度折 m/s。
      线速度不超过 60 m/min 判速度许可；速度为 0 时通过时间无定义，判无效。
  ============================================================
*)
FUNCTION FC_DL_LaneDiverterAngleCalc : BOOL
VAR_INPUT
    bEnable    : BOOL; // 使能：TRUE 时计算 / Enable: TRUE to compute
    bErr       : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rPkgW_mm   : REAL; // 包件宽度，垂直于输送方向 [mm] / package width perpendicular to the conveying direction [millimetre]
    rPkgL_mm   : REAL; // 包件长度，沿输送方向 [mm] / package length along the conveying direction [millimetre]
    rLaneGap_mm : REAL; // 相邻道中心间距 [mm] / centre distance between adjacent lanes [millimetre]
    rSpeedMpm  : REAL; // 输送线速度 [m/min] / conveyor line speed [metre per minute]
END_VAR
VAR_OUTPUT
    rAngleRad : REAL; // 最小偏转角 [rad] / minimum divert angle [radian]
    rAngleDeg : REAL; // 最小偏转角 [度] / minimum divert angle [degree]
    rCrossTime_s : REAL; // 包件通过道岔所需时间 [s] / time for the package to cross the diverter [second]
    bSpeedOk  : BOOL; // 速度许可：TRUE 表示线速度不超过 60 m/min / speed permitted, TRUE when the line speed is within 60 metres per minute
    bValid    : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX     : REAL := 3.0E38;   // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS       : REAL := 1.0E-12;  // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_RAD_TO_DEG : REAL := 0.0174533; // 弧度转度系数 [度/rad] / radian to degree factor [degree per radian]
    DL_MM_TO_M   : REAL := 1000.0;   // 毫米折米系数 [mm/m] / millimetre to metre factor [millimetre per metre]
    DL_MIN_PER_S : REAL := 60.0;     // 每分钟秒数 [s/min] / seconds per minute [second per minute]
    DL_SPEED_OK  : REAL := 60.0;     // 允许的最高线速度 [m/min] / permitted maximum line speed [metre per minute]
    DL_SPEED_MAX : REAL := 600.0;    // 线速度合理上限 [m/min] / sanity upper bound of the line speed [metre per minute]
    DL_GAP_MIN   : REAL := 1.0;      // 道间距合理下限 [mm] / sanity lower bound of the lane gap [millimetre]
    DL_GAP_MAX   : REAL := 10000.0;  // 道间距合理上限 [mm] / sanity upper bound of the lane gap [millimetre]
    DL_SIZE_MAX  : REAL := 5000.0;   // 包件尺寸合理上限 [mm] / sanity upper bound of the package dimension [millimetre]
END_VAR
VAR
    _bFin    : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rLenM   : REAL := 0.0;   // 包件长度折算米 [m] / package length in metre [metre]
    _rSpdMs  : REAL := 0.0;   // 线速度折算米每秒 [m/s] / line speed in metre per second [metre per second]
END_VAR

    // 段 1｜出口预置
    rAngleRad := 0.0;
    rAngleDeg := 0.0;
    rCrossTime_s := 0.0;
    bSpeedOk := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rPkgW_mm = rPkgW_mm) AND (ABS(rPkgW_mm) <= DL_R_MAX) AND (rPkgL_mm = rPkgL_mm) AND (ABS(rPkgL_mm) <= DL_R_MAX) AND (rLaneGap_mm = rLaneGap_mm) AND (ABS(rLaneGap_mm) <= DL_R_MAX) AND (rSpeedMpm = rSpeedMpm) AND (ABS(rSpeedMpm) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：包件尺寸非负且合理，道间距在合理区间，速度严格为正且合理
    IF (rPkgW_mm < 0.0) OR (rPkgW_mm > DL_SIZE_MAX) OR (rPkgL_mm < 0.0) OR (rPkgL_mm > DL_SIZE_MAX) THEN
        RETURN;
    END_IF;
    IF (rLaneGap_mm < DL_GAP_MIN) OR (rLaneGap_mm > DL_GAP_MAX) THEN
        RETURN;
    END_IF;
    IF (ABS(rSpeedMpm) <= DL_EPS) OR (rSpeedMpm < 0.0) OR (rSpeedMpm > DL_SPEED_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜最小转角
    rAngleRad := ATAN(rPkgW_mm / rLaneGap_mm);
    rAngleDeg := rAngleRad / DL_RAD_TO_DEG;
    // 段 6｜通过时间：长度折米、速度折米每秒
    _rLenM := rPkgL_mm / DL_MM_TO_M;
    _rSpdMs := rSpeedMpm / DL_MIN_PER_S;
    IF ABS(_rSpdMs) <= DL_EPS THEN
        RETURN;
    END_IF;
    rCrossTime_s := _rLenM / _rSpdMs;
    // 段 7｜速度许可
    IF rSpeedMpm <= DL_SPEED_OK THEN
        bSpeedOk := TRUE;
    ELSE
        bSpeedOk := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_LaneDiverterAngleCalc := bValid;
END_FUNCTION

(*
  ============================================================
  组件名 : FC_DL_TrackingOffsetChk
  分类   : DL_Motion
  功能   : 跟踪偏移校验，由编码器累计脉冲折算实际位移并与基准距离比较给出漂移报警
  复杂度 : C1
  版本   : 1.0.0
  作者   : 道莅工业代码库工厂 / R81
  日期   : 2026-11-24
  开源溯源 : clean-room（no upstream）—— 依据公开工程公式自研，未复制任何上游实现
  红线自检 : R1 无GVL/R2 无物理地址/R3 纯IEC/R4 防除零/R5 双语注释
  接口说明 :
      实际距离 = 累计脉冲数 / 每米脉冲数；偏移 = 实际距离 - 基准距离。
      偏移绝对值超过容差置漂移报警；每米脉冲为零时无法折算，判无效。
      脉冲数允许为负，表示编码器反向计数，此时实际距离为负，属正常工况不作拦截。
  ============================================================
*)
FUNCTION FC_DL_TrackingOffsetChk : BOOL
VAR_INPUT
    bEnable     : BOOL; // 使能：TRUE 时校验 / Enable: TRUE to check
    bErr        : BOOL; // 外部故障：TRUE 时立即退出并置结果无效 / External fault: TRUE aborts with invalid result
    rEncoderCnt : REAL; // 编码器累计脉冲数，带符号 [脉冲] / accumulated encoder counts with sign [count]
    rPulsePerM  : REAL; // 每米对应的脉冲数 [脉冲/m] / encoder counts per metre [count per metre]
    rRefM       : REAL; // 基准跟踪距离 [m] / reference tracking distance [metre]
    rTolM       : REAL; // 允许的偏移容差 [m] / permitted offset tolerance [metre]
END_VAR
VAR_OUTPUT
    rActM      : REAL; // 由脉冲折算的实际距离 [m] / actual distance derived from the counts [metre]
    rOffsetM   : REAL; // 实际距离相对基准的偏移 [m] / offset of the actual distance from the reference [metre]
    bDriftAlarm : BOOL; // 漂移报警：TRUE 表示偏移绝对值超过容差 / drift alarm, TRUE when the absolute offset exceeds the tolerance
    bValid     : BOOL; // 输出有效：TRUE 表示结果可用 / Output valid
END_VAR
VAR CONSTANT
    DL_R_MAX    : REAL := 3.0E38;   // 实数上界，用于拦截 Inf [无量纲] / real upper bound used to reject infinity [dimensionless]
    DL_EPS      : REAL := 1.0E-12;  // 除零判定阈值 [无量纲] / division guard threshold [dimensionless]
    DL_PULSE_MAX : REAL := 1.0E9;   // 每米脉冲合理上限 [脉冲/m] / sanity upper bound of the counts per metre [count per metre]
    DL_DIST_MAX : REAL := 100000.0; // 距离合理上限 [m] / sanity upper bound of the distance [metre]
END_VAR
VAR
    _bFin  : BOOL := FALSE; // 输入有限性判定结果 / input finiteness verdict
    _rAbs  : REAL := 0.0;   // 偏移绝对值 [m] / absolute offset [metre]
END_VAR

    // 段 1｜出口预置
    rActM := 0.0;
    rOffsetM := 0.0;
    bDriftAlarm := FALSE;
    bValid := FALSE;
    // 段 2｜使能闸与外部故障闸
    IF NOT bEnable THEN
        RETURN;
    END_IF;
    IF bErr THEN
        RETURN;
    END_IF;
    // 段 3｜非有限闸
    _bFin := (rEncoderCnt = rEncoderCnt) AND (ABS(rEncoderCnt) <= DL_R_MAX) AND (rPulsePerM = rPulsePerM) AND (ABS(rPulsePerM) <= DL_R_MAX) AND (rRefM = rRefM) AND (ABS(rRefM) <= DL_R_MAX) AND (rTolM = rTolM) AND (ABS(rTolM) <= DL_R_MAX);
    IF NOT _bFin THEN
        RETURN;
    END_IF;
    // 段 4｜域闸：每米脉冲严格为正且合理，基准距离与容差非负
    IF (ABS(rPulsePerM) <= DL_EPS) OR (rPulsePerM < 0.0) OR (rPulsePerM > DL_PULSE_MAX) THEN
        RETURN;
    END_IF;
    IF (rRefM < 0.0) OR (rRefM > DL_DIST_MAX) OR (rTolM < 0.0) OR (rTolM > DL_DIST_MAX) THEN
        RETURN;
    END_IF;
    // 段 5｜实际距离与偏移
    rActM := rEncoderCnt / rPulsePerM;
    rOffsetM := rActM - rRefM;
    // 段 6｜漂移报警
    _rAbs := ABS(rOffsetM);
    IF _rAbs > rTolM THEN
        bDriftAlarm := TRUE;
    ELSE
        bDriftAlarm := FALSE;
    END_IF;
    bValid := TRUE;
    FC_DL_TrackingOffsetChk := bValid;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_CoagDoseFromJarTest
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 由烧杯试验最佳投加量反算混凝剂计量泵体积流量 [L/h]，含母液浓度换算、人工修正与上限饱和
*)
FUNCTION FC_DL_CoagDoseFromJarTest : BOOL
VAR_INPUT
    rJarDoseMgL : REAL; // 罐试最佳投加量（以进水体积计）[mg/L] / jar-test optimum dose per litre of raw water
    rFlowM3h : REAL; // 处理水量 [m3/h] / treated water flow
    rDoseTrim : REAL; // 人工修正系数 [1]，1.0 = 不修正 / manual trim factor, 1.0 = no trim
    rDoseMaxLh : REAL; // 计量泵投加体积上限 [L/h] / dosing pump volumetric upper limit
    rStockGL : REAL; // 母液有效浓度 [g/L] / stock solution effective concentration
END_VAR
VAR_OUTPUT
    rDoseLh : REAL; // 投加体积流量 [L/h] / dosing volumetric flow
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=母液浓度非法 2=水量非法 3=超上限饱和 4=结果非有限 / event code
END_VAR
VAR
    rDoseGh : REAL; // 药剂质量流量中间量 [g/h] / intermediate coagulant mass flow
END_VAR

    // —— 段 0：全路径预清 —— //
    rDoseGh := 0.0;
    rDoseLh := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_CoagDoseFromJarTest := FALSE;
    // —— 段 1：分母闸（母液浓度、水量） —— //
    IF ABS(rStockGL) <= 1.0E-9 THEN
        iErrCode := 1; // 母液浓度非法，无法由质量流量换算体积流量 / bad stock concentration, volume flow not derivable
        RETURN;
    END_IF;
    IF rFlowM3h <= 0.0 THEN
        iErrCode := 2; // 无处理水量，投加量保持零 / no water flow, dose held at zero
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (mg/L)*(m3/h) = (g/m3)*(m3/h) = g/h；再 /(g/L) 得 L/h —— //
    rDoseGh := rJarDoseMgL * rFlowM3h; // 药剂质量流量 [g/h] / coagulant mass flow
    rDoseLh := rDoseGh / rStockGL * rDoseTrim; // 投加体积流量 [L/h] / dosing volumetric flow
    // —— 段 3：结果域闸（非有限即归零） —— //
    IF ABS(rDoseLh) > 1.0E15 THEN
        rDoseLh := 0.0;
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    // —— 段 4：限幅 [0, rDoseMaxLh]，负值归零、超上限饱和并置码 —— //
    IF rDoseLh < 0.0 THEN
        rDoseLh := 0.0; // 负投加无物理意义 / negative dose is unphysical
    END_IF;
    IF rDoseLh > rDoseMaxLh THEN
        rDoseLh := MAX(rDoseMaxLh, 0.0); // 饱和到泵上限（上限为负时取零）/ saturate to pump limit, floor zero
        iErrCode := 3; // 信息级：超上限已饱和 / info level: saturated at upper limit
    END_IF;
    bValid := TRUE;
    FC_DL_CoagDoseFromJarTest := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_FlocDilutionRatio
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 絮凝剂由高浓度母液稀释到目标浓度的稀释比与所需母液体积
*)
FUNCTION FC_DL_FlocDilutionRatio : BOOL
VAR_INPUT
    rStockPct : REAL; // 母液质量浓度 [%] / stock solution mass concentration
    rTargetPct : REAL; // 目标使用质量浓度 [%] / target working concentration
    rTankVolL : REAL; // 配液罐有效容积 [L] / dilution tank working volume
END_VAR
VAR_OUTPUT
    rRatio : REAL; // 稀释比 = 目标浓度/母液浓度 [L母液/L配液] / dilution ratio, stock litres per litre of batch
    rStockVolL : REAL; // 需投母液体积 [L] / required stock volume
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=母液浓度非法 2=目标浓度高于母液已按 1:1 饱和 3=结果非有限 / event code
END_VAR
VAR
    rRatioUse : REAL; // 实际使用稀释比（含饱和修正）[L/L] / dilution ratio actually applied
END_VAR

    // —— 段 0：全路径预清 —— //
    rRatioUse := 0.0;
    rRatio := 0.0;
    rStockVolL := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_FlocDilutionRatio := FALSE;
    // —— 段 1：分母闸（母液浓度） —— //
    IF ABS(rStockPct) <= 1.0E-9 THEN
        iErrCode := 1; // 母液浓度非法，稀释比无定义 / bad stock concentration, ratio undefined
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (%),(%) 同量纲相除得无量纲比 [L母液/L配液] —— //
    rRatioUse := rTargetPct / rStockPct; // 稀释比 [-] / raw dilution ratio
    // —— 段 3：目标浓度不得高于母液（无法靠稀释提浓），按 1:1 饱和 —— //
    IF rTargetPct > rStockPct THEN
        rRatioUse := 1.0; // 饱和为纯母液 / saturate to neat stock
        iErrCode := 2; // 信息级：目标浓度超母液，已按 1:1 处理 / info: target above stock, clamped to 1:1
    END_IF;
    IF rRatioUse < 0.0 THEN
        rRatioUse := 0.0; // 负浓度输入防御 / negative concentration guard
    END_IF;
    rRatio := rRatioUse;
    // —— 段 4：配液体积换算与结果域闸 —— //
    rStockVolL := rTankVolL * rRatio; // 需母液体积 [L] / required stock volume
    IF (ABS(rStockVolL) > 1.0E15) OR (ABS(rRatio) > 1.0E15) THEN
        rStockVolL := 0.0;
        rRatio := 0.0;
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    bValid := TRUE;
    FC_DL_FlocDilutionRatio := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_SettleVelocityCalc
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: Stokes 自由沉降末速度，含雷诺数域校验（Re>2 判为超出 Stokes 层流域）
*)
FUNCTION FC_DL_SettleVelocityCalc : BOOL
VAR_INPUT
    rDpUm : REAL; // 颗粒粒径 [µm] / particle diameter in micrometre
    rRhoP : REAL; // 颗粒密度 [kg/m3] / particle density
    rRhoF : REAL; // 流体密度 [kg/m3] / fluid density
    rMuPas : REAL; // 流体动力黏度 [mPa·s] / dynamic viscosity in mPa·s
END_VAR
VAR_OUTPUT
    rVsMmS : REAL; // 沉降末速度 [mm/s] / terminal settling velocity
    bValid : BOOL; // 结果有效位（超出 Stokes 域时置 FALSE）[-] / valid flag, FALSE when outside Stokes regime
    iErrCode : INT; // 事件码 0=正常 1=黏度非法 2=密度差不正（按 0 处理）3=Re 超域 4=结果非有限 / event code
END_VAR
VAR CONSTANT
    rGravity : REAL := 9.80665; // 标准重力加速度 [m/s2] / standard gravity
    rUmToM : REAL := 1.0E-6; // 微米转米系数 [m/µm] / micrometre to metre factor
    rMpasToPas : REAL := 1.0E-3; // 毫帕秒转帕秒系数 [Pa·s/(mPa·s)] / mPa·s to Pa·s factor
    rStokesCoef : REAL := 18.0; // Stokes 阻力式系数（无量纲）[-] / Stokes drag coefficient
    rReLimit : REAL := 2.0; // Stokes 层流域上界雷诺数 [-] / upper Reynolds number of Stokes regime
END_VAR
VAR
    rDm : REAL; // 颗粒粒径 [m] / particle diameter in metre
    rMuPas2 : REAL; // 动力黏度 [Pa·s] / dynamic viscosity in Pa·s
    rVsMs : REAL; // 沉降末速度 [m/s] / terminal velocity in m/s
    rRe : REAL; // 颗粒雷诺数 [-] / particle Reynolds number
END_VAR

    // —— 段 0：全路径预清 —— //
    rDm := 0.0;
    rMuPas2 := 0.0;
    rVsMs := 0.0;
    rRe := 0.0;
    rVsMmS := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_SettleVelocityCalc := FALSE;
    // —— 段 1：分母闸（黏度）与单位归一到 SI —— //
    IF rMuPas <= 0.0 THEN
        iErrCode := 1; // 黏度非正，Stokes 式无定义 / non-positive viscosity, Stokes law undefined
        RETURN;
    END_IF;
    rMuPas2 := rMuPas * rMpasToPas; // [mPa·s] -> [Pa·s] / viscosity to SI
    rDm := rDpUm * rUmToM; // [µm] -> [m] / diameter to SI
    // —— 段 2：不上浮判据（固相密度不大于液相时按零速处理） —— //
    IF rRhoP <= rRhoF THEN
        rVsMmS := 0.0;
        iErrCode := 2; // 密度差不正，颗粒不沉降 / non-positive density difference, no settling
        RETURN;
    END_IF;
    // —— 段 3：量纲链 (m/s2)*(m2)*(kg/m3)/(Pa·s) = m/s —— //
    rVsMs := rGravity * rDm * rDm * (rRhoP - rRhoF) / (rStokesCoef * rMuPas2); // 末速度 [m/s] / terminal velocity
    IF ABS(rVsMs) > 1.0E15 THEN
        rVsMs := 0.0;
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    // —— 段 4：Re 校验（d*v*rhoF/mu），超 2 即离开 Stokes 层流域 —— //
    rRe := rDm * rVsMs * rRhoF / rMuPas2; // 雷诺数 [-] / particle Reynolds number
    rVsMmS := rVsMs * 1000.0; // [m/s] -> [mm/s] / velocity to mm/s
    IF rRe > rReLimit THEN
        iErrCode := 3; // 超出 Stokes 域，给值但标无效 / outside Stokes regime, value kept but flagged
        bValid := FALSE;
        FC_DL_SettleVelocityCalc := FALSE;
        RETURN;
    END_IF;
    bValid := TRUE;
    FC_DL_SettleVelocityCalc := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_SludgeBlanketLevel
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 双压力变送器静压差法反算污泥界面（泥位）高度，含密度差可测性与量程限幅
*)
FUNCTION FC_DL_SludgeBlanketLevel : BOOL
VAR_INPUT
    rP1Bar : REAL; // 上取压点压力 [bar] / upper tap pressure in bar
    rP2Bar : REAL; // 下取压点压力 [bar] / lower tap pressure in bar
    rRhoSludge : REAL; // 污泥混合液密度 [kg/m3] / sludge mixture density
    rRhoWater : REAL; // 上清液密度 [kg/m3] / supernatant density
    rSpanM : REAL; // 取压点间距（量程）[m] / tap spacing, i.e. measuring span
END_VAR
VAR_OUTPUT
    rLevelM : REAL; // 泥位高度（自下取压点起）[m] / sludge blanket level above lower tap
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=密度差过小不可测 2=量程非法 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rBarToPa : REAL := 1.0E5; // 巴转帕系数 [Pa/bar] / bar to pascal factor
    rGravity : REAL := 9.80665; // 标准重力加速度 [m/s2] / standard gravity
    rRhoDiffMin : REAL := 1.0; // 密度差可测下限 [kg/m3] / minimum measurable density difference
END_VAR
VAR
    rDpPa : REAL; // 压差 [Pa] / differential pressure in pascal
    rRhoDiff : REAL; // 有效密度差 [kg/m3] / effective density difference
    rLevelRaw : REAL; // 未限幅泥位 [m] / unlimited level
END_VAR

    // —— 段 0：全路径预清 —— //
    rDpPa := 0.0;
    rRhoDiff := 0.0;
    rLevelRaw := 0.0;
    rLevelM := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_SludgeBlanketLevel := FALSE;
    // —— 段 1：量程闸 —— //
    IF rSpanM <= 0.0 THEN
        iErrCode := 2; // 量程非法，无物理意义 / invalid span, unphysical
        RETURN;
    END_IF;
    // —— 段 2：密度差可测性闸（分母闸） —— //
    rRhoDiff := rRhoSludge - rRhoWater; // 有效密度差 [kg/m3] / effective density difference
    IF ABS(rRhoDiff) < rRhoDiffMin THEN
        iErrCode := 1; // 密度差过小，压差法不可测 / density difference too small to resolve
        RETURN;
    END_IF;
    // —— 段 3：量纲链 (bar)*(Pa/bar) = Pa；(Pa)/((kg/m3)*(m/s2)) = m —— //
    rDpPa := (rP2Bar - rP1Bar) * rBarToPa; // 压差 [Pa] / differential pressure
    rLevelRaw := rDpPa / (rRhoDiff * rGravity); // 泥位 [m] / blanket level
    IF ABS(rLevelRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    // —— 段 4：限幅 [0, rSpanM] —— //
    IF rLevelRaw < 0.0 THEN
        rLevelM := 0.0; // 负泥位无意义（取压反接或空池）/ negative level meaningless, clamp to zero
    ELSIF rLevelRaw > rSpanM THEN
        rLevelM := rSpanM; // 超量程饱和到取压间距 / saturate at tap spacing
    ELSE
        rLevelM := rLevelRaw;
    END_IF;
    bValid := TRUE;
    FC_DL_SludgeBlanketLevel := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_ClarifierSurfaceLoad
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 沉淀池表面水力负荷计算与上限越限判定
*)
FUNCTION FC_DL_ClarifierSurfaceLoad : BOOL
VAR_INPUT
    rFlowM3h : REAL; // 进水流量 [m3/h] / influent flow
    rAreaM2 : REAL; // 沉淀池有效沉淀面积 [m2] / effective settling area
    rLimitM3m2h : REAL; // 表面负荷设计上限 [m3/(m2·h)] / design surface loading limit
END_VAR
VAR_OUTPUT
    rLoadM3m2h : REAL; // 表面水力负荷 [m3/(m2·h)] / surface hydraulic loading
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bOver : BOOL; // 越限标志（负荷高于设计上限）[-] / over-limit flag
    iErrCode : INT; // 事件码 0=正常 1=面积非法 2=结果非有限 / event code
END_VAR
VAR
    rLoadRaw : REAL; // 未限幅负荷 [m3/(m2·h)] / unlimited loading
END_VAR

    // —— 段 0：全路径预清 —— //
    rLoadRaw := 0.0;
    rLoadM3m2h := 0.0;
    bValid := FALSE;
    bOver := FALSE;
    iErrCode := 0;
    FC_DL_ClarifierSurfaceLoad := FALSE;
    // —— 段 1：分母闸（沉淀面积必须为正） —— //
    IF rAreaM2 <= 0.0 THEN
        iErrCode := 1; // 面积非法，负荷无定义 / invalid area, loading undefined
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (m3/h)/(m2) = m3/(m2·h) —— //
    rLoadRaw := rFlowM3h / rAreaM2; // 表面负荷 [m3/(m2·h)] / surface loading
    // —— 段 3：结果域闸（非有限即归零作废） —— //
    IF ABS(rLoadRaw) > 1.0E15 THEN
        iErrCode := 2; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    // —— 段 4：负流量防御与出参收口 —— //
    IF rLoadRaw < 0.0 THEN
        rLoadM3m2h := 0.0; // 负流量无物理意义 / negative flow is unphysical
    ELSE
        rLoadM3m2h := rLoadRaw;
    END_IF;
    bOver := rLoadM3m2h > rLimitM3m2h; // 越限判定 [-] / over-limit test
    bValid := TRUE;
    FC_DL_ClarifierSurfaceLoad := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_SviCalc
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 污泥容积指数 SVI 计算（30 min 沉降体积法），含合理域告警与上限饱和
*)
FUNCTION FC_DL_SviCalc : BOOL
VAR_INPUT
    rSettledVolMl : REAL; // 30 min 沉降污泥体积（每升混合液）[mL/L] / settled sludge volume per litre
    rMlssMgL : REAL; // 混合液悬浮固体浓度 [mg/L] / mixed liquor suspended solids
END_VAR
VAR_OUTPUT
    rSviMlg : REAL; // 污泥容积指数 [mL/g] / sludge volume index
    bValid : BOOL; // 结果有效位（合理域外仅告警，仍为 TRUE）[-] / valid flag, TRUE even when out of the typical band
    iErrCode : INT; // 事件码 0=正常 1=MLSS 非法 2=超合理域告警（40~500）3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rMlToL : REAL := 0.001; // 毫升转升系数 [L/mL] / millilitre to litre factor
    rMgToG : REAL := 0.001; // 毫克转克系数 [g/mg] / milligram to gram factor
    rSviLo : REAL := 40.0; // SVI 合理域下限 [mL/g] / lower bound of typical SVI band
    rSviHi : REAL := 500.0; // SVI 合理域上限 [mL/g] / upper bound of typical SVI band
    rSviCap : REAL := 999.0; // SVI 输出饱和上限 [mL/g] / output saturation cap
END_VAR
VAR
    rVolMl : REAL; // 沉降体积（负值已钳零）[mL/L] / settled volume clamped at zero
    rSviRaw : REAL; // 未限幅 SVI [mL/g] / unlimited SVI
END_VAR

    // —— 段 0：全路径预清 —— //
    rVolMl := 0.0;
    rSviRaw := 0.0;
    rSviMlg := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_SviCalc := FALSE;
    // —— 段 1：分母闸（MLSS 必须为正） —— //
    IF rMlssMgL <= 0.0 THEN
        iErrCode := 1; // MLSS 非法，SVI 无定义 / invalid MLSS, SVI undefined
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (mL/L)*(L/mL) /( (mg/L)*(g/mg) ) = (g/L)/(g/L) = mL/g —— //
    IF rSettledVolMl > 0.0 THEN
        rVolMl := rSettledVolMl; // 取输入正值 / take positive input
    END_IF;
    rSviRaw := rVolMl * rMlToL / (rMlssMgL * rMgToG); // SVI [mL/g] / sludge volume index
    // —— 段 3：结果域闸与上限饱和 —— //
    IF ABS(rSviRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rSviRaw > rSviCap THEN
        rSviMlg := rSviCap; // 超 999 饱和（工程上已属膨胀污泥）/ saturate at the cap
    ELSE
        rSviMlg := rSviRaw;
    END_IF;
    // —— 段 4：合理域告警（仅信息级，不影响有效位） —— //
    IF (rSviRaw < rSviLo) OR (rSviRaw > rSviHi) THEN
        iErrCode := 2; // 信息级：超出 40~500 正常带，检查污泥性状 / info: outside typical band, check sludge condition
    END_IF;
    bValid := TRUE;
    FC_DL_SviCalc := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_NtuCoagDoseAdj
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 沉后浊度偏差比例微调混凝投加基准，单次步长与总量双限幅
*)
FUNCTION FC_DL_NtuCoagDoseAdj : BOOL
VAR_INPUT
    rNtuOut : REAL; // 沉后实测浊度 [NTU] / measured settled water turbidity
    rNtuSp : REAL; // 沉后浊度设定值 [NTU] / turbidity setpoint
    rDoseBase : REAL; // 前馈投加基准 [L/h] / feed-forward base dose
    rKp : REAL; // 比例增益 [(L/h)/NTU] / proportional gain
    rStepMax : REAL; // 单次修正步长上限 [L/h] / maximum single-step correction
END_VAR
VAR_OUTPUT
    rDoseOut : REAL; // 修正后投加量 [L/h] / corrected dose
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=步长上限非法 2=基准投加为负 3=结果非有限 / event code
END_VAR
VAR
    rErr : REAL; // 浊度偏差 实测-设定 [NTU] / turbidity error
    rDelta : REAL; // 比例修正量 [L/h] / proportional correction
    rDoseRaw : REAL; // 未限幅投加量 [L/h] / unlimited dose
    rDoseHi : REAL; // 总量上限 = 2×基准 [L/h] / total upper limit, twice the base
END_VAR

    // —— 段 0：全路径预清 —— //
    rErr := 0.0;
    rDelta := 0.0;
    rDoseRaw := 0.0;
    rDoseHi := 0.0;
    rDoseOut := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_NtuCoagDoseAdj := FALSE;
    // —— 段 1：步长上限闸（限幅基准不可为零） —— //
    IF rStepMax <= 0.0 THEN
        iErrCode := 1; // 步长上限非法，无法限幅 / invalid step limit, clamping impossible
        RETURN;
    END_IF;
    // —— 段 2：基准投加合法性（负基准无物理意义） —— //
    IF rDoseBase < 0.0 THEN
        iErrCode := 2; // 基准投加为负，拒绝修正 / negative base dose rejected
        RETURN;
    END_IF;
    // —— 段 3：比例修正与步长限幅（量纲 (L/h)/NTU × NTU = L/h） —— //
    rErr := rNtuOut - rNtuSp; // 偏差 [NTU] / error
    rDelta := rKp * rErr; // 比例修正 [L/h] / proportional term
    IF rDelta > rStepMax THEN
        rDelta := rStepMax; // 正向步长饱和 / saturate positive step
    ELSIF rDelta < -rStepMax THEN
        rDelta := -rStepMax; // 负向步长饱和 / saturate negative step
    END_IF;
    rDoseRaw := rDoseBase + rDelta; // 修正后投加 [L/h] / corrected dose
    // —— 段 4：总量双限幅 [0, 2×基准] 与结果域闸 —— //
    rDoseHi := rDoseBase + rDoseBase; // 总量上限 [L/h] / total upper limit
    IF ABS(rDoseRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rDoseRaw < 0.0 THEN
        rDoseOut := 0.0; // 下限零 / floor at zero
    ELSIF rDoseRaw > rDoseHi THEN
        rDoseOut := rDoseHi; // 上限 2×基准 / ceiling at twice the base
    ELSE
        rDoseOut := rDoseRaw;
    END_IF;
    bValid := TRUE;
    FC_DL_NtuCoagDoseAdj := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_LamellaAreaCalc
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 斜板（斜管）沉淀区投影面积计算，按颗粒沉降速度与板倾角余弦折算并加余量系数
*)
FUNCTION FC_DL_LamellaAreaCalc : BOOL
VAR_INPUT
    rFlowM3h : REAL; // 处理水量 [m3/h] / treated water flow
    rVsMmS : REAL; // 设计颗粒沉降速度 [mm/s] / design particle settling velocity
    rCosTheta : REAL; // 板面与水平面夹角的余弦 [-]，如 60° ≈ 0.5 / cosine of plate inclination
    rAreaSafety : REAL; // 面积余量系数 [-]，典型 1.2~1.5 / area safety factor, typically 1.2~1.5
END_VAR
VAR_OUTPUT
    rAreaM2 : REAL; // 所需斜板投影面积 [m2] / required projected plate area
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=沉降速度非法 2=倾角过大 3=余量系数非法 4=结果非有限 / event code
END_VAR
VAR CONSTANT
    rSecPerHour : REAL := 3600.0; // 每小时秒数 [s/h] / seconds per hour
    rMmToM : REAL := 0.001; // 毫米转米系数 [m/mm] / millimetre to metre factor
    rCosMin : REAL := 0.1; // 可用余弦下限（倾角过大判据）[-] / minimum usable cosine
    rCosMax : REAL := 1.0; // 余弦物理上限（水平板）[-] / physical ceiling of cosine
END_VAR
VAR
    rFlowM3s : REAL; // 处理水量 [m3/s] / flow in cubic metres per second
    rVsMs : REAL; // 沉降速度 [m/s] / settling velocity in m/s
    rCosUse : REAL; // 生效余弦（上限已钳）[-] / effective cosine, capped at one
    rAreaRaw : REAL; // 未限幅面积 [m2] / unlimited area
END_VAR

    // —— 段 0：全路径预清 —— //
    rFlowM3s := 0.0;
    rVsMs := 0.0;
    rCosUse := 0.0;
    rAreaRaw := 0.0;
    rAreaM2 := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_LamellaAreaCalc := FALSE;
    // —— 段 1：分母闸（沉降速度必须为正） —— //
    IF rVsMmS <= 0.0 THEN
        iErrCode := 1; // 沉降速度非正，面积无定义 / non-positive settling velocity, area undefined
        RETURN;
    END_IF;
    IF rCosTheta <= rCosMin THEN
        iErrCode := 2; // 倾角过大（余弦过小），斜板失效 / inclination too steep, plates ineffective
        RETURN;
    END_IF;
    IF rAreaSafety <= 0.0 THEN
        iErrCode := 3; // 余量系数非法 / invalid safety factor
        RETURN;
    END_IF;
    // —— 段 2：单位归一 [m3/h]->[m3/s]、[mm/s]->[m/s] —— //
    rFlowM3s := rFlowM3h / rSecPerHour; // 水量 [m3/s] / flow in m3/s
    rVsMs := rVsMmS * rMmToM; // 沉速 [m/s] / velocity in m/s
    // —— 段 3：余弦物理上限钳位（cos 不得大于 1） —— //
    IF rCosTheta > rCosMax THEN
        rCosUse := rCosMax; // 超 1 视为水平板 / clamp to horizontal plate
    ELSE
        rCosUse := rCosTheta;
    END_IF;
    // —— 段 4：量纲链 (m3/s)/((m/s)*(-)) = m2 —— //
    rAreaRaw := rFlowM3s / (rVsMs * rCosUse) * rAreaSafety; // 斜板面积 [m2] / lamella area
    IF ABS(rAreaRaw) > 1.0E15 THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rAreaRaw < 0.0 THEN
        rAreaM2 := 0.0; // 负流量防御 / negative flow guard
    ELSE
        rAreaM2 := rAreaRaw;
    END_IF;
    bValid := TRUE;
    FC_DL_LamellaAreaCalc := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_ScrewPressThroughput
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 螺旋压榨机干固体（DS）处理量换算：小时量与按日运行小时数折算的日总量
*)
FUNCTION FC_DL_ScrewPressThroughput : BOOL
VAR_INPUT
    rFlowM3h : REAL; // 进泥体积流量 [m3/h] / sludge feed flow
    rTsPct : REAL; // 进泥含固率 [%] / feed total solids content
    rRunHours : REAL; // 日运行小时数 [h/d] / daily running hours
END_VAR
VAR_OUTPUT
    rDsKgH : REAL; // 干固体小时处理量 [kg/h] / dry solids throughput per hour
    rDsKgDay : REAL; // 干固体日处理量 [kg/d] / dry solids throughput per day
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=含固率超域 2=运行小时超域 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rRhoSludge : REAL := 1000.0; // 污泥近似密度 [kg/m3] / approximate sludge density
    rPctToFrac : REAL := 0.01; // 百分数转小数系数 [-]/[%] / percent to fraction factor
    rHourPerDay : REAL := 24.0; // 每日小时数 [h/d] / hours per day
END_VAR
VAR
    rDsRaw : REAL; // 未校验小时量 [kg/h] / unchecked hourly throughput
END_VAR

    // —— 段 0：全路径预清 —— //
    rDsRaw := 0.0;
    rDsKgH := 0.0;
    rDsKgDay := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_ScrewPressThroughput := FALSE;
    // —— 段 1：含固率域闸 (0, 100]% —— //
    IF (rTsPct <= 0.0) OR (rTsPct > 100.0) THEN
        iErrCode := 1; // 含固率超域，干固体量无意义 / TS out of domain, dry solids meaningless
        RETURN;
    END_IF;
    // —— 段 2：日运行小时域闸 (0, 24]h —— //
    IF (rRunHours <= 0.0) OR (rRunHours > rHourPerDay) THEN
        iErrCode := 2; // 运行小时超域 / running hours out of domain
        RETURN;
    END_IF;
    // —— 段 3：量纲链 (m3/h)*(kg/m3)*(%)*(0.01) = kg/h —— //
    rDsRaw := rFlowM3h * rRhoSludge * rTsPct * rPctToFrac; // 干固体量 [kg/h] / dry solids per hour
    IF ABS(rDsRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rDsRaw < 0.0 THEN
        rDsKgH := 0.0; // 负流量防御 / negative flow guard
    ELSE
        rDsKgH := rDsRaw;
    END_IF;
    // —— 段 4：日总量 = 小时量 × 日运行小时（量纲 kg/h × h/d = kg/d） —— //
    rDsKgDay := rDsKgH * rRunHours; // 日处理量 [kg/d] / dry solids per day
    bValid := TRUE;
    FC_DL_ScrewPressThroughput := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_CakeSolidsCalc
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 由进泥与出泥体积做干固体质量平衡，反算泥饼含固率与固体回收率（同密度近似）
*)
FUNCTION FC_DL_CakeSolidsCalc : BOOL
VAR_INPUT
    rFeedTsPct : REAL; // 进泥含固率 [%] / feed total solids
    rFeedM3h : REAL; // 进泥体积流量 [m3/h] / feed flow
    rCakeM3h : REAL; // 出泥饼体积流量 [m3/h] / cake flow
    rFiltrateTsPct : REAL; // 滤液含固率 [%]，固体损失实测 / filtrate solids, measured loss
END_VAR
VAR_OUTPUT
    rCakeTsPct : REAL; // 泥饼含固率 [%] / cake total solids
    rRecoveryPct : REAL; // 固体回收率 [%] / solids recovery
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=泥饼流量非法 2=体积不守恒 3=进泥流量非法 4=进泥含固率非法 5=结果非有限 / event code
END_VAR
VAR CONSTANT
    rRecoveryCap : REAL := 100.0; // 回收率饱和上限 [%] / recovery saturation cap
END_VAR
VAR
    rCakeTsRaw : REAL; // 未限幅泥饼含固率 [%] / unlimited cake solids
    rFeedSolid : REAL; // 进泥固体负荷 [%·m3/h] / feed solids product
    rCakeSolid : REAL; // 泥饼固体负荷 [%·m3/h] / cake solids product
    rRecoveryRaw : REAL; // 未限幅回收率 [%] / unlimited recovery
    rLossSolid : REAL; // 滤液固体损失 [%·m3/h] / filtrate solids loss
END_VAR

    // —— 段 0：全路径预清 —— //
    rCakeTsRaw := 0.0;
    rFeedSolid := 0.0;
    rCakeSolid := 0.0;
    rRecoveryRaw := 0.0;
    rCakeTsPct := 0.0;
    rRecoveryPct := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_CakeSolidsCalc := FALSE;
    // —— 段 1：分母闸（泥饼体积、进泥体积） —— //
    IF rCakeM3h <= 0.0 THEN
        iErrCode := 1; // 泥饼流量非法，含固率无定义 / invalid cake flow, cake solids undefined
        RETURN;
    END_IF;
    IF rFeedM3h <= 0.0 THEN
        iErrCode := 3; // 进泥流量非法 / invalid feed flow
        RETURN;
    END_IF;
    // —— 段 2：体积守恒预检（出泥体积不得大于进泥体积） —— //
    IF rCakeM3h > rFeedM3h THEN
        iErrCode := 2; // 体积不守恒，物料平衡失效 / volume not conserved, balance invalid
        RETURN;
    END_IF;
    // —— 段 3：量纲链 (%·m3/h)/(m3/h) = %（同密度近似消去 kg/m3） —— //
    rCakeTsRaw := rFeedTsPct * rFeedM3h / rCakeM3h; // 泥饼含固率 [%] / cake total solids
    IF ABS(rCakeTsRaw) > 1.0E15 THEN
        iErrCode := 5; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rCakeTsPct := rCakeTsRaw;
    // —— 段 4：固体回收率（分母闸：进泥含固率必须为正） —— //
    IF rFeedTsPct <= 0.0 THEN
        iErrCode := 4; // 进泥含固率非法，回收率置零 / invalid feed solids, recovery set to zero
        bValid := TRUE;
        FC_DL_CakeSolidsCalc := TRUE;
        RETURN;
    END_IF;
    rFeedSolid := rFeedTsPct * rFeedM3h; // 进泥固体负荷 [%·m3/h] / feed solids product
    IF rFiltrateTsPct < 0.0 THEN
        rFiltrateTsPct := 0.0; // 负含固率防御 / negative solids guard
    END_IF
    rCakeSolid := rCakeTsPct * rCakeM3h; // 泥饼固体负荷 [%·m3/h] / cake solids product
    // 原式 cakeSolid/feedSolid 恒等于 1（cakeTs 由平衡反算），改为按滤液固体损失实测：
    // 量纲: (m3/h)*(%) / ((m3/h)*(%)) = 无量纲，乘 100 得 %
    rLossSolid := rFiltrateTsPct * (rFeedM3h - rCakeM3h); // 滤液带走固体 [%·m3/h] / solids lost with filtrate
    rRecoveryRaw := (rFeedSolid - rLossSolid) / rFeedSolid * 100.0; // 回收率 [%] / recovery by loss
    IF rRecoveryRaw > rRecoveryCap THEN
        rRecoveryPct := rRecoveryCap; // 超 100% 饱和（仪表误差口径）/ saturate at 100 percent
    ELSIF rRecoveryRaw < 0.0 THEN
        rRecoveryPct := 0.0; // 负值防御 / negative guard
    ELSE
        rRecoveryPct := rRecoveryRaw;
    END_IF;
    bValid := TRUE;
    FC_DL_CakeSolidsCalc := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_PolymerDoseCalc
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: PAM 絮凝剂按干固体单耗折算质量投加量与母液体积投加量
  近似说明: 母液按「1 kg 溶液 ≈ 1 L」折算（浓度 ≤1% 时误差 <1%），已在公式处声明
*)
FUNCTION FC_DL_PolymerDoseCalc : BOOL
VAR_INPUT
    rDsKgH : REAL; // 干固体处理量 [kg/h] / dry solids throughput
    rDoseKgT : REAL; // PAM 单耗（每吨干固体）[kg/t] / polymer dose per tonne of dry solids
    rStockPct : REAL; // 母液配制浓度 [%] / stock solution concentration
END_VAR
VAR_OUTPUT
    rPolyKgH : REAL; // PAM 纯质投加量 [kg/h] / neat polymer mass flow
    rPolyLh : REAL; // PAM 母液体积投加量 [L/h] / stock solution volumetric flow
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=母液浓度超域 2=单耗为负 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rKgPerT : REAL := 1000.0; // 每吨公斤数 [kg/t] / kilograms per tonne
    rPctToFrac : REAL := 0.01; // 百分数转小数系数 [-]/[%] / percent to fraction factor
END_VAR
VAR
    rDsTh : REAL; // 干固体处理量 [t/h] / dry solids in tonnes per hour
    rPolyRaw : REAL; // 未限幅纯质投加 [kg/h] / unchecked neat polymer flow
    rStockFrac : REAL; // 母液质量分数 [-] / stock mass fraction
END_VAR

    // —— 段 0：全路径预清 —— //
    rDsTh := 0.0;
    rPolyRaw := 0.0;
    rStockFrac := 0.0;
    rPolyKgH := 0.0;
    rPolyLh := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_PolymerDoseCalc := FALSE;
    // —— 段 1：母液浓度域闸 (0, 100]% 兼分母闸 —— //
    IF (rStockPct <= 0.0) OR (rStockPct > 100.0) THEN
        iErrCode := 1; // 母液浓度超域，体积流量无定义 / stock concentration out of domain
        RETURN;
    END_IF;
    IF rDoseKgT < 0.0 THEN
        iErrCode := 2; // 单耗为负，拒绝换算 / negative dose rejected
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (kg/h)/(kg/t) = t/h；(t/h)*(kg/t) = kg/h —— //
    rDsTh := rDsKgH / rKgPerT; // 干固体 [t/h] / dry solids in t/h
    rPolyRaw := rDsTh * rDoseKgT; // 纯质 PAM [kg/h] / neat polymer flow
    IF ABS(rPolyRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rPolyRaw < 0.0 THEN
        rPolyKgH := 0.0; // 负干固体防御 / negative dry solids guard
    ELSE
        rPolyKgH := rPolyRaw;
    END_IF;
    // —— 段 3：母液体积 = 纯质量 / 质量分数（1 kg 溶液 ≈ 1 L 近似） —— //
    rStockFrac := rStockPct * rPctToFrac; // 质量分数 [-] / stock mass fraction
    rPolyLh := rPolyKgH / rStockFrac; // 母液体积 [L/h] / stock volumetric flow
    IF ABS(rPolyLh) > 1.0E15 THEN
        rPolyLh := 0.0;
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    bValid := TRUE;
    FC_DL_PolymerDoseCalc := TRUE;
END_FUNCTION

(*
