  许可证: 本项目自有 (MIT)
  功能: 离心液（分离液）浊度相对基线指数与跑料（携带固体）判定
*)
FUNCTION FC_DL_CentrateTurbidityIdx : BOOL
VAR_INPUT
    rNtuNow : REAL; // 当前离心液浊度 [NTU] / current centrate turbidity
    rNtuBase : REAL; // 清洁运行基线浊度 [NTU] / clean-operation baseline turbidity
    rNtuLimit : REAL; // 跑料报警浊度门槛 [NTU] / carry-over alarm threshold
END_VAR
VAR_OUTPUT
    rIdx : REAL; // 浊度指数 = 当前/基线 [-]，1.0 = 与基线持平 / turbidity index, 1.0 equals baseline
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bCarryOver : BOOL; // 跑料标志（浊度超门槛）[-] / solids carry-over flag
    iErrCode : INT; // 事件码 0=正常 1=基线浊度非法 2=指数超可观测上限 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rIdxCap : REAL := 1000.0; // 指数输出饱和上限 [-] / index saturation cap
END_VAR
VAR
    rIdxRaw : REAL; // 未限幅指数 [-] / unlimited index
END_VAR

    // —— 段 0：全路径预清 —— //
    rIdxRaw := 0.0;
    rIdx := 0.0;
    bValid := FALSE;
    bCarryOver := FALSE;
    iErrCode := 0;
    FC_DL_CentrateTurbidityIdx := FALSE;
    // —— 段 1：分母闸（基线浊度，清洗后近零会导致指数爆炸） —— //
    IF rNtuBase <= 0.0 THEN
        iErrCode := 1; // 基线浊度非法，指数无定义 / invalid baseline, index undefined
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (NTU)/(NTU) = 无量纲指数 —— //
    rIdxRaw := rNtuNow / rNtuBase; // 浊度指数 [-] / turbidity index
    // —— 段 3：结果域闸、负值防御与饱和 —— //
    IF ABS(rIdxRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rIdxRaw < 0.0 THEN
        rIdx := 0.0; // 负浊度不可能，钳零 / negative turbidity impossible
    ELSIF rIdxRaw > rIdxCap THEN
        rIdx := rIdxCap; // 超可观测上限饱和 / saturate at observable cap
        iErrCode := 2; // 信息级：指数超上限，基线可能失效 / info: index capped, baseline suspect
    ELSE
        rIdx := rIdxRaw;
    END_IF;
    // —— 段 4：跑料判定（比较用原始浊度，不用饱和后的指数） —— //
    bCarryOver := rNtuNow > rNtuLimit; // 跑料标志 [-] / carry-over flag
    bValid := TRUE;
    FC_DL_CentrateTurbidityIdx := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_FiltrateRecycleRatio
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 滤液回流比计算与随滤液返回的固体负荷核算，回流过高告警
*)
FUNCTION FC_DL_FiltrateRecycleRatio : BOOL
VAR_INPUT
    rFiltrateM3h : REAL; // 滤液回流流量 [m3/h] / filtrate recycle flow
    rFeedM3h : REAL; // 进泥（进料）流量 [m3/h] / feed flow
    rFiltrateTsPct : REAL; // 滤液含固率 [%] / filtrate total solids
END_VAR
VAR_OUTPUT
    rRatio : REAL; // 回流比 = 滤液/进料 [-]，无量纲 / recycle ratio, dimensionless
    rSolidRecycleKgH : REAL; // 随滤液返回的固体负荷 [kg/h] / solids returned with filtrate
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=进料流量非法 2=回流比过高（>0.5）3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rRhoLiquid : REAL := 1000.0; // 液相近似密度 [kg/m3] / approximate liquid density
    rPctToFrac : REAL := 0.01; // 百分数转小数系数 [-]/[%] / percent to fraction factor
    rRatioHi : REAL := 0.5; // 回流比告警上限 [-] / recycle ratio alarm limit
END_VAR
VAR
    rRatioRaw : REAL; // 未限幅回流比 [-] / unlimited recycle ratio
    rTsFrac : REAL; // 滤液含固质量分数 [-] / filtrate solids mass fraction
END_VAR

    // —— 段 0：全路径预清 —— //
    rRatioRaw := 0.0;
    rTsFrac := 0.0;
    rRatio := 0.0;
    rSolidRecycleKgH := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_FiltrateRecycleRatio := FALSE;
    // —— 段 1：分母闸（进料流量） —— //
    IF rFeedM3h <= 0.0 THEN
        iErrCode := 1; // 进料流量非法，回流比无定义 / invalid feed flow, ratio undefined
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (m3/h)/(m3/h) = 无量纲 —— //
    rRatioRaw := rFiltrateM3h / rFeedM3h; // 回流比 [-] / recycle ratio
    IF ABS(rRatioRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rRatioRaw < 0.0 THEN
        rRatio := 0.0; // 负流量防御 / negative flow guard
    ELSE
        rRatio := rRatioRaw;
    END_IF;
    // —— 段 3：回流比过高告警（信息级，数值照给） —— //
    IF rRatio > rRatioHi THEN
        iErrCode := 2; // 信息级：回流比过高，注意固体累积 / info: recycle too high, solids build-up risk
    END_IF;
    // —— 段 4：量纲链 (m3/h)*(kg/m3)*(%)*(0.01) = kg/h —— //
    rTsFrac := rFiltrateTsPct * rPctToFrac; // 质量分数 [-] / mass fraction
    IF rTsFrac < 0.0 THEN
        rTsFrac := 0.0; // 负含固率防御 / negative solids guard
    END_IF;
    rSolidRecycleKgH := rFiltrateM3h * rRhoLiquid * rTsFrac; // 返回固体负荷 [kg/h] / returned solids
    IF ABS(rSolidRecycleKgH) > 1.0E15 THEN
        rSolidRecycleKgH := 0.0;
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    bValid := TRUE;
    FC_DL_FiltrateRecycleRatio := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_DewaterMassBalance
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 脱水单元干固体质量平衡：由进泥与泥饼含固率反算泥饼量、滤液量与固体回收率
*)
FUNCTION FC_DL_DewaterMassBalance : BOOL
VAR_INPUT
    rFeedM3h : REAL; // 进泥体积流量 [m3/h] / feed sludge flow
    rFeedTsPct : REAL; // 进泥含固率 [%] / feed total solids
    rCakeTsPct : REAL; // 泥饼含固率 [%] / cake total solids
    rFiltrateTsPct : REAL; // 滤液含固率 [%]，固体损失实测 / filtrate solids, measured loss
END_VAR
VAR_OUTPUT
    rCakeM3h : REAL; // 泥饼体积流量 [m3/h] / cake flow
    rFiltrateM3h : REAL; // 滤液体积流量 [m3/h] / filtrate flow
    rRecoveryPct : REAL; // 固体回收率 [%] / solids recovery
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=泥饼含固率非法或不高於进泥 2=滤液量为负已归零 3=进泥流量非法 4=结果非有限 / event code
END_VAR
VAR CONSTANT
    rRecoveryCap : REAL := 100.0; // 回收率饱和上限 [%] / recovery saturation cap
END_VAR
VAR
    rCakeRaw : REAL; // 未校验泥饼量 [m3/h] / unchecked cake flow
    rFilRaw : REAL; // 未校验滤液量 [m3/h] / unchecked filtrate flow
    rFeedSolid : REAL; // 进泥固体负荷 [%·m3/h] / feed solids product
    rLossSolid : REAL; // 滤液固体损失 [%·m3/h] / filtrate solids loss
END_VAR

    // —— 段 0：全路径预清 —— //
    rCakeRaw := 0.0;
    rFilRaw := 0.0;
    rFeedSolid := 0.0;
    rCakeM3h := 0.0;
    rFiltrateM3h := 0.0;
    rRecoveryPct := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_DewaterMassBalance := FALSE;
    // —— 段 1：分母闸与物理域闸（泥饼含固率必须高于进泥） —— //
    IF (rCakeTsPct <= 0.0) OR (rCakeTsPct <= rFeedTsPct) THEN
        iErrCode := 1; // 泥饼含固率非法或未脱水，平衡失效 / cake solids invalid or no dewatering achieved
        RETURN;
    END_IF;
    IF rFeedM3h <= 0.0 THEN
        iErrCode := 3; // 进泥流量非法 / invalid feed flow
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (%·m3/h)/(%) = m3/h —— //
    rCakeRaw := rFeedM3h * rFeedTsPct / rCakeTsPct; // 泥饼量 [m3/h] / cake flow
    IF ABS(rCakeRaw) > 1.0E15 THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rCakeM3h := rCakeRaw;
    // —— 段 3：滤液量 = 进泥量 - 泥饼量，负值归零并置码 —— //
    rFilRaw := rFeedM3h - rCakeM3h; // 滤液量 [m3/h] / filtrate flow
    IF rFilRaw < 0.0 THEN
        rFiltrateM3h := 0.0;
        iErrCode := 2; // 负滤液量（含固率组合不自洽）已归零 / negative filtrate clamped to zero
    ELSE
        rFiltrateM3h := rFilRaw;
    END_IF;
    // —— 段 4：回收率（分母闸：进泥固体负荷） —— //
    rFeedSolid := rFeedTsPct * rFeedM3h; // 进泥固体负荷 [%·m3/h] / feed solids
    IF ABS(rFeedSolid) <= 1.0E-9 THEN
        rRecoveryPct := 0.0; // 无固体，回收率无定义置零 / no solids, recovery undefined
    ELSE
        // 原式分子为平衡产物，恒等于 100%，改为按滤液损失实测
        IF rFiltrateTsPct < 0.0 THEN
            rFiltrateTsPct := 0.0; // 负含固率防御 / negative solids guard
        END_IF
        rLossSolid := rFiltrateTsPct * rFiltrateM3h; // 滤液带走固体 [%·m3/h] / lost solids
        rRecoveryPct := (rFeedSolid - rLossSolid) / rFeedSolid * 100.0; // 回收率 [%] / recovery by loss
        IF rRecoveryPct > rRecoveryCap THEN
            rRecoveryPct := rRecoveryCap; // 饱和 100% / saturate at 100 percent
        END_IF
    END_IF;
    bValid := TRUE;
    FC_DL_DewaterMassBalance := TRUE;
END_FUNCTION

