    // —— 段 0：全路径预清 —— //
    rAreaM2h := 0.0;
    rLoadRaw := 0.0;
    rLoadKgM2h := 0.0;
    bValid := FALSE;
    bOver := FALSE;
    iErrCode := 0;
    FC_DL_BeltPressLoadRate := FALSE;
    // —— 段 1：分母闸（滤带面积速率 = 宽 × 速 × 60） —— //
    rAreaM2h := rBeltWidthM * rBeltSpeedMmin * rMinPerHour; // 面积速率 [m2/h] / belt area rate
    IF (rBeltWidthM <= 0.0) OR (rAreaM2h <= 0.0) THEN
        iErrCode := 1; // 滤带面积速率非法，比负荷无定义 / invalid belt area rate
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (kg/h)/(m2/h) = kg/(m2·h) —— //
    rLoadRaw := rDsKgH / rAreaM2h; // 比负荷 [kg/(m2·h)] / specific loading
    IF ABS(rLoadRaw) > 1.0E15 THEN
        iErrCode := 2; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    // —— 段 3：负值防御与过载判定 —— //
    IF rLoadRaw < 0.0 THEN
        rLoadKgM2h := 0.0; // 负干固体防御 / negative dry solids guard
    ELSE
        rLoadKgM2h := rLoadRaw;
    END_IF;
    bOver := rLoadKgM2h > rLoadHi; // 过载判定 [-] / overload test
    bValid := TRUE;
    FC_DL_BeltPressLoadRate := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_ScrubberLiquidGasRatio
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 湿式洗涤塔液气比（L/m3）计算、最低液量需求与低液气比告警
*)
FUNCTION FC_DL_ScrubberLiquidGasRatio : BOOL
VAR_INPUT
    rLiquidM3h : REAL; // 循环液流量 [m3/h] / scrubbing liquid flow
    rGasNm3h : REAL; // 标态烟气量 [Nm3/h] / flue gas flow at normal conditions
END_VAR
VAR_OUTPUT
    rLG : REAL; // 液气比 [L/m3] / liquid to gas ratio
    rLiquidNeedM3h : REAL; // 满足最低液气比所需液量 [m3/h] / liquid demand at the minimum ratio
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bLow : BOOL; // 低液气比告警（<2.0 L/m3）[-] / low ratio alarm
    iErrCode : INT; // 事件码 0=正常 1=烟气量非法 2=结果非有限 / event code
END_VAR
VAR CONSTANT
    rM3ToL : REAL := 1000.0; // 立方米转升系数 [L/m3] / cubic metre to litre factor
    rLgMin : REAL := 2.0; // 最低液气比 [L/m3] / minimum liquid to gas ratio
END_VAR
VAR
    rLgRaw : REAL; // 未限幅液气比 [L/m3] / unlimited ratio
    rNeedLh : REAL; // 最低液量需求 [L/h] / liquid demand in L/h
END_VAR

    // —— 段 0：全路径预清 —— //
    rLgRaw := 0.0;
    rNeedLh := 0.0;
    rLG := 0.0;
    rLiquidNeedM3h := 0.0;
    bValid := FALSE;
    bLow := FALSE;
    iErrCode := 0;
    FC_DL_ScrubberLiquidGasRatio := FALSE;
    // —— 段 1：分母闸（烟气量必须为正） —— //
    IF rGasNm3h <= 0.0 THEN
        iErrCode := 1; // 烟气量非法，液气比无定义 / invalid gas flow, ratio undefined
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (m3/h)/(Nm3/h) = 无量纲，×(L/m3) 得 L/m3 —— //
    rLgRaw := rLiquidM3h / rGasNm3h * rM3ToL; // 液气比 [L/m3] / liquid to gas ratio
    IF ABS(rLgRaw) > 1.0E15 THEN
        iErrCode := 2; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rLgRaw < 0.0 THEN
        rLG := 0.0; // 负液量防御 / negative liquid guard
    ELSE
        rLG := rLgRaw;
    END_IF;
    // —— 段 3：最低液量反算（量纲 (L/m3)×(Nm3/h)/(L/m3) = m3/h） —— //
    rNeedLh := rLgMin * rGasNm3h; // 最低液量 [L/h] / minimum liquid in L/h
    rLiquidNeedM3h := rNeedLh / rM3ToL; // 折算 m3/h / back to m3/h
    // —— 段 4：低液气比告警（信息级，数值照给） —— //
    bLow := rLG < rLgMin; // 低液气比标志 [-] / low ratio flag
    bValid := TRUE;
    FC_DL_ScrubberLiquidGasRatio := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_PackedBedHtu
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 填料吸收塔传质单元高度 HTU 与塔高估算（含 1.2 倍设计余量）
  假设声明: 气相摩尔质量按空气口径 29 kg/kmol 折算 kmol/h（低浓度污染物可忽略）
*)
FUNCTION FC_DL_PackedBedHtu : BOOL
VAR_INPUT
    rGasKgH : REAL; // 气相质量流量 [kg/h] / gas mass flow
    rLiquidKgH : REAL; // 液相质量流量 [kg/h] / liquid mass flow
    rKgaKmolM3h : REAL; // 体积总传质系数 Kga [kmol/(m3·h·atm)] / overall volumetric mass transfer coefficient
    rAreaM2 : REAL; // 塔截面积 [m2] / column cross-section area
    rNtu : REAL; // 传质单元数 NTU [-] / number of transfer units
    rPressAtm : REAL; // 操作压力 [atm]，Kga 为 atm 基 / operating pressure, Kga basis
END_VAR
VAR_OUTPUT
    rHtuM : REAL; // 传质单元高度 [m] / height of a transfer unit
    rHeightM : REAL; // 填料层高度（含余量）[m] / packed bed height with margin
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=Kga 非法 2=塔截面非法 3=无液相（填料未润湿）4=NTU 非法 5=结果非有限 / event code
END_VAR
VAR CONSTANT
    rMolWtGas : REAL := 29.0; // 气相平均摩尔质量 [kg/kmol] / mean gas molar mass
    rHeightMargin : REAL := 1.2; // 塔高设计余量系数 [-] / packed height design margin
END_VAR
VAR
    rGasKmolH : REAL; // 气相摩尔流量 [kmol/h] / gas molar flow
    rHtuRaw : REAL; // 未校验 HTU [m] / unchecked HTU
END_VAR

    // —— 段 0：全路径预清 —— //
    rGasKmolH := 0.0;
    rHtuRaw := 0.0;
    rHtuM := 0.0;
    rHeightM := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_PackedBedHtu := FALSE;
    // —— 段 1：分母闸（传质系数、塔截面） —— //
    IF rKgaKmolM3h <= 0.0 THEN
        iErrCode := 1; // 传质系数非法，HTU 无定义 / invalid mass transfer coefficient
        RETURN;
    END_IF;
    IF rAreaM2 <= 0.0 THEN
        iErrCode := 2; // 塔截面非法 / invalid column area
        RETURN;
    END_IF;
    // —— 段 2：液相存在性闸（无液膜则 Kga 不成立） —— //
    IF rLiquidKgH <= 0.0 THEN
        iErrCode := 3; // 无液相，填料未润湿，Kga 无效 / no liquid, packing not wetted, Kga invalid
        RETURN;
    END_IF;
    IF rNtu <= 0.0 THEN
        iErrCode := 4; // NTU 非法，塔高无意义 / invalid NTU
        RETURN;
    END_IF;
    // —— 段 3：量纲链 (kg/h)/(kg/kmol) = kmol/h；/(kmol/(m3·h)·m2) = m —— //
    rGasKmolH := rGasKgH / rMolWtGas; // 气相摩尔流量 [kmol/h] / gas molar flow
    // Kga 以 atm 为基准，故分母必须乘操作压力；漏乘 P 会把 HTU 高估 P 倍
    // 量纲: (kmol/h) / (kmol/(m3·h·atm) × m2 × atm) = m
    rHtuRaw := rGasKmolH / (rKgaKmolM3h * rAreaM2 * rPressAtm); // HTU [m] / height of transfer unit
    IF ABS(rHtuRaw) > 1.0E15 THEN
        iErrCode := 5; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rHtuRaw < 0.0 THEN
        rHtuM := 0.0; // 负流量防御 / negative flow guard
    ELSE
        rHtuM := rHtuRaw;
    END_IF;
    // —— 段 4：塔高 = HTU × NTU × 余量（量纲 m×-×- = m） —— //
    rHeightM := rHtuM * rNtu * rHeightMargin; // 填料层高度 [m] / packed height
    bValid := TRUE;
    FC_DL_PackedBedHtu := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_ReagentConsumeCalc
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 按进出口浓度差与化学计量比折算药剂消耗速率、日耗量与药罐可用天数
*)
FUNCTION FC_DL_ReagentConsumeCalc : BOOL
VAR_INPUT
    rGasNm3h : REAL; // 标态烟气量 [Nm3/h] / flue gas flow at normal conditions
    rInMgNm3 : REAL; // 入口污染物浓度 [mg/Nm3] / inlet pollutant concentration
    rOutMgNm3 : REAL; // 出口污染物浓度 [mg/Nm3] / outlet pollutant concentration
    rStoichRatio : REAL; // 药剂与污染物的质量化学计量比 [kg/kg] / stoichiometric mass ratio
    rTankKg : REAL; // 药罐当前存量 [kg] / reagent inventory in tank
END_VAR
VAR_OUTPUT
    rKgH : REAL; // 药剂小时消耗量 [kg/h] / reagent consumption per hour
    rKgDay : REAL; // 药剂日消耗量 [kg/d] / reagent consumption per day
    rDaysLeft : REAL; // 存量可用天数 [d] / inventory remaining in days
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=药罐存量非法 2=无脱除量无法推算天数 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rMgToKg : REAL := 1.0E-6; // 毫克转公斤系数 [kg/mg] / milligram to kilogram factor
    rHourPerDay : REAL := 24.0; // 每日小时数 [h/d] / hours per day
END_VAR
VAR
    rRemovalMgNm3 : REAL; // 净脱除浓度差 [mg/Nm3] / net removed concentration
    rKgHRaw : REAL; // 未校验小时消耗 [kg/h] / unchecked hourly consumption
END_VAR

    // —— 段 0：全路径预清 —— //
    rRemovalMgNm3 := 0.0;
    rKgHRaw := 0.0;
    rKgH := 0.0;
    rKgDay := 0.0;
    rDaysLeft := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_ReagentConsumeCalc := FALSE;
    // —— 段 1：药罐存量域闸 —— //
    IF rTankKg <= 0.0 THEN
        iErrCode := 1; // 药罐存量非法，可用天数置零 / invalid inventory, days left zeroed
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (mg/Nm3)*(Nm3/h)*(kg/mg) = kg/h；× (kg/kg) 仍为 kg/h —— //
    rRemovalMgNm3 := rInMgNm3 - rOutMgNm3; // 脱除浓度差 [mg/Nm3] / removed concentration
    IF rRemovalMgNm3 < 0.0 THEN
        rRemovalMgNm3 := 0.0; // 出口高于入口（仪表漂移）按零脱除 / outlet above inlet treated as no removal
    END_IF;
    rKgHRaw := rRemovalMgNm3 * rGasNm3h * rMgToKg * rStoichRatio; // 药剂消耗 [kg/h] / reagent consumption
    IF ABS(rKgHRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rKgH := rKgHRaw;
    // —— 段 3：日耗量 = 小时量 × 24（量纲 kg/h × h/d = kg/d） —— //
    rKgDay := rKgH * rHourPerDay; // 日耗量 [kg/d] / daily consumption
    // —— 段 4：可用天数（分母闸：日耗必须为正） —— //
    IF rKgDay <= 1.0E-9 THEN
        iErrCode := 2; // 无脱除量，天数无法推算，置零 / no consumption, days not derivable
        bValid := TRUE;
        FC_DL_ReagentConsumeCalc := TRUE;
        RETURN;
    END_IF;
    rDaysLeft := rTankKg / rKgDay; // 可用天数 [d] / remaining days
    IF ABS(rDaysLeft) > 1.0E15 THEN
        rDaysLeft := 0.0;
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    bValid := TRUE;
    FC_DL_ReagentConsumeCalc := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_CatalystActivityDecay
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 催化剂活性一阶衰减模型：活性、温度加速失活因子与剩余可用寿命 RUL
  模型: k = k0·EXP(Kt·(T-Tref))；act = EXP(-k·t)；RUL = (k·t + LN(1/0.7))/k
*)
FUNCTION FC_DL_CatalystActivityDecay : BOOL
VAR_INPUT
    rDeactBase : REAL; // 基准温度下失活速率常数 [1/h] / base deactivation rate constant
    rHoursRun : REAL; // 累计运行小时数 [h] / accumulated operating hours
    rTempC : REAL; // 实际运行温度 [°C] / actual operating temperature
    rTempRefC : REAL; // 基准温度 [°C] / reference temperature
    rKt : REAL; // 温度加速系数 [1/°C] / temperature acceleration coefficient
END_VAR
VAR_OUTPUT
    rActivity : REAL; // 相对活性 [-]，1.0 = 全新 / relative activity, 1.0 is fresh
    rRulHours : REAL; // 活性降至 0.7 的剩余小时数 [h] / remaining useful life to 70 percent activity
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=基准失活率非法 2=失活率近零无退化 3=运行小时为负 4=温度低于绝对零度 5=结果非有限 / event code
END_VAR
VAR CONSTANT
    rLnInv07 : REAL := 0.356674944; // LN(1/0.7) 寿命终点常数 [-] / LN of one over 0.7
    rActFloor : REAL := 0.0001; // 活性下限 [-]，防 LN(0) / activity floor preventing LN of zero
    rActCeil : REAL := 1.0; // 活性上限 [-]，不得高于全新 / activity ceiling, never above fresh
    rExpHi : REAL := 50.0; // EXP 指数量程上限 [-]，防溢出 / exponent ceiling guarding EXP overflow
    rExpLo : REAL := -50.0; // EXP 指数量程下限 [-] / exponent floor
    rKelvinOff : REAL := 273.15; // 开尔文偏移 [K] / kelvin offset
END_VAR
VAR
    rExpo : REAL; // 温度加速指数 [-] / temperature exponent
    rK : REAL; // 实际失活速率常数 [1/h] / effective deactivation rate constant
    rAct : REAL; // 未限幅活性 [-] / unlimited activity
    rRulRaw : REAL; // 未限幅剩余寿命 [h] / unlimited remaining life
END_VAR

    // —— 段 0：全路径预清 —— //
    rExpo := 0.0;
    rK := 0.0;
    rAct := 0.0;
    rRulRaw := 0.0;
    rActivity := rActFloor;
    rRulHours := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_CatalystActivityDecay := FALSE;
    // —— 段 1：输入域闸 —— //
    IF rDeactBase <= 0.0 THEN
        iErrCode := 1; // 基准失活率非法，衰减模型无定义 / invalid base rate, model undefined
        RETURN;
    END_IF;
    IF rHoursRun < 0.0 THEN
        iErrCode := 3; // 运行小时为负 / negative operating hours
        RETURN;
    END_IF;
    IF rTempC <= (0.0 - rKelvinOff) THEN
        iErrCode := 4; // 温度低于绝对零度，物理不可能 / temperature below absolute zero
        RETURN;
    END_IF;
    // —— 段 2：温度加速失活常数（指数先做量程钳位，防 EXP 溢出） —— //
    rExpo := rKt * (rTempC - rTempRefC); // 加速指数 [-] / acceleration exponent
    IF rExpo > rExpHi THEN
        rExpo := rExpHi; // 上限钳位 / clamp high
    ELSIF rExpo < rExpLo THEN
        rExpo := rExpLo; // 下限钳位 / clamp low
    END_IF;
    rK := rDeactBase * EXP(rExpo); // 失活速率常数 [1/h] / rate constant
    // —— 段 3：活性 = EXP(-k·t)，并限 [0.0001, 1] —— //
    rAct := EXP(0.0 - rK * rHoursRun); // 活性 [-] / activity
    IF rAct > rActCeil THEN
        rActivity := rActCeil; // 上限钳位 / clamp high
    ELSIF rAct < rActFloor THEN
        rActivity := rActFloor; // 下限钳位，保证后续 LN 有定义 / floor keeps LN defined
    ELSE
        rActivity := rAct;
    END_IF;
    // —— 段 4：RUL（分母闸：k 必须显著为正；LN 前闸：活性为正） —— //
    IF rK <= 1.0E-9 THEN
        rRulHours := 99999.0; // 失活率近零，视为无退化 / near-zero decay, treat as no degradation
        iErrCode := 2; // 信息级：无退化，寿命取哨兵值 / info: no degradation, sentinel life
        bValid := TRUE;
        FC_DL_CatalystActivityDecay := TRUE;
        RETURN;
    END_IF;
    IF rActivity <= 0.0 THEN
        iErrCode := 5; // 活性非正，LN 无定义 / non-positive activity, LN undefined
        RETURN;
    END_IF;
    // 量纲 (-)/(1/h) = h；目标时刻 LN(1/0.7)/k 减去已运行量 LN(1/act)/k
    rRulRaw := (rLnInv07 - LN(1.0 / rActivity)) / rK; // 剩余寿命 [h] / remaining life in hours
    IF ABS(rRulRaw) > 1.0E15 THEN
        rRulHours := 0.0;
        iErrCode := 5; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rRulRaw < 0.0 THEN
        rRulHours := 0.0; // 已过寿命终点 / life already exhausted
    ELSE
        rRulHours := rRulRaw;
    END_IF;
    bValid := TRUE;
    FC_DL_CatalystActivityDecay := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
