    // —— 段 0：全路径预清 —— //
    rDmM := 0.0;
    rAreaM2 := 0.0;
    rVelMs := 0.0;
    rLgRatio := 0.0;
    rDpPa := 0.0;
    rDpKpa := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_VenturiScrubDpEst := FALSE;
    // —— 段 1：分母闸（喉口直径、烟气量）与密度域闸 —— //
    IF rThroatDm <= 0.0 THEN
        iErrCode := 1; // 喉口直径非法，截面积无定义 / invalid throat diameter
        RETURN;
    END_IF;
    IF rGasM3h <= 0.0 THEN
        iErrCode := 2; // 烟气量非法，气速无定义 / invalid gas flow, velocity undefined
        RETURN;
    END_IF;
    IF rRhoGas <= 0.0 THEN
        iErrCode := 3; // 气体密度非法 / invalid gas density
        RETURN;
    END_IF;
    // —— 段 2：喉口几何与气速（量纲 (m3/h)/(s/h)/(m2) = m/s） —— //
    rDmM := rThroatDm * rDmToM; // 喉口直径 [m] / throat diameter
    rAreaM2 := rPi * rDmM * rDmM / 4.0; // 喉口面积 [m2] / throat area
    IF rAreaM2 <= 1.0E-9 THEN
        iErrCode := 1; // 面积退化，视为直径非法 / degenerate area, treat as invalid diameter
        RETURN;
    END_IF;
    rVelMs := rGasM3h / rSecPerHour / rAreaM2; // 喉口气速 [m/s] / throat velocity
    rLgRatio := rLiquidLM3h / rGasM3h * rM3ToL; // 液气比 [L/m3] / liquid to gas ratio
    // —— 段 3：压降估算（量纲 (kg/m3)*(m2/s2) = Pa） —— //
    rDpPa := (rRhoGas * rVelMs * rVelMs / 2.0) * (1.0 + rLgCoef * rLgRatio); // 压降 [Pa] / pressure drop
    IF ABS(rDpPa) > 1.0E15 THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    // —— 段 4：单位换算与负值防御 —— //
    IF rDpPa < 0.0 THEN
        rDpKpa := 0.0; // 负输入防御 / negative input guard
    ELSE
        rDpKpa := rDpPa * rPaToKpa; // 压降 [kPa] / pressure drop in kPa
    END_IF;
    bValid := TRUE;
    FC_DL_VenturiScrubDpEst := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_DemisterVelocityChk
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 除雾器截面气速与临界携带速度（Souders-Brown）比较，判定雾沫夹带
*)
FUNCTION FC_DL_DemisterVelocityChk : BOOL
VAR_INPUT
    rGasM3h : REAL; // 实际工况烟气量 [m3/h] / actual gas flow
    rAreaM2 : REAL; // 除雾器有效流通面积 [m2] / demister free area
    rRhoL : REAL; // 液相密度 [kg/m3] / liquid density
    rRhoG : REAL; // 气相密度 [kg/m3] / gas density
    rKFactor : REAL; // Souders-Brown 经验系数 [m/s] / Souders-Brown coefficient
END_VAR
VAR_OUTPUT
    rVelMs : REAL; // 截面气速 [m/s] / superficial gas velocity
    rVcritMs : REAL; // 临界夹带速度 [m/s] / critical carry-over velocity
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bCarryOver : BOOL; // 雾沫夹带标志（气速超临界）[-] / carry-over flag
    iErrCode : INT; // 事件码 0=正常 1=气相密度非法 2=流通面积非法 3=密度差不正 4=结果非有限 / event code
END_VAR
VAR CONSTANT
    rSecPerHour : REAL := 3600.0; // 每小时秒数 [s/h] / seconds per hour
END_VAR
VAR
    rRhoRatio : REAL; // 密度比 (ρL-ρG)/ρG [-] / density ratio
    rVelRaw : REAL; // 未限幅气速 [m/s] / unlimited velocity
    rVcritRaw : REAL; // 未限幅临界速度 [m/s] / unlimited critical velocity
END_VAR

    // —— 段 0：全路径预清 —— //
    rRhoRatio := 0.0;
    rVelRaw := 0.0;
    rVcritRaw := 0.0;
    rVelMs := 0.0;
    rVcritMs := 0.0;
    bValid := FALSE;
    bCarryOver := FALSE;
    iErrCode := 0;
    FC_DL_DemisterVelocityChk := FALSE;
    // —— 段 1：分母闸（气相密度、流通面积） —— //
    IF rRhoG <= 0.0 THEN
        iErrCode := 1; // 气相密度非法，临界速度无定义 / invalid gas density
        RETURN;
    END_IF;
    IF rAreaM2 <= 0.0 THEN
        iErrCode := 2; // 流通面积非法，气速无定义 / invalid free area
        RETURN;
    END_IF;
    // —— 段 2：截面气速（量纲 (m3/h)/(s/h)/(m2) = m/s） —— //
    rVelRaw := rGasM3h / rSecPerHour / rAreaM2; // 截面气速 [m/s] / superficial velocity
    IF ABS(rVelRaw) > 1.0E15 THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rVelRaw < 0.0 THEN
        rVelMs := 0.0; // 负流量防御 / negative flow guard
    ELSE
        rVelMs := rVelRaw;
    END_IF;
    // —— 段 3：临界速度 = K·SQRT((ρL-ρG)/ρG)（开方前闸 >= 0） —— //
    rRhoRatio := (rRhoL - rRhoG) / rRhoG; // 密度比 [-] / density ratio
    IF rRhoRatio < 0.0 THEN
        rVcritMs := 0.0;
        iErrCode := 3; // 密度差不正（气相重于液相），临界速度无意义 / non-positive density difference
        bValid := TRUE;
        FC_DL_DemisterVelocityChk := TRUE;
        RETURN;
    END_IF;
    rVcritRaw := rKFactor * SQRT(rRhoRatio); // 临界速度 [m/s] / critical velocity
    IF ABS(rVcritRaw) > 1.0E15 THEN
        rVcritMs := 0.0;
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rVcritRaw < 0.0 THEN
        rVcritMs := 0.0; // 负系数防御 / negative coefficient guard
    ELSE
        rVcritMs := rVcritRaw;
    END_IF;
    // —— 段 4：夹带判定与收口 —— //
    bCarryOver := rVelMs > rVcritMs; // 夹带标志 [-] / carry-over flag
    bValid := TRUE;
    FC_DL_DemisterVelocityChk := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_StackEmissionDilute
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 排放浓度干基折算与基准氧折算（20.9% 干烟气含氧基准口径）
*)
FUNCTION FC_DL_StackEmissionDilute : BOOL
VAR_INPUT
    rMeasMgNm3 : REAL; // 实测湿基浓度 [mg/Nm3] / measured wet-basis concentration
    rO2MeasPct : REAL; // 实测含氧量 [%] / measured oxygen content
    rO2RefPct : REAL; // 折算基准含氧量 [%]，典型 6 或 11 / reference oxygen content
    rMoistPct : REAL; // 烟气含湿量 [%] / flue gas moisture content
END_VAR
VAR_OUTPUT
    rDryMgNm3 : REAL; // 干基浓度 [mg/Nm3] / dry-basis concentration
    rRefMgNm3 : REAL; // 基准氧折算浓度 [mg/Nm3] / reference-oxygen corrected concentration
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=实测氧接近基准导致分母过小 2=含湿量超域 3=基准氧非法 4=结果非有限 / event code
END_VAR
VAR CONSTANT
    rO2Air : REAL := 20.9; // 干空气含氧量 [%] / oxygen in dry air
    rO2MinGap : REAL := 0.5; // 分母最小允许间隙 [%] / minimum denominator gap
    rMoistMax : REAL := 99.0; // 含湿量上限 [%] / moisture upper bound
    rPctToFrac : REAL := 0.01; // 百分数转小数系数 [-]/[%] / percent to fraction factor
END_VAR
VAR
    rDryFactor : REAL; // 干基换算因子 [-] / dry basis factor
    rO2GapMeas : REAL; // 实测氧与空气氧差 [%] / measured oxygen gap
    rO2GapRef : REAL; // 基准氧与空气氧差 [%] / reference oxygen gap
    rDryRaw : REAL; // 未校验干基浓度 [mg/Nm3] / unchecked dry concentration
    rRefRaw : REAL; // 未校验折算浓度 [mg/Nm3] / unchecked corrected concentration
END_VAR

    // —— 段 0：全路径预清 —— //
    rDryFactor := 0.0;
    rO2GapMeas := 0.0;
    rO2GapRef := 0.0;
    rDryRaw := 0.0;
    rRefRaw := 0.0;
    rDryMgNm3 := 0.0;
    rRefMgNm3 := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_StackEmissionDilute := FALSE;
    // —— 段 1：含湿量域闸与干基换算分母闸 —— //
    IF (rMoistPct < 0.0) OR (rMoistPct > rMoistMax) THEN
        iErrCode := 2; // 含湿量超域，干基换算无意义 / moisture out of domain
        RETURN;
    END_IF;
    rDryFactor := 1.0 - rMoistPct * rPctToFrac; // 干基因子 [-] / dry basis factor
    IF rDryFactor <= 1.0E-9 THEN
        iErrCode := 2; // 干基因子退化（近全湿）/ degenerate dry factor
        RETURN;
    END_IF;
    // —— 段 2：干基浓度 = 湿基/干基因子 —— //
    rDryRaw := rMeasMgNm3 / rDryFactor; // 干基浓度 [mg/Nm3] / dry concentration
    // —— 段 3：基准氧折算分母闸（实测氧不得接近空气氧） —— //
    rO2GapMeas := rO2Air - rO2MeasPct; // 实测氧间隙 [%] / measured gap
    IF ABS(rO2GapMeas) < rO2MinGap THEN
        iErrCode := 1; // 实测氧接近 20.9%，折算分母过小 / measured oxygen too close to air value
        RETURN;
    END_IF;
    rO2GapRef := rO2Air - rO2RefPct; // 基准氧间隙 [%] / reference gap
    IF rO2GapRef <= 0.0 THEN
        iErrCode := 3; // 基准氧不得高于空气氧 / reference oxygen above air value
        RETURN;
    END_IF;
    // —— 段 4：量纲链 (mg/Nm3)*(%)/(%) = mg/Nm3 —— //
    rRefRaw := rDryRaw * rO2GapRef / rO2GapMeas; // 折算浓度 [mg/Nm3] / corrected concentration
    IF (ABS(rDryRaw) > 1.0E15) OR (ABS(rRefRaw) > 1.0E15) THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rDryMgNm3 := rDryRaw;
    rRefMgNm3 := rRefRaw;
    bValid := TRUE;
    FC_DL_StackEmissionDilute := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_ComponentRulEstimate
  分类: DL_Device
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 依据健康度两次采样外推退化斜率与剩余寿命 RUL，并判定退化加速
*)
FUNCTION FC_DL_ComponentRulEstimate : BOOL
VAR_INPUT
    rHealthNow : REAL; // 本次健康度采样 [%]，100 = 全新 / current health sample in percent, 100 is new
    rHealthPrev : REAL; // 上次健康度采样 [%] / previous health sample
    rHoursDelta : REAL; // 两次采样间隔运行小时 [h] / operating hours between samples
    rFailThr : REAL; // 失效门限健康度 [%] / failure threshold health
END_VAR
VAR_OUTPUT
    rRulHours : REAL; // 剩余寿命 [h]，上限哨兵 99999 / remaining useful life, sentinel 99999
    rSlopePerH : REAL; // 退化斜率 [%/h] / degradation slope
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bAccel : BOOL; // 退化加速标志（斜率低于 -0.001 %/h）[-] / accelerated degradation flag
    iErrCode : INT; // 事件码 0=正常 1=间隔非法 2=无退化（哨兵寿命）3=已到门限 4=结果非有限 / event code
END_VAR
VAR CONSTANT
    rSlopeDead : REAL := 1.0E-9; // 斜率死区（视作无退化）[%/h] / slope dead band
    rSlopeAccel : REAL := -0.001; // 加速退化判据斜率 [%/h] / accelerated degradation slope threshold
    rRulCap : REAL := 99999.0; // 剩余寿命上限哨兵 [h] / remaining life sentinel cap
END_VAR
VAR
    rSlopeRaw : REAL; // 未限幅斜率 [%/h] / unchecked slope
    rRulRaw : REAL; // 未限幅剩余寿命 [h] / unchecked remaining life
    rHeadRoom : REAL; // 剩余健康度余量 [%] / health headroom
END_VAR

    // —— 段 0：全路径预清 —— //
    rSlopeRaw := 0.0;
    rRulRaw := 0.0;
    rHeadRoom := 0.0;
    rRulHours := 0.0;
    rSlopePerH := 0.0;
    bValid := FALSE;
    bAccel := FALSE;
    iErrCode := 0;
    FC_DL_ComponentRulEstimate := FALSE;
    // —— 段 1：分母闸（采样间隔必须为正） —— //
    IF rHoursDelta <= 0.0 THEN
        iErrCode := 1; // 采样间隔非法，斜率无定义 / invalid interval, slope undefined
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (% - %)/(h) = %/h —— //
    rSlopeRaw := (rHealthNow - rHealthPrev) / rHoursDelta; // 退化斜率 [%/h] / degradation slope
    IF ABS(rSlopeRaw) > 1.0E15 THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rSlopePerH := rSlopeRaw;
    // —— 段 3：无退化判据（死区内视作零斜率，寿命取哨兵） —— //
    IF ABS(rSlopePerH) < rSlopeDead THEN
        rRulHours := rRulCap; // 哨兵寿命 [h] / sentinel life
        iErrCode := 2; // 信息级：无退化 / info level: no degradation
        bValid := TRUE;
        FC_DL_ComponentRulEstimate := TRUE;
        RETURN;
    END_IF;
    // —— 段 4：剩余健康度余量与 RUL（分母闸：|斜率| 已过死区） —— //
    rHeadRoom := rHealthNow - rFailThr; // 剩余健康度 [%] / health headroom
    IF rHeadRoom <= 0.0 THEN
        rRulHours := 0.0; // 已到或越过失效门限 / threshold already reached
        iErrCode := 3; // 信息级：寿命耗尽 / info level: life exhausted
        bAccel := rSlopePerH < rSlopeAccel; // 仍给出加速判据 / acceleration still reported
        bValid := TRUE;
        FC_DL_ComponentRulEstimate := TRUE;
        RETURN;
    END_IF;
    rRulRaw := rHeadRoom / ABS(rSlopePerH); // 量纲 %/(%/h) = h / remaining life in hours
    IF ABS(rRulRaw) > 1.0E15 THEN
        rRulHours := 0.0;
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rRulRaw > rRulCap THEN
        rRulHours := rRulCap; // 上限饱和 / saturate at cap
    ELSE
        rRulHours := rRulRaw;
    END_IF;
    bAccel := rSlopePerH < rSlopeAccel; // 退化加速标志 [-] / accelerated degradation flag
    bValid := TRUE;
    FC_DL_ComponentRulEstimate := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_BrgThermalDriftRate
  分类: DL_Device
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 轴承温升速率计算、相对环境温升与温升过快判定
*)
FUNCTION FC_DL_BrgThermalDriftRate : BOOL
VAR_INPUT
    rTempNow : REAL; // 本次轴承温度 [°C] / current bearing temperature
    rTempPrev : REAL; // 上次轴承温度 [°C] / previous bearing temperature
    rDtMin : REAL; // 采样间隔 [min] / sampling interval in minutes
    rAmbC : REAL; // 环境温度 [°C] / ambient temperature
    rAlarmRisePerMin : REAL; // 温升速率报警门槛 [°C/min] / rise rate alarm threshold
END_VAR
VAR_OUTPUT
    rRisePerMin : REAL; // 温升速率 [°C/min] / temperature rise rate
    rOverAmbC : REAL; // 相对环境温升 [°C] / temperature rise above ambient
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bFastRise : BOOL; // 温升过快标志 [-] / fast rise flag
    iErrCode : INT; // 事件码 0=正常 1=采样间隔非法 2=结果非有限 / event code
END_VAR
VAR CONSTANT
    rAbsZero : REAL := -273.15; // 绝对零度 [°C] / absolute zero in Celsius
END_VAR
VAR
    rRiseRaw : REAL; // 未校验温升速率 [°C/min] / unchecked rise rate
END_VAR

    // —— 段 0：全路径预清 —— //
    rRiseRaw := 0.0;
    rRisePerMin := 0.0;
    rOverAmbC := 0.0;
    bValid := FALSE;
    bFastRise := FALSE;
    iErrCode := 0;
    FC_DL_BrgThermalDriftRate := FALSE;
    // —— 段 1：分母闸（采样间隔必须为正） —— //
    IF rDtMin <= 0.0 THEN
        iErrCode := 1; // 采样间隔非法，速率无定义 / invalid interval, rate undefined
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (°C - °C)/(min) = °C/min —— //
    rRiseRaw := (rTempNow - rTempPrev) / rDtMin; // 温升速率 [°C/min] / rise rate
    IF ABS(rRiseRaw) > 1.0E15 THEN
        iErrCode := 2; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rRisePerMin := rRiseRaw;
    // —— 段 3：相对环境温升（量纲 °C - °C = °C） —— //
    IF rTempNow <= rAbsZero THEN
        iErrCode := 2; // 温度低于绝对零度，物理不可能 / temperature below absolute zero
        RETURN;
    END_IF;
    rOverAmbC := rTempNow - rAmbC; // 相对环境温升 [°C] / rise above ambient
    // —— 段 4：温升过快判定（门槛为负时按绝对值口径比对） —— //
    IF rAlarmRisePerMin > 0.0 THEN
        bFastRise := rRisePerMin > rAlarmRisePerMin; // 常规比对 / normal comparison
    ELSE
        bFastRise := rRisePerMin > ABS(rAlarmRisePerMin); // 门槛配置异常时退化为绝对值口径 / fallback on bad threshold
    END_IF;
    bValid := TRUE;
    FC_DL_BrgThermalDriftRate := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_OilChangeInterval
  分类: DL_Device
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 按负荷、温度、污染三因子修正换油周期，并给出剩余小时与到期判定
*)
FUNCTION FC_DL_OilChangeInterval : BOOL
VAR_INPUT
    rBaseHours : REAL; // 基准换油周期 [h] / base oil change interval
    rLoadFactor : REAL; // 负荷修正因子 [-]，域 (0.1, 5.0] / load correction factor
    rTempFactor : REAL; // 温度修正因子 [-]，域 (0.1, 5.0] / temperature correction factor
    rContamFactor : REAL; // 污染修正因子 [-]，域 (0.1, 5.0] / contamination correction factor
    rHoursSince : REAL; // 上次换油后已运行小时 [h] / hours since last oil change
END_VAR
VAR_OUTPUT
    rIntervalH : REAL; // 修正后换油周期 [h] / corrected interval
    rRemainH : REAL; // 剩余可用小时 [h]，可为负（已超期）/ remaining hours, negative when overdue
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bDue : BOOL; // 到期标志（剩余 ≤ 0）[-] / due flag
    iErrCode : INT; // 事件码 0=正常 1=修正因子超域 2=基准周期非法 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rFactorLo : REAL := 0.1; // 因子域下限（不含）[-] / factor domain lower bound, exclusive
    rFactorHi : REAL := 5.0; // 因子域上限（含）[-] / factor domain upper bound, inclusive
END_VAR
VAR
    rIntervalRaw : REAL; // 未校验周期 [h] / unchecked interval
END_VAR

    // —— 段 0：全路径预清 —— //
    rIntervalRaw := 0.0;
    rIntervalH := 0.0;
    rRemainH := 0.0;
    bValid := FALSE;
    bDue := FALSE;
    iErrCode := 0;
    FC_DL_OilChangeInterval := FALSE;
    // —— 段 1：三因子域闸（含非正因子，防周期符号翻转） —— //
    IF (rLoadFactor <= rFactorLo) OR (rLoadFactor > rFactorHi)
       OR (rTempFactor <= rFactorLo) OR (rTempFactor > rFactorHi)
       OR (rContamFactor <= rFactorLo) OR (rContamFactor > rFactorHi) THEN
        iErrCode := 1; // 修正因子超域，周期不可信 / correction factor out of domain
        RETURN;
    END_IF;
    // —— 段 2：基准周期域闸 —— //
    IF rBaseHours <= 0.0 THEN
        iErrCode := 2; // 基准周期非法，周期无定义 / invalid base interval
        RETURN;
    END_IF;
    // —— 段 3：量纲链 (h)×(-)×(-)×(-) = h —— //
    rIntervalRaw := rBaseHours * rLoadFactor * rTempFactor * rContamFactor; // 修正周期 [h] / corrected interval
    IF ABS(rIntervalRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rIntervalH := rIntervalRaw;
    // —— 段 4：剩余小时（可为负，负值即超期量）与到期判定 —— //
    rRemainH := rIntervalH - rHoursSince; // 剩余小时 [h] / remaining hours
    bDue := rRemainH <= 0.0; // 到期判定 [-] / due test
    bValid := TRUE;
    FC_DL_OilChangeInterval := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_MtbfCalc
  分类: DL_Device
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: MTBF / MTTR / 可用率计算，含无失效样本的退化口径
*)
FUNCTION FC_DL_MtbfCalc : BOOL
VAR_INPUT
    rRunHours : REAL; // 统计窗内累计运行小时 [h] / accumulated running hours in window
    rFailCount : REAL; // 统计窗内失效次数 [次] / failure count in window
    rRepairHours : REAL; // 统计窗内累计修复停机小时 [h] / accumulated repair downtime
END_VAR
VAR_OUTPUT
    rMtbfH : REAL; // 平均无故障间隔 [h] / mean time between failures
    rMttrH : REAL; // 平均修复时间 [h] / mean time to repair
    rAvailPct : REAL; // 可用率 [%] / availability
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=失效次数为负 2=无失效样本（MTBF 取运行小时）3=结果非有限 4=运行小时非正 5=修复小时为负 / event code
END_VAR
VAR CONSTANT
    rInvPct : REAL := 100.0; // 可用率百分数系数 [%] / percentage factor
    rAvailCap : REAL := 100.0; // 可用率饱和上限 [%] / availability cap
END_VAR
VAR
    rFailUse : REAL; // 生效失效次数 [次] / effective failure count
    rMtbfRaw : REAL; // 未校验 MTBF [h] / unchecked MTBF
    rMttrRaw : REAL; // 未校验 MTTR [h] / unchecked MTTR
    rDenom : REAL; // 可用率分母 [h] / availability denominator
END_VAR

    // —— 段 0：全路径预清 —— //
    rFailUse := 0.0;
    rMtbfRaw := 0.0;
    rMttrRaw := 0.0;
    rDenom := 0.0;
    rMtbfH := 0.0;
    rMttrH := 0.0;
    rAvailPct := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_MtbfCalc := FALSE;
    // —— 段 1：失效次数域闸 —— //
    IF rFailCount < 0.0 THEN
        iErrCode := 1; // 失效次数为负，统计口径非法 / negative failure count
        RETURN;
    END_IF;
    IF rRunHours <= 0.0 THEN
        iErrCode := 4; // 运行小时非正，MTBF 无定义 / non-positive running hours
        RETURN;
    END_IF;
    IF rRepairHours < 0.0 THEN
        iErrCode := 5; // 修复小时为负，统计口径非法 / negative repair hours
        RETURN;
    END_IF;
    // —— 段 2：无失效样本退化口径（MTBF 取运行小时，MTTR 取 0） —— //
    IF rFailCount < 0.5 THEN
        rMtbfH := rRunHours; // MTBF 取运行小时 [h] / MTBF equals running hours
        rMttrH := 0.0; // 无失效则无修复时间 / no failure, no repair time
        rAvailPct := rAvailCap; // 无失效窗内可用率按 100% 计 / availability capped at 100 percent
        iErrCode := 2; // 信息级：无失效样本 / info level: no failure sample
        bValid := TRUE;
        FC_DL_MtbfCalc := TRUE;
        RETURN;
    END_IF;
    rFailUse := rFailCount; // 生效失效次数 [次] / effective failure count
    // —— 段 3：量纲链 (h)/(次) = h —— //
    rMtbfRaw := rRunHours / rFailUse; // MTBF [h] / mean time between failures
    rMttrRaw := rRepairHours / rFailUse; // MTTR [h] / mean time to repair
    IF (ABS(rMtbfRaw) > 1.0E15) OR (ABS(rMttrRaw) > 1.0E15) THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rMtbfH := rMtbfRaw;
    rMttrH := rMttrRaw;
    // —— 段 4：可用率（分母闸：MTBF+MTTR 不能为零） —— //
    rDenom := rMtbfH + rMttrH; // 分母 [h] / denominator
    IF ABS(rDenom) <= 1.0E-9 THEN
        rAvailPct := 0.0; // 分母退化，可用率置零 / degenerate denominator
        iErrCode := 3; // 信息级：可用率不可算 / info level: availability not computable
    ELSE
        rAvailPct := rMtbfH / rDenom * rInvPct; // 可用率 [%] / availability
        IF rAvailPct > rAvailCap THEN
            rAvailPct := rAvailCap; // 上限饱和 / saturate at cap
        ELSIF rAvailPct < 0.0 THEN
            rAvailPct := 0.0; // 下限钳零 / floor at zero
        END_IF
    END_IF;
    bValid := TRUE;
    FC_DL_MtbfCalc := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_SpareReorderPoint
  分类: DL_Device
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 备件订货点与缺料量计算，触发补货判定
*)
FUNCTION FC_DL_SpareReorderPoint : BOOL
VAR_INPUT
    rDailyUse : REAL; // 日均消耗量 [件/d] / average daily consumption
    rLeadDays : REAL; // 采购提前期 [d] / procurement lead time in days
    rSafetyDays : REAL; // 安全库存天数 [d] / safety stock in days
    rOnHand : REAL; // 当前在手库存 [件] / stock on hand
END_VAR
VAR_OUTPUT
    rRop : REAL; // 订货点 [件] / reorder point
    rShortQty : REAL; // 相对订货点的缺口量 [件] / shortage against the reorder point
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bReorder : BOOL; // 补货标志（在手 ≤ 订货点）[-] / reorder flag
    iErrCode : INT; // 事件码 0=正常 1=日耗为负 2=提前期为负已归零 3=安全天数为负已归零 4=结果非有限 / event code
END_VAR
VAR
    rLeadUse : REAL; // 生效提前期 [d] / effective lead time
    rSafetyUse : REAL; // 生效安全天数 [d] / effective safety days
    rCoverDays : REAL; // 合计覆盖天数 [d] / total coverage days
    rRopRaw : REAL; // 未校验订货点 [件] / unchecked reorder point
    rShortRaw : REAL; // 未校验缺口量 [件] / unchecked shortage
END_VAR

    // —— 段 0：全路径预清 —— //
    rLeadUse := 0.0;
    rSafetyUse := 0.0;
    rCoverDays := 0.0;
    rRopRaw := 0.0;
    rShortRaw := 0.0;
    rRop := 0.0;
    rShortQty := 0.0;
    bValid := FALSE;
    bReorder := FALSE;
    iErrCode := 0;
    FC_DL_SpareReorderPoint := FALSE;
    // —— 段 1：日耗域闸（负消耗无物理意义） —— //
    IF rDailyUse < 0.0 THEN
        iErrCode := 1; // 日耗为负，订货点不可信 / negative daily use
        RETURN;
    END_IF;
    // —— 段 2：天数负值归零（配置错误宽容处理） —— //
    IF rLeadDays < 0.0 THEN
        rLeadUse := 0.0;
        iErrCode := 2; // 提前期为负已归零 / negative lead time clamped
    ELSE
        rLeadUse := rLeadDays;
    END_IF;
    IF rSafetyDays < 0.0 THEN
        rSafetyUse := 0.0;
        iErrCode := 3; // 安全天数为负已归零 / negative safety days clamped
    ELSE
        rSafetyUse := rSafetyDays;
    END_IF;
    // —— 段 3：量纲链 (件/d)×(d) = 件 —— //
    rCoverDays := rLeadUse + rSafetyUse; // 覆盖天数 [d] / coverage days
    rRopRaw := rDailyUse * rCoverDays; // 订货点 [件] / reorder point
    IF ABS(rRopRaw) > 1.0E15 THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rRop := rRopRaw;
    // —— 段 4：缺口量 = MAX(0, 订货点-在手) 与补货判定 —— //
    rShortRaw := rRop - rOnHand; // 缺口 [件] / shortage
    IF rShortRaw < 0.0 THEN
        rShortQty := 0.0; // 库存充足，缺口为零 / enough stock
    ELSE
        rShortQty := rShortRaw;
    END_IF;
    bReorder := rOnHand <= rRop; // 补货标志 [-] / reorder flag
    bValid := TRUE;
    FC_DL_SpareReorderPoint := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_PmScheduleNext
  分类: DL_Device
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 由上次 PM 时刻与周期天数推算下次 PM 时刻、下次 PM 日期与逾期天数
  时基声明: 时刻统一经 DT_TO_DINT 折算为「自 1970-01-01 起的秒计数」做整数运算，
            避免 TIME 型毫秒量在 24.8 天以上溢出 DINT；最大 3650 d × 86400 s = 3.15E8 s 安全
*)
FUNCTION FC_DL_PmScheduleNext : BOOL
VAR_INPUT
    dtLast : DT; // 上次 PM 完成时刻 [DT] / last PM completion timestamp
    dtNow : DT; // 当前时刻 [DT] / current timestamp
    iIntervalDays : INT; // PM 周期 [d]，域 (0, 3650] / PM interval in days
END_VAR
VAR_OUTPUT
    dtNext : DT; // 下次 PM 到期时刻 [DT] / next PM due timestamp
    dNextDate : DATE; // 下次 PM 到期日期 [DATE] / next PM due date, operator friendly
    iOverdueDays : INT; // 逾期天数 [d]，未逾期为 0 / overdue days, zero when not overdue
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bOverdue : BOOL; // 逾期标志 [-] / overdue flag
    iErrCode : INT; // 事件码 0=正常 1=周期超域 2=上次时刻未初始化 3=秒计数溢出 / event code
END_VAR
VAR CONSTANT
    diSecPerDay : DINT := 86400; // 每日秒数 [s/d] / seconds per day
    diIntervalMax : DINT := 3650; // 周期天数上限 [d] / interval upper bound
END_VAR
VAR
    diLastSec : DINT; // 上次 PM 秒计数 [s] / last PM as seconds
    diNowSec : DINT; // 当前时刻秒计数 [s] / now as seconds
    diSpanSec : DINT; // 周期秒数 [s] / interval in seconds
    diNextSec : DINT; // 下次 PM 秒计数 [s] / next due as seconds
    diDiffSec : DINT; // 逾期秒数 [s] / overdue seconds
END_VAR

    // —— 段 0：全路径预清 —— //
    diLastSec := 0;
    diNowSec := 0;
    diSpanSec := 0;
    diNextSec := 0;
    diDiffSec := 0;
    dtNext := dtLast;
    dNextDate := DT_TO_DATE(dtLast);
    iOverdueDays := 0;
    bValid := FALSE;
    bOverdue := FALSE;
    iErrCode := 0;
    FC_DL_PmScheduleNext := FALSE;
    // —— 段 1：周期域闸 (0, 3650]d —— //
    IF (iIntervalDays <= 0) OR (INT_TO_DINT(iIntervalDays) > diIntervalMax) THEN
        iErrCode := 1; // 周期超域，不生成计划 / interval out of domain, no schedule issued
        RETURN;
    END_IF;
    // —— 段 2：上次时刻有效性闸（零值 = 未初始化） —— //
    diLastSec := DT_TO_DINT(dtLast); // 上次 PM 秒计数 [s] / last PM in seconds
    IF diLastSec <= 0 THEN
        iErrCode := 2; // 上次时刻未初始化 / last timestamp not initialised
        RETURN;
    END_IF;
    // —— 段 3：量纲链 (d)×(s/d) = s；加法后反查是否溢出为负 —— //
    diSpanSec := INT_TO_DINT(iIntervalDays) * diSecPerDay; // 周期秒数 [s] / interval in seconds
    diNextSec := diLastSec + diSpanSec; // 下次秒计数 [s] / next due in seconds
    IF diNextSec < diLastSec THEN
        iErrCode := 3; // 秒计数溢出，放弃本次计划 / second counter overflow, schedule dropped
        RETURN;
    END_IF;
    dtNext := DINT_TO_DT(diNextSec); // 下次到期时刻 [DT] / next due timestamp
    dNextDate := DT_TO_DATE(dtNext); // 到期日期 [DATE] / due date
    // —— 段 4：逾期天数 = MAX(0, (now-next)/86400) —— //
    diNowSec := DT_TO_DINT(dtNow); // 当前秒计数 [s] / now in seconds
    IF diNowSec > diNextSec THEN
        diDiffSec := diNowSec - diNextSec; // 逾期秒数 [s] / overdue seconds
        iOverdueDays := DINT_TO_INT(diDiffSec / diSecPerDay); // 逾期天数 [d] / overdue days
        bOverdue := TRUE;
    ELSE
        bOverdue := FALSE; // 未逾期 / not overdue
    END_IF;
    bValid := TRUE;
    FC_DL_PmScheduleNext := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_LubeIntervalCalc
  分类: DL_Device
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 按负荷、温度、粉尘三指数折算润滑间隔（基准除以三因子乘积），含因子与乘积双闸
*)
FUNCTION FC_DL_LubeIntervalCalc : BOOL
VAR_INPUT
    rBaseH : REAL; // 基准润滑间隔 [h] / base lubrication interval
    rLoadIdx : REAL; // 负荷指数 [-]，域 0~1.5 / load index
    rTempIdx : REAL; // 温度指数 [-]，域 0~1.5 / temperature index
    rDustIdx : REAL; // 粉尘指数 [-]，域 0~1.5 / dust index
END_VAR
VAR_OUTPUT
    rIntervalH : REAL; // 折算后润滑间隔 [h] / corrected lubrication interval
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=基准间隔非法 2=因子乘积过小已钳位 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rIdxLo : REAL := 0.2; // 单因子钳位下限 [-] / per-factor clamp floor
    rIdxHi : REAL := 2.0; // 单因子钳位上限 [-] / per-factor clamp ceiling
    rProdMin : REAL := 0.1; // 乘积下限，低于此则间隔不可信 [-] / product floor
    rProdFloor : REAL := 0.2; // 乘积过小时的替代值 [-] / substitute product applied when floored
END_VAR
VAR
    rLoadUse : REAL; // 生效负荷因子 [-] / effective load factor
    rTempUse : REAL; // 生效温度因子 [-] / effective temperature factor
    rDustUse : REAL; // 生效粉尘因子 [-] / effective dust factor
    rProd : REAL; // 三因子乘积 [-] / product of factors
    rProdUse : REAL; // 生效乘积 [-] / effective product
    rIntRaw : REAL; // 未校验间隔 [h] / unchecked interval
END_VAR

    // —— 段 0：全路径预清 —— //
    rLoadUse := 1.0;
    rTempUse := 1.0;
    rDustUse := 1.0;
    rProd := 0.0;
    rProdUse := rProdFloor; // 生效乘积缺省取替代值 [-] / effective product defaults to the floor
    rIntRaw := 0.0;
    rIntervalH := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_LubeIntervalCalc := FALSE;
    // —— 段 1：基准间隔域闸（兼最终分母的来源量） —— //
    IF rBaseH <= 0.0 THEN
        iErrCode := 1; // 基准间隔非法，间隔无定义 / invalid base interval
        RETURN;
    END_IF;
    // —— 段 2：三因子各自钳位到 [0.2, 2.0]（配置越界按边界处理，不中断） —— //
    IF rLoadIdx < rIdxLo THEN
        rLoadUse := rIdxLo; // 下限钳位 / clamp low
    ELSIF rLoadIdx > rIdxHi THEN
        rLoadUse := rIdxHi; // 上限钳位 / clamp high
    ELSE
        rLoadUse := rLoadIdx;
    END_IF;
    IF rTempIdx < rIdxLo THEN
        rTempUse := rIdxLo;
    ELSIF rTempIdx > rIdxHi THEN
        rTempUse := rIdxHi;
    ELSE
        rTempUse := rTempIdx;
    END_IF;
    IF rDustIdx < rIdxLo THEN
        rDustUse := rIdxLo;
    ELSIF rDustIdx > rIdxHi THEN
        rDustUse := rIdxHi;
    ELSE
        rDustUse := rDustIdx;
    END_IF;
    // —— 段 3：乘积闸（分母不得过小，否则间隔被无限拉长） —— //
    rProd := rLoadUse * rTempUse * rDustUse; // 三因子乘积 [-] / product
    IF rProd < rProdMin THEN
        rProdUse := rProdFloor; // 取替代常数（0.2），间隔最多放大 5 倍 / substitute product, interval at most 5x
        iErrCode := 2; // 信息级：乘积过小已钳位 / info level: product floored
    ELSE
        rProdUse := rProd;
    END_IF;
    // —— 段 4：量纲链 (h)/((-)×(-)×(-)) = h —— //
    rIntRaw := rBaseH / rProdUse; // 折算间隔 [h] / corrected interval
    IF ABS(rIntRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rIntervalH := rIntRaw;
    bValid := TRUE;
    FC_DL_LubeIntervalCalc := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_BiogasYieldCalc
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 厌氧消化沼气产量估算：进料 VS 量 × 降解率 × 单位产气率，折算日量与小时量
*)
FUNCTION FC_DL_BiogasYieldCalc : BOOL
VAR_INPUT
    rVsKgDay : REAL; // 进料挥发性固体量 [kg VS/d] / volatile solids fed per day
    rVsDestroyPct : REAL; // VS 降解率 [%] / volatile solids destruction rate
    rYieldM3KgVs : REAL; // 单位产气率 [m3/kgVS] / specific biogas yield
END_VAR
VAR_OUTPUT
    rGasM3Day : REAL; // 沼气日产量 [m3/d] / daily biogas production
    rGasM3h : REAL; // 沼气小时产量 [m3/h] / hourly biogas production
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=进料 VS 为负 2=降解率超域 3=产气率非法 4=结果非有限 / event code
END_VAR
VAR CONSTANT
    rPctToFrac : REAL := 0.01; // 百分数转小数系数 [-]/[%] / percent to fraction factor
    rHourPerDay : REAL := 24.0; // 每日小时数 [h/d] / hours per day
END_VAR
VAR
    rDestroyFrac : REAL; // 降解率小数 [-] / destruction fraction
    rGasRaw : REAL; // 未校验日产量 [m3/d] / unchecked daily production
END_VAR

    // —— 段 0：全路径预清 —— //
    rDestroyFrac := 0.0;
    rGasRaw := 0.0;
    rGasM3Day := 0.0;
    rGasM3h := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_BiogasYieldCalc := FALSE;
    // —— 段 1：输入域闸 —— //
    IF rVsKgDay < 0.0 THEN
        iErrCode := 1; // 进料 VS 为负，产气量无意义 / negative volatile solids
        RETURN;
    END_IF;
    IF (rVsDestroyPct <= 0.0) OR (rVsDestroyPct > 100.0) THEN
        iErrCode := 2; // 降解率超域 (0,100] / destruction rate out of domain
        RETURN;
    END_IF;
    IF rYieldM3KgVs <= 0.0 THEN
        iErrCode := 3; // 产气率非法，产气量无定义 / invalid specific yield
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (kgVS/d)×(-)×(m3/kgVS) = m3/d —— //
    rDestroyFrac := rVsDestroyPct * rPctToFrac; // 降解率 [-] / destruction fraction
    rGasRaw := rVsKgDay * rDestroyFrac * rYieldM3KgVs; // 日产量 [m3/d] / daily production
    IF ABS(rGasRaw) > 1.0E15 THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rGasM3Day := rGasRaw;
    // —— 段 3：小时量 = 日量 / 24（量纲 (m3/d)/(h/d) = m3/h） —— //
    rGasM3h := rGasM3Day / rHourPerDay; // 小时产量 [m3/h] / hourly production
    bValid := TRUE;
    FC_DL_BiogasYieldCalc := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_MethaneRatioCalc
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 沼气组分平衡求甲烷含量与低位热值 LHV，含 H2S 腐蚀告警
*)
FUNCTION FC_DL_MethaneRatioCalc : BOOL
VAR_INPUT
    rCo2Pct : REAL; // 二氧化碳体积分数 [%] / CO2 volume fraction
    rN2Pct : REAL; // 氮气体积分数 [%] / N2 volume fraction
    rO2Pct : REAL; // 氧气体积分数 [%] / O2 volume fraction
    rH2sPpm : REAL; // 硫化氢浓度 [ppm] / H2S concentration in ppm
END_VAR
VAR_OUTPUT
    rCh4Pct : REAL; // 甲烷体积分数 [%] / methane volume fraction
    rLhvMJm3 : REAL; // 低位热值 [MJ/m3] / lower heating value
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=组分和超 100（甲烷按 0 饱和）2=H2S 超 500ppm 告警 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rPctFull : REAL := 100.0; // 组分满量程 [%] / full scale of volume fraction
    rCh4Lhv : REAL := 35.8; // 纯甲烷低位热值 [MJ/m3] / LHV of pure methane
    rH2sLimit : REAL := 500.0; // H2S 腐蚀告警门槛 [ppm] / H2S corrosion alarm threshold
    rPctToFrac : REAL := 0.01; // 百分数转小数系数 [-]/[%] / percent to fraction factor
END_VAR
VAR
    rSumPct : REAL; // 非甲烷组分之和 [%] / sum of non-methane fractions
    rCh4Raw : REAL; // 未饱和甲烷含量 [%] / unlimited methane fraction
END_VAR

    // —— 段 0：全路径预清 —— //
    rSumPct := 0.0;
    rCh4Raw := 0.0;
    rCh4Pct := 0.0;
    rLhvMJm3 := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_MethaneRatioCalc := FALSE;
    // —— 段 1：量纲链 (% + % + %) = % —— //
    rSumPct := rCo2Pct + rN2Pct + rO2Pct; // 非甲烷组分和 [%] / non-methane sum
    // —— 段 2：组分和非负性与满量程闸 —— //
    IF rSumPct < 0.0 THEN
        iErrCode := 1; // 组分和为负，分析仪故障 / negative sum, analyser fault
        RETURN;
    END_IF;
    rCh4Raw := rPctFull - rSumPct; // 甲烷 = 100 - 其余 [%] / methane by difference
    // —— 段 3：甲烷负值饱和为 0 并置信息码 —— //
    IF (rCo2Pct < 0.0) OR (rN2Pct < 0.0) OR (rO2Pct < 0.0) THEN
        iErrCode := 4; // 组分负值：传感器非法，甲烷不可信 / negative component: invalid sensor
        bValid := FALSE;
        FC_DL_MethaneRatioCalc := TRUE;
        RETURN;
    END_IF
    IF rCh4Raw > 100.0 THEN
        rCh4Pct := 100.0; // 组分和偏低导致外推超 100%，饱和 / extrapolated above 100 percent, clamp
    ELSIF rCh4Raw < 0.0 THEN
        rCh4Pct := 0.0;
        iErrCode := 1; // 组分和超 100%，甲烷按零饱和 / sum above 100 percent, methane floored at zero
    ELSE
        rCh4Pct := rCh4Raw;
    END_IF;
    // —— 段 4：热值 (MJ/m3) = 甲烷份额 × 纯甲烷 LHV；H2S 告警 —— //
    rLhvMJm3 := rCh4Pct * rPctToFrac * rCh4Lhv; // 低位热值 [MJ/m3] / lower heating value
    IF ABS(rLhvMJm3) > 1.0E15 THEN
        rLhvMJm3 := 0.0;
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rH2sPpm > rH2sLimit THEN
        iErrCode := 2; // 信息级：H2S 超限，注意脱硫与腐蚀 / info: H2S high, check desulfurisation
    END_IF;
    bValid := TRUE;
    FC_DL_MethaneRatioCalc := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_OrganicLoadRate
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 厌氧反应器有机负荷率 OLR（kgVS/(m3·d)）与进料 VS 量计算，含过载判定
*)
FUNCTION FC_DL_OrganicLoadRate : BOOL
VAR_INPUT
    rFeedM3Day : REAL; // 进料体积流量 [m3/d] / feed flow per day
    rCodMgL : REAL; // 进料 COD 浓度 [mg/L] / feed COD concentration
    rVsTsRatio : REAL; // VS/TS 比 [-]，典型 0.7 / volatile to total solids ratio
    rTsKgM3 : REAL; // 进料总固体浓度 [kg/m3] / feed total solids concentration
    rReactorM3 : REAL; // 反应器有效容积 [m3] / reactor working volume
END_VAR
VAR_OUTPUT
    rOlrKgVsM3d : REAL; // 有机负荷率 [kgVS/(m3·d)] / organic loading rate
    rVsKgDay : REAL; // 进料挥发性固体量 [kgVS/d] / volatile solids fed per day
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bOver : BOOL; // 过载标志（>5.0 kgVS/(m3·d)）[-] / overload flag
    iErrCode : INT; // 事件码 0=正常 1=反应器容积非法 2=VS/TS 比超域 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rMgLToKgM3 : REAL := 0.001; // mg/L(=g/m3)转 kg/m3 系数 [kg/g] / mg per litre to kg per cubic metre
    rOlrHi : REAL := 5.0; // 过载门槛 [kgVS/(m3·d)] / overload threshold
END_VAR
VAR
    rCodKgM3 : REAL; // 进料 COD 浓度 [kg/m3] / COD concentration in kg/m3
    rVsRaw : REAL; // 未校验 VS 量 [kgVS/d] / unchecked volatile solids
    rOlrRaw : REAL; // 未校验负荷率 [kgVS/(m3·d)] / unchecked loading rate
END_VAR

    // —— 段 0：全路径预清 —— //
    rCodKgM3 := 0.0;
    rVsRaw := 0.0;
    rOlrRaw := 0.0;
    rOlrKgVsM3d := 0.0;
    rVsKgDay := 0.0;
    bValid := FALSE;
    bOver := FALSE;
    iErrCode := 0;
    FC_DL_OrganicLoadRate := FALSE;
    // —— 段 1：分母闸（反应器容积）与 VS/TS 比域闸 —— //
    IF rReactorM3 <= 0.0 THEN
        iErrCode := 1; // 反应器容积非法，负荷率无定义 / invalid reactor volume
        RETURN;
    END_IF;
    IF (rVsTsRatio <= 0.0) OR (rVsTsRatio > 1.0) THEN
        iErrCode := 2; // VS/TS 比超域 (0,1] / VS to TS ratio out of domain
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (m3/d)×(kg/m3)×(-) = kg/d —— //
    rCodKgM3 := rCodMgL * rMgLToKgM3; // COD 浓度 [kg/m3]，仅作参考量 / COD reference only
    // 量纲: (m3/d)*(kg/m3)*(-) = kgVS/d；VS 必须由 TS 乘 VS/TS 得，不得用 COD 冒充
    rVsRaw := rFeedM3Day * rTsKgM3 * rVsTsRatio; // VS 量 [kgVS/d] / volatile solids per day
    IF ABS(rVsRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    IF rVsRaw < 0.0 THEN
        rVsKgDay := 0.0; // 负进料防御 / negative feed guard
    ELSE
        rVsKgDay := rVsRaw;
    END_IF;
    // —— 段 3：负荷率（量纲 (kg/d)/(m3) = kg/(m3·d)） —— //
    rOlrRaw := rVsKgDay / rReactorM3; // 负荷率 [kgVS/(m3·d)] / organic loading rate
    IF ABS(rOlrRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rOlrKgVsM3d := rOlrRaw;
    // —— 段 4：过载判定 —— //
    bOver := rOlrKgVsM3d > rOlrHi; // 过载标志 [-] / overload flag
    bValid := TRUE;
    FC_DL_OrganicLoadRate := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_VfaAlkalinityRatio
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: VFA/碱度比计算与酸化风险分级（0=正常 1=关注 2=酸化预警）
*)
FUNCTION FC_DL_VfaAlkalinityRatio : BOOL
VAR_INPUT
    rVfaMgL : REAL; // 挥发性脂肪酸浓度 [mg/L，以乙酸计] / volatile fatty acids as acetic acid
    rAlkMgLcaco3 : REAL; // 碱度 [mg/L，以 CaCO3 计] / alkalinity as CaCO3
END_VAR
VAR_OUTPUT
    rRatio : REAL; // VFA/碱度比 [-] / VFA to alkalinity ratio
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iRisk : INT; // 风险等级 0=正常 1=关注 2=酸化预警 [-] / risk level
    iErrCode : INT; // 事件码 0=正常 1=碱度非法 2=比值超可观测上限 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rRiskWatch : REAL := 0.25; // 关注门槛 [-] / watch threshold
    rRiskAlarm : REAL := 0.4; // 酸化预警门槛 [-] / acidification alarm threshold
    rRatioCap : REAL := 100.0; // 比值输出饱和上限 [-] / ratio saturation cap
END_VAR
VAR
    rRatioRaw : REAL; // 未限幅比值 [-] / unchecked ratio
END_VAR

    // —— 段 0：全路径预清 —— //
    rRatioRaw := 0.0;
    rRatio := 0.0;
    iRisk := 0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_VfaAlkalinityRatio := FALSE;
    // —— 段 1：分母闸（碱度必须为正） —— //
    IF rAlkMgLcaco3 <= 0.0 THEN
        iErrCode := 1; // 碱度非法，比值无定义 / invalid alkalinity, ratio undefined
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (mg/L)/(mg/L) = 无量纲 —— //
    rRatioRaw := rVfaMgL / rAlkMgLcaco3; // 比值 [-] / ratio
    IF ABS(rRatioRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    // —— 段 3：负值防御与上限饱和 —— //
    IF rRatioRaw < 0.0 THEN
        rRatio := 0.0; // 负浓度防御 / negative concentration guard
    ELSIF rRatioRaw > rRatioCap THEN
        rRatio := rRatioCap; // 超上限饱和 / saturate at cap
        iErrCode := 2; // 信息级：比值超上限 / info level: ratio capped
    ELSE
        rRatio := rRatioRaw;
    END_IF;
    // —— 段 4：风险分级（用原始比值分级，避免饱和影响） —— //
    IF rRatioRaw > rRiskAlarm THEN
        iRisk := 2; // 酸化预警 / acidification alarm
    ELSIF rRatioRaw >= rRiskWatch THEN
        iRisk := 1; // 关注 / watch
    ELSE
        iRisk := 0; // 正常 / normal
    END_IF;
    bValid := TRUE;
    FC_DL_VfaAlkalinityRatio := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_GasHolderLevel
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 湿式气柜储气量标态折算与可释放能量估算
  口径声明: 能量按厂内标定简化系数 0.55 kWh/(m3·单位甲烷份额)×CH4 假设 0.6 计，
            非热力学严格值（严格口径为 9.94 kWh/m3 纯甲烷），仅供储量看板同比使用
*)
FUNCTION FC_DL_GasHolderLevel : BOOL
VAR_INPUT
    rPressKpa : REAL; // 柜内表压 [kPa] / gauge pressure in the holder
    rTempC : REAL; // 柜内气体温度 [°C] / gas temperature
    rVolM3 : REAL; // 气柜几何容积 [m3] / geometric holder volume
    rLevelPct : REAL; // 有效储气液位/行程 [%] / effective storage level
END_VAR
VAR_OUTPUT
    rNormM3 : REAL; // 标态储气量 [Nm3] / normalised stored volume
    rEnergyKwh : REAL; // 可释放能量估算 [kWh] / estimated releasable energy
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=温度超域 2=容积非法 3=压力非法 4=结果非有限 / event code
END_VAR
VAR CONSTANT
    rKelvinOff : REAL := 273.15; // 开尔文偏移 [K] / kelvin offset
    rPressRefKpa : REAL := 101.325; // 标准大气压 [kPa] / standard atmospheric pressure
    rTempMinC : REAL := -50.0; // 温度域下限 [°C] / temperature lower bound
    rPctToFrac : REAL := 0.01; // 百分数转小数系数 [-]/[%] / percent to fraction factor
    rKwhPerM3 : REAL := 0.55; // 能量简化系数 [kWh/m3] / simplified energy coefficient
    rCh4Assumed : REAL := 0.6; // 甲烷份额假设 [-] / assumed methane fraction
END_VAR
VAR
    rTempK : REAL; // 柜内绝对温度 [K] / absolute temperature
    rVolUseM3 : REAL; // 有效储气体积 [m3] / effective stored volume
    rNormRaw : REAL; // 未校验标态量 [Nm3] / unchecked normalised volume
END_VAR

    // —— 段 0：全路径预清 —— //
    rTempK := 0.0;
    rVolUseM3 := 0.0;
    rNormRaw := 0.0;
    rNormM3 := 0.0;
    rEnergyKwh := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_GasHolderLevel := FALSE;
    // —— 段 1：温度域闸（同时保护标态折算分母 273.15+T） —— //
    IF rTempC <= rTempMinC THEN
        iErrCode := 1; // 温度超域，标态折算无意义 / temperature out of domain
        RETURN;
    END_IF;
    IF rVolM3 <= 0.0 THEN
        iErrCode := 2; // 容积非法 / invalid holder volume
        RETURN;
    END_IF;
    // —— 段 2：压力域闸（表压需为正，绝对压 = 表压 + 大气压） —— //
    IF rPressKpa <= 0.0 THEN
        iErrCode := 3; // 压力非法，绝对压不可信 / invalid gauge pressure
        RETURN;
    END_IF;
    // —— 段 3：有效储气体积按液位折算，再作标态换算（量纲 m3×kPa/K÷kPa = Nm3） —— //
    rVolUseM3 := rVolM3 * rLevelPct * rPctToFrac; // 有效体积 [m3] / effective volume
    IF rVolUseM3 < 0.0 THEN
        rVolUseM3 := 0.0; // 负液位防御 / negative level guard
    END_IF;
    rTempK := rKelvinOff + rTempC; // 绝对温度 [K] / absolute temperature
    rNormRaw := rVolUseM3 * (rPressRefKpa + rPressKpa) * rKelvinOff / (rTempK * rPressRefKpa); // 标态量 [Nm3]
    IF ABS(rNormRaw) > 1.0E15 THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rNormM3 := rNormRaw;
    // —— 段 4：能量估算（量纲 Nm3 × kWh/m3 × - = kWh） —— //
    rEnergyKwh := rNormM3 * rKwhPerM3 * rCh4Assumed; // 能量估算 [kWh] / estimated energy
    bValid := TRUE;
    FC_DL_GasHolderLevel := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_DigesterRetentionTime
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 消化罐水力停留时间 HRT、固体停留时间 SRT 与容积负荷估算
  口径声明: 容积负荷按进料 VS 浓度假定 25 kg/m3 折算（现场标定前作为默认口径），
            SRT 分母取「废弃污泥流量 + 进料量的 2%（随出流带出固体）」
*)
FUNCTION FC_DL_DigesterRetentionTime : BOOL
VAR_INPUT
    rReactorM3 : REAL; // 反应器有效容积 [m3] / reactor working volume
    rFeedM3Day : REAL; // 进料流量 [m3/d] / feed flow
    rRecycleM3Day : REAL; // 废弃污泥（排泥）流量 [m3/d] / waste sludge flow
END_VAR
VAR_OUTPUT
    rHrtDay : REAL; // 水力停留时间 [d] / hydraulic retention time
    rSrtDay : REAL; // 固体停留时间 [d] / solids retention time
    rLoadingKgM3d : REAL; // 容积有机负荷 [kgVS/(m3·d)] / volumetric organic loading
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    iErrCode : INT; // 事件码 0=正常 1=进料流量非法 2=SRT 小于 HRT 已按 HRT 饱和 3=结果非有限 / event code
END_VAR
VAR CONSTANT
    rVsConcAssumed : REAL := 25.0; // 进料 VS 浓度假定值 [kgVS/m3] / assumed feed VS concentration
    rCarryFrac : REAL := 0.02; // 出流带出固体占进料比 [-] / solids carry-out fraction of feed
END_VAR
VAR
    rQTotalM3d : REAL; // 总吞吐流量 [m3/d] / total through flow
    rQOutM3d : REAL; // 固体出流当量流量 [m3/d] / solids outflow equivalent
    rHrtRaw : REAL; // 未校验 HRT [d] / unchecked HRT
    rSrtRaw : REAL; // 未校验 SRT [d] / unchecked SRT
    rLoadingRaw : REAL; // 未校验负荷 [kgVS/(m3·d)] / unchecked loading
END_VAR

    // —— 段 0：全路径预清 —— //
    rQTotalM3d := 0.0;
    rQOutM3d := 0.0;
    rHrtRaw := 0.0;
    rSrtRaw := 0.0;
    rLoadingRaw := 0.0;
    rHrtDay := 0.0;
    rSrtDay := 0.0;
    rLoadingKgM3d := 0.0;
    bValid := FALSE;
    iErrCode := 0;
    FC_DL_DigesterRetentionTime := FALSE;
    // —— 段 1：分母闸（总吞吐流量 = 进料 + 回流/排泥） —— //
    rQTotalM3d := rFeedM3Day + rRecycleM3Day; // 总吞吐 [m3/d] / total through flow
    IF (rQTotalM3d <= 0.0) OR (rFeedM3Day <= 0.0) THEN
        iErrCode := 1; // 流量非法，停留时间无定义 / invalid flow, retention time undefined
        RETURN;
    END_IF;
    IF rReactorM3 <= 0.0 THEN
        iErrCode := 1; // 容积非法 / invalid volume
        RETURN;
    END_IF;
    // —— 段 2：量纲链 (m3)/(m3/d) = d —— //
    rHrtRaw := rReactorM3 / rQTotalM3d; // HRT [d] / hydraulic retention time
    IF ABS(rHrtRaw) > 1.0E15 THEN
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rHrtDay := rHrtRaw;
    // —— 段 3：SRT 分母 = 排泥量 + 进料×2%（分母闸：不得为零） —— //
    rQOutM3d := rRecycleM3Day + rFeedM3Day * rCarryFrac; // 固体出流当量 [m3/d] / solids outflow equivalent
    IF rQOutM3d <= 1.0E-9 THEN
        rSrtDay := rHrtDay; // 无排泥即无固体流出，SRT 退化按 HRT 计 / no wasting, SRT falls back to HRT
        iErrCode := 2; // 信息级：SRT 按 HRT 饱和 / info level: SRT saturated at HRT
    ELSE
        rSrtRaw := rReactorM3 / rQOutM3d; // SRT [d] / solids retention time
        IF ABS(rSrtRaw) > 1.0E15 THEN
            rSrtRaw := rHrtDay; // 非有限兜底 / non-finite fallback
            iErrCode := 3;
        END_IF;
        IF rSrtRaw < rHrtDay THEN
            rSrtDay := rHrtDay; // SRT 不可能小于 HRT，饱和到 HRT / SRT cannot be below HRT
            iErrCode := 2; // 信息级：SRT 参数不自洽 / info level: SRT parameters inconsistent
        ELSE
            rSrtDay := rSrtRaw;
        END_IF
    END_IF;
    // —— 段 4：容积负荷（量纲 (m3/d)×(kg/m3)/(m3) = kg/(m3·d)） —— //
    rLoadingRaw := rFeedM3Day * rVsConcAssumed / rReactorM3; // 容积负荷 [kgVS/(m3·d)] / volumetric loading
    IF ABS(rLoadingRaw) > 1.0E15 THEN
        rLoadingKgM3d := 0.0;
        iErrCode := 3; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rLoadingKgM3d := rLoadingRaw;
    bValid := TRUE;
    FC_DL_DigesterRetentionTime := TRUE;
END_FUNCTION

(*
  道莅工业代码库 / Daoli Industrial ST Library
  组件: FC_DL_FlareFlowSizing
  分类: DL_Process
  开源溯源: 无（clean-room 工程公式自研；参考公开工艺计算公式，未复制任何受版权保护代码）
  许可证: 本项目自有 (MIT)
  功能: 火炬放空管径 sizing：标态最大气量折算工况实际体积流量后按设计流速反算管径
  设计口径: 管径按「流速限值的 70%」设计（HF 设计余量），实际流速 rVelMs 用于监看是否超限
*)
FUNCTION FC_DL_FlareFlowSizing : BOOL
VAR_INPUT
    rMaxGasM3h : REAL; // 标态最大放空气量 [Nm3/h] / maximum normal-condition gas flow
    rPressBar : REAL; // 放空管绝对压力 [bar] / absolute pressure in the flare header
    rTempC : REAL; // 放空气温度 [°C] / gas temperature
    rVelLimitMs : REAL; // 允许流速上限 [m/s] / allowable velocity limit
END_VAR
VAR_OUTPUT
    rDiaM : REAL; // 建议管内径 [m] / recommended internal diameter
    rVelMs : REAL; // 按建议管径核算的实际流速 [m/s] / actual velocity for the recommended diameter
    bValid : BOOL; // 结果有效位 [-] / result valid flag
    bOver : BOOL; // 流速越限标志 [-] / velocity over-limit flag
    iErrCode : INT; // 事件码 0=正常 1=流速上限非法 2=压力非法 3=温度超域 4=结果非有限 / event code
END_VAR
VAR CONSTANT
    rPi : REAL := 3.14159265358979; // 圆周率 [-] / pi
    rPressRefBar : REAL := 1.01325; // 标准大气压 [bar] / standard atmospheric pressure
    rKelvinOff : REAL := 273.15; // 开尔文偏移 [K] / kelvin offset
    rSecPerHour : REAL := 3600.0; // 每小时秒数 [s/h] / seconds per hour
    rTempMinC : REAL := -50.0; // 温度域下限 [°C] / temperature lower bound
    rDesignFrac : REAL := 0.7; // 设计流速占限值比例 [-] / design velocity fraction of the limit
END_VAR
VAR
    DL_FLARE_DIA_MIN : REAL := 0.08; // 工程最小放空管径 [m] / minimum practical flare diameter
    rVelDesign : REAL; // 设计流速 [m/s] / design velocity
    rQActualM3s : REAL; // 工况实际体积流量 [m3/s] / actual volumetric flow
    rAreaM2 : REAL; // 所需流通面积 [m2] / required flow area
    rDiaRaw : REAL; // 未校验管径 [m] / unchecked diameter
END_VAR

    // —— 段 0：全路径预清 —— //
    rVelDesign := 0.0;
    rQActualM3s := 0.0;
    rAreaM2 := 0.0;
    rDiaRaw := 0.0;
    rDiaM := 0.0;
    rVelMs := 0.0;
    bValid := FALSE;
    bOver := FALSE;
    iErrCode := 0;
    FC_DL_FlareFlowSizing := FALSE;
    // —— 段 1：输入域闸（流速上限、压力、温度） —— //
    IF rVelLimitMs <= 0.0 THEN
        iErrCode := 1; // 流速上限非法，管径无定义 / invalid velocity limit
        RETURN;
    END_IF;
    IF rPressBar <= 0.0 THEN
        iErrCode := 2; // 压力非法，工况折算无意义 / invalid absolute pressure
        RETURN;
    END_IF;
    IF rTempC <= rTempMinC THEN
        iErrCode := 3; // 温度超域，标态折算分母不可信 / temperature out of domain
        RETURN;
    END_IF;
    // —— 段 2：标态→工况折算（量纲 Nm3/h×(bar/bar)×(K/K) = m3/h，再 /3600 得 m3/s） —— //
    rQActualM3s := rMaxGasM3h * (rPressRefBar / rPressBar)
                   * ((rKelvinOff + rTempC) / rKelvinOff) / rSecPerHour; // 工况流量 [m3/s]
    IF rQActualM3s < 0.0 THEN
        rQActualM3s := 0.0; // 负气量防御 / negative flow guard
    END_IF;
    // —— 段 3：按设计流速反算面积与管径（分母闸：设计流速） —— //
    rVelDesign := rVelLimitMs * rDesignFrac; // 设计流速 [m/s] / design velocity
    IF rVelDesign <= 1.0E-9 THEN
        iErrCode := 1; // 设计流速退化 / degenerate design velocity
        RETURN;
    END_IF;
    rAreaM2 := rQActualM3s / rVelDesign; // 流通面积 [m2] / required area
    IF rAreaM2 < 0.0 THEN
        iErrCode := 4; // 面积不可能为负 / area cannot be negative
        RETURN;
    END_IF;
    rDiaRaw := SQRT(4.0 * rAreaM2 / rPi); // 管径 [m] / diameter
    IF ABS(rDiaRaw) > 1.0E15 THEN
        iErrCode := 4; // 结果非有限，强制归零 / non-finite result, forced to zero
        RETURN;
    END_IF;
    rDiaM := rDiaRaw;
    // —— 段 4：按管径回算实际流速并做越限监看 —— //
    IF rDiaM > 1.0E-9 THEN
        rVelMs := rQActualM3s / (rPi * rDiaM * rDiaM / 4.0); // 实际流速 [m/s] / actual velocity
    ELSE
        rVelMs := 0.0; // 退化管径 / degenerate diameter
    END_IF;
    // 管径由限速反算，回算流速恒等于限速，故 bOver 必须改判「所需管径小于工程最小管径」
    bOver := rDiaRaw < DL_FLARE_DIA_MIN; // 需更小管径才满足限速，即实际将超速 / needs smaller dia, will over-speed
    bValid := TRUE;
    FC_DL_FlareFlowSizing := TRUE;
END_FUNCTION
